/*
 * Stage61 display/NPC/event exact-ROM E2E for libmGBA.
 *
 * This translation unit deliberately embeds the reviewed Stage55 field-input
 * harness.  Save fixtures therefore start from a natural new game, enter the
 * requested map through the stock warp owner, write both alternating save
 * generations, and reopen through the title-screen Continue path in a fresh
 * core.  Host calls are preparation/readback only: event entry, choices,
 * movement, battle escape, menus, and revisits are driven with GBA keys.
 *
 * Coordinates and Stage61 IDs are supplied through validated environment
 * variables by scripts/run_stage61_mgba_validation.py.  This keeps the C
 * runner independent of generated JSON while allowing the final placement
 * allocator to move an interaction port without weakening the test.
 */
/* Debian's libmGBA is built with USE_DEBUGGERS.  mCore has conditional
 * debugger function pointers before savedataClone/savedataRestore, so its
 * installed feature manifest must be visible before core.h is first included.
 * Without this include the two savedata methods are read from the wrong ABI
 * slots even though earlier mCore methods appear to work. */
#include <mgba/flags.h>

/* Host-direct preparation must not borrow the interrupted live System/IRQ
 * stack.  This audited EWRAM gap ends below CFRU's field globals; the embedded
 * call helper snapshots/restores every byte and verifies a 64-byte guard. */
#define BATTLE_CORE_ISOLATE_HOST_CALL_STACK 1
#define BATTLE_CORE_HOST_STACK_BOTTOM_ADDRESS 0x0203DB00U
#define BATTLE_CORE_HOST_STACK_TOP_ADDRESS 0x0203DF80U
#define CODEX_IPAD_BOOTSTRAP_EMBEDDED
#define bootstrap_open_core s61_bootstrap_open_core
#define bootstrap_close_core s61_bootstrap_close_core
#define bootstrap_write_ppm s61_bootstrap_write_ppm_raw
#include "mgba_codex_battle_ipad_bootstrap.c"
#undef bootstrap_write_ppm
#undef bootstrap_close_core
#undef bootstrap_open_core

static struct mCore *bootstrap_open_core(const char *rom_path,
                                         const char *save_path,
                                         color_t *video);
static void bootstrap_close_core(struct mCore *core);
static void bootstrap_write_ppm(const char *save_path, const color_t *video)
{
    s61_bootstrap_write_ppm_raw(save_path, video);
}

