enum FixtureKind {
    FIXTURE_FACING_DIALOGUE,
};

struct Fixture {
    const char *name;
    enum FixtureKind kind;
    uint8_t group;
    uint8_t map;
    uint16_t x;
    uint16_t y;
    uint16_t action_key;
    uint16_t item;
    uint16_t flag;
    uint16_t trainer;
    uint8_t local_id;
};

struct FixtureResult {
    bool battle_seen;
    bool battle_completed;
    unsigned key_pulses;
    unsigned successful_steps;
    uint16_t first_wild_species;
    uint8_t first_wild_level;
    uint8_t battle_outcome;
    unsigned forced_switch_count;
    bool forced_switch_cursor_observed;
    bool forced_switch_usable_slot_selected;
    uint8_t forced_switch_cursor_initial[WORLD_MAX_FORCED_SWITCHES];
    uint8_t forced_switch_selected_slot[WORLD_MAX_FORCED_SWITCHES];
    uint16_t forced_switch_selected_hp[WORLD_MAX_FORCED_SWITCHES];
};

struct S61BallThrowResult {
    bool choose_action_seen;
    bool bag_opened;
    bool actual_direction_input;
    bool actual_a_input;
    bool runtime_cleaned;
    uint8_t action_cursor;
    uint8_t chosen_action;
    uint8_t outcome;
    unsigned input_pulses;
};

