static void s61_flash_select_bank(struct mCore *core, unsigned bank);
static void s61_assert_trainer_tower_local_fallback_precondition(
    struct mCore *core, bool allow_blank_sector31);

static void s61_log(struct mLogger *logger, int category,
                    enum mLogLevel level, const char *format, va_list args)
{
    if (s61_allow_expected_stage60_map_script_diagnostics
        && (level & (mLOG_FATAL | mLOG_ERROR | mLOG_WARN))) {
        ++s61_expected_stage60_map_script_diagnostics;
        if (s61_expected_stage60_first_pc == 0U
            && s61_diagnostic_core != NULL)
            s61_expected_stage60_first_pc = (uint32_t)read_register(
                s61_diagnostic_core, "pc");
        return;
    }
    /* A fresh libmGBA process reports its deterministic RTC delta (at ERROR
     * level in 0.10.x) when it attaches the writer process's valid save.  This
     * is host metadata, not a ROM error.  Suppress only that exact notice
     * during persistence READ; every other warning/error remains strict. */
    if ((s61_allow_savedata_time_offset_notice
         || s61_implicitly_allow_savedata_time_offset_notice)
        && level == mLOG_ERROR
        && strcmp(mLogCategoryName(category), "GBA Savedata") == 0
        && strcmp(format, "Savegame time offset set to %li") == 0) {
        if (s61_allow_savedata_time_offset_notice)
            ++s61_savedata_time_offset_notices;
        return;
    }
    if (!s61_illegal_opcode_dumped && s61_diagnostic_core != NULL
        && strstr(format, "Illegal opcode") != NULL) {
        struct mCore *core = s61_diagnostic_core;
        s61_illegal_opcode_dumped = true;
        fprintf(stderr,
                "stage61-first-illegal pc=%08" PRIX32
                " cpsr=%08" PRIX32 " lr=%08" PRIX32
                " sp=%08" PRIX32 " r0=%08" PRIX32
                " r1=%08" PRIX32 " r2=%08" PRIX32
                " r3=%08" PRIX32 " r4=%08" PRIX32
                " r5=%08" PRIX32 " r6=%08" PRIX32
                " r7=%08" PRIX32 " r8=%08" PRIX32
                " r9=%08" PRIX32 " r10=%08" PRIX32
                " r11=%08" PRIX32 " r12=%08" PRIX32
                " callback1=%08" PRIX32 " callback2=%08" PRIX32
                " battle_ptr=%08" PRIX32 " command=%u"
                " cursor=%u chosen=%u outcome=%u last_ball=%u\n",
                (uint32_t)read_register(core, "pc"),
                (uint32_t)read_register(core, "cpsr"),
                (uint32_t)read_register(core, "lr"),
                (uint32_t)read_register(core, "sp"),
                (uint32_t)read_register(core, "r0"),
                (uint32_t)read_register(core, "r1"),
                (uint32_t)read_register(core, "r2"),
                (uint32_t)read_register(core, "r3"),
                (uint32_t)read_register(core, "r4"),
                (uint32_t)read_register(core, "r5"),
                (uint32_t)read_register(core, "r6"),
                (uint32_t)read_register(core, "r7"),
                (uint32_t)read_register(core, "r8"),
                (uint32_t)read_register(core, "r9"),
                (uint32_t)read_register(core, "r10"),
                (uint32_t)read_register(core, "r11"),
                (uint32_t)read_register(core, "r12"),
                read32(core, 0x03003130U),
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                read32(core, ADDR_NEW_BATTLE_STRUCT_POINTER),
                read8(core, WORLD_BATTLE_BUFFER_A),
                read8(core, BATTLE_CORE_ACTION_SELECTION_CURSOR),
                read8(core, BATTLE_CORE_CHOSEN_ACTIONS),
                read8(core, BATTLE_CORE_BATTLE_OUTCOME),
                read16(core, WORLD_LAST_USED_BALL));
        uint32_t sp = (uint32_t)read_register(core, "sp");
        fprintf(stderr,
                "stage61-first-illegal-stack"
                " assert_arg0=%08" PRIX32
                " assert_arg1=%08" PRIX32
                " assert_arg2=%08" PRIX32
                " assert_arg3=%08" PRIX32
                " assert_caller=%08" PRIX32
                " free_internal_return=%08" PRIX32
                " free_caller=%08" PRIX32 "\n",
                read32(core, sp), read32(core, sp + 4U),
                read32(core, sp + 8U), read32(core, sp + 12U),
                read32(core, sp + 20U), read32(core, sp + 40U),
                read32(core, sp + 44U));
        if ((uint32_t)read_register(core, "pc") >= 0x081C7A5CU
            && (uint32_t)read_register(core, "pc") <= 0x081C7A60U) {
            uint32_t allocation =
                (uint32_t)read_register(core, "r4");
            fprintf(stderr,
                    "stage61-malloc-assert create_caller=%08" PRIX32
                    " otid=%08" PRIX32 " personality=%08" PRIX32
                    " dest_x=%08" PRIX32 " dest_y=%08" PRIX32
                    " palette_slot=%08" PRIX32
                    " window_id=%08" PRIX32
                    " is_trainer=%08" PRIX32
                    " wrapper_caller=%08" PRIX32
                    " wrapper_palette=%08" PRIX32
                    " wrapper_window=%08" PRIX32
                    " allocation=%08" PRIX32
                    " header=%08" PRIX32 "/%08" PRIX32
                    "/%08" PRIX32 "/%08" PRIX32 "\n",
                    read32(core, sp + 112U),
                    read32(core, sp + 72U), read32(core, sp + 76U),
                    read32(core, sp + 116U), read32(core, sp + 120U),
                    read32(core, sp + 124U), read32(core, sp + 128U),
                    read32(core, sp + 132U), read32(core, sp + 148U),
                    read32(core, sp + 152U), read32(core, sp + 156U),
                    allocation,
                    read32(core, allocation - 16U),
                    read32(core, allocation - 12U),
                    read32(core, allocation - 8U),
                    read32(core, allocation - 4U));
        }
    }
    bootstrap_log(logger, category, level, format, args);
}

static void world_die(const char *fixture, const char *message)
{
    fprintf(stderr, "mgba-stage61-world[%s][%s]: %s\n",
            fixture, world_phase, message);
    exit(1);
}

static uint32_t world_save1(struct mCore *core, const char *fixture)
{
    uint32_t pointer = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    if (pointer < 0x02000000U || pointer >= 0x02040000U || (pointer & 3U))
        world_die(fixture, "SaveBlock1 pointer differs");
    return pointer;
}

static bool world_script_enabled(struct mCore *core)
{
    return read8(core, WORLD_FIELD_CONTROLS_LOCKED) != 0U;
}

static bool world_overworld(struct mCore *core)
{
    return read32(core, BATTLE_CORE_MAIN_CALLBACK2) == BOOTSTRAP_CB2_OVERWORLD;
}

static void s61_effect_observer_sample_pc(struct mCore *core,
                                          uint32_t raw_pc);

/* Battle completion normally advances in coarse frame blocks.  A field
 * continuation can start inside the last such block, so stop on the exact CPU
 * instruction that installs the overworld callback.  The continuation driver
 * can then observe ScriptContext1's first resumed cursor before any field
 * printer or decision is consumed. */
static bool world_step_key_frames_until_overworld(struct mCore *core,
                                                  uint16_t keys,
                                                  unsigned frames,
                                                  bool stop_at_overworld)
{
    core->setKeys(core, keys);
    uint32_t first_frame = core->frameCounter(core);
    while ((uint32_t)(core->frameCounter(core) - first_frame) < frames) {
        if (stop_at_overworld && world_overworld(core))
            return true;
        uint32_t raw_pc = (uint32_t)read_register(core, "pc");
        s61_effect_observer_sample_pc(core, raw_pc);
        core->step(core);
    }
    return stop_at_overworld && world_overworld(core);
}

static bool world_step_pulse_until_overworld(struct mCore *core, uint16_t key,
                                             unsigned pressed,
                                             unsigned released,
                                             bool stop_at_overworld)
{
    return world_step_key_frames_until_overworld(
               core, key, pressed, stop_at_overworld)
        || world_step_key_frames_until_overworld(
               core, 0U, released, stop_at_overworld);
}

static void world_pulse(struct mCore *core, uint16_t key,
                        unsigned pressed, unsigned released)
{
    run_key_frames(core, key, pressed);
    run_key_frames(core, 0U, released);
}

static void s61_dump_save_load_trace(struct mCore *core, const char *phase)
{
    uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    uint32_t buffer = read32(core, 0x030053E4U);
    uint32_t chunk1 = 0U;
    if (s61_save_load_trace.chunks >= 0x02000000U
        && s61_save_load_trace.chunks + 16U < 0x02040000U)
        chunk1 = read32(core, s61_save_load_trace.chunks + 8U);
    fprintf(stderr,
            "stage61-save-load-trace phase=%s pc=%08" PRIX32
            " r0=%08" PRIX32 " r1=%08" PRIX32
            " save1=%08" PRIX32 " save1_head=%08" PRIX32
            "/%08" PRIX32 " buffer=%08" PRIX32
            " buffer_head=%08" PRIX32 "/%08" PRIX32
            " chunks=%08" PRIX32 " chunk1=%08" PRIX32
            " chunk1_head=%08" PRIX32 "/%08" PRIX32
            " first_sector=%u counter=%08" PRIX32 "\n",
            phase,
            (uint32_t)read_register(core, "pc"),
            (uint32_t)read_register(core, "r0"),
            (uint32_t)read_register(core, "r1"),
            save1,
            save1 >= 0x02000000U && save1 + 8U <= 0x02040000U
                ? read32(core, save1) : UINT32_MAX,
            save1 >= 0x02000000U && save1 + 8U <= 0x02040000U
                ? read32(core, save1 + 4U) : UINT32_MAX,
            buffer,
            buffer >= 0x02000000U && buffer + 8U <= 0x02040000U
                ? read32(core, buffer) : UINT32_MAX,
            buffer >= 0x02000000U && buffer + 8U <= 0x02040000U
                ? read32(core, buffer + 4U) : UINT32_MAX,
            s61_save_load_trace.chunks, chunk1,
            chunk1 >= 0x02000000U && chunk1 + 8U <= 0x02040000U
                ? read32(core, chunk1) : UINT32_MAX,
            chunk1 >= 0x02000000U && chunk1 + 8U <= 0x02040000U
                ? read32(core, chunk1 + 4U) : UINT32_MAX,
            read16(core, WORLD_FIRST_SAVE_SECTOR),
            read32(core, WORLD_SAVE_COUNTER));
}

static void s61_trace_save_load_pc(struct mCore *core)
{
    /* mGBA exposes the architectural Thumb r15 value (current+4), whereas
     * runtime symbols and LR contain instruction addresses. */
    uint32_t pc = ((uint32_t)read_register(core, "pc") - 4U) & ~1U;
    if (!s61_save_load_trace.entry_seen
        && pc == s61_save_load_trace.symbol) {
        s61_save_load_trace.entry_seen = true;
        s61_save_load_trace.caller =
            (uint32_t)read_register(core, "lr") & ~1U;
        s61_save_load_trace.chunks =
            (uint32_t)read_register(core, "r1");
        s61_dump_save_load_trace(core, "wrapper-entry");
    } else if (s61_save_load_trace.entry_seen
               && !s61_save_load_trace.stock_return_seen
               && pc == s61_save_load_trace.stock_return) {
        s61_save_load_trace.stock_return_seen = true;
        s61_dump_save_load_trace(core, "stock-return");
    } else if (s61_save_load_trace.stock_return_seen
               && !s61_save_load_trace.wrapper_return_seen
               && pc == s61_save_load_trace.caller) {
        s61_save_load_trace.wrapper_return_seen = true;
        s61_save_load_trace.loaded_save1 =
            read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
        s61_save_load_trace.loaded_head0 =
            read32(core, s61_save_load_trace.loaded_save1);
        s61_save_load_trace.loaded_head1 =
            read32(core, s61_save_load_trace.loaded_save1 + 4U);
        s61_dump_save_load_trace(core, "wrapper-return");
    } else if (s61_save_load_trace.wrapper_return_seen
               && !s61_save_load_trace.content_transition_seen
               && read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR)
                    == s61_save_load_trace.loaded_save1
               && (read32(core, s61_save_load_trace.loaded_save1)
                        != s61_save_load_trace.loaded_head0
                   || read32(core, s61_save_load_trace.loaded_save1 + 4U)
                        != s61_save_load_trace.loaded_head1)) {
        uint32_t sp = (uint32_t)read_register(core, "sp");
        s61_save_load_trace.content_transition_seen = true;
        fprintf(stderr,
                "stage61-save-load-trace phase=save1-content-transition"
                " mutating_pc=%08" PRIX32 " next_pc=%08" PRIX32
                " lr=%08" PRIX32 " sp=%08" PRIX32
                " stack0=%08" PRIX32 "/%08" PRIX32 "/%08" PRIX32
                " loaded=%08" PRIX32 " before=%08" PRIX32
                "/%08" PRIX32 " after=%08" PRIX32
                "/%08" PRIX32 "\n",
                s61_save_load_trace.previous_instruction_pc, pc,
                (uint32_t)read_register(core, "lr"), sp,
                read32(core, sp), read32(core, sp + 4U),
                read32(core, sp + 8U), s61_save_load_trace.loaded_save1,
                s61_save_load_trace.loaded_head0,
                s61_save_load_trace.loaded_head1,
                read32(core, s61_save_load_trace.loaded_save1),
                read32(core, s61_save_load_trace.loaded_save1 + 4U));
    } else if (s61_save_load_trace.wrapper_return_seen
               && !s61_save_load_trace.pointer_transition_seen
               && read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR)
                    != s61_save_load_trace.loaded_save1) {
        uint32_t new_save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
        s61_save_load_trace.pointer_transition_seen = true;
        fprintf(stderr,
                "stage61-save-load-trace phase=save1-pointer-transition"
                " mutating_pc=%08" PRIX32 " next_pc=%08" PRIX32
                " lr=%08" PRIX32 " sp=%08" PRIX32
                " stack0=%08" PRIX32 "/%08" PRIX32 "/%08" PRIX32
                " r0=%08" PRIX32 " r1=%08" PRIX32
                " r2=%08" PRIX32 " r3=%08" PRIX32
                " old=%08" PRIX32 " old_head=%08" PRIX32
                "/%08" PRIX32 " new=%08" PRIX32
                " new_head=%08" PRIX32 "/%08" PRIX32 "\n",
                s61_save_load_trace.previous_instruction_pc, pc,
                (uint32_t)read_register(core, "lr"),
                (uint32_t)read_register(core, "sp"),
                read32(core, (uint32_t)read_register(core, "sp")),
                read32(core, (uint32_t)read_register(core, "sp") + 4U),
                read32(core, (uint32_t)read_register(core, "sp") + 8U),
                (uint32_t)read_register(core, "r0"),
                (uint32_t)read_register(core, "r1"),
                (uint32_t)read_register(core, "r2"),
                (uint32_t)read_register(core, "r3"),
                s61_save_load_trace.loaded_save1,
                read32(core, s61_save_load_trace.loaded_save1),
                read32(core, s61_save_load_trace.loaded_save1 + 4U),
                new_save1, read32(core, new_save1),
                read32(core, new_save1 + 4U));
    }
    s61_save_load_trace.previous_instruction_pc = pc;
}

static void s61_continue_key_frames(struct mCore *core, uint16_t keys,
                                    unsigned frames)
{
    if (!s61_save_load_trace.enabled
        || s61_save_load_trace.pointer_transition_seen) {
        run_key_frames(core, keys, frames);
        return;
    }
    uint32_t target = core->frameCounter(core) + frames;
    core->setKeys(core, keys);
    while ((int32_t)(core->frameCounter(core) - target) < 0) {
        s61_trace_save_load_pc(core);
        core->step(core);
    }
    s61_trace_save_load_pc(core);
}

static void s61_continue_pulse(struct mCore *core, uint16_t key,
                               unsigned pressed, unsigned released)
{
    s61_continue_key_frames(core, key, pressed);
    s61_continue_key_frames(core, 0U, released);
}

static bool s61_sync_host_call_pc(struct mCore *core)
{
    /* runFrame may yield on the GBA IRQ vector.  Preserving that transient
     * PC/CPSR as a host-call return continuation corrupts the next field
     * frame.  An IRQ handler may itself call ROM, so a ROM-range PC alone is
     * insufficient: wait until ordinary System mode owns the CPU. */
    for (unsigned frame = 0U; frame < 120U; ++frame) {
        uint32_t pc = (uint32_t)read_register(core, "pc") & ~1U;
        uint32_t mode = (uint32_t)read_register(core, "cpsr") & 0x1FU;
        if (pc >= 0x08000000U && pc < 0x0A000000U && mode == 0x1FU)
            return true;
        run_key_frames(core, 0U, 1U);
    }
    fprintf(stderr,
            "Stage61 host-call sync timeout phase=%s pc=%08" PRIX32
            " cpsr=%08" PRIX32 " lr=%08" PRIX32 " sp=%08" PRIX32
            " callback=%08" PRIX32 " lock=%u\n",
            world_phase,
            (uint32_t)read_register(core, "pc"),
            (uint32_t)read_register(core, "cpsr"),
            (uint32_t)read_register(core, "lr"),
            (uint32_t)read_register(core, "sp"),
            read32(core, BATTLE_CORE_MAIN_CALLBACK2),
            world_script_enabled(core));
    return false;
}

static uint32_t s61_call_synced(struct mCore *core, uint32_t function,
                                uint32_t r0, uint32_t r1,
                                uint32_t r2, uint32_t r3)
{
    if (!s61_sync_host_call_pc(core))
        world_die(world_phase, "host ROM call scheduler PC did not settle");
    uint32_t result = call_preserving(core, function, r0, r1, r2, r3);
    run_key_frames(core, 0U, 1U);
    return result;
}

static uint32_t s61_call_save_sync(struct mCore *core)
{
    /* TrySavingData is fully synchronous and the established two-generation
     * save contract invokes it twice without scheduling a field frame in
     * between.  A frame here lets its temporary callback state run and
     * invalidates the second generation. */
    if (!s61_sync_host_call_pc(core))
        world_die(world_phase, "save call scheduler PC did not settle");
    return call_preserving(core, BOOTSTRAP_TRY_SAVE, 0U, 0U, 0U, 0U);
}

static void s61_create_mon_synced(struct mCore *core, uint32_t mon,
                                  uint16_t species, uint8_t level)
{
    /* create_mon performs a CreateMon call followed by two getter calls.  Its
     * CPU preservation is only valid when the captured continuation belongs
     * to ordinary System-mode ROM code; capturing a runFrame IRQ boundary can
     * otherwise restore a transient IRQ continuation and jump into low RAM on
     * the following field frame. */
    if (!s61_sync_host_call_pc(core))
        world_die(world_phase, "CreateMon scheduler PC did not settle");
    create_mon(core, mon, species, level);
}

static void s61_set_mon_data_u32(struct mCore *core, uint32_t mon,
                                 uint32_t field, uint32_t value)
{
    /* SetMonData and its readback form one synchronous transaction.  A field
     * frame between them can normalize a party slot before the readback; the
     * scheduler boundary belongs before the pair and after verification. */
    if (!s61_sync_host_call_pc(core))
        world_die(world_phase, "SetMonData scheduler PC did not settle");
    write32_bytes(core, SET_MON_DATA_SCRATCH, value);
    (void)call_preserving(
        core, ROM_SET_MON_DATA, mon, field, SET_MON_DATA_SCRATCH, 0U);
    uint32_t actual = call_preserving(
        core, BATTLE_CORE_GET_MON_DATA, mon, field, 0U, 0U);
    if (actual != value) {
        fprintf(stderr, "SetMonData debug mon=%08" PRIX32
                " field=%" PRIu32 " expected=%" PRIu32
                " actual=%" PRIu32 " pc=%08" PRIX32 "\n",
                mon, field, value, actual,
                (uint32_t)read_register(core, "pc"));
        world_die(world_phase, "scheduler-safe SetMonData readback failed");
    }
    run_key_frames(core, 0U, 1U);
}

static void world_wait_player_ready(struct mCore *core,
                                    const struct Fixture *fixture)
{
    unsigned stable_frames = 0U;
    uint8_t first_object_id = read8(core, WORLD_PLAYER_AVATAR + 5U);
    if (first_object_id >= 16U
        || !(read8(core, WORLD_OBJECT_EVENTS
                   + first_object_id * 0x24U) & 1U))
        world_pulse(core, WORLD_KEY_UP, 1U, 180U);
    for (unsigned frames = 0U; frames < 3600U; frames += 15U) {
        uint8_t object_id = read8(core, WORLD_PLAYER_AVATAR + 5U);
        uint32_t object = WORLD_OBJECT_EVENTS + object_id * 0x24U;
        uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
        bool save_ready = save1 >= 0x02000000U && save1 < 0x02040000U
            && (save1 & 3U) == 0U;
        bool object_ready = object_id < 16U
            && (read8(core, object) & 1U)
            && (read8(core, object + 0x18U) & 0xFU) >= 1U
            && (read8(core, object + 0x18U) & 0xFU) <= 4U
            && read16(core, object + 0x10U) != 0U
            && read16(core, object + 0x12U) != 0U;
        bool stationary = read8(
            core, WORLD_PLAYER_AVATAR + WORLD_PLAYER_RUNNING_STATE_OFFSET) == 0U
            && read8(core, WORLD_PLAYER_AVATAR
                     + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET) == 0U;
        if (world_overworld(core) && save_ready && object_ready && stationary
            && !world_script_enabled(core)) {
            stable_frames += 15U;
            if (stable_frames >= 120U)
                return;
        } else {
            stable_frames = 0U;
        }
        run_key_frames(core, 0U, 15U);
    }
    uint8_t object_id = read8(core, WORLD_PLAYER_AVATAR + 5U);
    uint32_t object = WORLD_OBJECT_EVENTS + object_id * 0x24U;
    uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    fprintf(stderr,
            "field-ready diagnostic case=%s object_id=%u active=%u "
            "object_state=%u object_xy=%u,%u map=%u/%u pos=%u,%u "
            "overworld=%u script=%u controls=%u running=%u tile=%u "
            "message=%u callback=%08" PRIX32 "\n",
            fixture->name, object_id,
            object_id < 16U ? read8(core, object) & 1U : 0U,
            object_id < 16U ? read8(core, object + 0x18U) & 0xFU : 0U,
            object_id < 16U ? read16(core, object + 0x10U) : 0U,
            object_id < 16U ? read16(core, object + 0x12U) : 0U,
            save1 >= 0x02000000U && save1 < 0x02040000U
                ? read8(core, save1 + 4U) : 0xFFU,
            save1 >= 0x02000000U && save1 < 0x02040000U
                ? read8(core, save1 + 5U) : 0xFFU,
            save1 >= 0x02000000U && save1 < 0x02040000U
                ? read16(core, save1) : 0U,
            save1 >= 0x02000000U && save1 < 0x02040000U
                ? read16(core, save1 + 2U) : 0U,
            world_overworld(core), world_script_enabled(core),
            read8(core, WORLD_FIELD_CONTROLS_LOCKED),
            read8(core, WORLD_PLAYER_AVATAR
                        + WORLD_PLAYER_RUNNING_STATE_OFFSET),
            read8(core, WORLD_PLAYER_AVATAR
                        + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET),
            read8(core, WORLD_FIELD_MESSAGE_STATE),
            read32(core, BATTLE_CORE_MAIN_CALLBACK2));
    fprintf(stderr,
            "field-ready script diagnostic context1=%08" PRIX32
            " special_result=%u pc=%08" PRIX32 " cpsr=%08" PRIX32 "\n",
            read32(core, WORLD_SCRIPT_CONTEXT1_POINTER),
            read16(core, WORLD_SPECIAL_RESULT),
            (uint32_t)read_register(core, "pc"),
            (uint32_t)read_register(core, "cpsr"));
    world_die(fixture->name, "Continue did not settle on an input-ready field");
}

static void world_continue(struct mCore *core, const struct Fixture *fixture)
{
    world_phase = "fresh-core-continue";
    memset(&s61_save_load_trace, 0, sizeof(s61_save_load_trace));
    const char *trace = getenv("S61_TRACE_SAVE_LOAD");
    if (trace != NULL && trace[0] != '\0' && strcmp(trace, "0") != 0) {
        const char *symbol = getenv("S61_HANDLE_LOAD_SYMBOL");
        s61_save_load_trace.enabled = true;
        s61_save_load_trace.symbol = symbol != NULL && symbol[0] != '\0'
            ? (uint32_t)strtoul(symbol, NULL, 0) & ~1U
            : 0x0943D61CU;
        /* GCC's current wrapper stores r1 then returns from the stock call at
         * entry+0x0C.  It is deliberately overridable so a rebuilt runtime
         * can retain this instruction-level diagnostic without stale PCs. */
        const char *stock_return = getenv("S61_HANDLE_LOAD_STOCK_RETURN");
        s61_save_load_trace.stock_return =
            stock_return != NULL && stock_return[0] != '\0'
                ? (uint32_t)strtoul(stock_return, NULL, 0) & ~1U
                : s61_save_load_trace.symbol + 0x0CU;
    }
    s61_continue_key_frames(core, 0U, BOOTSTRAP_TITLE_FRAMES);
    for (unsigned pulse = 0U; pulse < BOOTSTRAP_CONTINUE_PULSES; ++pulse) {
        s61_continue_pulse(core, pulse == 0U ? 8U : WORLD_KEY_A,
                           2U, BOOTSTRAP_CONTINUE_WAIT_FRAMES);
        uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
        if (world_overworld(core)
            && save1 >= 0x02000000U && save1 < 0x02040000U
            && !(save1 & 3U)
            && read8(core, save1 + 4U) == fixture->group
            && read8(core, save1 + 5U) == fixture->map) {
            run_key_frames(core, 0U, 300U);
            for (unsigned attempt = 0U; attempt < 8U; ++attempt) {
                if (read8(core, WORLD_QUEST_LOG_STATE) == 0U
                    && read8(core, WORLD_QUEST_LOG_PLAYBACK_STATE) == 0U) {
                    run_key_frames(core, 0U, 420U);
                    if (read8(core, WORLD_QUEST_LOG_STATE) == 0U
                        && read8(core, WORLD_QUEST_LOG_PLAYBACK_STATE) == 0U)
                        return;
                }
                world_pulse(core, WORLD_KEY_B, 2U, 180U);
            }
            world_die(fixture->name,
                      "Continue recap did not return to field state");
        }
    }
    uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    fprintf(stderr,
            "Stage61 Continue timeout phase=%s pc=%08" PRIX32
            " cpsr=%08" PRIX32 " callback=%08" PRIX32
            " save1=%08" PRIX32 " expected_map=%u/%u"
            " actual_map=%u/%u first_sector=%u counter=%08" PRIX32
            " quest=%u playback=%u\n",
            world_phase, (uint32_t)read_register(core, "pc"),
            (uint32_t)read_register(core, "cpsr"),
            read32(core, BATTLE_CORE_MAIN_CALLBACK2), save1,
            fixture->group, fixture->map,
            save1 >= 0x02000000U && save1 < 0x02040000U
                ? read8(core, save1 + 4U) : 0xFFU,
            save1 >= 0x02000000U && save1 < 0x02040000U
                ? read8(core, save1 + 5U) : 0xFFU,
            read16(core, WORLD_FIRST_SAVE_SECTOR),
            read32(core, WORLD_SAVE_COUNTER),
            read8(core, WORLD_QUEST_LOG_STATE),
            read8(core, WORLD_QUEST_LOG_PLAYBACK_STATE));
    world_die(fixture->name, "natural Continue did not reach fixture");
}

static void world_generate_save(const char *rom_path, const char *save_path,
                                const struct Fixture *fixture,
                                uint16_t x, uint16_t y)
{
    world_phase = "natural-new-game";
    bootstrap_write_blank_save(save_path);
    struct mCore *core = bootstrap_open_core(rom_path, save_path, NULL);
    run_trace_prefix(core);
    run_fixed_frames(core);
    (void)world_save1(core, fixture->name);

    world_phase = "stock-warp-save";
    s61_assert_trainer_tower_local_fallback_precondition(core, true);
    (void)s61_call_synced(core, BOOTSTRAP_KANTO_WARP,
                         fixture->group, fixture->map, x, y);
    run_key_frames(core, 0U, BOOTSTRAP_FIELD_FRAMES);
    uint32_t save1 = world_save1(core, fixture->name);
    if (read8(core, save1 + 4U) != fixture->group
        || read8(core, save1 + 5U) != fixture->map
        || read16(core, save1) != x || read16(core, save1 + 2U) != y
        || !world_overworld(core))
        world_die(fixture->name, "stock warp did not reach fixture");

    for (unsigned byte = 0U;
         byte < BOOTSTRAP_TEAM_SIZE * BOOTSTRAP_MON_SIZE; ++byte)
        write8(core, BOOTSTRAP_PLAYER_PARTY + byte, 0U);
    for (unsigned slot = 0U; slot < BOOTSTRAP_TEAM_SIZE; ++slot) {
        uint32_t mon = BOOTSTRAP_PLAYER_PARTY + slot * BOOTSTRAP_MON_SIZE;
        s61_create_mon_synced(core, mon, 150U, 100U);
        /* create_mon_synced leaves the exact audited System-mode
         * continuation restored, so keep the remaining party construction in
         * the same synchronous transaction.  Advancing a field frame between
         * these calls executes the intentionally-broken Stage60 map-script
         * baseline and destroys its transient SaveMapView owner. */
        set_mon_data_u32(core, mon, MON_DATA_MOVE1,
                         WORLD_QA_MOVE_DARK_PULSE);
        set_mon_data_u32(core, mon, MON_DATA_PP1, 63U);
    }
    write8(core, BOOTSTRAP_PLAYER_COUNT, BOOTSTRAP_TEAM_SIZE);
    bootstrap_prepare_save_map_view(core);
    uint32_t first_save = s61_call_save_sync(core);
    uint32_t second_save = s61_call_save_sync(core);
    if (first_save != BOOTSTRAP_STATUS_OK
        || second_save != BOOTSTRAP_STATUS_OK) {
        fprintf(stderr, "initial save debug first=%" PRIu32
                " second=%" PRIu32 " callback=%08" PRIX32
                " lock=%u pc=%08" PRIX32 "\n",
                first_save, second_save,
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                world_script_enabled(core),
                (uint32_t)read_register(core, "pc"));
        world_die(fixture->name, "two-generation save failed");
    }
    bootstrap_close_core(core);
}

static bool world_walk_to_new_tile(struct mCore *core, uint16_t key,
                                   uint16_t *x, uint16_t *y,
                                   struct FixtureResult *result)
{
    uint16_t next_x = *x;
    uint16_t next_y = *y;
    bool coordinate_changed = false;
    ++result->key_pulses;
    for (unsigned frame = 0U; frame < 40U; ++frame) {
        run_key_frames(core, key, 1U);
        if (!world_overworld(core)) {
            core->setKeys(core, 0U);
            if (coordinate_changed) {
                *x = next_x;
                *y = next_y;
                ++result->successful_steps;
            }
            return false;
        }
        uint32_t save1 = world_save1(core, "walk");
        next_x = read16(core, save1);
        next_y = read16(core, save1 + 2U);
        coordinate_changed = next_x != *x || next_y != *y;
        if (coordinate_changed
            && read8(core, WORLD_PLAYER_AVATAR
                           + WORLD_PLAYER_RUNNING_STATE_OFFSET)
                   == WORLD_PLAYER_MOVING
            && read8(core, WORLD_PLAYER_AVATAR
                           + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET)
                   == WORLD_PLAYER_TILE_CENTER) {
            core->setKeys(core, 0U);
            *x = next_x;
            *y = next_y;
            ++result->successful_steps;
            run_key_frames(core, 0U, 45U);
            return world_overworld(core);
        }
    }
    run_key_frames(core, 0U, 4U);
    return false;
}

static void world_record_wild(struct mCore *core,
                              const struct Fixture *fixture,
                              struct FixtureResult *result)
{
    uint16_t species = 0U;
    uint8_t level = 0U;
    for (unsigned frames = 0U; frames < 1800U; frames += 15U) {
        uint32_t enemy = ADDR_BATTLE_MONS + BATTLE_MON_SIZE;
        species = read16(core, enemy);
        level = read8(core, enemy + BATTLE_CORE_MON_LEVEL);
        if (read8(core, ADDR_BATTLERS_COUNT) >= 2U
            && read16(core, enemy + BATTLE_CORE_MON_HP) != 0U
            && species != 0U && level != 0U)
            break;
        run_key_frames(core, 0U, 15U);
    }
    if (species == 0U || level == 0U)
        world_die(fixture->name, "scripted battle has an empty enemy");
    result->first_wild_species = species;
    result->first_wild_level = level;
}

static uint32_t world_party_mon_data(struct mCore *core, unsigned slot,
                                     uint32_t field)
{
    return call_preserving(
        core, BATTLE_CORE_GET_MON_DATA,
        BOOTSTRAP_PLAYER_PARTY + slot * BOOTSTRAP_MON_SIZE,
        field, 0U, 0U);
}

/* Command 22 has two materially different meanings.  When the active mon is
 * healthy it is the optional post-KO switch prompt and B is the observed
 * decline.  With active HP=0 the stock callback owns the real party menu; in
 * that state selecting the stale current cursor with A is rejected forever.
 * Inspect all six actual party records through GetMonData, observe the live
 * party cursor, move it with D-pad input until it names a usable non-active
 * slot, and only then accept the SHIFT action with two intentional A presses. */
static bool world_complete_forced_switch(
    struct mCore *core, const struct Fixture *fixture,
    struct FixtureResult *result, unsigned bank)
{
    if (result->forced_switch_count >= WORLD_MAX_FORCED_SWITCHES)
        world_die(fixture->name, "more forced switches than party slots");

    uint32_t command = WORLD_BATTLE_BUFFER_A + bank * 0x200U;
    for (unsigned frame = 0U; frame < 240U; frame += 5U) {
        if (read32(core, BATTLE_CORE_MAIN_CALLBACK2)
                == WORLD_PARTY_MENU_MAIN_CALLBACK
            && read8(core, command) == WORLD_BATTLE_COMMAND_CHOOSE_POKEMON)
            break;
        run_key_frames(core, 0U, 5U);
    }
    if (read32(core, BATTLE_CORE_MAIN_CALLBACK2)
            != WORLD_PARTY_MENU_MAIN_CALLBACK
        || read8(core, command) != WORLD_BATTLE_COMMAND_CHOOSE_POKEMON) {
        fprintf(stderr,
                "forced-switch menu diagnostic case=%s bank=%u callback=%08"
                PRIX32 " command=%u active_hp=%u\n",
                fixture->name, bank,
                read32(core, BATTLE_CORE_MAIN_CALLBACK2), read8(core, command),
                read16(core, ADDR_BATTLE_MONS + bank * BATTLE_MON_SIZE
                             + BATTLE_CORE_MON_HP));
        world_die(fixture->name,
                  "forced switch did not enter the stock party menu");
    }

    if (!s61_sync_host_call_pc(core))
        world_die(fixture->name,
                  "forced-switch GetMonData scheduler PC did not settle");
    uint8_t party_count = read8(core, BOOTSTRAP_PLAYER_COUNT);
    if (party_count == 0U || party_count > BOOTSTRAP_TEAM_SIZE)
        world_die(fixture->name, "forced switch party count is invalid");
    uint8_t candidate = 0xFFU;
    uint16_t candidate_hp = 0U;
    uint16_t party_hp[BOOTSTRAP_TEAM_SIZE] = {0};
    uint16_t party_species[BOOTSTRAP_TEAM_SIZE] = {0};
    uint8_t party_egg[BOOTSTRAP_TEAM_SIZE] = {0};
    for (unsigned slot = 0U; slot < party_count; ++slot) {
        party_species[slot] = (uint16_t)world_party_mon_data(
            core, slot, WORLD_MON_DATA_SPECIES);
        party_hp[slot] = (uint16_t)world_party_mon_data(
            core, slot, WORLD_MON_DATA_HP);
        party_egg[slot] = (uint8_t)world_party_mon_data(
            core, slot, WORLD_MON_DATA_IS_EGG);
        bool already_active = false;
        for (unsigned player_bank = 0U; player_bank < 4U;
             player_bank += 2U) {
            if (player_bank < read8(core, ADDR_BATTLERS_COUNT)
                && read16(core, ADDR_BATTLER_PARTY_INDEXES
                                + player_bank * 2U) == slot
                && read16(core, ADDR_BATTLE_MONS
                                + player_bank * BATTLE_MON_SIZE
                                + BATTLE_CORE_MON_HP) != 0U) {
                already_active = true;
            }
        }
        if (candidate == 0xFFU && party_species[slot] != 0U
            && party_hp[slot] != 0U && party_egg[slot] == 0U
            && !already_active) {
            candidate = (uint8_t)slot;
            candidate_hp = party_hp[slot];
        }
    }
    if (candidate == 0xFFU) {
        fprintf(stderr,
                "forced-switch no-usable-slot case=%s bank=%u count=%u "
                "indexes=%u,%u hp=%u,%u,%u,%u,%u,%u "
                "species=%u,%u,%u,%u,%u,%u eggs=%u,%u,%u,%u,%u,%u\n",
                fixture->name, bank, party_count,
                read16(core, ADDR_BATTLER_PARTY_INDEXES),
                read16(core, ADDR_BATTLER_PARTY_INDEXES + 4U),
                party_hp[0], party_hp[1], party_hp[2], party_hp[3],
                party_hp[4], party_hp[5],
                party_species[0], party_species[1], party_species[2],
                party_species[3], party_species[4], party_species[5],
                party_egg[0], party_egg[1], party_egg[2], party_egg[3],
                party_egg[4], party_egg[5]);
        world_die(fixture->name, "forced switch has no usable party slot");
    }

    unsigned trace_index = result->forced_switch_count;
    uint8_t initial_cursor = read8(core, BATTLE_CORE_SELECTED_PARTY_MON);
    result->forced_switch_cursor_initial[trace_index] = initial_cursor;
    bool cursor_sane = initial_cursor <= BOOTSTRAP_TEAM_SIZE;
    bool cursor_moved_or_already_selected = initial_cursor == candidate;
    for (unsigned move = 0U;
         read8(core, BATTLE_CORE_SELECTED_PARTY_MON) != candidate
             && move < 12U;
         ++move) {
        uint8_t before = read8(core, BATTLE_CORE_SELECTED_PARTY_MON);
        world_pulse(core, WORLD_KEY_DOWN, 2U, 30U);
        uint8_t after = read8(core, BATTLE_CORE_SELECTED_PARTY_MON);
        if (before <= BOOTSTRAP_TEAM_SIZE
            && after <= BOOTSTRAP_TEAM_SIZE && before != after)
            cursor_moved_or_already_selected = true;
    }
    uint8_t selected_cursor = read8(core, BATTLE_CORE_SELECTED_PARTY_MON);
    if (!cursor_sane || !cursor_moved_or_already_selected
        || selected_cursor != candidate) {
        fprintf(stderr,
                "forced-switch cursor diagnostic case=%s bank=%u initial=%u "
                "selected=%u target=%u hp=%u callback=%08" PRIX32 "\n",
                fixture->name, bank, initial_cursor, selected_cursor,
                candidate, candidate_hp,
                read32(core, BATTLE_CORE_MAIN_CALLBACK2));
        world_die(fixture->name,
                  "real party cursor did not reach the usable slot");
    }

    result->forced_switch_cursor_observed = true;
    result->forced_switch_selected_slot[trace_index] = candidate;
    result->forced_switch_selected_hp[trace_index] = candidate_hp;
    world_pulse(core, WORLD_KEY_A, 2U, 80U);
    world_pulse(core, WORLD_KEY_A, 2U, 180U);
    for (unsigned frame = 0U; frame < 300U; frame += 5U) {
        uint16_t active_slot = read16(
            core, ADDR_BATTLER_PARTY_INDEXES + bank * 2U);
        uint16_t active_hp = read16(
            core, ADDR_BATTLE_MONS + bank * BATTLE_MON_SIZE
                      + BATTLE_CORE_MON_HP);
        if (active_slot == candidate && active_hp != 0U) {
            ++result->forced_switch_count;
            result->forced_switch_usable_slot_selected = true;
            return true;
        }
        run_key_frames(core, 0U, 5U);
    }
    fprintf(stderr,
            "forced-switch commit diagnostic case=%s bank=%u initial=%u "
            "selected=%u selected_hp=%u active_slot=%u active_hp=%u "
            "callback=%08" PRIX32 " command=%u\n",
            fixture->name, bank, initial_cursor, candidate, candidate_hp,
            read16(core, ADDR_BATTLER_PARTY_INDEXES + bank * 2U),
            read16(core, ADDR_BATTLE_MONS + bank * BATTLE_MON_SIZE
                         + BATTLE_CORE_MON_HP),
            read32(core, BATTLE_CORE_MAIN_CALLBACK2), read8(core, command));
    world_die(fixture->name,
              "usable party selection did not become the active battler");
    return false;
}

static void world_finish_battle(struct mCore *core,
                                const struct Fixture *fixture,
                                struct FixtureResult *result,
                                bool flee)
{
    bool initialized = false;
    result->battle_seen = true;
    world_phase = flee ? "gba-run-from-wild" : "gba-complete-battle";
    for (unsigned pulse = 0U; pulse < 1200U; ++pulse) {
        if (read8(core, BATTLE_CORE_BATTLE_OUTCOME) != 0U)
            result->battle_outcome = read8(core, BATTLE_CORE_BATTLE_OUTCOME);
        if (read32(core, ADDR_NEW_BATTLE_STRUCT_POINTER) != 0U
            || read8(core, ADDR_BATTLERS_COUNT) != 0U)
            initialized = true;
        if (initialized && world_overworld(core)) {
            result->battle_completed = true;
            return;
        }
        if (!initialized) {
            (void)world_step_key_frames_until_overworld(
                core, 0U, 30U, false);
            if (pulse % 6U == 5U)
                (void)world_step_pulse_until_overworld(
                    core, WORLD_KEY_A, 2U, 30U, false);
            continue;
        }
        if (flee && pulse % 5U == 0U) {
            if (world_step_pulse_until_overworld(
                    core, WORLD_KEY_RIGHT, 2U, 16U, true)
                || world_step_pulse_until_overworld(
                    core, WORLD_KEY_DOWN, 2U, 16U, true)) {
                result->battle_completed = true;
                return;
            }
        }
        bool handled_party_switch = false;
        for (unsigned bank = 0U; bank < 4U; bank += 2U) {
            if (read8(core, 0x02022B24U + bank * 0x200U)
                    != WORLD_BATTLE_COMMAND_CHOOSE_POKEMON)
                continue;
            if (read16(core, ADDR_BATTLE_MONS
                             + bank * BATTLE_MON_SIZE
                             + BATTLE_CORE_MON_HP) != 0U) {
                /* Enemy fainted: decline the optional switch prompt. */
                world_pulse(core, WORLD_KEY_B, 2U, 30U);
            } else {
                (void)world_complete_forced_switch(
                    core, fixture, result, bank);
            }
            handled_party_switch = true;
            break;
        }
        if (!handled_party_switch
            && world_step_pulse_until_overworld(
                core, WORLD_KEY_A, 2U, BATTLE_CORE_MENU_INPUT_WAIT, true)) {
            result->battle_completed = true;
            return;
        }
        if (world_overworld(core)) {
            result->battle_completed = true;
            return;
        }
        if (flee && pulse % 7U == 6U
            && world_step_pulse_until_overworld(
                core, WORLD_KEY_B, 2U, 30U, true)) {
            result->battle_completed = true;
            return;
        }
    }
    fprintf(stderr,
            "battle-completion diagnostic case=%s flee=%u initialized=%u "
            "outcome=%u live_outcome=%u type=%08" PRIX32
            " battle_ptr=%08" PRIX32 " battlers=%u "
            "commands=%u,%u,%u,%u hp=%u,%u,%u,%u "
            "overworld=%u script=%u message=%u callback=%08" PRIX32
            " context1=%08" PRIX32 " pc=%08" PRIX32
            " cpsr=%08" PRIX32 "\n",
            fixture->name, flee ? 1U : 0U, initialized ? 1U : 0U,
            result->battle_outcome,
            read8(core, BATTLE_CORE_BATTLE_OUTCOME),
            read32(core, ADDR_BATTLE_TYPE_FLAGS),
            read32(core, ADDR_NEW_BATTLE_STRUCT_POINTER),
            read8(core, ADDR_BATTLERS_COUNT),
            read8(core, 0x02022B24U), read8(core, 0x02022D24U),
            read8(core, 0x02022F24U), read8(core, 0x02023124U),
            read16(core, ADDR_BATTLE_MONS + BATTLE_CORE_MON_HP),
            read16(core, ADDR_BATTLE_MONS + BATTLE_MON_SIZE
                         + BATTLE_CORE_MON_HP),
            read16(core, ADDR_BATTLE_MONS + 2U * BATTLE_MON_SIZE
                         + BATTLE_CORE_MON_HP),
            read16(core, ADDR_BATTLE_MONS + 3U * BATTLE_MON_SIZE
                         + BATTLE_CORE_MON_HP),
            world_overworld(core) ? 1U : 0U,
            world_script_enabled(core) ? 1U : 0U,
            read8(core, WORLD_FIELD_MESSAGE_STATE),
            read32(core, BATTLE_CORE_MAIN_CALLBACK2),
            read32(core, WORLD_SCRIPT_CONTEXT1_POINTER),
            (uint32_t)read_register(core, "pc"),
            (uint32_t)read_register(core, "cpsr"));
    world_die(fixture->name, "battle did not return to field through keys");
}

