static void s61_die(const char *message)
{
    /* A fatal error can occur inside capture or emulator callbacks while an
     * RFU attempt is active.  Tear external state down before exiting so the
     * same detach -> peer-core -> peripheral -> hub order covers every
     * ordinary mismatch and every fail-closed process error. */
    if (s61_rfu_attempt.hub != NULL)
        (void)s61_rfu_attempt_cleanup();
    fprintf(stderr, "mgba-stage61-display-npc-event[%s]: %s\n",
            s61_case_name, message);
    exit(1);
}

static uint64_t s61_framebuffer_rgb_fnv1a64(const color_t *video)
{
    uint64_t hash = UINT64_C(14695981039346656037);
    for (unsigned index = 0U; index < 240U * 160U; ++index) {
        uint32_t pixel = (uint32_t)video[index];
        for (unsigned byte = 0U; byte < 3U; ++byte) {
            hash ^= (uint8_t)(pixel >> (byte * 8U));
            hash *= UINT64_C(1099511628211);
        }
    }
    return hash;
}

static uint64_t s61_read_ppm_rgb_fnv1a64(const char *save_path)
{
    static const uint8_t header[] = "P6\n240 160\n255\n";
    char path[4096];
    int length = snprintf(path, sizeof(path), "%s.ppm", save_path);
    if (length <= 0 || (size_t)length >= sizeof(path))
        s61_die("framebuffer artifact readback path formatting failed");
    FILE *stream = fopen(path, "rb");
    uint8_t actual_header[sizeof(header) - 1U];
    if (stream == NULL
        || fread(actual_header, 1U, sizeof(actual_header), stream)
            != sizeof(actual_header)
        || memcmp(actual_header, header, sizeof(actual_header)) != 0)
        s61_die("framebuffer artifact readback header differs");
    uint64_t hash = UINT64_C(14695981039346656037);
    size_t remaining = 240U * 160U * 3U;
    uint8_t buffer[4096U];
    while (remaining != 0U) {
        size_t amount = remaining < sizeof(buffer)
            ? remaining : sizeof(buffer);
        if (fread(buffer, 1U, amount, stream) != amount)
            s61_die("framebuffer artifact readback RGB is truncated");
        for (size_t index = 0U; index < amount; ++index) {
            hash ^= buffer[index];
            hash *= UINT64_C(1099511628211);
        }
        remaining -= amount;
    }
    if (fgetc(stream) != EOF || ferror(stream) || fclose(stream) != 0)
        s61_die("framebuffer artifact readback size/close differs");
    return hash;
}

static bool s61_framebuffer_role_is_valid(const char *role)
{
    if (role == NULL || role[0] == '\0')
        return false;
    for (const char *cursor = role; *cursor != '\0'; ++cursor) {
        if (!(*cursor == '_' || (*cursor >= 'A' && *cursor <= 'Z')
              || (*cursor >= '0' && *cursor <= '9')))
            return false;
    }
    return true;
}

static void s61_write_framebuffer_ppm(const char *save_path,
                                      const color_t *video,
                                      const char *role)
{
    if (s61_artifact_directory == NULL
        || !s61_framebuffer_role_is_valid(role))
        s61_die("framebuffer artifact registry is not initialized");
    size_t directory_size = strlen(s61_artifact_directory);
    if (strncmp(save_path, s61_artifact_directory, directory_size) != 0
        || save_path[directory_size] != '/')
        s61_die("framebuffer artifact path escapes work directory");
    const char *relative_stem = save_path + directory_size + 1U;
    if (relative_stem[0] == '\0' || strstr(relative_stem, "..") != NULL
        || strchr(relative_stem, '\\') != NULL
        || strchr(relative_stem, '"') != NULL)
        s61_die("framebuffer artifact relative path is invalid");
    size_t path_size = strlen(relative_stem) + sizeof(".ppm");
    char *relative_path = malloc(path_size);
    if (relative_path == NULL)
        s61_die("framebuffer artifact path allocation failed");
    int length = snprintf(relative_path, path_size, "%s.ppm", relative_stem);
    if (length <= 0 || (size_t)length >= path_size)
        s61_die("framebuffer artifact path formatting failed");
    for (size_t index = 0U; index < s61_framebuffer_artifact_count; ++index) {
        if (strcmp(s61_framebuffer_artifacts[index].path, relative_path) == 0)
            s61_die("framebuffer artifact path was reused");
    }
    if (s61_framebuffer_artifact_count
            == s61_framebuffer_artifact_capacity) {
        size_t next_capacity = s61_framebuffer_artifact_capacity == 0U
            ? 64U : s61_framebuffer_artifact_capacity * 2U;
        if (next_capacity < s61_framebuffer_artifact_capacity
            || next_capacity > SIZE_MAX / sizeof(*s61_framebuffer_artifacts))
            s61_die("framebuffer artifact registry capacity overflow");
        void *grown = realloc(
            s61_framebuffer_artifacts,
            next_capacity * sizeof(*s61_framebuffer_artifacts));
        if (grown == NULL)
            s61_die("framebuffer artifact registry allocation failed");
        s61_framebuffer_artifacts = grown;
        s61_framebuffer_artifact_capacity = next_capacity;
    }
    uint64_t video_hash = s61_framebuffer_rgb_fnv1a64(video);
    bootstrap_write_ppm(save_path, video);
    uint64_t file_hash = s61_read_ppm_rgb_fnv1a64(save_path);
    if (file_hash != video_hash)
        s61_die("framebuffer artifact RGB differs from captured video");
    s61_framebuffer_artifacts[s61_framebuffer_artifact_count++] =
        (struct S61FramebufferArtifact){
            .path = relative_path,
            .role = role,
            .rgb_fnv1a64 = file_hash,
        };
}

static bool s61_bool_env(const char *name, bool fallback)
{
    const char *text_value = getenv(name);
    if (text_value == NULL || text_value[0] == '\0')
        return fallback;
    if (strcmp(text_value, "1") == 0 || strcmp(text_value, "true") == 0)
        return true;
    if (strcmp(text_value, "0") == 0 || strcmp(text_value, "false") == 0)
        return false;
    s61_die("boolean fixture environment value is invalid");
    return false;
}

static unsigned s61_uint_env(const char *name, unsigned fallback,
                             unsigned maximum)
{
    const char *text_value = getenv(name);
    char *end = NULL;
    unsigned long value;
    if (text_value == NULL || text_value[0] == '\0')
        return fallback;
    errno = 0;
    value = strtoul(text_value, &end, 0);
    if (errno != 0 || end == text_value || *end != '\0' || value > maximum)
        s61_die("numeric fixture environment value is invalid");
    return (unsigned)value;
}

