static uint64_t s61_hash_bytes(const uint8_t *raw, size_t size)
{
    uint64_t hash = UINT64_C(14695981039346656037);
    for (size_t index = 0U; index < size; ++index) {
        hash ^= raw[index];
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}

/* Byte-leaf provenance is emitted in both the runner and independently
 * recomputed by Python before it is admitted to retention. */
static void s61_effect_sha256(const uint8_t *raw, size_t size, char out[65])
{
    uint32_t h[8] = {0x6a09e667U,0xbb67ae85U,0x3c6ef372U,0xa54ff53aU,
                     0x510e527fU,0x9b05688cU,0x1f83d9abU,0x5be0cd19U};
    static const uint32_t k[64] = {
        0x428a2f98U,0x71374491U,0xb5c0fbcfU,0xe9b5dba5U,0x3956c25bU,0x59f111f1U,0x923f82a4U,0xab1c5ed5U,0xd807aa98U,0x12835b01U,0x243185beU,0x550c7dc3U,0x72be5d74U,0x80deb1feU,0x9bdc06a7U,0xc19bf174U,0xe49b69c1U,0xefbe4786U,0x0fc19dc6U,0x240ca1ccU,0x2de92c6fU,0x4a7484aaU,0x5cb0a9dcU,0x76f988daU,0x983e5152U,0xa831c66dU,0xb00327c8U,0xbf597fc7U,0xc6e00bf3U,0xd5a79147U,0x06ca6351U,0x14292967U,0x27b70a85U,0x2e1b2138U,0x4d2c6dfcU,0x53380d13U,0x650a7354U,0x766a0abbU,0x81c2c92eU,0x92722c85U,0xa2bfe8a1U,0xa81a664bU,0xc24b8b70U,0xc76c51a3U,0xd192e819U,0xd6990624U,0xf40e3585U,0x106aa070U,0x19a4c116U,0x1e376c08U,0x2748774cU,0x34b0bcb5U,0x391c0cb3U,0x4ed8aa4aU,0x5b9cca4fU,0x682e6ff3U,0x748f82eeU,0x78a5636fU,0x84c87814U,0x8cc70208U,0x90befffaU,0xa4506cebU,0xbef9a3f7U,0xc67178f2U};
    uint64_t bits = (uint64_t)size * 8U;
    size_t padded = size + 1U;
    while (padded % 64U != 56U) ++padded;
    uint8_t *m = calloc(padded + 8U, 1U);
    if (m == NULL) s61_die("effect observer SHA allocation failed");
    if (size != 0U) memcpy(m, raw, size);
    m[size] = 0x80U;
    for (unsigned i = 0U; i < 8U; ++i) m[padded + i] = (uint8_t)(bits >> (56U - i * 8U));
    for (size_t off = 0U; off < padded + 8U; off += 64U) {
        uint32_t w[64];
        for (unsigned i = 0U; i < 16U; ++i) w[i] = ((uint32_t)m[off+i*4U]<<24U)|((uint32_t)m[off+i*4U+1U]<<16U)|((uint32_t)m[off+i*4U+2U]<<8U)|m[off+i*4U+3U];
        for (unsigned i = 16U; i < 64U; ++i) { uint32_t a=w[i-15U],b=w[i-2U]; uint32_t s0=((a>>7U)|(a<<25U))^((a>>18U)|(a<<14U))^(a>>3U), s1=((b>>17U)|(b<<15U))^((b>>19U)|(b<<13U))^(b>>10U); w[i]=w[i-16U]+s0+w[i-7U]+s1; }
        uint32_t a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],z=h[7];
        for (unsigned i = 0U; i < 64U; ++i) { uint32_t s1=((e>>6U)|(e<<26U))^((e>>11U)|(e<<21U))^((e>>25U)|(e<<7U)), t1=z+s1+((e&f)^((~e)&g))+k[i]+w[i], s0=((a>>2U)|(a<<30U))^((a>>13U)|(a<<19U))^((a>>22U)|(a<<10U)), t2=s0+((a&b)^(a&c)^(b&c)); z=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2; }
        h[0]+=a;h[1]+=b;h[2]+=c;h[3]+=d;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=z;
    }
    free(m);
    for (unsigned i = 0U; i < 8U; ++i) (void)snprintf(out+i*8U,9U,"%08" PRIx32,h[i]);
}

/*
 * Raw effect observer
 * -------------------
 * The Python parent validates and binds every semantic expectation.  This
 * runner intentionally receives only a TSV of byte ranges, program counters
 * and register capture locations.  It consequently cannot manufacture a
 * case/owner/effect result from a semantic label.  The existing mGBA
 * instruction-step harness is used instead of frame-PC sampling: hook rows
 * are architectural instruction addresses and are recorded only while a real
 * input case has armed the observer immediately before its producer input.
 */
enum {
    S61_EFFECT_MAX_WATCHES = 512U,
    S61_EFFECT_MAX_CASE_ID = 1024U,
    S61_EFFECT_MAX_WATCH_ID = 112U,
    S61_EFFECT_MAX_HOOKS = 131072U,
    S61_EFFECT_MAX_CAPTURES = 8U,
};

struct S61EffectCapture {
    unsigned ordinal;
    char phase[16];
    char location[32];
    unsigned width_bits;
    char capture[16];
    uint32_t pointee_length;
    bool stack_location;
    uint32_t stack_offset;
};

enum S61EffectResolverKind {
    S61_EFFECT_NONE,
    S61_EFFECT_ABSOLUTE,
    S61_EFFECT_U32_POINTER,
    S61_EFFECT_U32_CODE_POINTER_AT,
    S61_EFFECT_SCRIPT_CURSOR_DISPATCH,
};

struct S61EffectWatch {
    char watch_id[S61_EFFECT_MAX_WATCH_ID];
    enum S61EffectResolverKind resolver;
    uint32_t address;
    uint32_t pointer_address;
    uint32_t offset;
    uint32_t address_min;
    uint32_t address_max_exclusive;
    uint32_t pointer_slot;
    uint32_t length;
    uint32_t hook_pc;
    uint32_t resolved_hook_pc;
    bool target_thumb;
    bool breakpoint_set;
    ssize_t breakpoint_id;
    uint8_t *before;
    uint64_t before_hash;
    uint32_t before_address;
    struct S61EffectCapture captures[S61_EFFECT_MAX_CAPTURES];
    unsigned capture_count;
    uint32_t script_context_address;
    uint32_t script_cursor_offset;
    char completion_boundary[32];
    unsigned hook_hits;
};

struct S61EffectObserver {
    bool enabled;
    struct mCore *core;
    struct mDebugger *debugger;
    char output[4096];
    char active_case[S61_EFFECT_MAX_CASE_ID];
    struct S61EffectWatch watches[S61_EFFECT_MAX_WATCHES];
    unsigned watch_count;
    uint64_t ordinal;
    struct {
        unsigned watch_index;
        uint64_t hook_ordinal;
        uint32_t return_pc;
        uint32_t entry_sp;
    } returns[S61_EFFECT_MAX_HOOKS];
    unsigned return_count;
};

static struct S61EffectObserver s61_effect_observer;

static const char S61_EFFECT_RAW_WATCH_HEADER[] =
    "watch_index\twatch_id\tresolver_kind\tspace\taddress\t"
    "pointer_address\toffset\taddress_min\taddress_max_exclusive\t"
    "pointer_slot\ttarget_thumb\tlength\thook_pc\tcompletion_boundary\t"
    "script_context_address\tscript_cursor_offset\topcode_load_pc\t"
    "opcode_load_raw_hex\thook_raw_hex\thandler_table_start_offset\t"
    "handler_table_end_offset\targ_capture";

static uint32_t s61_effect_parse_u32(const char *value, const char *label,
                                     bool allow_dash)
{
    if (value == NULL || value[0] == '\0'
        || (allow_dash && strcmp(value, "-") == 0))
        return 0U;
    char *end = NULL;
    errno = 0;
    unsigned long parsed = strtoul(value, &end, 0);
    if (errno != 0 || end == value || *end != '\0'
        || parsed > UINT32_MAX) {
        fprintf(stderr, "effect observer invalid %s: %s\n", label, value);
        s61_die("effect observer TSV整数が不正");
    }
    return (uint32_t)parsed;
}

static enum S61EffectResolverKind s61_effect_resolver(const char *value)
{
    if (strcmp(value, "NONE") == 0)
        return S61_EFFECT_NONE;
    if (strcmp(value, "ABSOLUTE") == 0)
        return S61_EFFECT_ABSOLUTE;
    if (strcmp(value, "U32_POINTER") == 0)
        return S61_EFFECT_U32_POINTER;
    if (strcmp(value, "U32_CODE_POINTER_AT") == 0)
        return S61_EFFECT_U32_CODE_POINTER_AT;
    if (strcmp(value, "SCRIPT_CURSOR_DISPATCH") == 0)
        return S61_EFFECT_SCRIPT_CURSOR_DISPATCH;
    s61_die("effect observer resolver kindが未知");
    return S61_EFFECT_NONE;
}

static bool s61_effect_parse_stack_location(const char *location,
                                            uint32_t *offset)
{
    static const char prefix[] = "STACK+";
    if (strncmp(location, prefix, sizeof(prefix) - 1U) != 0)
        return false;
    const char *digits = location + sizeof(prefix) - 1U;
    if (*digits == '\0')
        s61_die("effect observer STACK capture offsetが空です");
    uint32_t parsed = 0U;
    for (const unsigned char *cursor = (const unsigned char *)digits;
         *cursor != '\0'; ++cursor) {
        if (!isdigit(*cursor))
            s61_die("effect observer STACK capture offsetが不正です");
        uint32_t digit = (uint32_t)(*cursor - (unsigned char)'0');
        if (parsed > (UINT32_MAX - digit) / 10U)
            s61_die("effect observer STACK capture offsetが範囲外です");
        parsed = parsed * 10U + digit;
    }
    if (offset != NULL)
        *offset = parsed;
    return true;
}

static bool s61_effect_capture_phase_present(
    const struct S61EffectWatch *watch, const char *phase)
{
    for (unsigned index = 0U; index < watch->capture_count; ++index)
        if (strcmp(watch->captures[index].phase, phase) == 0)
            return true;
    return false;
}

static void s61_effect_parse_captures(struct S61EffectWatch *watch,
                                      const char *raw)
{
    if (strcmp(raw, "-") == 0)
        return;
    char buffer[1024];
    if (strlen(raw) >= sizeof(buffer))
        s61_die("effect observer capture TSVが長すぎます");
    memcpy(buffer, raw, strlen(raw) + 1U);
    char *entry = buffer;
    while (entry != NULL) {
        char *next = strchr(entry, '|');
        if (next != NULL) *next++ = '\0';
        if (watch->capture_count >= S61_EFFECT_MAX_CAPTURES)
            s61_die("effect observer capture数が多すぎます");
        char *parts[6] = {0};
        unsigned count = 0U;
        char *cursor = entry;
        while (count < 6U) {
            parts[count++] = cursor;
            char *comma = strchr(cursor, ',');
            if (comma == NULL)
                break;
            *comma = '\0';
            cursor = comma + 1U;
        }
        if (count != 6U || strchr(cursor, ',') != NULL)
            s61_die("effect observer capture field数が不正");
        struct S61EffectCapture *capture =
            &watch->captures[watch->capture_count++];
        capture->ordinal = s61_effect_parse_u32(
            parts[0], "capture ordinal", false);
        uint32_t stack_offset = 0U;
        bool stack_location = s61_effect_parse_stack_location(
            parts[2], &stack_offset);
        bool register_location = strcmp(parts[2], "R0") == 0
            || strcmp(parts[2], "R1") == 0
            || strcmp(parts[2], "R2") == 0
            || strcmp(parts[2], "R3") == 0
            || strcmp(parts[2], "LR") == 0;
        if (capture->ordinal + 1U != watch->capture_count
            || (strcmp(parts[1], "ENTRY") != 0 && strcmp(parts[1], "RETURN") != 0)
            || (!register_location && !stack_location)
            || (strcmp(parts[1], "RETURN") == 0
                && strcmp(parts[2], "R0") != 0)
            || (strcmp(parts[3], "8") != 0 && strcmp(parts[3], "16") != 0
                && strcmp(parts[3], "32") != 0)
            || (strcmp(parts[4], "VALUE") != 0 && strcmp(parts[4], "POINTER_BYTES") != 0))
            s61_die("effect observer capture schemaが不正");
        memcpy(capture->phase, parts[1], strlen(parts[1]) + 1U);
        memcpy(capture->location, parts[2], strlen(parts[2]) + 1U);
        capture->width_bits = s61_effect_parse_u32(parts[3], "capture width", false);
        memcpy(capture->capture, parts[4], strlen(parts[4]) + 1U);
        capture->pointee_length = s61_effect_parse_u32(parts[5], "capture pointee", false);
        capture->stack_location = stack_location;
        capture->stack_offset = stack_offset;
        if ((strcmp(capture->capture, "VALUE") == 0 && capture->pointee_length != 0U)
            || (strcmp(capture->capture, "POINTER_BYTES") == 0
                && (capture->width_bits != 32U
                    || capture->pointee_length == 0U
                    || capture->pointee_length > 0x20000U))
            || (strcmp(capture->location, "LR") == 0
                && (strcmp(capture->phase, "ENTRY") != 0
                    || capture->width_bits != 32U
                    || strcmp(capture->capture, "VALUE") != 0)))
            s61_die("effect observer capture width/pointeeが不正");
        entry = next;
    }
    unsigned entry_lr_count = 0U;
    unsigned return_count = 0U;
    for (unsigned index = 0U; index < watch->capture_count; ++index) {
        const struct S61EffectCapture *capture = &watch->captures[index];
        if (strcmp(capture->phase, "ENTRY") == 0
            && strcmp(capture->location, "LR") == 0)
            ++entry_lr_count;
        if (strcmp(capture->phase, "RETURN") == 0)
            ++return_count;
    }
    if (entry_lr_count > 1U
        || ((entry_lr_count == 1U) != (return_count != 0U)))
        s61_die("effect observer LR/RETURN capture組が不正");
}

static bool s61_effect_span_within(uint32_t address, uint32_t length,
                                   uint32_t lower, uint32_t upper)
{
    return length != 0U && address >= lower && address < upper
        && length <= upper - address;
}

static bool s61_effect_readable_span(uint32_t address, uint32_t length)
{
    return s61_effect_span_within(
               address, length, 0x02000000U, 0x02040000U)
        || s61_effect_span_within(
               address, length, 0x03000000U, 0x03008000U)
        || s61_effect_span_within(
               address, length, 0x05000000U, 0x05000400U)
        || s61_effect_span_within(
               address, length, 0x06000000U, 0x06018000U)
        || s61_effect_span_within(
               address, length, 0x07000000U, 0x07000400U)
        || s61_effect_span_within(
               address, length, 0x08000000U, 0x0A000000U)
        || s61_effect_span_within(
               address, length, 0x0E000000U, 0x0E020000U);
}

static bool s61_effect_stack_span(uint32_t address, uint32_t length)
{
    return s61_effect_span_within(
               address, length, 0x02000000U, 0x02040000U)
        || s61_effect_span_within(
               address, length, 0x03000000U, 0x03008000U);
}

static uint32_t s61_effect_capture_value(
    struct mCore *core, const struct S61EffectCapture *capture)
{
    if (capture->stack_location) {
        uint32_t sp = (uint32_t)read_register(core, "sp");
        uint32_t byte_count = capture->width_bits / 8U;
        if (capture->stack_offset > UINT32_MAX - sp
            || !s61_effect_stack_span(
                sp + capture->stack_offset, byte_count))
            s61_die("effect observer STACK capture addressが不正");
        uint32_t value = 0U;
        for (uint32_t index = 0U; index < byte_count; ++index)
            value |= (uint32_t)read8(
                core, sp + capture->stack_offset + index) << (index * 8U);
        return value;
    }
    const char *name = strcmp(capture->location, "R0") == 0 ? "r0"
        : strcmp(capture->location, "R1") == 0 ? "r1"
        : strcmp(capture->location, "R2") == 0 ? "r2"
        : strcmp(capture->location, "R3") == 0 ? "r3"
        : strcmp(capture->location, "LR") == 0 ? "lr" : NULL;
    if (name == NULL)
        s61_die("effect observer capture registerが不正");
    return (uint32_t)read_register(core, name);
}

static bool s61_effect_read_range(struct mCore *core,
                                  const struct S61EffectWatch *watch,
                                  uint8_t *destination,
                                  uint32_t *resolved_address)
{
    if (watch->length == 0U) {
        if (resolved_address != NULL)
            *resolved_address = 0U;
        return true;
    }
    uint32_t address = 0U;
    if (watch->resolver == S61_EFFECT_ABSOLUTE) {
        address = watch->address;
        if (!s61_effect_readable_span(address, watch->length))
            return false;
    } else if (watch->resolver == S61_EFFECT_U32_POINTER) {
        if (!s61_effect_readable_span(watch->pointer_address, 4U)
            || watch->address_min >= watch->address_max_exclusive
            || !s61_effect_readable_span(
                watch->address_min,
                watch->address_max_exclusive - watch->address_min))
            return false;
        uint32_t pointer = read32(core, watch->pointer_address);
        if (pointer < watch->address_min
            || pointer >= watch->address_max_exclusive
            || watch->offset > watch->address_max_exclusive - pointer
            || watch->length > watch->address_max_exclusive - pointer
                                - watch->offset)
            return false;
        address = pointer + watch->offset;
        if (!s61_effect_readable_span(address, watch->length))
            return false;
    } else if (watch->resolver == S61_EFFECT_U32_CODE_POINTER_AT) {
        if (!s61_effect_readable_span(watch->pointer_slot, 4U))
            return false;
        uint32_t pointer = read32(core, watch->pointer_slot);
        if (!watch->target_thumb || !(pointer & 1U))
            return false;
        address = pointer & ~1U;
        if (address < 0x08000000U || address > 0x0A000000U - watch->length)
            return false;
    } else {
        return false;
    }
    for (uint32_t index = 0U; index < watch->length; ++index)
        destination[index] = read8(core, address + index);
    if (resolved_address != NULL)
        *resolved_address = address;
    return true;
}

static void s61_effect_write_binary(const char *case_id,
                                    const struct S61EffectWatch *watch,
                                    const char *suffix, const uint8_t *raw,
                                    char relative[4096])
{
    if (watch->length == 0U) {
        relative[0] = '\0';
        return;
    }
    char directory[4096];
    const char *slash = strrchr(s61_effect_observer.output, '/');
    if (slash == NULL || (size_t)(slash - s61_effect_observer.output)
                            >= sizeof(directory))
        s61_die("effect observer output pathが不正");
    size_t directory_size = (size_t)(slash - s61_effect_observer.output);
    memcpy(directory, s61_effect_observer.output, directory_size);
    directory[directory_size] = '\0';
    char effects_directory[4096];
    int effects_made = snprintf(effects_directory, sizeof(effects_directory),
                                "%s/effects", directory);
    if (effects_made <= 0 || (size_t)effects_made >= sizeof(effects_directory)
        || (mkdir(effects_directory, 0700) != 0 && errno != EEXIST))
        s61_die("effect observer artifact directoryを作れません");
    char case_directory[4096];
    int made = snprintf(case_directory, sizeof(case_directory),
                        "%s/%s", effects_directory, case_id);
    if (made <= 0 || (size_t)made >= sizeof(case_directory)
        || (mkdir(case_directory, 0700) != 0 && errno != EEXIST))
        s61_die("effect observer case artifact directoryを作れません");
    char path[4096];
    int size = snprintf(path, sizeof(path), "%s/effect-%s-%s.bin",
                        case_directory, watch->watch_id, suffix);
    if (size <= 0 || (size_t)size >= sizeof(path))
        s61_die("effect observer raw artifact pathが長すぎます");
    FILE *stream = fopen(path, "wb");
    if (stream == NULL || fwrite(raw, 1U, watch->length, stream)
        != watch->length || fclose(stream) != 0)
        s61_die("effect observer raw artifactを書けません");
    int rel_size = snprintf(relative, 4096, "effects/%s/effect-%s-%s.bin",
                            case_id, watch->watch_id, suffix);
    if (rel_size <= 0 || rel_size >= 4096)
        s61_die("effect observer raw artifact relative pathが長すぎます");
}

static uint64_t s61_effect_next_ordinal(void)
{
    if (++s61_effect_observer.ordinal > S61_EFFECT_MAX_HOOKS)
        s61_die("effect observer event上限を超えました");
    return s61_effect_observer.ordinal;
}

static int s61_effect_emit_captures(
    FILE *stream, struct mCore *core, const struct S61EffectWatch *watch,
    const char *phase, uint64_t event_ordinal)
{
    unsigned emitted = 0U;
    for (unsigned index = 0U; index < watch->capture_count; ++index) {
        const struct S61EffectCapture *capture = &watch->captures[index];
        if (strcmp(capture->phase, phase) != 0)
            continue;
        uint32_t value = s61_effect_capture_value(core, capture);
        uint32_t masked = capture->width_bits == 32U ? value
            : value & ((1U << capture->width_bits) - 1U);
        int written = 0;
        if (strcmp(capture->capture, "VALUE") == 0) {
            written = fprintf(stream,
                "%s{\"ordinal\":%u,\"location\":\"%s\","
                "\"width_bits\":%u,\"capture\":\"%s\","
                "\"value\":\"0x%08" PRIX32 "\"}",
                emitted == 0U ? "" : ",", capture->ordinal,
                capture->location, capture->width_bits, capture->capture,
                masked);
        } else {
            if (!s61_effect_readable_span(value, capture->pointee_length))
                s61_die("effect observer pointer capture addressが不正");
            uint8_t *bytes = malloc(capture->pointee_length);
            char suffix[64], pointer_path[4096], pointer_sha[65];
            if (bytes == NULL)
                s61_die("effect observer pointer capture allocation failed");
            for (uint32_t offset = 0U; offset < capture->pointee_length;
                 ++offset)
                bytes[offset] = read8(core, value + offset);
            int suffix_size = snprintf(
                suffix, sizeof(suffix), "hook-%" PRIu64 "-capture-%u",
                event_ordinal, capture->ordinal);
            if (suffix_size <= 0
                || (size_t)suffix_size >= sizeof(suffix))
                s61_die("effect observer pointer capture suffix不正");
            struct S61EffectWatch mirror = *watch;
            mirror.length = capture->pointee_length;
            s61_effect_write_binary(
                s61_effect_observer.active_case, &mirror, suffix, bytes,
                pointer_path);
            s61_effect_sha256(
                bytes, capture->pointee_length, pointer_sha);
            written = fprintf(stream,
                "%s{\"ordinal\":%u,\"location\":\"%s\","
                "\"width_bits\":%u,\"capture\":\"POINTER_BYTES\","
                "\"value\":\"0x%08" PRIX32 "\",\"pointee\":{"
                "\"path\":\"%s\",\"sha256\":\"%s\","
                "\"size\":%" PRIu32 "}}",
                emitted == 0U ? "" : ",", capture->ordinal,
                capture->location, capture->width_bits, masked,
                pointer_path, pointer_sha, capture->pointee_length);
            free(bytes);
        }
        if (written < 0)
            return -1;
        ++emitted;
    }
    return 0;
}

static uint64_t s61_effect_emit_entry_hook(
    struct mCore *core, struct S61EffectWatch *watch, uint32_t raw_pc)
{
    uint64_t ordinal = s61_effect_next_ordinal();
    ++watch->hook_hits;
    FILE *stream = fopen(s61_effect_observer.output, "ab");
    if (stream == NULL)
        s61_die("effect observer JSONLを開けません");
    int written = fprintf(stream,
        "{\"kind\":\"HOOK\",\"case_id\":\"%s\","
        "\"watch_id\":\"%s\",\"ordinal\":%" PRIu64 ","
        "\"pc\":\"0x%08" PRIX32 "\",\"lr\":\"0x%08" PRIX32 "\","
        "\"r0\":\"0x%08" PRIX32 "\",\"r1\":\"0x%08" PRIX32 "\","
        "\"r2\":\"0x%08" PRIX32 "\",\"r3\":\"0x%08" PRIX32 "\","
        "\"raw_pc\":\"0x%08" PRIX32
        "\",\"capture_phase\":\"ENTRY\",\"captures\":[",
        s61_effect_observer.active_case, watch->watch_id, ordinal,
        watch->resolved_hook_pc, (uint32_t)read_register(core, "lr"),
        (uint32_t)read_register(core, "r0"),
        (uint32_t)read_register(core, "r1"),
        (uint32_t)read_register(core, "r2"),
        (uint32_t)read_register(core, "r3"), raw_pc);
    if (written >= 0)
        written = s61_effect_emit_captures(
            stream, core, watch, "ENTRY", ordinal);
    if (written >= 0
        && watch->resolver == S61_EFFECT_SCRIPT_CURSOR_DISPATCH) {
        if (watch->script_cursor_offset > UINT32_MAX
                - watch->script_context_address
            || !s61_effect_readable_span(
                watch->script_context_address
                    + watch->script_cursor_offset,
                4U))
            s61_die("effect observer SCRIPT context cursorが不正");
        uint32_t context_cursor = read32(
            core, watch->script_context_address
                      + watch->script_cursor_offset);
        written = fprintf(stream,
            "],\"script\":{\"context_cursor\":\"0x%08" PRIX32
            "\",\"opcode\":\"0x%02" PRIX32
            "\",\"cursor\":\"0x%08" PRIX32 "\"}}\n",
            context_cursor,
            (uint32_t)read_register(core, "r1") & 0xFFU,
            (uint32_t)read_register(core, "r2"));
    } else if (written >= 0) {
        written = fputs("]}\n", stream);
    }
    if (written < 0 || fclose(stream) != 0)
        s61_die("effect observer JSONL entry hookを書けません");
    return ordinal;
}

static void s61_effect_emit_return(
    struct mCore *core, const struct S61EffectWatch *watch,
    uint64_t entry_ordinal, uint32_t instruction_pc, uint32_t raw_pc)
{
    uint64_t ordinal = s61_effect_next_ordinal();
    FILE *stream = fopen(s61_effect_observer.output, "ab");
    if (stream == NULL)
        s61_die("effect observer JSONLを開けません");
    int written = fprintf(stream,
        "{\"kind\":\"RETURN\",\"case_id\":\"%s\","
        "\"watch_id\":\"%s\",\"ordinal\":%" PRIu64 ","
        "\"entry_ordinal\":%" PRIu64 ","
        "\"pc\":\"0x%08" PRIX32 "\",\"lr\":\"0x%08" PRIX32 "\","
        "\"r0\":\"0x%08" PRIX32 "\",\"r1\":\"0x%08" PRIX32 "\","
        "\"r2\":\"0x%08" PRIX32 "\",\"r3\":\"0x%08" PRIX32 "\","
        "\"raw_pc\":\"0x%08" PRIX32
        "\",\"capture_phase\":\"RETURN\",\"captures\":[",
        s61_effect_observer.active_case, watch->watch_id, ordinal,
        entry_ordinal, instruction_pc,
        (uint32_t)read_register(core, "lr"),
        (uint32_t)read_register(core, "r0"),
        (uint32_t)read_register(core, "r1"),
        (uint32_t)read_register(core, "r2"),
        (uint32_t)read_register(core, "r3"), raw_pc);
    if (written >= 0)
        written = s61_effect_emit_captures(
            stream, core, watch, "RETURN", ordinal);
    if (written >= 0)
        written = fputs("]}\n", stream);
    if (written < 0 || fclose(stream) != 0)
        s61_die("effect observer JSONL returnを書けません");
}

static void s61_effect_observer_attach(struct mCore *core)
{
    if (!s61_effect_observer.enabled || core == NULL)
        return;
    if (s61_effect_observer.core != NULL)
        s61_die("effect observer core二重attach");
    /* ``s61_step_capture_frames`` is the already-reviewed instruction-level
     * mGBA execution path for every catalog/event producer.  Sampling there
     * preserves normal timing and avoids debugger pause semantics changing a
     * field-script race. */
    s61_effect_observer.core = core;
}

static void s61_effect_observer_detach(struct mCore *core)
{
    if (!s61_effect_observer.enabled || core == NULL)
        return;
    if (s61_effect_observer.core != core)
        s61_die("effect observer core detach不一致");
    s61_effect_observer.core = NULL;
    s61_effect_observer.debugger = NULL;
}

static bool s61_effect_pending_return_matches(
    unsigned index, uint32_t instruction_pc, uint32_t stack_pointer)
{
    return s61_effect_observer.returns[index].return_pc == instruction_pc
        && s61_effect_observer.returns[index].entry_sp == stack_pointer;
}

static void s61_effect_observer_sample_returns(
    struct mCore *core, uint32_t instruction_pc, uint32_t raw_pc)
{
    uint32_t stack_pointer = (uint32_t)read_register(core, "sp");
    while (s61_effect_observer.return_count != 0U) {
        unsigned top = s61_effect_observer.return_count - 1U;
        if (!s61_effect_pending_return_matches(
                top, instruction_pc, stack_pointer))
            break;
        unsigned watch_index =
            s61_effect_observer.returns[top].watch_index;
        uint64_t hook_ordinal =
            s61_effect_observer.returns[top].hook_ordinal;
        if (watch_index >= s61_effect_observer.watch_count)
            s61_die("effect observer pending return watchが不正");
        --s61_effect_observer.return_count;
        s61_effect_emit_return(
            core, &s61_effect_observer.watches[watch_index],
            hook_ordinal, instruction_pc, raw_pc);
    }
    for (unsigned index = 0U;
         index < s61_effect_observer.return_count; ++index) {
        if (s61_effect_pending_return_matches(
                index, instruction_pc, stack_pointer))
            s61_die("effect observer return nestingが不正");
    }
}

static void s61_effect_observer_emit_entry(
    struct mCore *core, unsigned watch_index, uint32_t raw_pc)
{
    struct S61EffectWatch *watch =
        &s61_effect_observer.watches[watch_index];
    bool tracks_return = s61_effect_capture_phase_present(watch, "RETURN");
    uint32_t link = 0U;
    uint32_t stack_pointer = 0U;
    if (tracks_return) {
        if (watch->resolver == S61_EFFECT_SCRIPT_CURSOR_DISPATCH)
            s61_die("effect observer SCRIPT dispatcher returnは禁止です");
        if (s61_effect_observer.return_count >= S61_EFFECT_MAX_HOOKS)
            s61_die("effect observer pending return上限を超えました");
        link = (uint32_t)read_register(core, "lr");
        stack_pointer = (uint32_t)read_register(core, "sp");
        uint32_t return_pc = link & ~1U;
        if (!(link & 1U) || return_pc < 0x08000000U
            || return_pc >= 0x0A000000U
            || !s61_effect_stack_span(stack_pointer, 4U))
            s61_die("effect observer entry LR/SPが不正");
    }
    uint64_t hook_ordinal =
        s61_effect_emit_entry_hook(core, watch, raw_pc);
    if (tracks_return) {
        unsigned pending = s61_effect_observer.return_count++;
        s61_effect_observer.returns[pending].watch_index = watch_index;
        s61_effect_observer.returns[pending].hook_ordinal = hook_ordinal;
        s61_effect_observer.returns[pending].return_pc = link & ~1U;
        s61_effect_observer.returns[pending].entry_sp = stack_pointer;
    }
}

static void s61_effect_observer_sample_pc(struct mCore *core,
                                          uint32_t raw_pc)
{
    if (!s61_effect_observer.enabled || core != s61_effect_observer.core
        || s61_effect_observer.active_case[0] == '\0')
        return;
    uint32_t instruction_pc = (raw_pc - 4U) & ~1U;
    s61_effect_observer_sample_returns(core, instruction_pc, raw_pc);
    for (unsigned index = 0U; index < s61_effect_observer.watch_count;
         ++index) {
        struct S61EffectWatch *watch = &s61_effect_observer.watches[index];
        if (watch->resolved_hook_pc != 0U
            && watch->resolved_hook_pc == instruction_pc)
            s61_effect_observer_emit_entry(core, index, raw_pc);
    }
}

static uint64_t s61_effect_observer_total_hook_hits(void)
{
    uint64_t total = 0U;
    for (unsigned index = 0U; index < s61_effect_observer.watch_count;
         ++index)
        total += s61_effect_observer.watches[index].hook_hits;
    return total;
}

static void s61_effect_observer_sequence_case_id(
    char *destination, size_t destination_size, const char *source_case_id,
    unsigned sequence_ordinal)
{
    if (destination == NULL || destination_size == 0U
        || source_case_id == NULL || source_case_id[0] == '\0'
        || sequence_ordinal >= 10000U)
        s61_die("effect observer sequence case ID引数が不正");
    int written = snprintf(
        destination, destination_size, "%s--run-%04u", source_case_id,
        sequence_ordinal);
    if (written <= 0 || (size_t)written >= destination_size)
        s61_die("effect observer sequence case IDが長すぎます");
}

static void s61_effect_observer_prepare_watch(
    struct mCore *core, struct S61EffectWatch *watch)
{
    watch->resolved_hook_pc = watch->hook_pc;
    if (watch->resolver != S61_EFFECT_U32_CODE_POINTER_AT)
        return;
    if (!s61_effect_readable_span(watch->pointer_slot, 4U))
        s61_die("effect observer dynamic hook pointer slotが不正");
    uint32_t pointer = read32(core, watch->pointer_slot);
    uint32_t target = pointer & ~1U;
    if (!watch->target_thumb || !(pointer & 1U)
        || !s61_effect_span_within(
            target, watch->length, 0x08000000U, 0x0A000000U))
        s61_die("effect observer dynamic hook targetが不正");
    watch->resolved_hook_pc = target;
}

static void s61_effect_observer_begin_case(struct mCore *core,
                                           const char *case_id)
{
    if (!s61_effect_observer.enabled)
        return;
    if (core != s61_effect_observer.core || case_id == NULL
        || case_id[0] == '\0' || strlen(case_id)
                                  >= sizeof(s61_effect_observer.active_case))
        s61_die("effect observer case開始引数が不正");
    for (const unsigned char *cursor = (const unsigned char *)case_id;
         *cursor != '\0'; ++cursor) {
        if (!isalnum(*cursor) && *cursor != '-' && *cursor != '_'
            && *cursor != '.' && *cursor != ':')
            s61_die("effect observer case artifact pathが不正");
    }
    if (s61_effect_observer.active_case[0] != '\0')
        s61_die("effect observer caseが未完了です");
    if (s61_effect_observer.return_count != 0U)
        s61_die("effect observer begin前pending returnが残っています");
    memcpy(s61_effect_observer.active_case, case_id, strlen(case_id) + 1U);
    s61_effect_observer.ordinal = 0U;
    s61_effect_observer.return_count = 0U;
    for (unsigned index = 0U; index < s61_effect_observer.watch_count;
         ++index) {
        struct S61EffectWatch *watch = &s61_effect_observer.watches[index];
        watch->hook_hits = 0U;
        s61_effect_observer_prepare_watch(core, watch);
        free(watch->before);
        watch->before = NULL;
        watch->before_hash = 0U;
        if (watch->length == 0U)
            continue;
        watch->before = malloc(watch->length);
        if (watch->before == NULL
            || !s61_effect_read_range(core, watch, watch->before,
                                      &watch->before_address))
            s61_die("effect observer pre-input raw snapshot失敗");
        watch->before_hash = s61_hash_bytes(watch->before, watch->length);
    }
}

static void s61_effect_observer_end_case(struct mCore *core)
{
    if (!s61_effect_observer.enabled)
        return;
    if (core != s61_effect_observer.core
        || s61_effect_observer.active_case[0] == '\0')
        s61_die("effect observer case終了引数が不正");
    if (s61_effect_observer.return_count != 0U)
        s61_die("effect observer case終了時に未帰還callがあります");
    FILE *stream = fopen(s61_effect_observer.output, "ab");
    if (stream == NULL)
        s61_die("effect observer JSONLを開けません");
    if (fprintf(stream, "{\"kind\":\"CASE_END\",\"case_id\":\"%s\","
                "\"watch_ids\":[", s61_effect_observer.active_case) < 0)
        s61_die("effect observer CASE headerを書けません");
    for (unsigned index = 0U; index < s61_effect_observer.watch_count;
         ++index)
        if (fprintf(stream, "%s\"%s\"", index == 0U ? "" : ",",
                    s61_effect_observer.watches[index].watch_id) < 0)
            s61_die("effect observer CASE watchを書けません");
    if (fputs("],\"raw\":{", stream) == EOF)
        s61_die("effect observer CASE raw headerを書けません");
    for (unsigned index = 0U; index < s61_effect_observer.watch_count;
         ++index) {
        struct S61EffectWatch *watch = &s61_effect_observer.watches[index];
        uint8_t *after = NULL;
        uint64_t after_hash = 0U;
        uint32_t after_address = 0U;
        char before_path[4096], after_path[4096], transition_path[4096];
        char before_sha[65] = "", after_sha[65] = "", transition_sha[65] = "";
        before_path[0] = after_path[0] = transition_path[0] = '\0';
        if (watch->length != 0U) {
            after = malloc(watch->length);
            if (after == NULL || !s61_effect_read_range(core, watch, after,
                                                        &after_address))
                s61_die("effect observer post-input raw snapshot失敗");
            after_hash = s61_hash_bytes(after, watch->length);
            s61_effect_sha256(watch->before, watch->length, before_sha);
            s61_effect_sha256(after, watch->length, after_sha);
            s61_effect_write_binary(s61_effect_observer.active_case, watch,
                                    "before", watch->before, before_path);
            s61_effect_write_binary(s61_effect_observer.active_case, watch,
                                    "after", after, after_path);
            if (after_hash != watch->before_hash) {
                s61_effect_write_binary(s61_effect_observer.active_case, watch,
                                        "transition-1", after, transition_path);
                s61_effect_sha256(after, watch->length, transition_sha);
            }
        }
        int raw_written = transition_path[0] == '\0'
            ? fprintf(stream, "%s\"%s\":{\"before_fnv1a64\":\"%016" PRIX64 "\",\"after_fnv1a64\":\"%016" PRIX64 "\",\"length\":%" PRIu32 ",\"before\":{\"path\":\"%s\",\"sha256\":\"%s\",\"address\":\"0x%08" PRIX32 "\"},\"after\":{\"path\":\"%s\",\"sha256\":\"%s\",\"address\":\"0x%08" PRIX32 "\"},\"transition\":null,\"completion\":{\"boundary\":\"%s\",\"ordinal\":%" PRIu64 "}}", index == 0U ? "" : ",", watch->watch_id, watch->before_hash, after_hash, watch->length, before_path, before_sha, watch->before_address, after_path, after_sha, after_address, watch->completion_boundary, s61_effect_observer.ordinal)
            : fprintf(stream, "%s\"%s\":{\"before_fnv1a64\":\"%016" PRIX64 "\",\"after_fnv1a64\":\"%016" PRIX64 "\",\"length\":%" PRIu32 ",\"before\":{\"path\":\"%s\",\"sha256\":\"%s\",\"address\":\"0x%08" PRIX32 "\"},\"after\":{\"path\":\"%s\",\"sha256\":\"%s\",\"address\":\"0x%08" PRIX32 "\"},\"transition\":{\"path\":\"%s\",\"sha256\":\"%s\"},\"completion\":{\"boundary\":\"%s\",\"ordinal\":%" PRIu64 "}}", index == 0U ? "" : ",", watch->watch_id, watch->before_hash, after_hash, watch->length, before_path, before_sha, watch->before_address, after_path, after_sha, after_address, transition_path, transition_sha, watch->completion_boundary, s61_effect_observer.ordinal);
        if (raw_written < 0)
            s61_die("effect observer CASE rawを書けません");
        free(after);
        free(watch->before);
        watch->before = NULL;
    }
    if (fputs("},\"hook_hits\":{", stream) == EOF)
        s61_die("effect observer CASE hook headerを書けません");
    for (unsigned index = 0U; index < s61_effect_observer.watch_count;
         ++index)
        if (fprintf(stream, "%s\"%s\":%u", index == 0U ? "" : ",",
                    s61_effect_observer.watches[index].watch_id,
                    s61_effect_observer.watches[index].hook_hits) < 0)
            s61_die("effect observer CASE hookを書けません");
    if (fputs("}}\n", stream) == EOF || fclose(stream) != 0)
        s61_die("effect observer CASEを書けません");
    s61_effect_observer.active_case[0] = '\0';
}

static void s61_effect_observer_load(void)
{
    const char *path = getenv("S61_EFFECT_RAW_WATCH_TSV");
    if (path == NULL || path[0] == '\0')
        return;
    const char *output = getenv("S61_EFFECT_OBSERVER_OUTPUT");
    if (output == NULL || output[0] != '/' || strlen(output)
                                           >= sizeof(s61_effect_observer.output))
        s61_die("effect observer output absolute pathが必要です");
    FILE *stream = fopen(path, "rb");
    if (stream == NULL)
        s61_die("effect observer TSVを開けません");
    char line[16384];
    if (fgets(line, sizeof(line), stream) == NULL)
        s61_die("effect observer TSVが空です");
    line[strcspn(line, "\r\n")] = '\0';
    if (strcmp(line, S61_EFFECT_RAW_WATCH_HEADER) != 0)
        s61_die("effect observer TSV header不一致");
    memcpy(s61_effect_observer.output, output, strlen(output) + 1U);
    while (fgets(line, sizeof(line), stream) != NULL) {
        if (strchr(line, '\n') == NULL && !feof(stream))
            s61_die("effect observer TSV rowが長すぎます");
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0'
            || s61_effect_observer.watch_count >= S61_EFFECT_MAX_WATCHES)
            s61_die("effect observer TSV row数が不正");
        char *fields[22] = {0};
        unsigned fields_count = 0U;
        char *cursor = line;
        while (fields_count < 22U) {
            fields[fields_count++] = cursor;
            char *tab = strchr(cursor, '\t');
            if (tab == NULL)
                break;
            *tab = '\0';
            cursor = tab + 1U;
        }
        if (fields_count != 22U || strchr(cursor, '\t') != NULL
            || fields[1][0] == '\0'
            || strlen(fields[1]) >= S61_EFFECT_MAX_WATCH_ID
            || (strcmp(fields[10], "-") != 0
                && strcmp(fields[10], "0") != 0
                && strcmp(fields[10], "1") != 0))
            s61_die("effect observer TSV field数/IDが不正");
        uint32_t declared_index = s61_effect_parse_u32(
            fields[0], "watch_index", false);
        if (declared_index != s61_effect_observer.watch_count)
            s61_die("effect observer TSV watch_index順が不正");
        for (unsigned index = 0U;
             index < s61_effect_observer.watch_count; ++index)
            if (strcmp(
                    fields[1],
                    s61_effect_observer.watches[index].watch_id) == 0)
                s61_die("effect observer TSV watch IDが重複");
        struct S61EffectWatch *watch =
            &s61_effect_observer.watches[s61_effect_observer.watch_count++];
        memset(watch, 0, sizeof(*watch));
        memcpy(watch->watch_id, fields[1], strlen(fields[1]) + 1U);
        watch->resolver = s61_effect_resolver(fields[2]);
        watch->address = s61_effect_parse_u32(fields[4], "address", true);
        watch->pointer_address = s61_effect_parse_u32(
            fields[5], "pointer_address", true);
        watch->offset = s61_effect_parse_u32(fields[6], "offset", true);
        watch->address_min = s61_effect_parse_u32(
            fields[7], "address_min", true);
        watch->address_max_exclusive = s61_effect_parse_u32(
            fields[8], "address_max_exclusive", true);
        watch->pointer_slot = s61_effect_parse_u32(
            fields[9], "pointer_slot", true);
        watch->target_thumb = strcmp(fields[10], "1") == 0;
        watch->length = s61_effect_parse_u32(fields[11], "length", false);
        watch->hook_pc = s61_effect_parse_u32(fields[12], "hook_pc", true)
            & ~1U;
        if (strlen(fields[13]) >= sizeof(watch->completion_boundary))
            s61_die("effect observer completion boundaryが長すぎます");
        memcpy(watch->completion_boundary, fields[13], strlen(fields[13]) + 1U);
        watch->script_context_address = s61_effect_parse_u32(
            fields[14], "script_context_address", true);
        watch->script_cursor_offset = s61_effect_parse_u32(
            fields[15], "script_cursor_offset", true);
        s61_effect_parse_captures(watch, fields[21]);
        bool has_return =
            s61_effect_capture_phase_present(watch, "RETURN");
        if ((watch->resolver == S61_EFFECT_NONE
             || watch->resolver == S61_EFFECT_SCRIPT_CURSOR_DISPATCH)
            != (watch->length == 0U)
            || (watch->length != 0U && watch->length > 0x20000U)
            || watch->completion_boundary[0] == '\0'
            || (watch->hook_pc != 0U
                && (watch->hook_pc < 0x08000000U
                    || watch->hook_pc >= 0x0A000000U))
            || (watch->capture_count != 0U && watch->hook_pc == 0U
                && watch->resolver != S61_EFFECT_U32_CODE_POINTER_AT)
            || ((watch->resolver == S61_EFFECT_NONE
                 || watch->resolver == S61_EFFECT_SCRIPT_CURSOR_DISPATCH)
                && watch->hook_pc == 0U)
            || (watch->resolver == S61_EFFECT_SCRIPT_CURSOR_DISPATCH
                && has_return)
            || (watch->resolver == S61_EFFECT_U32_CODE_POINTER_AT
                && (!watch->target_thumb || watch->hook_pc != 0U)))
            s61_die("effect observer TSV resolver/lengthが不正");
    }
    if (ferror(stream) || fclose(stream) != 0
        || s61_effect_observer.watch_count == 0U)
        s61_die("effect observer TSV read/close失敗");
    FILE *meta = fopen(s61_effect_observer.output, "wb");
    if (meta == NULL || fprintf(meta,
        "{\"kind\":\"META\",\"watch_count\":%u}\n",
        s61_effect_observer.watch_count) < 0 || fclose(meta) != 0)
        s61_die("effect observer metaを書けません");
    s61_effect_observer.enabled = true;
}

static struct mCore *bootstrap_open_core(const char *rom_path,
                                         const char *save_path,
                                         color_t *video)
{
    struct mCore *core = s61_bootstrap_open_core(rom_path, save_path, video);
    s61_effect_observer_attach(core);
    return core;
}

static void bootstrap_close_core(struct mCore *core)
{
    s61_effect_observer_detach(core);
    s61_bootstrap_close_core(core);
}

static bool s61_saveblock_byte_is_volatile(unsigned block, size_t offset)
{
    /* SaveBlock2's play-time owner advances with emulated VBlanks while an
     * interaction is being rendered.  It is preserved in the raw evidence,
     * but zeroed only for the persistent semantic hash.  No SaveBlock1 byte
     * is implicitly volatile: walking happens before the before-snapshot, so
     * an unlisted story/daycare/berry/stat mutation must remain observable. */
    return block == 2U
        && offset >= S61_SAVE_BLOCK2_PLAY_TIME_START
        && offset < S61_SAVE_BLOCK2_PLAY_TIME_END;
}

static uint64_t s61_hash_saveblock_normalized(
    const uint8_t *raw, size_t size, unsigned block)
{
    uint64_t hash = UINT64_C(14695981039346656037);
    for (size_t index = 0U; index < size; ++index) {
        uint8_t value = s61_saveblock_byte_is_volatile(block, index)
            ? 0U : raw[index];
        hash ^= value;
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}

static bool s61_same_message(const struct S61Message *left,
                             const uint8_t *raw, size_t size)
{
    return left->size == size && memcmp(left->raw, raw, size) == 0;
}

static void s61_capture_var_result(struct S61Capture *capture,
                                   uint16_t var_result)
{
    if (var_result == 0xFFFFU)
        return;
    if (!capture->var_result_seen) {
        capture->var_result_seen = true;
        capture->first_var_result = var_result;
        capture->last_var_result = var_result;
        capture->var_result_values[0] = var_result;
        capture->var_result_value_count = 1U;
    } else if (var_result != capture->last_var_result) {
        if (capture->var_result_value_count >= S61_MAX_VAR_RESULTS)
            s61_die("VAR_RESULT transition count exceeded capture bound");
        capture->last_var_result = var_result;
        capture->var_result_values[capture->var_result_value_count++] =
            var_result;
        ++capture->var_result_changes;
    }
}

static void s61_sample_post_battle_instruction(struct mCore *core)
{
    struct S61PostBattleContinuationResult *result = s61_active_post_battle;
    if (result == NULL || !result->capture_open)
        return;
    bool active = read8(core, WORLD_SCRIPT_CONTEXT1_STATE) == 0U;
    uint32_t pointer = read32(core, WORLD_SCRIPT_CONTEXT1_POINTER);
    if (active && pointer == result->observed_resume_pc
        && (!result->last_context_active
            || result->last_script_pointer != pointer)) {
        ++result->resume_pc_hit_count;
    }
    result->last_context_active = active;
    result->last_script_pointer = pointer;
    s61_capture_var_result(&result->capture,
                           read16(core, WORLD_SPECIAL_RESULT));
}

static void s61_capture_frame(struct mCore *core, struct S61Capture *capture)
{
    uint64_t framebuffer = bootstrap_framebuffer_hash(s61_video);
    unsigned baseline_difference = 0U;
    for (unsigned pixel = 0U; pixel < 240U * 160U; ++pixel) {
        if (capture->baseline[pixel] != s61_video[pixel])
            ++baseline_difference;
    }
    if (baseline_difference > capture->maximum_baseline_pixel_difference) {
        capture->maximum_baseline_pixel_difference = baseline_difference;
        memcpy(capture->maximum_difference_frame, s61_video,
               sizeof(capture->maximum_difference_frame));
    }
    if (capture->first_framebuffer_hash == 0U)
        capture->first_framebuffer_hash = framebuffer;
    capture->last_framebuffer_hash = framebuffer;
    if (capture->previous_valid
        && memcmp(capture->previous, s61_video, sizeof(capture->previous)) != 0)
        ++capture->framebuffer_changes;
    memcpy(capture->previous, s61_video, sizeof(capture->previous));
    capture->previous_valid = true;

    s61_capture_var_result(capture, read16(core, WORLD_SPECIAL_RESULT));

    uint8_t state = read8(core, S61_FIELD_MESSAGE_STATE);
    if (state < 4U)
        ++capture->state_counts[state];
    if (state == 0U)
        return;
    ++capture->active_frames;
    if (capture->suppress_semantic_content)
        return;

    uint8_t raw[S61_MAX_MESSAGE_BYTES];
    size_t size = 0U;
    while (size < sizeof(raw)) {
        raw[size] = read8(core, S61_G_STRING_VAR4 + (uint32_t)size);
        ++size;
        if (raw[size - 1U] == 0xFFU)
            break;
    }
    if (size == sizeof(raw) && raw[size - 1U] != 0xFFU)
        s61_die("gStringVar4 did not terminate within the capture bound");
    if (size == 1U && raw[0] == 0xFFU)
        return;
    for (unsigned index = 0U; index < capture->count; ++index) {
        if (s61_same_message(&capture->messages[index], raw, size))
            return;
    }
    if (capture->count >= S61_MAX_MESSAGES)
        s61_die("message capture count exceeded the fixture bound");
    struct S61Message *message = &capture->messages[capture->count++];
    message->state = state;
    message->size = (uint16_t)size;
    memcpy(message->raw, raw, size);
    message->raw_hash = s61_hash_bytes(raw, size);
    message->framebuffer_hash = framebuffer;
    if (capture->artifact_prefix != NULL
        && capture->artifact_prefix[0] != '\0') {
        char path[4096];
        int length = snprintf(path, sizeof(path), "%s-message-%02u",
                              capture->artifact_prefix, capture->count);
        if (length <= 0 || (size_t)length >= sizeof(path))
            s61_die("message screenshot path formatting failed");
        s61_write_framebuffer_ppm(
            path, s61_video, "DIALOGUE_MESSAGE_FRAME");
    }
}

static void s61_assert_text_printer_preimage(struct mCore *core)
{
    static const uint8_t expected[16U] = {
        0xF0U, 0xB5U, 0x47U, 0x46U, 0x80U, 0xB4U, 0x84U, 0xB0U,
        0x0AU, 0x9CU, 0x0BU, 0x9DU, 0x0CU, 0x9FU, 0x09U, 0x06U,
    };
    for (unsigned index = 0U; index < sizeof(expected); ++index) {
        if (read8(core, S61_ADD_TEXT_PRINTER + index) != expected[index])
            s61_die("AddTextPrinter entry preimage differs");
    }
    static const uint8_t template_expected[16U] = {
        0xF0U, 0xB5U, 0x06U, 0x1CU, 0x94U, 0x46U, 0x09U, 0x06U,
        0x0DU, 0x0EU, 0x03U, 0x48U, 0x00U, 0x68U, 0x00U, 0x28U,
    };
    for (unsigned index = 0U; index < sizeof(template_expected); ++index) {
        if (read8(core, S61_ADD_TEXT_PRINTER_TEMPLATE + index)
                != template_expected[index])
            s61_die("template AddTextPrinter entry preimage differs");
    }
}

static bool s61_thumb_bl_target(struct mCore *core, uint32_t address,
                                uint32_t expected_target)
{
    if ((address & 1U) != 0U || address < 0x08000000U
        || address + 3U >= 0x0A000000U)
        return false;
    uint16_t high = read16(core, address);
    uint16_t low = read16(core, address + 2U);
    if ((high & 0xF800U) != 0xF000U || (low & 0xF800U) != 0xF800U)
        return false;
    int32_t displacement = (int32_t)(
        ((uint32_t)(high & 0x07FFU) << 12U)
        | ((uint32_t)(low & 0x07FFU) << 1U));
    if ((displacement & 0x00400000L) != 0)
        displacement -= 0x00800000L;
    return (uint32_t)(address + 4U + displacement) == expected_target;
}

/* Capture at the direct Thumb BL as well as accepting the callee entry.
 * libmGBA's debugger register may expose an instruction PC, +2, or the
 * architected Thumb pipeline +4 at different stop boundaries.  Decoding
 * the real call instruction makes the ABI capture independent of that
 * representation and binds every row to its exact static caller site. */
static bool s61_text_printer_callsite(struct mCore *core, uint32_t raw_pc,
                                     uint32_t *caller, uint32_t *target)
{
    static const uint32_t deltas[] = {0U, 2U, 4U};
    uint32_t even = raw_pc & ~1U;
    for (unsigned index = 0U;
         index < sizeof(deltas) / sizeof(deltas[0]); ++index) {
        if (even < deltas[index])
            continue;
        uint32_t candidate = even - deltas[index];
        static const uint32_t targets[] = {
            S61_ADD_TEXT_PRINTER, S61_ADD_TEXT_PRINTER_TEMPLATE,
        };
        for (unsigned target_index = 0U;
             target_index < sizeof(targets) / sizeof(targets[0]);
             ++target_index) {
            if (!s61_thumb_bl_target(core, candidate, targets[target_index]))
                continue;
            *caller = candidate;
            *target = targets[target_index];
            return true;
        }
    }
    return false;
}

static void s61_capture_printer_call(struct mCore *core,
                                     struct S61Capture *capture)
{
    uint32_t raw_pc = (uint32_t)read_register(core, "pc");
    uint32_t instruction = (raw_pc - 4U) & ~1U;
    uint32_t caller = 0U;
    uint32_t target = 0U;
    bool at_callsite = s61_text_printer_callsite(
        core, raw_pc, &caller, &target);
    uint32_t even = raw_pc & ~1U;
    if (!at_callsite) {
        static const uint32_t entries[] = {
            S61_ADD_TEXT_PRINTER, S61_ADD_TEXT_PRINTER_TEMPLATE,
        };
        for (unsigned entry_index = 0U;
             entry_index < sizeof(entries) / sizeof(entries[0]);
             ++entry_index) {
            uint32_t entry = entries[entry_index];
            if (instruction == entry || even == entry
                || (raw_pc >= 2U && ((raw_pc - 2U) & ~1U) == entry)) {
                target = entry;
                break;
            }
        }
    }
    bool at_entry = target != 0U;
    if (!at_callsite && !at_entry)
        return;
    if (!at_callsite) {
        uint32_t link = (uint32_t)read_register(core, "lr") & ~1U;
        if (link < 0x08000004U || link > 0x0A000000U)
            s61_die("AddTextPrinter caller LR is outside cartridge ROM");
        caller = link - 4U;
    }
    if (capture->printer_call_count != 0U) {
        const struct S61PrinterCall *previous =
            &capture->printer_calls[capture->printer_call_count - 1U];
        if (previous->instruction_address == target
            && previous->caller_instruction_address == caller
            && previous->frame == core->frameCounter(core))
            return;
    }
    if (capture->printer_call_count >= S61_MAX_PRINTER_CALLS)
        s61_die("AddTextPrinter call count exceeded capture bound");
    struct S61PrinterCall *call =
        &capture->printer_calls[capture->printer_call_count++];
    call->frame = core->frameCounter(core);
    call->instruction_address = target;
    call->caller_instruction_address = caller;
    if (target == S61_ADD_TEXT_PRINTER) {
        call->window = (uint32_t)read_register(core, "r0") & 0xFFU;
        call->font = (uint32_t)read_register(core, "r1") & 0xFFU;
        call->text_pointer = (uint32_t)read_register(core, "r2");
        call->speed = read32(
            core, (uint32_t)read_register(core, "sp") + 4U) & 0xFFU;
    } else {
        uint32_t template = (uint32_t)read_register(core, "r0");
        if (template < 0x02000000U || template + 15U >= 0x03008000U)
            s61_die("template AddTextPrinter owner pointer is invalid");
        call->window = read8(core, template + 4U);
        call->font = read8(core, template + 5U);
        call->text_pointer = read32(core, template);
        call->speed = (uint32_t)read_register(core, "r1") & 0xFFU;
    }
    bool popup_iwram = s61_case_name != NULL
        && strncmp(s61_case_name, "MAP_POPUP_", 10U) == 0
        && call->text_pointer >= S61_MAP_NAME_POPUP_BUFFER_START
        && call->text_pointer < S61_MAP_NAME_POPUP_BUFFER_END;
    bool general_iwram = call->text_pointer >= 0x03000000U
        && call->text_pointer < 0x03008000U;
    if (!((call->text_pointer >= 0x02000000U
           && call->text_pointer < 0x02040000U)
          || general_iwram
          || (call->text_pointer >= 0x08000000U
              && call->text_pointer < 0x0A000000U))) {
        fprintf(stderr,
                "ADD_TEXT_PRINTER_DIAGNOSTIC case=%s raw_pc=%08" PRIX32
                " instruction_pc=%08" PRIX32 " r0=%08" PRIX32
                " r1=%08" PRIX32 " r2=%08" PRIX32 " r3=%08" PRIX32
                " frame=%" PRIu32 "\n",
                s61_case_name != NULL ? s61_case_name : "unknown",
                raw_pc, instruction, call->window, call->font,
                call->text_pointer, call->speed, call->frame);
        s61_die("AddTextPrinter text pointer is outside GBA ROM/EWRAM/IWRAM");
    }
    size_t size = 0U;
    size_t maximum_size = S61_MAX_MESSAGE_BYTES;
    if (popup_iwram)
        maximum_size = S61_MAP_NAME_POPUP_BUFFER_END - call->text_pointer;
    else if (general_iwram
             && 0x03008000U - call->text_pointer < maximum_size)
        maximum_size = 0x03008000U - call->text_pointer;
    while (size < maximum_size) {
        call->raw[size] = read8(
            core, call->text_pointer + (uint32_t)size);
        ++size;
        if (call->raw[size - 1U] == 0xFFU)
            break;
    }
    if (size == maximum_size
        && call->raw[size - 1U] != 0xFFU)
        s61_die("AddTextPrinter text did not terminate within bound");
    call->size = (uint16_t)size;
    call->raw_hash = s61_hash_bytes(call->raw, size);
}

static bool s61_cpu_pc_is_executable(uint32_t raw_pc)
{
    uint32_t pc = raw_pc & ~1U;
    /* Instruction stepping can legitimately observe BIOS code, copied
     * EWRAM/IWRAM helpers (notably flash code), or the 32 MiB ROM.  Every
     * other region is data/I/O and therefore an invalid native target.  This
     * catches corrupt script callnative pointers before they degrade into a
     * generic timeout (for example text bytes decoded as 0x37192311). */
    return pc < 0x00004000U
        || (pc >= 0x02000000U && pc < 0x02040000U)
        || (pc >= 0x03000000U && pc < 0x03008000U)
        || (pc >= 0x08000000U && pc < 0x0A000000U);
}

static bool s61_capture_invalid_control_flow(
    struct mCore *core, struct S61Capture *capture)
{
    uint32_t raw_pc = (uint32_t)read_register(core, "pc");
    if (s61_cpu_pc_is_executable(raw_pc))
        return false;
    if (!capture->invalid_control_flow) {
        capture->invalid_control_flow = true;
        capture->invalid_pc = raw_pc;
        capture->invalid_cpsr = (uint32_t)read_register(core, "cpsr");
        capture->invalid_lr = (uint32_t)read_register(core, "lr");
        fprintf(stderr,
                "stage61-invalid-control-flow case=%s pc=%08" PRIX32
                " cpsr=%08" PRIX32 " lr=%08" PRIX32
                " callback=%08" PRIX32 " lock=%u message_state=%u\n",
                s61_case_name != NULL ? s61_case_name : "unknown",
                capture->invalid_pc, capture->invalid_cpsr,
                capture->invalid_lr,
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                world_script_enabled(core),
                read8(core, S61_FIELD_MESSAGE_STATE));
    }
    return true;
}

static void s61_stale_runtime_diag_begin(struct mCore *core)
{
    struct S61StaleRuntimeDiagnostic *diag =
        &s61_stale_runtime_diagnostic;
    memset(diag, 0, sizeof(*diag));
    diag->ewram_before = malloc(S61_STALE_DIAG_EWRAM_SIZE);
    if (diag->ewram_before == NULL)
        s61_die("stale checkflag EWRAM diagnostic allocation failed");
    for (uint32_t offset = 0U; offset < S61_STALE_DIAG_EWRAM_SIZE;
         ++offset)
        diag->ewram_before[offset] = read8(core, 0x02000000U + offset);
    diag->initial_save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    diag->initial_save2 = read32(core, BOOTSTRAP_SAVE_BLOCK2_PTR);
    diag->initial_storage = read32(core, WORLD_POKEMON_STORAGE_PTR);
    for (unsigned byte = 0U; byte < sizeof(diag->initial_save1_head); ++byte)
        diag->initial_save1_head[byte] = read8(
            core, diag->initial_save1 + byte);
    diag->last_script_pointer = UINT32_MAX;
    diag->enabled = true;
}

static void s61_stale_runtime_diag_before_step(struct mCore *core,
                                                uint32_t raw_pc)
{
    struct S61StaleRuntimeDiagnostic *diag =
        &s61_stale_runtime_diagnostic;
    if (!diag->enabled)
        return;
    uint32_t script_pointer = read32(core, WORLD_SCRIPT_CONTEXT1_POINTER);
    if (script_pointer != diag->last_script_pointer) {
        if (diag->script_transition_count
            < S61_STALE_DIAG_MAX_SCRIPT_TRANSITIONS) {
            unsigned index = diag->script_transition_count++;
            diag->script_pointers[index] = script_pointer;
            diag->script_raw_pcs[index] = raw_pc;
            diag->script_frames[index] = core->frameCounter(core);
            diag->script_states[index] = read8(
                core, WORLD_SCRIPT_CONTEXT1_STATE);
        }
        diag->last_script_pointer = script_pointer;
    }
}

static void s61_stale_runtime_diag_after_step(struct mCore *core,
                                               uint32_t mutating_pc)
{
    struct S61StaleRuntimeDiagnostic *diag =
        &s61_stale_runtime_diagnostic;
    if (!diag->enabled)
        return;
    uint32_t next_pc = (uint32_t)read_register(core, "pc");
    uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    if (!diag->save1_pointer_changed && save1 != diag->initial_save1) {
        diag->save1_pointer_changed = true;
        diag->save1_pointer_mutating_pc = mutating_pc;
        diag->save1_pointer_next_pc = next_pc;
        diag->save1_pointer_old = diag->initial_save1;
        diag->save1_pointer_new = save1;
        diag->save1_pointer_frame = core->frameCounter(core);
    }
    if (!diag->save1_head_changed) {
        for (unsigned byte = 0U; byte < sizeof(diag->initial_save1_head);
             ++byte) {
            if (read8(core, diag->initial_save1 + byte)
                == diag->initial_save1_head[byte])
                continue;
            diag->save1_head_changed = true;
            diag->save1_head_mutating_pc = mutating_pc;
            diag->save1_head_next_pc = next_pc;
            diag->save1_head_frame = core->frameCounter(core);
            break;
        }
    }
    diag->previous_instruction_pc = mutating_pc;
}

static void s61_stale_runtime_diag_dump(struct mCore *core)
{
    struct S61StaleRuntimeDiagnostic *diag =
        &s61_stale_runtime_diagnostic;
    if (!diag->enabled)
        return;
    uint32_t current_save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    uint32_t current_save2 = read32(core, BOOTSTRAP_SAVE_BLOCK2_PTR);
    uint32_t current_storage = read32(core, WORLD_POKEMON_STORAGE_PTR);
    fprintf(stderr,
            "stale checkflag ownership diagnostic save1=%08" PRIX32
            "->%08" PRIX32 " save2=%08" PRIX32 "->%08" PRIX32
            " storage=%08" PRIX32 "->%08" PRIX32
            " callback=%08" PRIX32 " context_state=%u"
            " context_ptr=%08" PRIX32 " pc=%08" PRIX32
            " cpsr=%08" PRIX32 " lr=%08" PRIX32 "\n",
            diag->initial_save1, current_save1,
            diag->initial_save2, current_save2,
            diag->initial_storage, current_storage,
            read32(core, BATTLE_CORE_MAIN_CALLBACK2),
            read8(core, WORLD_SCRIPT_CONTEXT1_STATE),
            read32(core, WORLD_SCRIPT_CONTEXT1_POINTER),
            (uint32_t)read_register(core, "pc"),
            (uint32_t)read_register(core, "cpsr"),
            (uint32_t)read_register(core, "lr"));
    fprintf(stderr,
            "stale checkflag first mutation pointer=%u pc=%08" PRIX32
            " next=%08" PRIX32 " frame=%" PRIu32
            " old=%08" PRIX32 " new=%08" PRIX32
            " head=%u pc=%08" PRIX32 " next=%08" PRIX32
            " frame=%" PRIu32 " old_head=",
            diag->save1_pointer_changed ? 1U : 0U,
            diag->save1_pointer_mutating_pc,
            diag->save1_pointer_next_pc,
            diag->save1_pointer_frame,
            diag->save1_pointer_old, diag->save1_pointer_new,
            diag->save1_head_changed ? 1U : 0U,
            diag->save1_head_mutating_pc,
            diag->save1_head_next_pc,
            diag->save1_head_frame);
    for (unsigned byte = 0U; byte < sizeof(diag->initial_save1_head); ++byte)
        fprintf(stderr, "%02X", diag->initial_save1_head[byte]);
    fprintf(stderr, " current_old_head=");
    for (unsigned byte = 0U; byte < sizeof(diag->initial_save1_head); ++byte)
        fprintf(stderr, "%02X", read8(core, diag->initial_save1 + byte));
    fprintf(stderr, " current_ptr_head=");
    if (current_save1 >= 0x02000000U
        && current_save1 + 8U <= 0x02040000U) {
        for (unsigned byte = 0U; byte < 8U; ++byte)
            fprintf(stderr, "%02X", read8(core, current_save1 + byte));
    } else {
        fprintf(stderr, "INVALID");
    }
    fputc('\n', stderr);
    fprintf(stderr, "stale checkflag script pointer transitions count=%u",
            diag->script_transition_count);
    for (unsigned index = 0U; index < diag->script_transition_count;
         ++index)
        fprintf(stderr,
                " [%u]=%08" PRIX32 "@pc%08" PRIX32 "/f%" PRIu32
                "/s%u",
                index, diag->script_pointers[index],
                diag->script_raw_pcs[index], diag->script_frames[index],
                diag->script_states[index]);
    fputc('\n', stderr);
    unsigned range_count = 0U;
    uint32_t first_start = UINT32_MAX;
    uint32_t first_end = UINT32_MAX;
    uint32_t last_start = UINT32_MAX;
    uint32_t last_end = UINT32_MAX;
    uint32_t offset = 0U;
    while (offset < S61_STALE_DIAG_EWRAM_SIZE) {
        if (diag->ewram_before[offset]
            == read8(core, 0x02000000U + offset)) {
            ++offset;
            continue;
        }
        uint32_t start = offset;
        do {
            ++offset;
        } while (offset < S61_STALE_DIAG_EWRAM_SIZE
                 && diag->ewram_before[offset]
                    != read8(core, 0x02000000U + offset));
        uint32_t end = offset;
        if (range_count == 0U) {
            first_start = start;
            first_end = end;
        }
        last_start = start;
        last_end = end;
        ++range_count;
    }
    fprintf(stderr,
            "stale checkflag EWRAM delta ranges=%u first=%08" PRIX32
            "..%08" PRIX32 " last=%08" PRIX32 "..%08" PRIX32 "\n",
            range_count,
            first_start == UINT32_MAX ? UINT32_MAX
                : 0x02000000U + first_start,
            first_end == UINT32_MAX ? UINT32_MAX
                : 0x02000000U + first_end,
            last_start == UINT32_MAX ? UINT32_MAX
                : 0x02000000U + last_start,
            last_end == UINT32_MAX ? UINT32_MAX
                : 0x02000000U + last_end);
}

static void s61_stale_runtime_diag_end(void)
{
    free(s61_stale_runtime_diagnostic.ewram_before);
    memset(&s61_stale_runtime_diagnostic, 0,
           sizeof(s61_stale_runtime_diagnostic));
}

static bool s61_signed_ram_fixture_matches(
    struct mCore *core, const struct S61ExternalControl *control,
    bool after_interaction);

static void s61_sample_internal_controls(struct mCore *core)
{
    if (s61_active_control_row == NULL
        || s61_active_control_sequence == NULL)
        return;
    /* The rematch byte is seeded before stock warp and must survive map load
     * and the complete physical approach.  A normal OBJECT consumer then
     * assigns gSpecialVar_LastTalked.  This instruction-window sampler is
     * read-only: it proves the natural producer saw the already-live byte and
     * cannot conceal a map-load clear with a late host rewrite. */
    for (unsigned index = 0U;
         index < s61_active_control_row->external_control_count; ++index) {
        struct S61ExternalControl *control =
            &s61_active_control_row->external_controls[index];
        if (control->kind != S61_CONTROL_REMATCH_STATE
            || control->deferred_applied
            || !world_script_enabled(core)
            || read16(core, WORLD_SPECIAL_LAST_TALKED)
                != (uint16_t)control->values[1])
            continue;
        uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
        if (save1 < 0x02000000U
            || save1 + S61_SAVE_BLOCK1_SIZE > 0x02040000U
            || (save1 & 3U) != 0U)
            s61_die("catalog deferred rematch SaveBlock1 pointer invalid");
        control->producer_observed_value = read8(
            core, save1 + control->values[2]);
        control->deferred_applied = true;
        ++control->deferred_hit_count;
        if (control->producer_observed_value
                != (uint8_t)control->values[3])
            s61_die("catalog rematch byte differs in producer window");
    }
    uint32_t script_pointer = read32(core, WORLD_SCRIPT_CONTEXT1_POINTER);
    for (unsigned index = 0U;
         index < s61_active_control_row->external_control_count; ++index) {
        struct S61ExternalControl *control =
            &s61_active_control_row->external_controls[index];
        if (control->kind != S61_CONTROL_SIGNED_RAM_SCRIPT)
            continue;
        uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
        uint32_t program = save1 + S61_RAM_SCRIPT_OFFSET
            + S61_RAM_SCRIPT_PROGRAM_OFFSET;
        if (save1 >= 0x02000000U
            && save1 + S61_SAVE_BLOCK1_SIZE <= 0x02040000U
            && script_pointer >= program
            && script_pointer < program + S61_RAM_SCRIPT_PROGRAM_SIZE) {
            control->deferred_applied = true;
            ++control->deferred_hit_count;
        }
    }
    for (unsigned index = 0U;
         index < s61_active_control_row->internal_control_count; ++index) {
        struct S61InternalControl *control =
            &s61_active_control_row->internal_controls[index];
        if (control->sequence_id != NULL
            && strcmp(control->sequence_id, s61_active_control_sequence) != 0) {
            control->window_active = false;
            continue;
        }
        if (control->expected_token_index != s61_active_control_token_index) {
            control->window_active = false;
            continue;
        }
        /* The script interpreter advances scriptPtr while decoding the
         * compare instruction.  Instruction-step sampling observes the full
         * [before, after] bytecode interval without modifying ROM/EWRAM. */
        if (script_pointer < control->before_pc
            || script_pointer > control->after_pc) {
            control->window_active = false;
            continue;
        }
        if (!control->window_active) {
            control->active_execution_ordinal = control->execution_count++;
            control->window_active = true;
        }
        if (control->active_execution_ordinal
                != control->expected_execution_ordinal)
            continue;
        uint16_t actual = read16(core, control->owner_address);
        if (control->hit_count == 0U) {
            control->observed_value = actual;
            control->observed_script_pointer = script_pointer;
        }
        ++control->hit_count;
        if (actual != control->expected_value)
            control->value_mismatch = true;
    }
}

