static void s61_stateful_trace_record(
    struct S61StatefulRuntimeTrace *trace,
    enum S61StatefulTraceKind kind, uint32_t pc)
{
    if (trace->event_count >= S61_STATEFUL_MAX_TRACE_EVENTS)
        s61_die("stateful menu dynamic trace event bound exceeded");
    if (kind == S61_STATEFUL_TRACE_MENU)
        ++trace->menu_iteration;
    trace->events[trace->event_count++] = (struct S61StatefulTraceEvent){
        .kind = kind,
        .pc = pc,
        .instruction_ordinal = trace->instruction_ordinal,
        .menu_iteration = trace->menu_iteration,
    };
    switch (kind) {
    case S61_STATEFUL_TRACE_ROOT: ++trace->root_hits; break;
    case S61_STATEFUL_TRACE_MENU: ++trace->menu_hits; break;
    case S61_STATEFUL_TRACE_BRANCH: ++trace->branch_hits; break;
    case S61_STATEFUL_TRACE_CHECKMONEY: ++trace->checkmoney_hits; break;
    case S61_STATEFUL_TRACE_CHECKSPACE: ++trace->checkspace_hits; break;
    case S61_STATEFUL_TRACE_REMOVEMONEY: ++trace->removemoney_hits; break;
    case S61_STATEFUL_TRACE_ADDITEM: ++trace->additem_hits; break;
    case S61_STATEFUL_TRACE_BACKEDGE: ++trace->backedge_hits; break;
    case S61_STATEFUL_TRACE_SPECIAL: ++trace->special_hits; break;
    case S61_STATEFUL_TRACE_TERMINAL: ++trace->terminal_hits; break;
    }
}

static bool s61_stateful_pc_in(const uint32_t *values, unsigned count,
                               uint32_t value)
{
    for (unsigned index = 0U; index < count; ++index)
        if (values[index] != 0U && values[index] == value)
            return true;
    return false;
}

static void s61_stateful_trace_sample(struct mCore *core,
                                      uint32_t instruction_pc)
{
    struct S61StatefulRuntimeTrace *trace = s61_active_stateful_trace;
    if (trace == NULL || trace->spec == NULL)
        return;
    ++trace->instruction_ordinal;
    const struct S61StatefulFamilySpec *spec = trace->spec;
    if (spec->family == S61_STATEFUL_RESEARCH_AUX
        && trace->root_hits != 0U) {
        uint16_t result = read16(core, WORLD_SPECIAL_RESULT);
        if (result == 9U)
            trace->research_open_busy_result_seen = true;
        if (result == 2U)
            trace->research_cancel_result_seen = true;
    }
    if (spec->special_pc != 0U && instruction_pc == spec->special_pc)
        s61_stateful_trace_record(
            trace, S61_STATEFUL_TRACE_SPECIAL, instruction_pc);
    /* At this pinned dispatcher instruction the previous LDRB has completed:
     * R1 is the opcode and R2 is the exact opcode address being executed.
     * Sampling ScriptContext's stored cursor instead observes the fallthrough
     * candidate before goto_if resolves and produces false branch/effect hits. */
    if (instruction_pc != S61_STATEFUL_SCRIPT_DISPATCH_PC)
        return;
    uint32_t cursor = (uint32_t)read_register(core, "r2");
    uint8_t opcode = (uint8_t)read_register(core, "r1");
    if (cursor < 0x08000000U || cursor >= 0x0A000000U
        || read8(core, cursor) != opcode)
        return;
    if (cursor == spec->root_pc)
        s61_stateful_trace_record(trace, S61_STATEFUL_TRACE_ROOT, cursor);
    if (cursor == spec->menu_pc)
        s61_stateful_trace_record(trace, S61_STATEFUL_TRACE_MENU, cursor);
    if (cursor == spec->terminal_pc) {
        s61_stateful_trace_record(trace, S61_STATEFUL_TRACE_TERMINAL, cursor);
        if (!trace->terminal_failure_branch_seen)
            s61_stateful_trace_record(
                trace, S61_STATEFUL_TRACE_BRANCH, cursor);
    }
    if (s61_stateful_pc_in(spec->choice_pc, 4U, cursor))
        s61_stateful_trace_record(trace, S61_STATEFUL_TRACE_BRANCH, cursor);
    if (spec->family == S61_STATEFUL_BILL) {
        if (cursor == 0x09434AD9U || cursor == 0x09434A15U
            || cursor == 0x09434A0BU)
            s61_stateful_trace_record(
                trace, S61_STATEFUL_TRACE_BRANCH, cursor);
        if (s61_stateful_pc_in(spec->choice_backedge_pc, 4U, cursor))
            s61_stateful_trace_record(
                trace, S61_STATEFUL_TRACE_BACKEDGE, cursor);
        return;
    }
    if (spec->family == S61_STATEFUL_RESEARCH_AUX) {
        if (cursor == spec->backedge_pc)
            s61_stateful_trace_record(
                trace, S61_STATEFUL_TRACE_BACKEDGE, cursor);
        return;
    }
    if (s61_stateful_pc_in(spec->checkmoney_pc, 3U, cursor))
        s61_stateful_trace_record(
            trace, S61_STATEFUL_TRACE_CHECKMONEY, cursor);
    if (cursor == spec->checkspace_pc)
        s61_stateful_trace_record(
            trace, S61_STATEFUL_TRACE_CHECKSPACE, cursor);
    if (s61_stateful_pc_in(spec->removemoney_pc, 3U, cursor))
        s61_stateful_trace_record(
            trace, S61_STATEFUL_TRACE_REMOVEMONEY, cursor);
    if (cursor == spec->additem_pc)
        s61_stateful_trace_record(trace, S61_STATEFUL_TRACE_ADDITEM, cursor);
    if (cursor == spec->backedge_pc)
        s61_stateful_trace_record(trace, S61_STATEFUL_TRACE_BACKEDGE, cursor);
    if (cursor == spec->insufficient_pc || cursor == spec->bag_full_pc) {
        trace->terminal_failure_branch_seen = true;
        s61_stateful_trace_record(trace, S61_STATEFUL_TRACE_BRANCH, cursor);
    }
}

static bool s61_event_common_standard_opcode(uint8_t opcode)
{
    return opcode == 0x08U || opcode == 0x09U
        || opcode == 0x0AU || opcode == 0x0BU;
}

static uint8_t s61_event_common_standard_index(
    struct mCore *core, uint32_t cursor, uint8_t opcode)
{
    if (opcode == 0x08U || opcode == 0x09U)
        return read8(core, cursor + 1U);
    if (opcode == 0x0AU || opcode == 0x0BU)
        return read8(core, cursor + 2U);
    return 0U;
}

static void s61_event_common_assert_binding(
    struct mCore *core, const struct S61EventTriggerRow *trigger)
{
    uint8_t opcode = read8(core, trigger->caller_instruction_pc);
    if (trigger->standard_index >= WORLD_STANDARD_SCRIPT_COUNT
        || !s61_event_common_standard_opcode(opcode)
        || s61_event_common_standard_index(
            core, trigger->caller_instruction_pc, opcode)
            != trigger->standard_index
        || read32(
            core, WORLD_STANDARD_SCRIPT_TABLE
                + (uint32_t)trigger->standard_index * 4U)
            != trigger->root_pc)
        s61_die("event runtime COMMON ROM caller/table binding differs");
}

static void s61_event_common_dispatch_sample(
    struct mCore *core, uint32_t instruction_pc,
    struct S61Capture *capture)
{
    if (capture->event_common_expected_caller_pc == 0U
        || instruction_pc != S61_STATEFUL_SCRIPT_DISPATCH_PC)
        return;
    uint32_t cursor = (uint32_t)read_register(core, "r2");
    uint8_t opcode = (uint8_t)read_register(core, "r1");
    uint32_t context = (uint32_t)read_register(core, "r4");
    if (cursor < 0x08000000U || cursor >= 0x0A000000U
        || read8(core, cursor) != opcode)
        return;
    ++capture->event_common_dispatch_ordinal;
    uint64_t ordinal = capture->event_common_dispatch_ordinal;

    /* A callstd-family transfer is an edge in the bytecode-dispatch stream,
     * not an ARM/Thumb CPU-PC edge.  Consume the pending exact caller on the
     * very next dispatcher sample and require the same ScriptContext1. */
    if (capture->event_common_pending_edge) {
        if (cursor == capture->event_common_expected_root_pc
            && context == capture->event_common_pending_context
            && ordinal
                == capture->event_common_pending_caller_dispatch_ordinal + 1U) {
            ++capture->event_common_adjacent_edge_hits;
        }
        capture->event_common_pending_edge = false;
    }

    if (cursor == capture->event_common_expected_physical_root_pc) {
        if (capture->event_common_physical_root_dispatch_hits == 0U) {
            capture->event_common_first_physical_root_context = context;
            capture->event_common_first_physical_root_dispatch_ordinal =
                ordinal;
        }
        capture->event_common_last_physical_root_context = context;
        capture->event_common_last_physical_root_dispatch_ordinal = ordinal;
        ++capture->event_common_physical_root_dispatch_hits;
    }
    if (cursor == capture->event_common_expected_root_pc) {
        if (capture->event_common_root_dispatch_hits == 0U) {
            capture->event_common_first_root_context = context;
            capture->event_common_first_root_dispatch_ordinal = ordinal;
        }
        ++capture->event_common_root_dispatch_hits;
    }
    if (cursor != capture->event_common_expected_caller_pc)
        return;

    bool opcode_exact = s61_event_common_standard_opcode(opcode);
    uint8_t standard_index = s61_event_common_standard_index(
        core, cursor, opcode);
    uint16_t last_talked = read16(core, WORLD_SPECIAL_LAST_TALKED);
    bool standard_index_exact = opcode_exact
        && standard_index == capture->event_common_expected_standard_index;
    bool last_talked_exact =
        last_talked == capture->event_common_expected_local_id;
    bool context_exact = context == WORLD_SCRIPT_CONTEXT1_STATE;
    bool physical_prefix_exact =
        capture->event_common_last_physical_root_dispatch_ordinal != 0U
        && capture->event_common_last_physical_root_dispatch_ordinal < ordinal
        && capture->event_common_last_physical_root_context == context;
    if (capture->event_common_caller_instruction_hits == 0U) {
        capture->event_common_first_caller_opcode = opcode;
        capture->event_common_first_caller_standard_index = standard_index;
        capture->event_common_first_caller_last_talked = last_talked;
        capture->event_common_first_caller_context = context;
        capture->event_common_first_caller_dispatch_ordinal = ordinal;
    }
    ++capture->event_common_caller_instruction_hits;
    if (opcode_exact)
        ++capture->event_common_opcode_family_hits;
    if (standard_index_exact)
        ++capture->event_common_standard_index_hits;
    if (last_talked_exact)
        ++capture->event_common_last_talked_hits;
    if (context_exact)
        ++capture->event_common_context_hits;
    if (physical_prefix_exact)
        ++capture->event_common_physical_prefix_hits;
    if (opcode_exact && standard_index_exact && last_talked_exact
        && context_exact && physical_prefix_exact) {
        capture->event_common_pending_edge = true;
        capture->event_common_pending_context = context;
        capture->event_common_pending_caller_dispatch_ordinal = ordinal;
    }
}

static bool s61_event_common_dispatch_exact(
    const struct S61Capture *capture)
{
    unsigned caller_hits = capture->event_common_caller_instruction_hits;
    return caller_hits != 0U
        && capture->event_common_physical_root_dispatch_hits != 0U
        && capture->event_common_opcode_family_hits == caller_hits
        && capture->event_common_standard_index_hits == caller_hits
        && capture->event_common_last_talked_hits == caller_hits
        && capture->event_common_context_hits == caller_hits
        && capture->event_common_physical_prefix_hits == caller_hits
        && capture->event_common_adjacent_edge_hits == caller_hits
        && capture->event_common_root_dispatch_hits == caller_hits
        && !capture->event_common_pending_edge
        && capture->event_common_first_physical_root_context
            == WORLD_SCRIPT_CONTEXT1_STATE
        && capture->event_common_first_caller_context
            == WORLD_SCRIPT_CONTEXT1_STATE
        && capture->event_common_first_root_context
            == WORLD_SCRIPT_CONTEXT1_STATE
        && capture->event_common_first_physical_root_dispatch_ordinal != 0U
        && capture->event_common_first_physical_root_dispatch_ordinal
            < capture->event_common_first_caller_dispatch_ordinal
        && capture->event_common_first_root_dispatch_ordinal
            == capture->event_common_first_caller_dispatch_ordinal + 1U;
}

static uint16_t s61_event_read_var_owner(struct mCore *core, uint16_t id)
{
    if (id >= 0x4000U && id < 0x4100U) {
        uint32_t save1 = world_save1(core, "event-root-var-readback");
        return read16(
            core, save1 + S61_SAVE1_VARS_OFFSET + (id - 0x4000U) * 2U);
    }
    if (id >= 0x5000U && id < 0x5200U)
        return read16(
            core, WORLD_EXPANDED_FLAGS_VARS + 0x200U
                + (id - 0x5000U) * 2U);
    s61_die("event runtime MAP condition var owner is unsupported");
    return 0U;
}


static void s61_event_write_var_owner(
    struct mCore *core, uint16_t id, uint16_t value)
{
    if (id >= 0x4000U && id < 0x4100U) {
        uint32_t save1 = world_save1(core, "event-phase-var-write");
        write16(
            core, save1 + S61_SAVE1_VARS_OFFSET + (id - 0x4000U) * 2U,
            value);
        return;
    }
    if (id >= 0x5000U && id < 0x5200U) {
        write16(
            core, WORLD_EXPANDED_FLAGS_VARS + 0x200U
                + (id - 0x5000U) * 2U,
            value);
        return;
    }
    s61_die("event runtime MAP phase var owner is unsupported");
}


static uint32_t s61_event_flag_owner_address(
    struct mCore *core, uint16_t id, unsigned *bit)
{
    *bit = id & 7U;
    if (id < S61_STOCK_FLAG_BYTES * 8U) {
        uint32_t save1 = world_save1(core, "event-phase-flag-owner");
        return save1 + S61_SAVE1_FLAGS_OFFSET + (id >> 3U);
    }
    if (id >= 0x1000U
        && id < 0x1000U + S61_EXPANDED_FLAG_BYTES * 8U)
        return WORLD_EXPANDED_FLAGS_VARS + ((id - 0x1000U) >> 3U);
    if (id >= 0x4000U && id <= 0x407FU)
        return WORLD_ENGINE_SPECIAL_FLAGS + ((id - 0x4000U) >> 3U);
    s61_die("event runtime MAP phase flag owner is unsupported");
    return 0U;
}


static bool s61_event_read_flag_owner(struct mCore *core, uint16_t id)
{
    unsigned bit = 0U;
    uint32_t address = s61_event_flag_owner_address(core, id, &bit);
    return (read8(core, address) & (1U << bit)) != 0U;
}


static void s61_event_write_flag_owner(
    struct mCore *core, uint16_t id, bool value)
{
    unsigned bit = 0U;
    uint32_t address = s61_event_flag_owner_address(core, id, &bit);
    uint8_t byte = read8(core, address);
    uint8_t mask = (uint8_t)(1U << bit);
    byte = value ? (uint8_t)(byte | mask) : (uint8_t)(byte & ~mask);
    write8(core, address, byte);
}


static void s61_map_phase_control_apply(
    struct mCore *core, struct S61Capture *capture, unsigned phase_index,
    uint32_t first_attempt_ordinal)
{
    if (capture->event_map_trigger == NULL || phase_index >= 2U)
        s61_die("MAP phase control lacks trigger/phase identity");
    struct S61MapPhaseControlEvidence *evidence =
        &capture->event_map_phase_controls[phase_index];
    if (evidence->application_count != 0U || evidence->applied)
        s61_die("MAP phase control was reapplied");
    const struct S61MapPhaseControl *phase = phase_index == 0U
        ? &capture->event_map_trigger->map_pre_transition
        : &capture->event_map_trigger->map_pre_field_input;
    for (unsigned index = 0U; index < phase->variable_count; ++index)
        s61_event_write_var_owner(
            core, phase->variables[index].id, phase->variables[index].value);
    for (unsigned index = 0U; index < phase->flag_count; ++index)
        s61_event_write_flag_owner(
            core, phase->flags[index].id, phase->flags[index].value);
    evidence->applied = true;
    evidence->application_count = 1U;
    evidence->application_instruction_ordinal =
        capture->event_instruction_ordinal;
    evidence->first_attempt_ordinal = first_attempt_ordinal;
    evidence->readback_exact = true;
    for (unsigned index = 0U; index < phase->variable_count; ++index) {
        if (s61_event_read_var_owner(core, phase->variables[index].id)
                != phase->variables[index].value)
            evidence->readback_exact = false;
    }
    for (unsigned index = 0U; index < phase->flag_count; ++index) {
        if (s61_event_read_flag_owner(core, phase->flags[index].id)
                != phase->flags[index].value)
            evidence->readback_exact = false;
    }
    if (!evidence->readback_exact)
        s61_die("MAP phase control direct-owner readback differs");
}


static void s61_map_engine_clear_read_state(
    struct mCore *core, struct S61MapEngineClearState *state)
{
    static const uint16_t system_flags[] = {
        0x0803U, 0x0804U, 0x0805U, 0x0807U, 0x0842U,
    };
    for (unsigned index = 0U; index < ARRAY_LEN(state->variables); ++index)
        state->variables[index] = s61_event_read_var_owner(
            core, (uint16_t)(0x4000U + index));
    for (unsigned index = 0U;
         index < ARRAY_LEN(state->temporary_flags); ++index)
        state->temporary_flags[index] = s61_event_read_flag_owner(
            core, (uint16_t)index);
    for (unsigned index = 0U; index < ARRAY_LEN(system_flags); ++index)
        state->system_flags[index] = s61_event_read_flag_owner(
            core, system_flags[index]);
}


static void s61_map_engine_clear_capture_preimage(
    struct mCore *core, struct S61Capture *capture)
{
    struct S61MapEngineClearEvidence *evidence =
        &capture->event_map_engine_clear;
    if (evidence->preimage_captured || evidence->postimage_captured)
        s61_die("MAP engine-clear preimage was captured more than once");
    s61_map_engine_clear_read_state(core, &evidence->preimage);
    evidence->preimage_captured = true;
    for (unsigned index = 0U;
         index < ARRAY_LEN(evidence->preimage.variables); ++index) {
        if (evidence->preimage.variables[index] == 0U)
            s61_die("MAP engine-clear TEMP var preimage is zero");
    }
    for (unsigned index = 0U;
         index < ARRAY_LEN(evidence->preimage.temporary_flags); ++index) {
        if (!evidence->preimage.temporary_flags[index])
            s61_die("MAP engine-clear TEMP flag preimage is false");
    }
    for (unsigned index = 0U;
         index < ARRAY_LEN(evidence->preimage.system_flags); ++index) {
        if (!evidence->preimage.system_flags[index])
            s61_die("MAP engine-clear system flag preimage is false");
    }
}


static void s61_map_engine_clear_capture_postimage(
    struct mCore *core, struct S61Capture *capture, uint8_t first_tag)
{
    struct S61MapEngineClearEvidence *evidence =
        &capture->event_map_engine_clear;
    if (!evidence->preimage_captured || evidence->postimage_captured
        || evidence->capture_count != 0U)
        s61_die("MAP engine-clear postimage boundary differs");
    if (first_tag != 3U && first_tag != 1U && first_tag != 5U
        && first_tag != 4U && first_tag != 2U)
        s61_die("MAP engine-clear first destination attempt tag differs");
    s61_map_engine_clear_read_state(core, &evidence->postimage);
    evidence->postimage_captured = true;
    evidence->capture_count = 1U;
    evidence->capture_instruction_ordinal =
        capture->event_instruction_ordinal;
    evidence->first_attempt_ordinal =
        capture->event_map_lifecycle_attempt_count;
    evidence->first_attempt_tag = first_tag;
    evidence->readback_exact = true;
    for (unsigned index = 0U;
         index < ARRAY_LEN(evidence->postimage.variables); ++index) {
        if (evidence->postimage.variables[index] != 0U)
            evidence->readback_exact = false;
    }
    for (unsigned index = 0U;
         index < ARRAY_LEN(evidence->postimage.temporary_flags); ++index) {
        if (evidence->postimage.temporary_flags[index])
            evidence->readback_exact = false;
    }
    for (unsigned index = 0U;
         index < ARRAY_LEN(evidence->postimage.system_flags); ++index) {
        if (evidence->postimage.system_flags[index])
            evidence->readback_exact = false;
    }
    if (!evidence->readback_exact)
        s61_die("MAP engine ClearTempFieldEventData postimage differs");
}


static void s61_assert_map_lifecycle_hook_preimages(struct mCore *core)
{
    struct S61MapHookPreimage {
        uint32_t address;
        uint8_t raw[4U];
    };
    /* These bytes are pinned from the actual Stage61 ROM, then interpreted
     * against MapHeaderRunScriptType/MapHeaderCheckScriptTable in script.c.
     * Any rebuilt ROM must re-prove these instruction/register contracts. */
    static const struct S61MapHookPreimage expected[] = {
        {WORLD_MAP_SCRIPT_ROOT_EXECUTOR_ENTRY_PC,
         {0x30U, 0xB5U, 0x05U, 0x1CU}},
        {WORLD_MAP_SCRIPT_OUTER_MATCH_PC,
         {0x01U, 0x32U, 0x10U, 0x78U}},
        {WORLD_MAP_SCRIPT_OUTER_ROOT_FIELD_PC,
         {0x10U, 0x78U, 0x51U, 0x78U}},
        {WORLD_MAP_SCRIPT_DIRECT_ATTEMPT_PC,
         {0x00U, 0xB5U, 0x00U, 0x06U}},
        {WORLD_MAP_SCRIPT_DIRECT_RESULT_PC,
         {0x00U, 0x28U, 0x01U, 0xD0U}},
        {WORLD_MAP_SCRIPT_ROOT_CALLSITE_PC,
         {0xFFU, 0xF7U, 0xBBU, 0xFFU}},
        {WORLD_MAP_SCRIPT_DIRECT_RETURN_PC,
         {0x01U, 0xBCU, 0x00U, 0x47U}},
        {WORLD_MAP_SCRIPT_CONDITIONAL_ATTEMPT_PC,
         {0x70U, 0xB5U, 0x00U, 0x06U}},
        {WORLD_MAP_SCRIPT_CONDITIONAL_OUTER_RESULT_PC,
         {0x00U, 0x2EU, 0x05U, 0xD0U}},
        {WORLD_MAP_SCRIPT_CONDITION_SCAN_PC,
         {0x31U, 0x78U, 0x70U, 0x78U}},
        {WORLD_MAP_SCRIPT_CONDITION_COMPARE_PC,
         {0x84U, 0x42U, 0x01U, 0xD0U}},
        {WORLD_MAP_SCRIPT_CONDITION_SELECTED_PC,
         {0x30U, 0x78U, 0x71U, 0x78U}},
        {WORLD_MAP_SCRIPT_CONDITIONAL_RETURN_PC,
         {0x70U, 0xBCU, 0x02U, 0xBCU}},
        {WORLD_MAP_SCRIPT_ON_FRAME_CALLSITE_PC,
         {0xFFU, 0xF7U, 0x2CU, 0xFFU}},
        {WORLD_MAP_SCRIPT_ON_WARP_IN_CALLSITE_PC,
         {0xFFU, 0xF7U, 0x4EU, 0xFFU}},
    };
    for (unsigned row = 0U;
         row < sizeof(expected) / sizeof(expected[0]); ++row) {
        for (unsigned byte = 0U; byte < sizeof(expected[row].raw); ++byte) {
            if (read8(core, expected[row].address + byte)
                != expected[row].raw[byte])
                s61_die("MAP lifecycle hook preimage differs");
        }
    }
}

static bool s61_map_lifecycle_rom_pointer(uint32_t address, uint32_t size)
{
    return address >= 0x08000000U && address <= 0x09FFFFFFU
        && size <= 0x02000000U
        && address <= 0x0A000000U - size;
}

static void s61_map_lifecycle_location(
    struct mCore *core, uint8_t *group, uint8_t *map)
{
    uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    if (save1 < 0x02000000U
        || save1 + S61_SAVE_BLOCK1_SIZE > 0x02040000U
        || (save1 & 3U) != 0U)
        s61_die("MAP lifecycle SaveBlock1 pointer is invalid");
    *group = read8(core, save1 + 4U);
    *map = read8(core, save1 + 5U);
}

static void s61_map_lifecycle_append(
    struct mCore *core, struct S61Capture *capture,
    enum S61MapLifecycleObservationKind kind,
    enum S61MapLifecycleAttemptResult result, uint32_t instruction_pc,
    uint32_t outer_record_address, uint32_t root_field_address,
    uint32_t root_pc)
{
    if (capture->event_map_lifecycle_observation_count
        >= S61_MAP_LIFECYCLE_MAX_OBSERVATIONS)
        s61_die("MAP lifecycle verbose observation worst-case overflow");
    if (capture->event_map_lifecycle_observation_count
        == capture->event_map_lifecycle_observation_capacity) {
        unsigned capacity = capture->event_map_lifecycle_observation_capacity
            == 0U ? 256U
            : capture->event_map_lifecycle_observation_capacity * 2U;
        if (capacity > S61_MAP_LIFECYCLE_MAX_OBSERVATIONS)
            capacity = S61_MAP_LIFECYCLE_MAX_OBSERVATIONS;
        struct S61MapLifecycleObservation *grown = realloc(
            capture->event_map_lifecycle_observations,
            (size_t)capacity * sizeof(*grown));
        if (grown == NULL)
            s61_die("MAP lifecycle verbose observation allocation failed");
        capture->event_map_lifecycle_observations = grown;
        capture->event_map_lifecycle_observation_capacity = capacity;
    }
    unsigned index = capture->event_map_lifecycle_observation_count++;
    struct S61MapLifecycleObservation *observation =
        &capture->event_map_lifecycle_observations[index];
    observation->kind = kind;
    observation->result = result;
    observation->phase = capture->event_map_lifecycle_phase;
    observation->ordinal = index;
    observation->instruction_ordinal = capture->event_instruction_ordinal;
    observation->instruction_pc = instruction_pc;
    observation->attempt_ordinal =
        capture->event_map_lifecycle_attempt_valid
        ? capture->event_map_lifecycle_current_attempt_ordinal : UINT32_MAX;
    observation->frame = core->frameCounter(core);
    observation->r0 = (uint32_t)read_register(core, "r0");
    observation->r1 = (uint32_t)read_register(core, "r1");
    observation->r2 = (uint32_t)read_register(core, "r2");
    observation->r4 = (uint32_t)read_register(core, "r4");
    observation->r5 = (uint32_t)read_register(core, "r5");
    observation->r6 = (uint32_t)read_register(core, "r6");
    observation->lr = (uint32_t)read_register(core, "lr");
    observation->outer_record_address = outer_record_address;
    observation->root_field_address = root_field_address;
    observation->root_pc = root_pc;
    observation->tag = capture->event_map_lifecycle_tag;
    s61_map_lifecycle_location(
        core, &observation->group, &observation->map);
}

static enum S61MapLifecycleSourcePhase s61_map_lifecycle_source_phase(
    const struct S61Capture *capture, uint8_t tag)
{
    unsigned ordinal = capture->event_map_lifecycle_attempt_count;
    if (capture->event_map_lifecycle_phase
        == S61_MAP_LIFECYCLE_PHASE_FIELD_RETURN) {
        unsigned first = capture->event_map_lifecycle_phase_boundaries[1U]
            .before_observed_attempt_ordinal;
        if (ordinal == first && tag == 5U)
            return S61_MAP_SOURCE_PHASE_FIELD_RETURN_RESUME;
        if (ordinal == first + 1U && tag == 7U)
            return S61_MAP_SOURCE_PHASE_FIELD_RETURN_RETURN_TO_FIELD;
        s61_die("MAP lifecycle FIELD_RETURN source phase/tag differs");
    }
    if (capture->event_map_lifecycle_phase
        != S61_MAP_LIFECYCLE_PHASE_INITIAL_LOAD)
        s61_die("MAP lifecycle attempt has no active phase");
    if (ordinal == 0U && tag == 3U)
        return S61_MAP_SOURCE_PHASE_INITIAL_TRANSITION;
    if (ordinal == 1U && tag == 1U)
        return S61_MAP_SOURCE_PHASE_INITIAL_LOAD;
    if (ordinal == 2U && tag == 5U)
        return S61_MAP_SOURCE_PHASE_INITIAL_RESUME;
    bool connection = capture->event_map_trigger != NULL
        && strstr(capture->event_map_trigger->transition_contract,
                  "CONNECTION") != NULL;
    if (!connection && ordinal == 3U && tag == 4U)
        return S61_MAP_SOURCE_PHASE_INITIAL_WARP_IN;
    if (tag == 2U && ordinal >= (connection ? 3U : 4U))
        return S61_MAP_SOURCE_PHASE_PRE_FIELD_INPUT_ON_FRAME;
    s61_die("MAP lifecycle initial source phase/tag differs");
    return S61_MAP_SOURCE_PHASE_NONE;
}

static uint32_t s61_map_lifecycle_outer_index(
    struct mCore *core, uint32_t outer_record)
{
    uint32_t table = read32(core, WORLD_MAP_HEADER + 8U);
    if (!s61_map_lifecycle_rom_pointer(table, 1U)
        || !s61_map_lifecycle_rom_pointer(outer_record, 5U)
        || outer_record < table || (outer_record - table) % 5U != 0U)
        s61_die("MAP lifecycle outer row/table binding differs");
    uint32_t index = (outer_record - table) / 5U;
    if (index > 255U || read8(core, outer_record) == 0U)
        s61_die("MAP lifecycle outer row index differs");
    return index;
}

static void s61_map_lifecycle_begin_attempt(
    struct mCore *core, struct S61Capture *capture, uint32_t raw_tag)
{
    if (capture->event_map_lifecycle_attempt_active)
        s61_die("MAP lifecycle attempt nested before return");
    if (raw_tag == 0U || raw_tag > 7U)
        s61_die("MAP lifecycle attempt tag is invalid");
    if (capture->event_map_lifecycle_attempt_count
        >= S61_MAP_LIFECYCLE_MAX_ORDERED_ATTEMPTS)
        s61_die("MAP lifecycle ordered attempt buffer overflow");
    if (raw_tag == 2U
        && ++capture->event_map_lifecycle_tag2_attempt_count
            > S61_MAP_LIFECYCLE_TAG2_ATTEMPT_CAP)
        s61_die("MAP lifecycle tag2 attempt cap exceeded 256");
    unsigned ordinal = capture->event_map_lifecycle_attempt_count;
    struct S61MapLifecycleOrderedAttempt *attempt =
        &capture->event_map_lifecycle_attempts[ordinal];
    attempt->result = S61_MAP_ATTEMPT_RESULT_NONE;
    attempt->phase = capture->event_map_lifecycle_phase;
    attempt->source_phase = s61_map_lifecycle_source_phase(
        capture, (uint8_t)raw_tag);
    attempt->observed_attempt_ordinal = ordinal;
    attempt->source_attempt_ordinal = ordinal + 1U;
    attempt->outer_index = UINT32_MAX;
    attempt->selected_condition_index = UINT32_MAX;
    attempt->tag = (uint8_t)raw_tag;
    s61_map_lifecycle_location(core, &attempt->group, &attempt->map);
    capture->event_map_lifecycle_attempt_active = true;
    capture->event_map_lifecycle_attempt_valid = true;
    capture->event_map_lifecycle_dispatch_observed = false;
    capture->event_map_lifecycle_condition_selected = false;
    capture->event_map_lifecycle_tag = (uint8_t)raw_tag;
    capture->event_map_lifecycle_current_attempt_ordinal =
        capture->event_map_lifecycle_attempt_count++;
    capture->event_map_lifecycle_current_outer_index = UINT32_MAX;
    capture->event_map_lifecycle_current_outer_record = 0U;
    capture->event_map_lifecycle_current_selected_condition_index = UINT32_MAX;
    capture->event_map_lifecycle_current_selected_condition_record = 0U;
    capture->event_map_lifecycle_current_root_field = 0U;
    capture->event_map_lifecycle_current_root_pc = 0U;
    capture->event_map_lifecycle_last_scanned_root_field = 0U;
}

static struct S61MapLifecycleOrderedAttempt *s61_map_lifecycle_attempt(
    struct S61Capture *capture)
{
    if (!capture->event_map_lifecycle_attempt_valid
        || capture->event_map_lifecycle_current_attempt_ordinal
            >= capture->event_map_lifecycle_attempt_count)
        s61_die("MAP lifecycle ordered attempt identity differs");
    return &capture->event_map_lifecycle_attempts[
        capture->event_map_lifecycle_current_attempt_ordinal];
}

static void s61_map_lifecycle_finish_attempt(
    struct S61Capture *capture, enum S61MapLifecycleAttemptResult result)
{
    struct S61MapLifecycleOrderedAttempt *attempt =
        s61_map_lifecycle_attempt(capture);
    attempt->result = result;
    attempt->outer_index = capture->event_map_lifecycle_current_outer_index;
    attempt->outer_record_address =
        capture->event_map_lifecycle_current_outer_record;
    attempt->selected_condition_index =
        capture->event_map_lifecycle_current_selected_condition_index;
    attempt->selected_condition_record_address =
        capture->event_map_lifecycle_current_selected_condition_record;
    attempt->root_field_address =
        capture->event_map_lifecycle_current_root_field;
    attempt->root_pc = capture->event_map_lifecycle_current_root_pc;
}

static void s61_map_lifecycle_append_dispatch(struct S61Capture *capture)
{
    if (capture->event_map_lifecycle_dispatch_count
        >= S61_MAP_LIFECYCLE_MAX_ORDERED_ATTEMPTS)
        s61_die("MAP lifecycle ordered dispatch buffer overflow");
    struct S61MapLifecycleOrderedAttempt *attempt =
        s61_map_lifecycle_attempt(capture);
    if (attempt->root_pc == 0U || attempt->root_field_address == 0U)
        s61_die("MAP lifecycle ordered dispatch root is absent");
    unsigned ordinal = capture->event_map_lifecycle_dispatch_count++;
    struct S61MapLifecycleOrderedDispatch *dispatch =
        &capture->event_map_lifecycle_dispatches[ordinal];
    dispatch->dispatch_ordinal = ordinal;
    dispatch->observed_attempt_ordinal = attempt->observed_attempt_ordinal;
    dispatch->source_attempt_ordinal = attempt->source_attempt_ordinal;
}

static void s61_map_lifecycle_require_attempt(
    const struct S61Capture *capture, const char *label)
{
    if (!capture->event_map_lifecycle_attempt_active
        || !capture->event_map_lifecycle_attempt_valid)
        s61_die(label);
}

static void s61_map_lifecycle_sample(
    struct mCore *core, uint32_t instruction_pc,
    struct S61Capture *capture)
{
    if (!capture->event_map_lifecycle_enabled
        || capture->event_map_lifecycle_quiescent)
        return;
    if (!capture->event_map_producer_started
        || capture->event_map_trigger == NULL)
        return;
    uint8_t current_group = 0U;
    uint8_t current_map = 0U;
    s61_map_lifecycle_location(core, &current_group, &current_map);
    if (current_group != capture->event_map_trigger->destination_group
        || current_map != capture->event_map_trigger->destination_map) {
        if (capture->event_map_lifecycle_attempt_active)
            s61_die("MAP lifecycle left destination during an attempt");
        return;
    }
    uint32_t r0 = (uint32_t)read_register(core, "r0");
    uint32_t r2 = (uint32_t)read_register(core, "r2");
    uint32_t r6 = (uint32_t)read_register(core, "r6");
    if (instruction_pc == WORLD_MAP_SCRIPT_DIRECT_ATTEMPT_PC) {
        uint8_t tag = (uint8_t)(r0 & 0xFFU);
        if (!capture->event_map_engine_clear.postimage_captured)
            s61_map_engine_clear_capture_postimage(core, capture, tag);
        if (tag == 2U
            && capture->event_map_phase_controls[1].application_count == 0U)
            s61_map_phase_control_apply(
                core, capture, 1U,
                capture->event_map_lifecycle_attempt_count);
        s61_map_lifecycle_begin_attempt(core, capture, tag);
        if (capture->event_map_lifecycle_tag == 2U
            || capture->event_map_lifecycle_tag == 4U)
            s61_die("MAP lifecycle conditional tag used direct dispatcher");
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_DIRECT_ATTEMPT,
            S61_MAP_ATTEMPT_RESULT_NONE, instruction_pc, 0U, 0U, 0U);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_CONDITIONAL_ATTEMPT_PC) {
        uint8_t tag = (uint8_t)(r0 & 0xFFU);
        if (!capture->event_map_engine_clear.postimage_captured)
            s61_map_engine_clear_capture_postimage(core, capture, tag);
        if (tag == 2U
            && capture->event_map_phase_controls[1].application_count == 0U)
            s61_map_phase_control_apply(
                core, capture, 1U,
                capture->event_map_lifecycle_attempt_count);
        s61_map_lifecycle_begin_attempt(core, capture, tag);
        if (capture->event_map_lifecycle_tag != 2U
            && capture->event_map_lifecycle_tag != 4U)
            s61_die("MAP lifecycle direct tag used conditional dispatcher");
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_CONDITIONAL_ATTEMPT,
            S61_MAP_ATTEMPT_RESULT_NONE, instruction_pc, 0U, 0U, 0U);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_OUTER_MATCH_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle outer match lacks attempt");
        if (!s61_map_lifecycle_rom_pointer(r2, 5U)
            || read8(core, r2) != capture->event_map_lifecycle_tag)
            s61_die("MAP lifecycle outer match register differs");
        capture->event_map_lifecycle_current_outer_record = r2;
        capture->event_map_lifecycle_current_outer_index =
            s61_map_lifecycle_outer_index(core, r2);
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_OUTER_MATCH,
            S61_MAP_ATTEMPT_RESULT_NONE, instruction_pc, r2, 0U, 0U);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_DIRECT_RESULT_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle direct result lacks attempt");
        enum S61MapLifecycleAttemptResult result =
            S61_MAP_ATTEMPT_RESULT_NONE;
        uint32_t root_field = 0U;
        if (r0 == 0U) {
            if (capture->event_map_lifecycle_current_outer_record != 0U)
                s61_die("MAP lifecycle direct outer resolved null root");
            result = S61_MAP_ATTEMPT_RESULT_TAG_ABSENT;
        } else {
            uint32_t outer =
                capture->event_map_lifecycle_current_outer_record;
            if (!s61_map_lifecycle_rom_pointer(outer, 5U))
                s61_die("MAP lifecycle direct root lacks outer record");
            root_field = outer + 1U;
            if (read32(core, root_field) != r0
                || !s61_map_lifecycle_rom_pointer(r0, 1U))
                s61_die("MAP lifecycle direct root register differs");
            capture->event_map_lifecycle_current_root_field = root_field;
            capture->event_map_lifecycle_current_root_pc = r0;
        }
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_DIRECT_RESULT, result,
            instruction_pc,
            capture->event_map_lifecycle_current_outer_record,
            root_field, r0);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_ROOT_CALLSITE_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle direct dispatch lacks attempt");
        if (capture->event_map_lifecycle_current_root_pc == 0U
            || r0 != capture->event_map_lifecycle_current_root_pc)
            s61_die("MAP lifecycle direct dispatch root differs");
        capture->event_map_lifecycle_dispatch_observed = true;
        s61_map_lifecycle_finish_attempt(
            capture, S61_MAP_ATTEMPT_RESULT_DISPATCH);
        s61_map_lifecycle_append_dispatch(capture);
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_DIRECT_DISPATCH,
            S61_MAP_ATTEMPT_RESULT_DISPATCH, instruction_pc,
            capture->event_map_lifecycle_current_outer_record,
            capture->event_map_lifecycle_current_root_field, r0);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_DIRECT_RETURN_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle direct return lacks attempt");
        if (capture->event_map_lifecycle_current_root_pc != 0U
            && !capture->event_map_lifecycle_dispatch_observed)
            s61_die("MAP lifecycle direct root was not dispatched");
        enum S61MapLifecycleAttemptResult result =
            capture->event_map_lifecycle_dispatch_observed
                ? S61_MAP_ATTEMPT_RESULT_DISPATCH
                : S61_MAP_ATTEMPT_RESULT_TAG_ABSENT;
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_DIRECT_RETURN, result,
            instruction_pc,
            capture->event_map_lifecycle_current_outer_record,
            capture->event_map_lifecycle_current_root_field,
            capture->event_map_lifecycle_current_root_pc);
        s61_map_lifecycle_finish_attempt(capture, result);
        capture->event_map_lifecycle_attempt_active = false;
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_CONDITIONAL_OUTER_RESULT_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle conditional outer result lacks attempt");
        enum S61MapLifecycleAttemptResult result = r6 == 0U
            ? S61_MAP_ATTEMPT_RESULT_TAG_ABSENT
            : S61_MAP_ATTEMPT_RESULT_NONE;
        if ((r6 == 0U)
            != (capture->event_map_lifecycle_current_outer_record == 0U))
            s61_die("MAP lifecycle conditional outer result differs");
        if (r6 != 0U) {
            uint32_t outer =
                capture->event_map_lifecycle_current_outer_record;
            if (!s61_map_lifecycle_rom_pointer(outer, 5U)
                || read32(core, outer + 1U) != r6
                || !s61_map_lifecycle_rom_pointer(r6, 2U))
                s61_die("MAP lifecycle condition table register differs");
        }
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_CONDITIONAL_OUTER_RESULT,
            result, instruction_pc,
            capture->event_map_lifecycle_current_outer_record, 0U, 0U);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_CONDITION_SCAN_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle condition scan lacks attempt");
        if (!s61_map_lifecycle_rom_pointer(r6, 2U))
            s61_die("MAP lifecycle condition scan pointer differs");
        uint32_t root_field = 0U;
        uint32_t root = 0U;
        enum S61MapLifecycleAttemptResult result =
            S61_MAP_ATTEMPT_RESULT_NONE;
        if (read16(core, r6) == 0U) {
            result = S61_MAP_ATTEMPT_RESULT_NO_CONDITION_MATCH;
            capture->event_map_lifecycle_last_scanned_root_field = 0U;
        } else {
            if (!s61_map_lifecycle_rom_pointer(r6, 8U))
                s61_die("MAP lifecycle condition record exceeds ROM");
            root_field = r6 + 4U;
            root = read32(core, root_field);
            if (!s61_map_lifecycle_rom_pointer(root, 1U))
                s61_die("MAP lifecycle condition root pointer differs");
            capture->event_map_lifecycle_last_scanned_root_field = root_field;
        }
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_CONDITION_SCAN, result,
            instruction_pc,
            capture->event_map_lifecycle_current_outer_record,
            root_field, root);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_CONDITION_COMPARE_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle condition compare lacks attempt");
        if (!s61_map_lifecycle_rom_pointer(r6, 4U))
            s61_die("MAP lifecycle condition compare root field differs");
        if (r6 != capture->event_map_lifecycle_last_scanned_root_field)
            s61_die("MAP lifecycle condition compare row differs");
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_CONDITION_COMPARE,
            S61_MAP_ATTEMPT_RESULT_NONE, instruction_pc,
            capture->event_map_lifecycle_current_outer_record,
            r6, read32(core, r6));
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_CONDITION_SELECTED_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle condition selection lacks attempt");
        if (!s61_map_lifecycle_rom_pointer(r6, 4U))
            s61_die("MAP lifecycle selected root field differs");
        if (r6 != capture->event_map_lifecycle_last_scanned_root_field)
            s61_die("MAP lifecycle selected condition row differs");
        capture->event_map_lifecycle_condition_selected = true;
        capture->event_map_lifecycle_dispatch_observed = true;
        capture->event_map_lifecycle_current_root_field = r6;
        capture->event_map_lifecycle_current_root_pc = read32(core, r6);
        uint32_t condition_table = read32(
            core, capture->event_map_lifecycle_current_outer_record + 1U);
        if (r6 < condition_table + 4U
            || (r6 - condition_table - 4U) % 8U != 0U)
            s61_die("MAP lifecycle selected condition index differs");
        capture->event_map_lifecycle_current_selected_condition_index =
            (r6 - condition_table - 4U) / 8U;
        capture->event_map_lifecycle_current_selected_condition_record =
            r6 - 4U;
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_CONDITION_SELECTION,
            S61_MAP_ATTEMPT_RESULT_DISPATCH, instruction_pc,
            capture->event_map_lifecycle_current_outer_record, r6,
            capture->event_map_lifecycle_current_root_pc);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_CONDITIONAL_RETURN_PC) {
        s61_map_lifecycle_require_attempt(
            capture, "MAP lifecycle conditional return lacks attempt");
        enum S61MapLifecycleAttemptResult result;
        if (r0 != 0U) {
            if (!capture->event_map_lifecycle_condition_selected
                || r0 != capture->event_map_lifecycle_current_root_pc)
                s61_die("MAP lifecycle conditional return root differs");
            result = S61_MAP_ATTEMPT_RESULT_DISPATCH;
        } else if (capture->event_map_lifecycle_current_outer_record == 0U) {
            result = S61_MAP_ATTEMPT_RESULT_TAG_ABSENT;
        } else {
            result = S61_MAP_ATTEMPT_RESULT_NO_CONDITION_MATCH;
        }
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_CONDITIONAL_RETURN, result,
            instruction_pc,
            capture->event_map_lifecycle_current_outer_record,
            capture->event_map_lifecycle_current_root_field, r0);
        s61_map_lifecycle_finish_attempt(capture, result);
        capture->event_map_lifecycle_attempt_active = false;
        if (capture->event_map_lifecycle_tag == 2U && r0 == 0U)
            capture->event_map_lifecycle_quiescent = true;
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_ON_FRAME_CALLSITE_PC
        || instruction_pc == WORLD_MAP_SCRIPT_ON_WARP_IN_CALLSITE_PC) {
        uint8_t expected_tag = instruction_pc
            == WORLD_MAP_SCRIPT_ON_FRAME_CALLSITE_PC ? 2U : 4U;
        if (!capture->event_map_lifecycle_attempt_valid
            || capture->event_map_lifecycle_tag != expected_tag
            || !capture->event_map_lifecycle_condition_selected
            || r0 != capture->event_map_lifecycle_current_root_pc)
            s61_die("MAP lifecycle conditional dispatch root differs");
        s61_map_lifecycle_append_dispatch(capture);
        s61_map_lifecycle_append(
            core, capture,
            expected_tag == 2U ? S61_MAP_OBSERVATION_TAG2_DISPATCH
                : S61_MAP_OBSERVATION_TAG4_DISPATCH,
            S61_MAP_ATTEMPT_RESULT_DISPATCH, instruction_pc,
            capture->event_map_lifecycle_current_outer_record,
            capture->event_map_lifecycle_current_root_field, r0);
        return;
    }
    if (instruction_pc == WORLD_MAP_SCRIPT_ROOT_EXECUTOR_ENTRY_PC) {
        if (!capture->event_map_lifecycle_attempt_valid
            || capture->event_map_lifecycle_current_root_pc == 0U
            || r0 != capture->event_map_lifecycle_current_root_pc)
            s61_die("MAP lifecycle root executor has no proven dispatch");
        s61_map_lifecycle_append(
            core, capture, S61_MAP_OBSERVATION_ROOT_EXECUTOR,
            S61_MAP_ATTEMPT_RESULT_DISPATCH, instruction_pc,
            capture->event_map_lifecycle_current_outer_record,
            capture->event_map_lifecycle_current_root_field, r0);
    }
}

static void s61_map_lifecycle_mark_phase(
    struct mCore *core, struct S61Capture *capture,
    enum S61MapLifecyclePhase phase)
{
    if (!capture->event_map_lifecycle_enabled)
        return;
    if (capture->event_map_lifecycle_attempt_active)
        s61_die("MAP lifecycle phase changed during attempt");
    if (capture->event_map_lifecycle_phase_boundary_count
        >= S61_MAP_LIFECYCLE_MAX_PHASE_BOUNDARIES)
        s61_die("MAP lifecycle phase boundary buffer overflow");
    unsigned boundary_ordinal =
        capture->event_map_lifecycle_phase_boundary_count++;
    if ((boundary_ordinal == 0U
         && phase != S61_MAP_LIFECYCLE_PHASE_INITIAL_LOAD)
        || (boundary_ordinal == 1U
            && phase != S61_MAP_LIFECYCLE_PHASE_FIELD_RETURN))
        s61_die("MAP lifecycle phase boundary order differs");
    struct S61MapLifecyclePhaseBoundary *boundary =
        &capture->event_map_lifecycle_phase_boundaries[boundary_ordinal];
    boundary->phase = phase;
    boundary->boundary_ordinal = boundary_ordinal;
    boundary->before_observed_attempt_ordinal =
        capture->event_map_lifecycle_attempt_count;
    boundary->before_source_attempt_ordinal =
        capture->event_map_lifecycle_attempt_count + 1U;
    capture->event_map_lifecycle_phase = phase;
    capture->event_map_lifecycle_attempt_valid = false;
    capture->event_map_lifecycle_quiescent = false;
    capture->event_map_lifecycle_tag = 0U;
    capture->event_map_lifecycle_current_outer_index = UINT32_MAX;
    capture->event_map_lifecycle_current_outer_record = 0U;
    capture->event_map_lifecycle_current_selected_condition_index = UINT32_MAX;
    capture->event_map_lifecycle_current_selected_condition_record = 0U;
    capture->event_map_lifecycle_current_root_field = 0U;
    capture->event_map_lifecycle_current_root_pc = 0U;
    capture->event_map_lifecycle_last_scanned_root_field = 0U;
    uint32_t raw_pc = (uint32_t)read_register(core, "pc");
    s61_map_lifecycle_append(
        core, capture, S61_MAP_OBSERVATION_PHASE_BOUNDARY,
        S61_MAP_ATTEMPT_RESULT_NONE, (raw_pc - 4U) & ~1U,
        0U, 0U, 0U);
}

static void s61_sample_facility_execution(
    struct mCore *core, struct S61Capture *capture,
    uint32_t instruction_pc);
static void s61_attach_facility_execution(
    struct mCore *core, struct S61Capture *capture,
    struct S61ExternalControl *control);
static void s61_finalize_facility_execution(
    struct mCore *core, struct S61Capture *capture);
static void s61_release_facility_execution(struct S61Capture *capture);
static const char *s61_facility_nullable_u16(
    uint16_t value, char buffer[16U]);

static void s61_step_capture_frames(struct mCore *core, uint16_t keys,
                                    unsigned frames,
                                    struct S61Capture *capture)
{
    if (s61_active_facility_execution != NULL
        && s61_active_facility_execution->active_boundary_observed) {
        core->setKeys(core, 0U);
        return;
    }
    if (capture->lifecycle_paused_after_first_flag_set) {
        core->setKeys(core, 0U);
        return;
    }
    core->setKeys(core, keys);
    uint32_t first_frame = core->frameCounter(core);
    while ((uint32_t)(core->frameCounter(core) - first_frame) < frames) {
        if (s61_capture_invalid_control_flow(core, capture))
            return;
        s61_sample_internal_controls(core);
        uint32_t before = core->frameCounter(core);
        uint32_t raw_pc = (uint32_t)read_register(core, "pc");
        uint32_t instruction_pc = (raw_pc - 4U) & ~1U;
        if (world_script_enabled(core)) {
            if (capture->script_context_active_instructions == 0U)
                capture->first_script_context_pointer = read32(
                    core, WORLD_SCRIPT_CONTEXT1_POINTER);
            ++capture->script_context_active_instructions;
        }
        if (!world_overworld(core)) {
            if (capture->non_overworld_instructions == 0U)
                capture->first_non_overworld_callback = read32(
                    core, BATTLE_CORE_MAIN_CALLBACK2);
            ++capture->non_overworld_instructions;
        }
        s61_stateful_trace_sample(core, instruction_pc);
        s61_effect_observer_sample_pc(core, raw_pc);
        s61_stale_runtime_diag_before_step(core, raw_pc);
        ++capture->event_instruction_ordinal;
        s61_event_common_dispatch_sample(core, instruction_pc, capture);
        s61_map_lifecycle_sample(core, instruction_pc, capture);
        if (capture->lifecycle_flag_owner_address != 0U) {
            bool flag_set = (
                read8(core, capture->lifecycle_flag_owner_address)
                & capture->lifecycle_flag_mask) != 0U;
            if (flag_set && !capture->lifecycle_flag_set_observed) {
                capture->lifecycle_flag_set_observed = true;
                capture->lifecycle_first_flag_set_ordinal =
                    capture->event_instruction_ordinal;
                if (capture->lifecycle_pause_after_first_flag_set) {
                    capture->lifecycle_paused_after_first_flag_set = true;
                    core->setKeys(core, 0U);
                    return;
                }
            } else if (!flag_set && capture->lifecycle_flag_set_observed
                       && !capture->lifecycle_flag_clear_after_set_observed) {
                capture->lifecycle_flag_clear_after_set_observed = true;
                capture->lifecycle_first_flag_clear_ordinal =
                    capture->event_instruction_ordinal;
            }
        }
        if (capture->lifecycle_destination_group != 0U
            || capture->lifecycle_destination_map != 0U) {
            uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
            if (save1 >= 0x02000000U
                && save1 + S61_SAVE_BLOCK1_SIZE <= 0x02040000U
                && (save1 & 3U) == 0U
                && read8(core, save1 + 4U)
                    == capture->lifecycle_destination_group
                && read8(core, save1 + 5U)
                    == capture->lifecycle_destination_map) {
                if (!capture->lifecycle_destination_map_observed) {
                    capture->lifecycle_destination_map_observed = true;
                    capture->lifecycle_first_destination_map_ordinal =
                        capture->event_instruction_ordinal;
                }
                if (read16(core, save1) == capture->lifecycle_destination_x
                    && read16(core, save1 + 2U)
                        == capture->lifecycle_destination_y
                    && !capture->lifecycle_destination_endpoint_observed) {
                    capture->lifecycle_destination_endpoint_observed = true;
                    capture->lifecycle_first_destination_endpoint_ordinal =
                        capture->event_instruction_ordinal;
                }
            }
        }
        if (capture->event_consumer_instruction_pc != 0U
            && instruction_pc == capture->event_consumer_instruction_pc) {
            if (capture->event_consumer_instruction_hits == 0U) {
                capture->event_first_consumer_raw_pc = raw_pc;
                capture->event_first_consumer_instruction_ordinal =
                    capture->event_instruction_ordinal;
            }
            ++capture->event_consumer_instruction_hits;
        }
        if (capture->event_resume_callback_pc != 0U
            && instruction_pc == capture->event_resume_callback_pc) {
            if (capture->event_resume_callback_hits == 0U)
                capture->event_first_resume_callback_ordinal =
                    capture->event_instruction_ordinal;
            ++capture->event_resume_callback_hits;
        }
        if (capture->event_callback_install_instruction_pc != 0U
            && instruction_pc
                == capture->event_callback_install_instruction_pc) {
            if (capture->event_callback_install_instruction_hits == 0U)
                capture->event_first_callback_install_ordinal =
                    capture->event_instruction_ordinal;
            ++capture->event_callback_install_instruction_hits;
        }
        if (capture->event_callback_dispatch_instruction_pc != 0U
            && instruction_pc
                == capture->event_callback_dispatch_instruction_pc) {
            if (capture->event_callback_dispatch_instruction_hits == 0U)
                capture->event_first_callback_dispatch_ordinal =
                    capture->event_instruction_ordinal;
            ++capture->event_callback_dispatch_instruction_hits;
        }
        if (capture->event_immediate_root_callsite_pc != 0U
            && instruction_pc
                == capture->event_immediate_root_callsite_pc) {
            uint32_t operand = (uint32_t)read_register(core, "r0");
            uint32_t save1 = world_save1(
                core, "immediate-map-script-callsite");
            if (capture->event_immediate_root_callsite_hits == 0U) {
                capture->event_first_immediate_root_callsite_operand =
                    operand;
                capture->event_first_immediate_root_callsite_ordinal =
                    capture->event_instruction_ordinal;
                capture->event_first_root_script_pointer = operand;
                capture->event_first_root_frame = core->frameCounter(core);
                capture->event_first_root_group = read8(core, save1 + 4U);
                capture->event_first_root_map = read8(core, save1 + 5U);
                capture->event_first_root_x = read16(core, save1);
                capture->event_first_root_y = read16(core, save1 + 2U);
                capture->event_root_entry_var_result =
                    read16(core, WORLD_SPECIAL_RESULT);
                capture->event_root_entry_var_result_seen = true;
                capture->event_first_root_ordinal =
                    capture->event_instruction_ordinal;
            }
            capture->event_last_immediate_root_callsite_operand = operand;
            capture->event_last_immediate_root_callsite_ordinal =
                capture->event_instruction_ordinal;
            capture->event_last_immediate_root_group =
                read8(core, save1 + 4U);
            capture->event_last_immediate_root_map =
                read8(core, save1 + 5U);
            capture->event_last_immediate_root_x = read16(core, save1);
            capture->event_last_immediate_root_y = read16(core, save1 + 2U);
            if (capture->event_root_script_pointer != 0U
                && operand == capture->event_root_script_pointer) {
                if (capture->event_immediate_expected_root_callsite_hits == 0U) {
                    capture->event_first_expected_root_script_pointer = operand;
                    capture->event_first_expected_root_frame =
                        core->frameCounter(core);
                    capture->event_first_expected_root_group =
                        read8(core, save1 + 4U);
                    capture->event_first_expected_root_map =
                        read8(core, save1 + 5U);
                    capture->event_first_expected_root_x =
                        read16(core, save1);
                    capture->event_first_expected_root_y =
                        read16(core, save1 + 2U);
                    capture->event_first_expected_root_ordinal =
                        capture->event_instruction_ordinal;
                    if (capture->event_map_condition_target_var != 0U) {
                        capture->event_map_condition_target_readback_exact =
                            s61_event_read_var_owner(
                                core,
                                capture->event_map_condition_target_var)
                            == capture->event_map_condition_target_value;
                        capture->event_map_precedence_guards_readback_exact =
                            true;
                        for (unsigned index = 0U;
                             index
                                 < capture->event_map_precedence_guard_count;
                             ++index) {
                            if (s61_event_read_var_owner(
                                    core,
                                    capture->event_map_precedence_guard_vars[
                                        index])
                                != capture->event_map_precedence_guard_values[
                                    index])
                                capture->
                                    event_map_precedence_guards_readback_exact =
                                        false;
                        }
                    }
                }
                if (capture->event_map_lifecycle_phase
                        == S61_MAP_LIFECYCLE_PHASE_FIELD_RETURN) {
                    if (capture->
                            event_map_field_return_expected_root_callsite_hits
                        == 0U) {
                        capture->
                            event_map_field_return_first_root_script_pointer =
                                operand;
                        capture->event_map_field_return_first_root_group =
                            read8(core, save1 + 4U);
                        capture->event_map_field_return_first_root_map =
                            read8(core, save1 + 5U);
                        capture->event_map_field_return_first_root_x =
                            read16(core, save1);
                        capture->event_map_field_return_first_root_y =
                            read16(core, save1 + 2U);
                        capture->event_map_field_return_first_root_ordinal =
                            capture->event_instruction_ordinal;
                    }
                    ++capture->
                        event_map_field_return_expected_root_callsite_hits;
                }
                ++capture->event_immediate_expected_root_callsite_hits;
            }
            ++capture->event_immediate_root_callsite_hits;
        }
        if (capture->event_immediate_root_executor_pc != 0U
            && instruction_pc
                == capture->event_immediate_root_executor_pc) {
            uint32_t operand = (uint32_t)read_register(core, "r0");
            if (capture->event_immediate_root_executor_hits == 0U) {
                capture->event_first_immediate_root_executor_operand =
                    operand;
                capture->event_first_immediate_root_executor_ordinal =
                    capture->event_instruction_ordinal;
            }
            capture->event_last_immediate_root_executor_operand = operand;
            capture->event_last_immediate_root_executor_ordinal =
                capture->event_instruction_ordinal;
            if (capture->event_root_script_pointer != 0U
                && operand == capture->event_root_script_pointer)
                ++capture->event_immediate_expected_root_executor_hits;
            ++capture->event_immediate_root_executor_hits;
        }
        if (capture->event_root_script_pointer != 0U
            && world_script_enabled(core)) {
            uint32_t script_pointer = read32(
                core, WORLD_SCRIPT_CONTEXT1_POINTER);
            if (script_pointer == capture->event_root_script_pointer) {
                if (capture->event_root_script_pointer_hits == 0U) {
                    capture->event_first_root_script_pointer = script_pointer;
                    capture->event_first_root_frame =
                        core->frameCounter(core);
                    uint32_t save1 = read32(
                        core, BOOTSTRAP_SAVE_BLOCK1_PTR);
                    if (save1 < 0x02000000U || save1 >= 0x02040000U
                        || (save1 & 3U) != 0U)
                        s61_die("event runtime root-hit SaveBlock1 is invalid");
                    capture->event_first_root_group = read8(core, save1 + 4U);
                    capture->event_first_root_map = read8(core, save1 + 5U);
                    capture->event_first_root_x = read16(core, save1);
                    capture->event_first_root_y = read16(core, save1 + 2U);
                    capture->event_root_entry_var_result =
                        read16(core, WORLD_SPECIAL_RESULT);
                    capture->event_root_entry_var_result_seen = true;
                    capture->event_first_root_ordinal =
                        capture->event_instruction_ordinal;
                }
                ++capture->event_root_script_pointer_hits;
            }
            if (capture->event_caller_script_pointer != 0U
                && script_pointer == capture->event_caller_script_pointer) {
                if (capture->event_caller_script_pointer_hits == 0U) {
                    capture->event_first_caller_script_pointer =
                        script_pointer;
                    capture->event_first_caller_frame =
                        core->frameCounter(core);
                    capture->event_first_caller_ordinal =
                        capture->event_instruction_ordinal;
                }
                ++capture->event_caller_script_pointer_hits;
            }
            if (capture->event_alternate_script_pointer != 0U
                && script_pointer
                    == capture->event_alternate_script_pointer) {
                if (capture->event_alternate_script_pointer_hits == 0U) {
                    capture->event_first_alternate_frame =
                        core->frameCounter(core);
                    capture->event_first_alternate_ordinal =
                        capture->event_instruction_ordinal;
                }
                ++capture->event_alternate_script_pointer_hits;
            }
            if (capture->lifecycle_set_script_pointer != 0U
                && script_pointer == capture->lifecycle_set_script_pointer) {
                if (capture->lifecycle_set_script_pointer_hits == 0U)
                    capture->lifecycle_first_set_site_ordinal =
                        capture->event_instruction_ordinal;
                ++capture->lifecycle_set_script_pointer_hits;
            }
            if (capture->lifecycle_map_root_script_pointer != 0U
                && script_pointer
                    == capture->lifecycle_map_root_script_pointer) {
                if (capture->lifecycle_map_root_script_pointer_hits == 0U)
                    capture->lifecycle_first_map_root_ordinal =
                        capture->event_instruction_ordinal;
                ++capture->lifecycle_map_root_script_pointer_hits;
            }
            if (capture->lifecycle_clear_script_pointer != 0U
                && script_pointer
                    == capture->lifecycle_clear_script_pointer) {
                if (capture->lifecycle_clear_script_pointer_hits == 0U)
                    capture->lifecycle_first_clear_site_ordinal =
                        capture->event_instruction_ordinal;
                ++capture->lifecycle_clear_script_pointer_hits;
            }
        }
        s61_sample_facility_execution(core, capture, instruction_pc);
        if (s61_active_facility_execution != NULL
            && s61_active_facility_execution->active_boundary_observed) {
            core->setKeys(core, 0U);
            return;
        }
        bool watched = capture->watched_instruction_pc != 0U
            && (instruction_pc == capture->watched_instruction_pc
                || (raw_pc & ~1U) == capture->watched_instruction_pc);
        if (capture->watched_script_pointer_start != 0U) {
            uint32_t script_pointer = read32(
                core, WORLD_SCRIPT_CONTEXT1_POINTER);
            if (script_pointer >= capture->watched_script_pointer_start
                && script_pointer <= capture->watched_script_pointer_end) {
                if (capture->watched_script_pointer_hits == 0U)
                    capture->watched_first_script_pointer = script_pointer;
                ++capture->watched_script_pointer_hits;
            }
        }
        if (watched) {
            if (capture->watched_instruction_hits == 0U)
                capture->watched_first_before_pc = raw_pc;
            ++capture->watched_instruction_hits;
        }
        if (!capture->suppress_semantic_content)
            s61_capture_printer_call(core, capture);
        s61_rfu_scheduler_step_local(core);
        if (capture->track_var_result_instructions)
            s61_sample_post_battle_instruction(core);
        s61_stale_runtime_diag_after_step(core, instruction_pc);
        s61_sample_internal_controls(core);
        if (watched && capture->watched_first_after_pc == 0U)
            capture->watched_first_after_pc =
                (uint32_t)read_register(core, "pc");
        if (s61_capture_invalid_control_flow(core, capture))
            return;
        if (core->frameCounter(core) != before)
            s61_capture_frame(core, capture);
    }
}

static void s61_step_capture_pulse(struct mCore *core, uint16_t key,
                                   unsigned pressed, unsigned released,
                                   struct S61Capture *capture)
{
    s61_step_capture_frames(core, key, pressed, capture);
    s61_step_capture_frames(core, 0U, released, capture);
}

static void s61_frames(struct mCore *core, uint16_t keys, unsigned frames,
                       struct S61Capture *capture)
{
    /* Event post-battle continuation deliberately has no semantic/text
     * capture in this phase, but its already-declared effect watch PCs still
     * belong to the active case.  Preserve instruction-level effect sampling
     * without manufacturing a S61Capture or observing battle-engine PCs that
     * are absent from the watch plan. */
    if (capture == NULL && s61_effect_observer.enabled
        && s61_effect_observer.active_case[0] != '\0') {
        core->setKeys(core, keys);
        uint32_t first_frame = core->frameCounter(core);
        while ((uint32_t)(core->frameCounter(core) - first_frame) < frames) {
            uint32_t raw_pc = (uint32_t)read_register(core, "pc");
            s61_effect_observer_sample_pc(core, raw_pc);
            core->step(core);
        }
        return;
    }
    core->setKeys(core, keys);
    for (unsigned frame = 0U; frame < frames; ++frame) {
        core->runFrame(core);
        if (capture != NULL)
            s61_capture_frame(core, capture);
    }
}

static void s61_pulse(struct mCore *core, uint16_t key,
                      unsigned pressed, unsigned released,
                      struct S61Capture *capture)
{
    if (capture != NULL) {
        s61_step_capture_pulse(core, key, pressed, released, capture);
        return;
    }
    s61_frames(core, key, pressed, capture);
    s61_frames(core, 0U, released, capture);
}

static struct Fixture s61_world_fixture(const char *name,
                                        const struct S61Interaction *source)
{
    struct Fixture fixture = {
        .name = name,
        .kind = FIXTURE_FACING_DIALOGUE,
        .group = source->group,
        .map = source->map,
        .x = source->start_x,
        .y = source->start_y,
        .action_key = source->action_key,
        .item = 0U,
        .flag = 0U,
        .trainer = 0U,
        .local_id = source->local_id,
    };
    return fixture;
}

static void s61_save_path(char *destination, size_t size,
                          const char *directory, const char *suffix)
{
    int length = snprintf(destination, size, "%s/%s.srm", directory, suffix);
    if (length <= 0 || (size_t)length >= size)
        s61_die("save path formatting failed");
}

static void s61_assert_trainer_tower_local_fallback_precondition(
    struct mCore *core, bool allow_blank_sector31)
{
    /* JP ReadTrainerTowerAndValidate first asks TryReadSpecialSaveSector for
     * physical sectors 30 and 31.  The special-sector sentinel is 0xB39D in
     * the first little-endian u32.  Stage61's canonical save lifecycle owns
     * sector 31 for the modern VGS1 image and leaves sector 30 erased; accept
     * only those exact canonical heads before title Continue can execute any
     * map/event owner.  The generation process also gates its initial erased
     * sector31 (FFFFFFFF) immediately before the first stock warp; after the
     * two canonical saves only 00000000 is accepted.  An imported eReader
     * save is deliberately out of scope and therefore fails closed here. */
    s61_flash_select_bank(core, 1U);
    uint32_t sector30_first = read32(core, WORLD_SECTOR30_FLASH);
    uint32_t sector31_first = read32(core, WORLD_SECTOR31_FLASH);
    s61_flash_select_bank(core, 0U);
    if (sector30_first != UINT32_C(0xFFFFFFFF)
        || (sector31_first != UINT32_C(0x00000000)
            && (!allow_blank_sector31
                || sector31_first != UINT32_C(0xFFFFFFFF)))) {
        fprintf(stderr,
                "Trainer Tower canonical-save precondition failed: "
                "sector30_first_u32=%08" PRIX32
                " sector31_first_u32=%08" PRIX32 "\n",
                sector30_first, sector31_first);
        s61_die("external/eReader save is outside Stage61 runner scope");
    }
}

static struct mCore *s61_open_fresh(const char *rom_path,
                                    const char *save_path,
                                    const struct Fixture *fixture)
{
    memset(s61_video, 0, sizeof(s61_video));
    bool previous_implicit_rtc_notice =
        s61_implicitly_allow_savedata_time_offset_notice;
    s61_implicitly_allow_savedata_time_offset_notice = true;
    struct mCore *core = bootstrap_open_core(rom_path, save_path, s61_video);
    s61_implicitly_allow_savedata_time_offset_notice =
        previous_implicit_rtc_notice;
    s61_diagnostic_core = core;
    s61_illegal_opcode_dumped = false;
    s61_assert_trainer_tower_local_fallback_precondition(core, false);
    world_continue(core, fixture);
    world_wait_player_ready(core, fixture);
    return core;
}

static const struct S61ExternalControl *s61_catalog_rfu_control(
    const struct S61CatalogRow *row)
{
    const struct S61ExternalControl *result = NULL;
    for (unsigned index = 0U; index < row->external_control_count; ++index) {
        const struct S61ExternalControl *control =
            &row->external_controls[index];
        if (control->kind != S61_CONTROL_RFU_SESSION
            && control->kind != S61_CONTROL_CENTER_LINK_SESSION)
            continue;
        if (result != NULL)
            s61_die("catalog row has more than one link-session owner");
        result = control;
    }
    return result;
}

static void s61_prepare_rfu_var_result_preimage(
    struct mCore *core, const struct S61CatalogRow *row)
{
    const struct S61ExternalControl *control = s61_catalog_rfu_control(row);
    if (control == NULL)
        return;
    if (s61_rfu_attempt.active)
        s61_die("RFU VAR_RESULT preimage write occurred in active attempt");
    write16(core, WORLD_SPECIAL_RESULT, 0xFFFFU);
    if (read16(core, WORLD_SPECIAL_RESULT) != 0xFFFFU)
        s61_die("RFU VAR_RESULT quiescent preimage did not commit");
    if (control->kind == S61_CONTROL_CENTER_LINK_SESSION) {
        /* Sentinel-only writes prove that the expected selector later came
         * from the physical event script.  The harness never injects the
         * requested group or a minigame mode. */
        write16(core, WORLD_SPECIAL_VAR_8004, 0xFFFFU);
        write16(core, WORLD_SPECIAL_VAR_8005, 0xFFFFU);
        if (read16(core, WORLD_SPECIAL_VAR_8004) != 0xFFFFU
            || read16(core, WORLD_SPECIAL_VAR_8005) != 0xFFFFU)
            s61_die("center-link selector sentinel preimage did not commit");
    }
}

static unsigned s61_rfu_minigame_peer_program(
    uint16_t special, uint8_t mode, uint16_t *keys, unsigned capacity)
{
    /* These are harness-owned, fixed physical key programs.  They are never
     * accepted from TSV.  Peers select the same minigame mode as the local
     * endpoint and the complementary leader/join role. */
    static const uint16_t join_mode0[] = {
        WORLD_KEY_A, WORLD_KEY_A, WORLD_KEY_A, WORLD_KEY_A,
        WORLD_KEY_A, WORLD_KEY_B, WORLD_KEY_A, WORLD_KEY_B,
        WORLD_KEY_A, WORLD_KEY_B, WORLD_KEY_A,
    };
    static const uint16_t join_mode1[] = {
        WORLD_KEY_A, WORLD_KEY_A, WORLD_KEY_DOWN, WORLD_KEY_A,
        WORLD_KEY_A, WORLD_KEY_A, WORLD_KEY_B, WORLD_KEY_A,
        WORLD_KEY_B, WORLD_KEY_A, WORLD_KEY_B, WORLD_KEY_A,
    };
    static const uint16_t leader_mode0[] = {
        WORLD_KEY_A, WORLD_KEY_A, WORLD_KEY_A, WORLD_KEY_A,
        WORLD_KEY_DOWN, WORLD_KEY_A, WORLD_KEY_B, WORLD_KEY_A,
        WORLD_KEY_B, WORLD_KEY_A, WORLD_KEY_B, WORLD_KEY_A,
    };
    static const uint16_t leader_mode1[] = {
        WORLD_KEY_A, WORLD_KEY_A, WORLD_KEY_DOWN, WORLD_KEY_A,
        WORLD_KEY_A, WORLD_KEY_DOWN, WORLD_KEY_A, WORLD_KEY_B,
        WORLD_KEY_A, WORLD_KEY_B, WORLD_KEY_A, WORLD_KEY_B,
        WORLD_KEY_A,
    };
    const uint16_t *program;
    unsigned count;
    bool peer_is_leader = special == 364U;
    if (peer_is_leader && mode == 0U) {
        program = leader_mode0;
        count = ARRAY_LEN(leader_mode0);
    } else if (peer_is_leader) {
        program = leader_mode1;
        count = ARRAY_LEN(leader_mode1);
    } else if (mode == 0U) {
        program = join_mode0;
        count = ARRAY_LEN(join_mode0);
    } else {
        program = join_mode1;
        count = ARRAY_LEN(join_mode1);
    }
    if (count > capacity)
        s61_die("RFU fixed peer program exceeds local bound");
    memcpy(keys, program, count * sizeof(*keys));
    return count;
}

static void s61_rfu_program_append(
    uint16_t *keys, unsigned *count, unsigned capacity, uint16_t key)
{
    if (*count >= capacity)
        s61_die("RFU fixed peer program exceeds local bound");
    keys[(*count)++] = key;
}

static unsigned s61_center_link_peer_program(
    uint8_t link_group, uint16_t peer_special,
    uint16_t *keys, unsigned capacity)
{
    /* Source-menu projection for Direct Corner attendant:
     * service -> optional battle subtype/confirmation -> stock save -> role.
     * The trailing B/A pulses keep asynchronous wait/cancel/retry screens
     * progressing without accepting an executable program from TSV. */
    unsigned count = 0U;
    s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
    s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
    if (link_group == 3U) {
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
    } else if (link_group <= 2U) {
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_DOWN);
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
        for (unsigned index = 0U; index < link_group; ++index)
            s61_rfu_program_append(
                keys, &count, capacity, WORLD_KEY_DOWN);
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
    } else if (link_group == 5U) {
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_DOWN);
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_DOWN);
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
    } else {
        s61_die("center-link fixed peer program group is outside registry");
    }
    for (unsigned index = 0U; index < 4U; ++index)
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
    if (peer_special == 363U)
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_DOWN);
    else if (peer_special != 364U)
        s61_die("center-link fixed peer program role is outside registry");
    s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
    for (unsigned index = 0U; index < 3U; ++index) {
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_B);
        s61_rfu_program_append(keys, &count, capacity, WORLD_KEY_A);
    }
    return count;
}

static unsigned s61_rfu_peer_program(
    const struct S61ExternalControl *control, unsigned slot,
    uint16_t *keys, unsigned capacity)
{
    if (control->kind == S61_CONTROL_RFU_SESSION)
        return s61_rfu_minigame_peer_program(
            (uint16_t)control->id, (uint8_t)control->values[1],
            keys, capacity);
    if (control->kind != S61_CONTROL_CENTER_LINK_SESSION
        || slot == 0U || slot >= control->values[0])
        s61_die("center-link peer program lifecycle is outside registry");
    return s61_center_link_peer_program(
        (uint8_t)control->values[1],
        s61_rfu_attempt.endpoint_roles[slot], keys, capacity);
}

static void s61_rfu_update_peer_keys(unsigned slot)
{
    struct mCore *core = s61_rfu_attempt.cores[slot];
    const struct S61ExternalControl *control = s61_rfu_attempt.control;
    uint16_t program[32U];
    unsigned count = s61_rfu_peer_program(
        control, slot, program, ARRAY_LEN(program));
    uint32_t elapsed = core->frameCounter(core)
        - s61_rfu_attempt.peer_start_frame[slot];
    unsigned token = elapsed / 47U;
    unsigned phase = elapsed % 47U;
    core->setKeys(core, token < count && phase < 2U ? program[token] : 0U);
}

static void s61_rfu_observe_center_selectors(unsigned slot)
{
    const struct S61ExternalControl *control = s61_rfu_attempt.control;
    if (control == NULL
        || control->kind != S61_CONTROL_CENTER_LINK_SESSION)
        return;
    uint16_t link_group = read16(
        s61_rfu_attempt.cores[slot], WORLD_SPECIAL_VAR_8004);
    uint16_t mode = read16(
        s61_rfu_attempt.cores[slot], WORLD_SPECIAL_VAR_8005);
    if (link_group == (uint16_t)control->values[1])
        s61_rfu_attempt.selector_observed[slot] = true;
    else if (link_group != 0xFFFFU)
        s61_rfu_attempt.unexpected_link_group_observed = true;
    if (mode != 0xFFFFU)
        s61_rfu_attempt.mode_selector_write_observed = true;
}

static bool s61_rfu_topology_is_discovered(void)
{
    if (!s61_rfu_attempt.active)
        return false;
    unsigned count = (unsigned)s61_rfu_attempt.control->values[0];
    if (count == 1U)
        return true;
    for (unsigned slot = 0U; slot < count; ++slot) {
        if (Stage61RfuPeripheralSignal(
                s61_rfu_attempt.peripherals[slot]) == 0U)
            return false;
    }
    return true;
}

static void s61_rfu_update_fault_lifecycle(void)
{
    const struct S61ExternalControl *control = s61_rfu_attempt.control;
    if (!s61_rfu_attempt.active)
        return;
    if (!s61_rfu_attempt.topology_discovered
        && s61_rfu_topology_is_discovered())
        s61_rfu_attempt.topology_discovered = true;
    uint32_t fault_code = control->values[5];
    struct Stage61RfuScenario observed;
    if (fault_code != 0U && s61_rfu_attempt.topology_discovered
        && !s61_rfu_attempt.initial_fault_armed) {
        struct Stage61RfuScenario scenario = {
            .adapterPresent = true,
            .faultMode = fault_code == 1U
                ? STAGE61_RFU_FAULT_REJECT_NEXT
                : STAGE61_RFU_FAULT_DISCONNECT_NEXT,
            .rejectCommand = 0U,
            .transferCycles = 0U,
        };
        size_t trace_index = Stage61RfuPeripheralTraceCount(
            s61_rfu_attempt.peripherals[0]);
        if (Stage61RfuPeripheralConfigure(
                s61_rfu_attempt.peripherals[0], &scenario)) {
            s61_rfu_attempt.initial_fault_trace_index = trace_index;
            s61_rfu_attempt.initial_fault_armed = true;
        }
    }
    if (s61_rfu_attempt.initial_fault_armed
        && !s61_rfu_attempt.initial_fault_consumed
        && Stage61RfuPeripheralGetScenario(
            s61_rfu_attempt.peripherals[0], &observed)
        && observed.faultMode == STAGE61_RFU_FAULT_NONE)
        s61_rfu_attempt.initial_fault_consumed = true;
    if (s61_rfu_attempt.retry_fault_reconfigured
        && !s61_rfu_attempt.retry_fault_consumed
        && Stage61RfuPeripheralGetScenario(
            s61_rfu_attempt.peripherals[0], &observed)
        && observed.faultMode == STAGE61_RFU_FAULT_NONE)
        s61_rfu_attempt.retry_fault_consumed = true;
    if (fault_code != 3U || !s61_rfu_attempt.initial_fault_consumed
        || s61_rfu_attempt.retry_fault_reconfigured
        || read16(s61_rfu_attempt.cores[0], WORLD_SPECIAL_RESULT) != 8U)
        return;
    struct Stage61RfuScenario scenario = {
        .adapterPresent = true,
        .faultMode = STAGE61_RFU_FAULT_REJECT_NEXT,
        .rejectCommand = 0U,
        .transferCycles = 0U,
    };
    size_t trace_index = Stage61RfuPeripheralTraceCount(
        s61_rfu_attempt.peripherals[0]);
    if (Stage61RfuPeripheralConfigure(
            s61_rfu_attempt.peripherals[0], &scenario)) {
        s61_rfu_attempt.retry_fault_trace_index = trace_index;
        s61_rfu_attempt.retry_fault_reconfigured = true;
    }
}

static void s61_rfu_scheduler_step_local(struct mCore *local_core)
{
    if (!s61_rfu_attempt.active) {
        local_core->step(local_core);
        return;
    }
    if (local_core != s61_rfu_attempt.cores[0])
        s61_die("RFU scheduler local core identity differs");
    for (unsigned guard = 0U; guard < 100000U; ++guard) {
        uint64_t minimum = UINT64_MAX;
        uint64_t maximum = 0U;
        unsigned selected = 0U;
        unsigned ties = 0U;
        unsigned count = (unsigned)s61_rfu_attempt.control->values[0];
        for (unsigned slot = 0U; slot < count; ++slot) {
            uint64_t now = mTimingGlobalTime(
                s61_rfu_attempt.cores[slot]->timing);
            if (now < minimum) {
                minimum = now;
                selected = slot;
                ties = 1U;
            } else if (now == minimum) {
                ++ties;
            }
            if (now > maximum)
                maximum = now;
        }
        if (ties > 1U)
            ++s61_rfu_attempt.scheduler_tie_breaks;
        uint64_t skew = maximum - minimum;
        if (skew > s61_rfu_attempt.scheduler_max_skew)
            s61_rfu_attempt.scheduler_max_skew = skew;
        if (selected != 0U)
            s61_rfu_update_peer_keys(selected);
        s61_rfu_attempt.cores[selected]->step(
            s61_rfu_attempt.cores[selected]);
        s61_rfu_observe_center_selectors(selected);
        ++s61_rfu_attempt.scheduler_iterations;
        ++s61_rfu_attempt.scheduler_slot_steps[selected];
        s61_rfu_update_fault_lifecycle();
        if (selected == 0U)
            return;
    }
    s61_die("RFU scheduler did not select local core within bound");
}

static bool s61_rfu_attempt_cleanup(void)
{
    for (unsigned slot = 0U; slot < STAGE61_RFU_MAX_ENDPOINTS; ++slot) {
        if (s61_rfu_attempt.peripherals[slot] != NULL)
            Stage61RfuPeripheralDetach(
                s61_rfu_attempt.peripherals[slot]);
    }
    for (unsigned slot = 1U; slot < STAGE61_RFU_MAX_ENDPOINTS; ++slot) {
        struct mCore *peer = s61_rfu_attempt.cores[slot];
        color_t *video = s61_rfu_attempt.peer_video[slot];
        s61_rfu_attempt.cores[slot] = NULL;
        s61_rfu_attempt.peer_video[slot] = NULL;
        if (peer != NULL)
            s61_bootstrap_close_core(peer);
        free(video);
    }
    for (unsigned slot = 0U; slot < STAGE61_RFU_MAX_ENDPOINTS; ++slot) {
        struct Stage61RfuPeripheral *peripheral =
            s61_rfu_attempt.peripherals[slot];
        s61_rfu_attempt.peripherals[slot] = NULL;
        if (peripheral != NULL)
            Stage61RfuPeripheralDestroy(peripheral);
    }
    struct Stage61RfuHub *hub = s61_rfu_attempt.hub;
    s61_rfu_attempt.hub = NULL;
    bool hub_destroyed = hub == NULL || Stage61RfuHubDestroy(hub);
    memset(&s61_rfu_attempt, 0, sizeof(s61_rfu_attempt));
    return hub_destroyed;
}

static void s61_rfu_attempt_begin(
    struct mCore *local_core, const char *rom_path, const char *save_path,
    const void *interaction_state, size_t state_size,
    const struct S61ExternalControl *control,
    const struct S61CatalogRow *row)
{
    if (control == NULL)
        return;
    if (s61_rfu_attempt.active || interaction_state == NULL
        || state_size == 0U || !s61_link_session_registry_tuple(control))
        s61_die("RFU attempt begin received invalid lifecycle/scenario");
    memset(&s61_rfu_attempt, 0, sizeof(s61_rfu_attempt));
    s61_rfu_attempt.control = control;
    s61_rfu_attempt.owner_key = row == NULL ? NULL : row->owner_key;
    s61_rfu_attempt.calling_root = row == NULL ? 0U : row->runtime_root;
    s61_rfu_attempt.cores[0] = local_core;
    s61_rfu_attempt.endpoint_roles[0] = (uint16_t)control->id;
    if (control->kind == S61_CONTROL_CENTER_LINK_SESSION) {
        s61_rfu_attempt.selector_preimage_sentinel_written =
            read16(local_core, WORLD_SPECIAL_VAR_8004) == 0xFFFFU
            && read16(local_core, WORLD_SPECIAL_VAR_8005) == 0xFFFFU;
        if (!s61_rfu_attempt.selector_preimage_sentinel_written)
            s61_die("center-link selector preimage was not quiescent");
    }
    s61_rfu_attempt.hub = Stage61RfuHubCreate();
    if (s61_rfu_attempt.hub == NULL)
        s61_die("RFU hub allocation failed");
    unsigned count = (unsigned)control->values[0];
    for (unsigned slot = 0U; slot < count; ++slot) {
        if (slot != 0U)
            s61_rfu_attempt.endpoint_roles[slot] =
                control->kind == S61_CONTROL_CENTER_LINK_SESSION
                && control->id == 364U && slot > 1U
                    ? 364U : control->id == 363U ? 364U : 363U;
        if (slot != 0U) {
            s61_rfu_attempt.peer_video[slot] = calloc(
                240U * 160U, sizeof(color_t));
            if (s61_rfu_attempt.peer_video[slot] == NULL)
                s61_die("RFU peer framebuffer allocation failed");
            s61_rfu_attempt.cores[slot] = s61_bootstrap_open_core(
                rom_path, save_path, s61_rfu_attempt.peer_video[slot]);
            if (s61_rfu_attempt.cores[slot] == NULL
                || !s61_rfu_attempt.cores[slot]->loadState(
                    s61_rfu_attempt.cores[slot], interaction_state))
                s61_die("RFU peer quiescent savestate load failed");
            if (control->kind == S61_CONTROL_CENTER_LINK_SESSION
                && (read16(
                        s61_rfu_attempt.cores[slot],
                        WORLD_SPECIAL_VAR_8004) != 0xFFFFU
                    || read16(
                        s61_rfu_attempt.cores[slot],
                        WORLD_SPECIAL_VAR_8005) != 0xFFFFU))
                s61_die("center-link peer selector preimage was not quiescent");
        }
        s61_rfu_attempt.peripherals[slot] = Stage61RfuPeripheralCreate(
            s61_rfu_attempt.hub);
        if (s61_rfu_attempt.peripherals[slot] == NULL)
            s61_die("RFU endpoint allocation failed");
        struct Stage61RfuScenario scenario = {
            .adapterPresent = true,
            .faultMode = STAGE61_RFU_FAULT_NONE,
            .rejectCommand = 0U,
            .transferCycles = 0U,
        };
        if (!Stage61RfuPeripheralConfigure(
                s61_rfu_attempt.peripherals[slot], &scenario))
            s61_die("RFU endpoint scenario configure failed");
    }
    if (!Stage61RfuHubIsQuiescent(s61_rfu_attempt.hub))
        s61_die("RFU endpoints were not quiescent before attach");
    s61_rfu_attempt.quiescent_load_before_attach = true;
    for (unsigned slot = 0U; slot < count; ++slot) {
        struct GBA *gba = (struct GBA *)s61_rfu_attempt.cores[slot]->board;
        if (gba == NULL || !Stage61RfuPeripheralAttach(
                s61_rfu_attempt.peripherals[slot], &gba->sio))
            s61_die("RFU endpoint attach failed");
    }
    if (!Stage61RfuHubReset(s61_rfu_attempt.hub))
        s61_die("RFU hub reset after quiescent loads failed");
    s61_rfu_attempt.reset_epoch = 1U;
    s61_rfu_attempt.hub_reset_after_all_loads = true;
    for (unsigned slot = 1U; slot < count; ++slot)
        s61_rfu_attempt.peer_start_frame[slot] =
            s61_rfu_attempt.cores[slot]->frameCounter(
                s61_rfu_attempt.cores[slot]);
    s61_rfu_attempt.active = true;
}

static void s61_rfu_collect_observed_results(
    const struct S61Capture *capture, struct S61RfuAttemptEvidence *evidence)
{
    for (unsigned index = 0U; index < capture->var_result_value_count;
         ++index) {
        uint16_t value = capture->var_result_values[index];
        if (value != 1U && value != 5U && value != 6U && value != 8U)
            continue;
        if (evidence->observed_result_count != 0U
            && evidence->observed_results[
                evidence->observed_result_count - 1U] == value)
            continue;
        if (evidence->observed_result_count >= 2U) {
            evidence->observed_result_count = 3U;
            return;
        }
        evidence->observed_results[evidence->observed_result_count++] =
            (uint8_t)value;
    }
}

static void s61_rfu_attempt_end(
    const struct S61Capture *capture, struct S61RfuAttemptEvidence *evidence)
{
    memset(evidence, 0, sizeof(*evidence));
    if (!s61_rfu_attempt.active)
        return;
    const struct S61ExternalControl *control = s61_rfu_attempt.control;
    unsigned count = (unsigned)control->values[0];
    evidence->applicable = true;
    evidence->scenario_id = control->scenario_id;
    evidence->special = (uint16_t)control->id;
    evidence->center_link_session =
        control->kind == S61_CONTROL_CENTER_LINK_SESSION;
    evidence->owner_key = s61_rfu_attempt.owner_key;
    evidence->calling_root = s61_rfu_attempt.calling_root;
    if (evidence->center_link_session) {
        evidence->link_group = (uint8_t)control->values[1];
        evidence->activity = control->activity;
        evidence->capacity_min = (uint8_t)control->values[6];
        evidence->capacity_max = (uint8_t)control->values[7];
        evidence->topology_policy = control->topology_policy;
    } else {
        evidence->activity_mode = (uint8_t)control->values[1];
    }
    evidence->endpoint_count = (uint8_t)count;
    evidence->expected_result_count = (uint8_t)control->values[2];
    evidence->expected_results[0] = (uint8_t)control->values[3];
    if (evidence->expected_result_count == 2U)
        evidence->expected_results[1] = (uint8_t)control->values[4];
    evidence->fault_code = (uint8_t)control->values[5];
    evidence->reset_epoch = s61_rfu_attempt.reset_epoch;
    evidence->host_memory_writes = s61_rfu_attempt.host_memory_writes;
    evidence->quiescent_load_before_attach =
        s61_rfu_attempt.quiescent_load_before_attach;
    evidence->hub_reset_after_all_loads =
        s61_rfu_attempt.hub_reset_after_all_loads;
    evidence->exchange_isolated_used =
        s61_rfu_attempt.exchange_isolated_used;
    evidence->topology_discovered = s61_rfu_attempt.topology_discovered;
    evidence->selector_preimage_sentinel_written =
        s61_rfu_attempt.selector_preimage_sentinel_written;
    evidence->unexpected_link_group_observed =
        s61_rfu_attempt.unexpected_link_group_observed;
    evidence->mode_selector_write_observed =
        s61_rfu_attempt.mode_selector_write_observed;
    memcpy(evidence->endpoint_roles, s61_rfu_attempt.endpoint_roles,
           sizeof(evidence->endpoint_roles));
    for (unsigned slot = 0U; slot < count; ++slot) {
        if (s61_rfu_attempt.selector_observed[slot])
            ++evidence->selector_observed_endpoint_count;
        if (evidence->endpoint_roles[slot] == 363U)
            ++evidence->leader_endpoint_count;
        else if (evidence->endpoint_roles[slot] == 364U)
            ++evidence->join_endpoint_count;
    }
    evidence->initial_fault_armed = s61_rfu_attempt.initial_fault_armed;
    evidence->initial_fault_consumed =
        s61_rfu_attempt.initial_fault_consumed;
    evidence->scheduler_iterations = s61_rfu_attempt.scheduler_iterations;
    evidence->scheduler_tie_breaks = s61_rfu_attempt.scheduler_tie_breaks;
    evidence->scheduler_max_skew = s61_rfu_attempt.scheduler_max_skew;
    evidence->retry_fault_reconfigured =
        s61_rfu_attempt.retry_fault_reconfigured;
    evidence->retry_fault_consumed = s61_rfu_attempt.retry_fault_consumed;
    memcpy(evidence->scheduler_slot_steps,
           s61_rfu_attempt.scheduler_slot_steps,
           sizeof(evidence->scheduler_slot_steps));
    s61_rfu_collect_observed_results(capture, evidence);
    evidence->segment_count = evidence->observed_result_count > 2U
        ? 2U : evidence->observed_result_count;
    bool endpoints_exact = true;
    bool initial_fault_trace = false;
    bool retry_fault_trace = false;
    uint16_t stations[STAGE61_RFU_MAX_ENDPOINTS] = {0};
    for (unsigned slot = 0U; slot < count; ++slot) {
        struct S61RfuEndpointEvidence *endpoint = &evidence->endpoints[slot];
        struct Stage61RfuPeripheral *peripheral =
            s61_rfu_attempt.peripherals[slot];
        endpoint->trace_count = Stage61RfuPeripheralTraceCount(peripheral);
        endpoint->trace_hash = Stage61RfuPeripheralTraceHash(peripheral);
        endpoint->station_id = Stage61RfuPeripheralStationId(peripheral);
        endpoint->host_bitmap = Stage61RfuPeripheralHostBitmap(peripheral);
        endpoint->signal = Stage61RfuPeripheralSignal(peripheral);
        endpoint->healthy = Stage61RfuPeripheralHealthy(peripheral);
        endpoint->overflow = Stage61RfuPeripheralTraceOverflowed(peripheral);
        stations[slot] = endpoint->station_id;
        for (size_t trace_index = 0U;
             trace_index < endpoint->trace_count; ++trace_index) {
            struct Stage61RfuTraceEntry entry;
            if (!Stage61RfuPeripheralTraceRead(
                    peripheral, trace_index, &entry))
                s61_die("RFU trace read failed inside reported bound");
            if (entry.kind == STAGE61_RFU_TRACE_REJECTION)
                ++endpoint->rejection_count;
            if (slot == 0U
                && entry.kind == STAGE61_RFU_TRACE_REJECTION
                && trace_index
                    >= s61_rfu_attempt.initial_fault_trace_index
                && (!s61_rfu_attempt.retry_fault_reconfigured
                    || trace_index
                        < s61_rfu_attempt.retry_fault_trace_index))
                initial_fault_trace = true;
            if (slot == 0U
                && entry.kind == STAGE61_RFU_TRACE_REJECTION
                && s61_rfu_attempt.retry_fault_reconfigured
                && trace_index >= s61_rfu_attempt.retry_fault_trace_index)
                retry_fault_trace = true;
            if (slot == 0U && control->values[5] >= 2U
                && entry.kind == STAGE61_RFU_TRACE_REJECTION
                && trace_index
                    >= s61_rfu_attempt.initial_fault_trace_index
                && (!s61_rfu_attempt.retry_fault_reconfigured
                    || trace_index
                        < s61_rfu_attempt.retry_fault_trace_index))
                ++endpoint->disconnect_count;
        }
        endpoint->exact = endpoint->trace_count != 0U
            && endpoint->healthy && !endpoint->overflow;
        for (unsigned prior = 0U; prior < slot; ++prior) {
            if (stations[prior] == stations[slot])
                endpoint->exact = false;
        }
        endpoints_exact = endpoints_exact && endpoint->exact;
    }
    bool results_exact = evidence->observed_result_count
            == evidence->expected_result_count
        && memcmp(evidence->observed_results, evidence->expected_results,
                  evidence->expected_result_count) == 0;
    bool initial_fault_exact = control->values[5] == 0U
        ? !evidence->initial_fault_armed
            && !evidence->initial_fault_consumed
        : evidence->initial_fault_armed
            && evidence->initial_fault_consumed && initial_fault_trace;
    bool retry_fault_exact = control->values[5] != 3U
        ? !evidence->retry_fault_reconfigured
            && !evidence->retry_fault_consumed
        : evidence->retry_fault_reconfigured
            && evidence->retry_fault_consumed && retry_fault_trace;
    bool scheduler_exact = evidence->scheduler_iterations != 0U;
    for (unsigned slot = 0U; slot < count; ++slot)
        scheduler_exact = scheduler_exact
            && evidence->scheduler_slot_steps[slot] != 0U;
    evidence->exact = results_exact && endpoints_exact
        && initial_fault_exact && retry_fault_exact
        && evidence->topology_discovered
        && evidence->reset_epoch == 1U
        && evidence->host_memory_writes == 0U
        && evidence->quiescent_load_before_attach
        && evidence->hub_reset_after_all_loads
        && !evidence->exchange_isolated_used
        && scheduler_exact;
    if (evidence->center_link_session) {
        unsigned expected_leaders = count == 1U
            ? (control->id == 363U ? 1U : 0U) : 1U;
        evidence->exact = evidence->exact
            && evidence->selector_preimage_sentinel_written
            && evidence->selector_observed_endpoint_count == count
            && !evidence->unexpected_link_group_observed
            && !evidence->mode_selector_write_observed
            && evidence->host_selector_value_writes == 0U
            && evidence->leader_endpoint_count == expected_leaders
            && evidence->join_endpoint_count == count - expected_leaders;
    }

    if (!s61_rfu_attempt_cleanup())
        s61_die("RFU hub retained endpoints during cleanup");
}

static void s61_print_rfu_attempt_evidence(
    const struct S61RfuAttemptEvidence *evidence)
{
    if (!evidence->applicable) {
        fputs("null", stdout);
        return;
    }
    if (evidence->center_link_session) {
        printf("{\"scenario_id\":\"%s\",\"special\":%u,"
               "\"role\":\"%s\","
               "\"profile\":\"POKEMON_CENTER_LINK\","
               "\"calling_root\":\"0x%08" PRIX32 "\","
               "\"owner_key\":\"%s\",\"link_group\":%u,"
               "\"activity\":\"%s\",\"capacity_min\":%u,"
               "\"capacity_max\":%u,\"topology_policy\":\"%s\","
               "\"endpoint_count\":%u,\"expected_results\":[",
               evidence->scenario_id, evidence->special,
               evidence->special == 363U ? "LEADER" : "JOIN",
               evidence->calling_root,
               evidence->owner_key == NULL ? "" : evidence->owner_key,
               evidence->link_group, evidence->activity,
               evidence->capacity_min, evidence->capacity_max,
               evidence->topology_policy, evidence->endpoint_count);
    } else {
        printf("{\"scenario_id\":\"%s\",\"special\":%u,"
               "\"role\":\"%s\",\"activity_mode\":%u,"
               "\"endpoint_count\":%u,\"expected_results\":[",
               evidence->scenario_id, evidence->special,
               evidence->special == 363U ? "LEADER" : "JOIN",
               evidence->activity_mode, evidence->endpoint_count);
    }
    for (unsigned index = 0U; index < evidence->expected_result_count; ++index)
        printf("%s%u", index == 0U ? "" : ",",
               evidence->expected_results[index]);
    fputs("],\"observed_results\":[", stdout);
    unsigned observed_count = evidence->observed_result_count > 2U
        ? 2U : evidence->observed_result_count;
    for (unsigned index = 0U; index < observed_count; ++index)
        printf("%s%u", index == 0U ? "" : ",",
               evidence->observed_results[index]);
    printf("],\"observed_result_overflow\":%s,\"fault_code\":%u,"
           "\"reset_epoch\":%u,\"host_memory_writes\":%u,"
           "\"quiescent_load_before_attach\":%s,"
           "\"hub_reset_after_all_loads\":%s,"
           "\"exchange_isolated_used\":%s,"
           "\"topology_discovered\":%s,"
           "\"initial_fault_armed\":%s,"
           "\"initial_fault_consumed\":%s,"
           "\"retry_fault_reconfigured\":%s,"
           "\"retry_fault_consumed\":%s",
           evidence->observed_result_count > 2U ? "true" : "false",
           evidence->fault_code, evidence->reset_epoch,
           evidence->host_memory_writes,
           evidence->quiescent_load_before_attach ? "true" : "false",
           evidence->hub_reset_after_all_loads ? "true" : "false",
           evidence->exchange_isolated_used ? "true" : "false",
           evidence->topology_discovered ? "true" : "false",
           evidence->initial_fault_armed ? "true" : "false",
           evidence->initial_fault_consumed ? "true" : "false",
           evidence->retry_fault_reconfigured ? "true" : "false",
           evidence->retry_fault_consumed ? "true" : "false");
    if (evidence->center_link_session) {
        printf(",\"selector_preimage_sentinel_written\":%s,"
               "\"selector_observed_endpoint_count\":%u,"
               "\"unexpected_link_group_observed\":%s,"
               "\"mode_selector_write_observed\":%s,"
               "\"host_selector_value_writes\":%u,"
               "\"leader_endpoint_count\":%u,"
               "\"join_endpoint_count\":%u,\"endpoint_roles\":[",
               evidence->selector_preimage_sentinel_written
                   ? "true" : "false",
               evidence->selector_observed_endpoint_count,
               evidence->unexpected_link_group_observed ? "true" : "false",
               evidence->mode_selector_write_observed ? "true" : "false",
               evidence->host_selector_value_writes,
               evidence->leader_endpoint_count,
               evidence->join_endpoint_count);
        for (unsigned slot = 0U; slot < evidence->endpoint_count; ++slot)
            printf("%s%u", slot == 0U ? "" : ",",
                   evidence->endpoint_roles[slot]);
        putchar(']');
    }
    printf(",\"scheduler\":{\"policy\":"
           "\"MIN_GLOBAL_CYCLE_TIE_SLOT_ORDER_INSTRUCTION_STEP\","
           "\"iterations\":%" PRIu64 ",\"tie_breaks\":%" PRIu64 ","
           "\"max_skew\":%" PRIu64 ",\"slot_steps\":[",
           evidence->scheduler_iterations, evidence->scheduler_tie_breaks,
           evidence->scheduler_max_skew);
    for (unsigned slot = 0U; slot < evidence->endpoint_count; ++slot)
        printf("%s%" PRIu64, slot == 0U ? "" : ",",
               evidence->scheduler_slot_steps[slot]);
    printf("],\"run_frame_used\":false},\"segment_count\":%u,"
           "\"endpoint_traces\":[", evidence->segment_count);
    for (unsigned slot = 0U; slot < evidence->endpoint_count; ++slot) {
        const struct S61RfuEndpointEvidence *endpoint =
            &evidence->endpoints[slot];
        printf("%s{\"slot\":%u,\"trace_count\":%zu,"
               "\"trace_fnv1a64\":\"%016" PRIX64 "\","
               "\"healthy\":%s,\"overflow\":%s,"
               "\"station_id\":%u,\"host_bitmap\":%u,"
               "\"signal\":%" PRIu32 ",\"rejection_count\":%u,"
               "\"disconnect_count\":%u,\"exact\":%s}",
               slot == 0U ? "" : ",", slot, endpoint->trace_count,
               endpoint->trace_hash,
               endpoint->healthy ? "true" : "false",
               endpoint->overflow ? "true" : "false",
               endpoint->station_id, endpoint->host_bitmap,
               endpoint->signal, endpoint->rejection_count,
               endpoint->disconnect_count,
               endpoint->exact ? "true" : "false");
    }
    printf("],\"exact\":%s}", evidence->exact ? "true" : "false");
}

static void s61_case_rfu_runner_attach_contract(
    const char *rom_path, const char *directory)
{
    printf("{\"schema_version\":1,"
           "\"case\":\"rfu_runner_attach_contract\","
           "\"production_exchange_isolated_used\":false,"
           "\"host_memory_writes\":0,\"topologies\":[");
    unsigned failed = 0U;
    for (unsigned topology = 1U;
         topology <= STAGE61_RFU_MAX_ENDPOINTS; ++topology) {
        struct Stage61RfuHub *hub = Stage61RfuHubCreate();
        struct mCore *cores[STAGE61_RFU_MAX_ENDPOINTS] = {0};
        struct Stage61RfuPeripheral
            *peripherals[STAGE61_RFU_MAX_ENDPOINTS] = {0};
        color_t *videos[STAGE61_RFU_MAX_ENDPOINTS] = {0};
        if (hub == NULL)
            s61_die("RFU attach-contract hub allocation failed");
        for (unsigned slot = 0U; slot < topology; ++slot) {
            char save_path[4096U];
            int length = snprintf(
                save_path, sizeof(save_path), "%s/rfu-%u-%u.srm",
                directory, topology, slot);
            if (length <= 0 || (size_t)length >= sizeof(save_path))
                s61_die("RFU attach-contract save path overflow");
            videos[slot] = calloc(240U * 160U, sizeof(color_t));
            if (videos[slot] == NULL)
                s61_die("RFU attach-contract video allocation failed");
            cores[slot] = s61_bootstrap_open_core(
                rom_path, save_path, videos[slot]);
            if (cores[slot] == NULL)
                s61_die("RFU attach-contract core open failed");
        }
        size_t state_size = cores[0]->stateSize(cores[0]);
        void *state = malloc(state_size);
        if (state == NULL || !cores[0]->saveState(cores[0], state))
            s61_die("RFU attach-contract quiescent state save failed");
        for (unsigned slot = 0U; slot < topology; ++slot) {
            if (!cores[slot]->loadState(cores[slot], state))
                s61_die("RFU attach-contract quiescent state load failed");
            peripherals[slot] = Stage61RfuPeripheralCreate(hub);
            if (peripherals[slot] == NULL)
                s61_die("RFU attach-contract endpoint allocation failed");
        }
        bool fifth_rejected = true;
        if (topology == STAGE61_RFU_MAX_ENDPOINTS) {
            struct Stage61RfuPeripheral *fifth =
                Stage61RfuPeripheralCreate(hub);
            fifth_rejected = fifth == NULL;
            if (fifth != NULL)
                Stage61RfuPeripheralDestroy(fifth);
        }
        bool live_destroy_rejected = !Stage61RfuHubDestroy(hub);
        for (unsigned slot = 0U; slot < topology; ++slot) {
            struct GBA *gba = (struct GBA *)cores[slot]->board;
            if (gba == NULL || !Stage61RfuPeripheralAttach(
                    peripherals[slot], &gba->sio))
                s61_die("RFU attach-contract endpoint attach failed");
        }
        if (!Stage61RfuHubReset(hub))
            s61_die("RFU attach-contract post-load hub reset failed");
        struct S61ExternalControl control = {0};
        control.kind = topology == 4U
            ? S61_CONTROL_CENTER_LINK_SESSION : S61_CONTROL_RFU_SESSION;
        control.id = 363U;
        control.scenario_id = topology == 4U
            ? "group2-leader-result1"
            : topology == 1U
            ? "mode0-leader-result5"
            : topology == 2U
                ? "mode0-leader-result1" : "mode1-leader-result1";
        control.values[0] = topology;
        control.values[1] = topology == 4U ? 2U
            : topology == 3U ? 1U : 0U;
        control.values[2] = 1U;
        control.values[3] = topology == 1U ? 5U : 1U;
        control.values[4] = 65535U;
        control.values[5] = 0U;
        if (topology == 4U) {
            control.activity = "multi-battle";
            control.topology_policy = "EXACT_SOURCE_CAPACITY";
            control.values[6] = 4U;
            control.values[7] = 4U;
            control.value_count = 8U;
        } else {
            control.value_count = 6U;
        }
        bool registry_tuple_exact =
            s61_link_session_registry_tuple(&control);
        struct S61ExternalControl unregistered = control;
        unregistered.scenario_id = "mode0-leader-user-program";
        bool unregistered_rejected =
            !s61_link_session_registry_tuple(&unregistered);
        memset(&s61_rfu_attempt, 0, sizeof(s61_rfu_attempt));
        s61_rfu_attempt.active = true;
        s61_rfu_attempt.control = &control;
        s61_rfu_attempt.hub = hub;
        for (unsigned slot = 0U; slot < topology; ++slot) {
            s61_rfu_attempt.cores[slot] = cores[slot];
            s61_rfu_attempt.peripherals[slot] = peripherals[slot];
            s61_rfu_attempt.peer_start_frame[slot] =
                cores[slot]->frameCounter(cores[slot]);
            s61_rfu_attempt.endpoint_roles[slot] =
                slot == 0U ? 363U : 364U;
        }
        for (unsigned instruction = 0U; instruction < 2048U; ++instruction)
            s61_rfu_scheduler_step_local(cores[0]);
        bool exact = registry_tuple_exact && unregistered_rejected
            && fifth_rejected && live_destroy_rejected
            && Stage61RfuHubEndpointCount(hub) == topology
            && s61_rfu_attempt.scheduler_iterations >= 2048U;
        for (unsigned slot = 0U; slot < topology; ++slot) {
            exact = exact && s61_rfu_attempt.scheduler_slot_steps[slot] != 0U
                && Stage61RfuPeripheralIsAttached(peripherals[slot])
                && Stage61RfuPeripheralHealthy(peripherals[slot])
                && !Stage61RfuPeripheralTraceOverflowed(peripherals[slot]);
        }
        printf("%s{\"endpoint_count\":%u,"
               "\"one_core_cancel_boundary\":%s,"
               "\"quiescent_load_before_attach\":true,"
               "\"hub_reset_after_all_loads\":true,"
               "\"registry_tuple_exact\":%s,"
               "\"unregistered_scenario_rejected\":%s,"
               "\"fifth_endpoint_rejected\":%s,"
               "\"live_hub_destroy_rejected\":%s,"
               "\"scheduler_iterations\":%" PRIu64 ","
               "\"slot_steps\":[",
               topology == 1U ? "" : ",", topology,
               topology == 1U ? "true" : "false",
               registry_tuple_exact ? "true" : "false",
               unregistered_rejected ? "true" : "false",
               fifth_rejected ? "true" : "false",
               live_destroy_rejected ? "true" : "false",
               s61_rfu_attempt.scheduler_iterations);
        for (unsigned slot = 0U; slot < topology; ++slot)
            printf("%s%" PRIu64, slot == 0U ? "" : ",",
                   s61_rfu_attempt.scheduler_slot_steps[slot]);
        printf("],\"exact\":%s}", exact ? "true" : "false");
        if (!exact)
            ++failed;
        s61_rfu_attempt.active = false;
        for (unsigned slot = 0U; slot < topology; ++slot)
            Stage61RfuPeripheralDetach(peripherals[slot]);
        for (unsigned slot = 0U; slot < topology; ++slot) {
            s61_bootstrap_close_core(cores[slot]);
            free(videos[slot]);
            Stage61RfuPeripheralDestroy(peripherals[slot]);
        }
        if (!Stage61RfuHubDestroy(hub))
            s61_die("RFU attach-contract final hub destroy failed");
        free(state);
        memset(&s61_rfu_attempt, 0, sizeof(s61_rfu_attempt));
    }
    printf("],\"failed\":%u,\"untested\":0,\"warnings\":0,"
           "\"status\":\"%s\"}\n", failed,
           failed == 0U ? "PASS" : "FAIL");
}

