static void s61_snapshot_persistence_writer_before(const char *save_path)
{
    const char *destination = getenv("S61_PERSIST_WRITER_BEFORE_SRM");
    if (destination == NULL || destination[0] == '\0')
        return;
    FILE *source = fopen(save_path, "rb");
    FILE *target = fopen(destination, "wb");
    if (source == NULL || target == NULL)
        s61_die("persistence writer-before snapshot open failed");
    uint8_t buffer[4096U];
    size_t total = 0U;
    while (total < BOOTSTRAP_SAVE_SIZE) {
        size_t request = BOOTSTRAP_SAVE_SIZE - total;
        if (request > sizeof(buffer))
            request = sizeof(buffer);
        size_t count = fread(buffer, 1U, request, source);
        if (count != request || fwrite(buffer, 1U, count, target) != count)
            s61_die("persistence writer-before snapshot copy failed");
        total += count;
    }
    if (fgetc(source) != EOF || ferror(source)
        || fflush(target) != 0 || fclose(source) != 0
        || fclose(target) != 0)
        s61_die("persistence writer-before snapshot size/close failed");
}

static unsigned s61_flag(struct mCore *core, uint16_t flag)
{
    return (unsigned)s61_call_synced(core, WORLD_FLAG_GET, flag, 0U, 0U, 0U);
}

static bool s61_engine_special_flag_owner(struct mCore *core, uint16_t flag)
{
    if (flag < 0x4000U || flag > 0x407FU)
        s61_die("engine special flag owner read outside ABI range");
    unsigned bit = flag - 0x4000U;
    return (read8(core, WORLD_ENGINE_SPECIAL_FLAGS + (bit >> 3U))
            & (1U << (bit & 7U))) != 0U;
}

static unsigned s61_item(struct mCore *core, uint16_t item)
{
    return (unsigned)s61_call_synced(
        core, BATTLE_CORE_CHECK_BAG_HAS_ITEM, item, 1U, 0U, 0U);
}

