static void s61_assert_player_position_api_preimages(struct mCore *core)
{
    /* These are the Japanese FireRed/Vega final-ROM entries.  English
     * decomp link addresses silently jump into unrelated code, so every
     * physical-position read/move is pinned to the reviewed opcodes. */
    static const uint8_t get_dest_coords[] = {
        0x30U, 0xB5U, 0x09U, 0x4DU, 0x09U, 0x4CU, 0x63U, 0x79U,
        0xDAU, 0x00U, 0xD2U, 0x18U, 0x92U, 0x00U, 0x52U, 0x19U,
        0x12U, 0x8AU, 0x02U, 0x80U, 0x62U, 0x79U, 0xD0U, 0x00U,
        0x80U, 0x18U, 0x80U, 0x00U, 0x40U, 0x19U, 0x40U, 0x8AU,
        0x08U, 0x80U, 0x30U, 0xBCU, 0x01U, 0xBCU, 0x00U, 0x47U,
        0x6CU, 0x6DU, 0x03U, 0x02U, 0xACU, 0x6FU, 0x03U, 0x02U,
    };
    static const uint8_t set_camera_focus_coords[] = {
        0x00U, 0x04U, 0x00U, 0x0CU, 0x09U, 0x04U, 0x09U, 0x0CU,
        0x03U, 0x4AU, 0x12U, 0x68U, 0x07U, 0x38U, 0x10U, 0x80U,
        0x07U, 0x39U, 0x51U, 0x80U, 0x70U, 0x47U, 0x00U, 0x00U,
        0x48U, 0x50U, 0x00U, 0x03U,
    };
    static const uint8_t move_player_to_map_coords[] = {
        0x00U, 0xB5U, 0x03U, 0x1CU, 0x0AU, 0x1CU, 0x08U, 0x48U,
        0x41U, 0x79U, 0xC8U, 0x00U, 0x40U, 0x18U, 0x80U, 0x00U,
        0x06U, 0x49U, 0x40U, 0x18U, 0x1BU, 0x04U, 0x1BU, 0x14U,
        0x12U, 0x04U, 0x12U, 0x14U, 0x19U, 0x1CU, 0x02U, 0xF0U,
        0xF5U, 0xFFU, 0x01U, 0xBCU, 0x00U, 0x47U, 0x00U, 0x00U,
        0xACU, 0x6FU, 0x03U, 0x02U, 0x6CU, 0x6DU, 0x03U, 0x02U,
    };
    if (!s61_core_range_equals(
            core, WORLD_PLAYER_GET_DEST_COORDS & ~1U,
            get_dest_coords, sizeof(get_dest_coords),
            "PlayerGetDestCoords ROM preimage")
        || !s61_core_range_equals(
            core, WORLD_SET_CAMERA_FOCUS_COORDS & ~1U,
            set_camera_focus_coords, sizeof(set_camera_focus_coords),
            "SetCameraFocusCoords ROM preimage")
        || !s61_core_range_equals(
            core, WORLD_MOVE_PLAYER_TO_MAP_COORDS & ~1U,
            move_player_to_map_coords, sizeof(move_player_to_map_coords),
            "MovePlayerToMapCoords ROM preimage"))
        s61_die("Japanese final-ROM player-position API preimage differs");
}
