static bool s61_object_visible(struct mCore *core,
                               const struct S61Interaction *fixture)
{
    for (unsigned slot = 0U; slot < 16U; ++slot) {
        uint32_t object = WORLD_OBJECT_EVENTS + slot * 0x24U;
        if ((read8(core, object) & 1U) != 0U
            && read8(core, object + 8U) == fixture->local_id
            && read8(core, object + 9U) == fixture->map
            && read8(core, object + 10U) == fixture->group)
            return true;
    }
    return false;
}

static struct S61WarpSnapshot s61_snapshot_warp(struct mCore *core,
                                                uint32_t address)
{
    struct S61WarpSnapshot result = {0};
    result.group = read8(core, address);
    result.map = read8(core, address + 1U);
    result.warp_id = read8(core, address + 2U);
    result.x = (int16_t)read16(core, address + 4U);
    result.y = (int16_t)read16(core, address + 6U);
    return result;
}

static void s61_snapshot_object(struct mCore *core,
                                const struct S61Interaction *interaction,
                                struct S61ObjectSnapshot *result)
{
    result->slot = -1;
    for (unsigned slot = 0U; slot < 16U; ++slot) {
        uint32_t object = WORLD_OBJECT_EVENTS + slot * 0x24U;
        if ((read8(core, object) & 1U) == 0U
            || read8(core, object + 8U) != interaction->local_id
            || read8(core, object + 9U) != interaction->map
            || read8(core, object + 10U) != interaction->group)
            continue;
        result->active = true;
        result->invisible = (read8(core, object + 1U) & 0x20U) != 0U;
        result->slot = (int)slot;
        result->current_x = (int16_t)read16(core, object + 0x10U);
        result->current_y = (int16_t)read16(core, object + 0x12U);
        result->previous_x = (int16_t)read16(core, object + 0x14U);
        result->previous_y = (int16_t)read16(core, object + 0x16U);
        return;
    }
}

static bool s61_runtime_object_less(
    const struct S61RuntimeObjectEntry *left,
    const struct S61RuntimeObjectEntry *right)
{
    if (left->group != right->group)
        return left->group < right->group;
    if (left->map != right->map)
        return left->map < right->map;
    if (left->local_id != right->local_id)
        return left->local_id < right->local_id;
    return left->slot < right->slot;
}

static void s61_snapshot_runtime_objects(
    struct mCore *core, struct S61RuntimeObjectInventory *result)
{
    uint8_t semantic[S61_RUNTIME_OBJECT_SLOT_COUNT * 14U] = {0};
    for (unsigned slot = 0U; slot < S61_RUNTIME_OBJECT_SLOT_COUNT; ++slot) {
        uint32_t object = WORLD_OBJECT_EVENTS + slot * 0x24U;
        if ((read8(core, object) & 1U) == 0U)
            continue;
        struct S61RuntimeObjectEntry *entry =
            &result->entries[result->count++];
        entry->slot = (uint8_t)slot;
        entry->local_id = read8(core, object + 8U);
        entry->map = read8(core, object + 9U);
        entry->group = read8(core, object + 10U);
        entry->invisible = (read8(core, object + 1U) & 0x20U) != 0U;
        entry->current_x = (int16_t)read16(core, object + 0x10U);
        entry->current_y = (int16_t)read16(core, object + 0x12U);
        entry->previous_x = (int16_t)read16(core, object + 0x14U);
        entry->previous_y = (int16_t)read16(core, object + 0x16U);
    }
    for (unsigned index = 1U; index < result->count; ++index) {
        struct S61RuntimeObjectEntry value = result->entries[index];
        unsigned destination = index;
        while (destination != 0U
               && s61_runtime_object_less(
                   &value, &result->entries[destination - 1U])) {
            result->entries[destination] = result->entries[destination - 1U];
            --destination;
        }
        result->entries[destination] = value;
    }
    for (unsigned index = 0U; index < result->count; ++index) {
        const struct S61RuntimeObjectEntry *entry = &result->entries[index];
        uint8_t *bytes = semantic + index * 14U;
        bytes[0] = entry->group;
        bytes[1] = entry->map;
        bytes[2] = entry->local_id;
        bytes[3] = entry->slot;
        bytes[4] = entry->invisible ? 1U : 0U;
        bytes[5] = (uint8_t)entry->current_x;
        bytes[6] = (uint8_t)((uint16_t)entry->current_x >> 8U);
        bytes[7] = (uint8_t)entry->current_y;
        bytes[8] = (uint8_t)((uint16_t)entry->current_y >> 8U);
        bytes[9] = (uint8_t)entry->previous_x;
        bytes[10] = (uint8_t)((uint16_t)entry->previous_x >> 8U);
        bytes[11] = (uint8_t)entry->previous_y;
        bytes[12] = (uint8_t)((uint16_t)entry->previous_y >> 8U);
        bytes[13] = 0U;
    }
    result->hash = s61_hash_bytes(semantic, result->count * 14U);
}

static void s61_snapshot_loaded_templates(
    struct mCore *core, uint32_t save1,
    struct S61LoadedTemplateInventory *result)
{
    uint32_t events = read32(core, WORLD_MAP_HEADER + 4U);
    if (!((events >= 0x02000000U && events < 0x02040000U)
          || (events >= 0x08000000U && events < 0x0A000000U)))
        s61_die("loaded map events pointer differs");
    result->count = read8(core, events);
    if (result->count > S61_LOADED_TEMPLATE_COUNT)
        s61_die("loaded template count exceeds SaveBlock bound");
    for (unsigned index = 0U; index < result->count; ++index) {
        uint32_t template = save1 + 0x08E0U + index * 0x18U;
        result->entries[index].local_id = read8(core, template);
        result->entries[index].hash = s61_hash_core_range(
            core, template, 0x18U);
    }
    for (unsigned index = 1U; index < result->count; ++index) {
        struct S61LoadedTemplateEntry value = result->entries[index];
        unsigned destination = index;
        while (destination != 0U
               && (result->entries[destination - 1U].local_id
                       > value.local_id
                   || (result->entries[destination - 1U].local_id
                           == value.local_id
                       && result->entries[destination - 1U].hash
                           > value.hash))) {
            result->entries[destination] = result->entries[destination - 1U];
            --destination;
        }
        result->entries[destination] = value;
    }
    uint8_t semantic[S61_LOADED_TEMPLATE_COUNT * 9U] = {0};
    for (unsigned index = 0U; index < result->count; ++index) {
        semantic[index * 9U] = result->entries[index].local_id;
        for (unsigned byte = 0U; byte < 8U; ++byte)
            semantic[index * 9U + 1U + byte] =
                (uint8_t)(result->entries[index].hash >> (byte * 8U));
    }
    result->hash = s61_hash_bytes(semantic, result->count * 9U);
}

static void s61_decode_object_template(
    const struct S61SideEffectSnapshot *state,
    struct S61ObjectTemplateSnapshot *result)
{
    result->raw_hash = s61_hash_bytes(result->raw, sizeof(result->raw));
    result->local_id = result->raw[0U];
    result->graphics_id = result->raw[1U];
    result->kind = result->raw[2U];
    result->x = (int16_t)(
        (uint16_t)result->raw[4U]
        | ((uint16_t)result->raw[5U] << 8U));
    result->y = (int16_t)(
        (uint16_t)result->raw[6U]
        | ((uint16_t)result->raw[7U] << 8U));
    result->elevation = result->raw[8U];
    result->movement_type = result->raw[9U];
    result->movement_range_x = result->raw[10U] & 0x0FU;
    result->movement_range_y = result->raw[10U] >> 4U;
    result->trainer_type = (uint16_t)(
        (uint16_t)result->raw[12U]
        | ((uint16_t)result->raw[13U] << 8U));
    result->trainer_range_or_berry_tree_id = (uint16_t)(
        (uint16_t)result->raw[14U]
        | ((uint16_t)result->raw[15U] << 8U));
    result->script = (uint32_t)result->raw[16U]
        | ((uint32_t)result->raw[17U] << 8U)
        | ((uint32_t)result->raw[18U] << 16U)
        | ((uint32_t)result->raw[19U] << 24U);
    result->hide_flag = (uint16_t)(
        (uint16_t)result->raw[20U]
        | ((uint16_t)result->raw[21U] << 8U));
    if (result->hide_flag < 0x0900U)
        result->hide_flag_set =
            (state->stock_flags[result->hide_flag >> 3U]
             & (1U << (result->hide_flag & 7U))) != 0U;
    else if (result->hide_flag < 0x1900U)
        result->hide_flag_set =
            (state->expanded_flags[
                (result->hide_flag - 0x0900U) >> 3U]
             & (1U << (result->hide_flag & 7U))) != 0U;
}

static unsigned s61_map_object_template_count(struct mCore *core,
                                               uint32_t *events_out)
{
    uint32_t events = read32(core, WORLD_MAP_HEADER + 4U);
    if (!((events >= 0x02000000U && events < 0x02040000U)
          || (events >= 0x08000000U && events < 0x0A000000U)))
        s61_die("map events pointer differs during template snapshot");
    unsigned count = read8(core, events);
    if (count > S61_LOADED_TEMPLATE_COUNT)
        s61_die("map object template count exceeds SaveBlock bound");
    *events_out = events;
    return count;
}

static void s61_snapshot_static_object_template(
    struct mCore *core, const struct S61Interaction *interaction,
    const struct S61SideEffectSnapshot *state,
    struct S61ObjectTemplateSnapshot *result)
{
    result->slot = -1;
    uint32_t events = 0U;
    unsigned count = s61_map_object_template_count(core, &events);
    uint32_t templates = read32(core, events + 4U);
    if (count != 0U
        && !((templates >= 0x02000000U
              && templates + count * 0x18U <= 0x02040000U)
             || (templates >= 0x08000000U
                 && templates + count * 0x18U <= 0x0A000000U)))
        s61_die("static map object template pointer/range differs");
    for (unsigned slot = 0U; slot < count; ++slot) {
        uint32_t template = templates + slot * 0x18U;
        if (read8(core, template) != interaction->local_id)
            continue;
        result->found = true;
        result->slot = (int)slot;
        s61_read_core_range(
            core, template, result->raw, sizeof(result->raw));
        s61_decode_object_template(state, result);
        return;
    }
}

static void s61_snapshot_object_template(
    struct mCore *core, uint32_t save1,
    const struct S61Interaction *interaction,
    const struct S61SideEffectSnapshot *state,
    struct S61ObjectTemplateSnapshot *result)
{
    result->slot = -1;
    uint32_t events = 0U;
    unsigned count = s61_map_object_template_count(core, &events);
    (void)events;
    for (unsigned slot = 0U; slot < count; ++slot) {
        uint32_t template = save1 + 0x08E0U + slot * 0x18U;
        if (read8(core, template) != interaction->local_id)
            continue;
        result->found = true;
        result->slot = (int)slot;
        s61_read_core_range(
            core, template, result->raw, sizeof(result->raw));
        s61_decode_object_template(state, result);
        return;
    }
}

static void s61_add_item_quantity(struct S61SideEffectSnapshot *result,
                                  uint16_t id, uint16_t quantity)
{
    if (id == 0U || quantity == 0U)
        return;
    for (unsigned index = 0U; index < result->item_count; ++index) {
        if (result->items[index].id == id) {
            result->items[index].quantity += quantity;
            return;
        }
    }
    if (result->item_count >= S61_ITEM_SLOT_COUNT)
        s61_die("bag item snapshot exceeded physical slot count");
    result->items[result->item_count].id = id;
    result->items[result->item_count].quantity = quantity;
    ++result->item_count;
}

static void s61_sort_item_quantities(struct S61SideEffectSnapshot *result)
{
    for (unsigned index = 1U; index < result->item_count; ++index) {
        struct S61ItemQuantity value = result->items[index];
        unsigned destination = index;
        while (destination != 0U
               && result->items[destination - 1U].id > value.id) {
            result->items[destination] = result->items[destination - 1U];
            --destination;
        }
        result->items[destination] = value;
    }
}

static void s61_snapshot_side_effects(
    struct mCore *core, const struct S61Interaction *interaction,
    struct S61SideEffectSnapshot *result)
{
    static const uint16_t pocket_offsets[] = {
        0x0310U, 0x03B8U, 0x0430U, 0x0464U, 0x054CU,
    };
    static const uint8_t pocket_counts[] = {
        42U, 30U, 13U, 58U, 43U,
    };
    uint8_t flag_bytes[S61_STOCK_FLAG_BYTES + S61_EXPANDED_FLAG_BYTES];
    uint8_t var_bytes[(S61_STOCK_VAR_COUNT + S61_EXPANDED_VAR_COUNT) * 2U];
    uint8_t item_bytes[S61_ITEM_SLOT_COUNT * 4U];
    memset(result, 0, sizeof(*result));
    result->map_layout_id = read16(core, WORLD_MAP_HEADER + 0x12U);
    uint32_t save1 = world_save1(core, s61_case_name);
    uint32_t save2 = read32(core, BOOTSTRAP_SAVE_BLOCK2_PTR);
    if (save1 + S61_SAVE_BLOCK1_SIZE > 0x02040000U)
        s61_die("catalog side-effect SaveBlock1 range differs");
    if (save2 < 0x02000000U
        || save2 + S61_SAVE_BLOCK2_SIZE > 0x02040000U
        || (save2 & 3U) != 0U)
        s61_die("catalog side-effect SaveBlock2 pointer differs");

    for (unsigned index = 0U; index < S61_SAVE_BLOCK1_SIZE; ++index)
        result->saveblock1[index] = read8(core, save1 + index);
    for (unsigned index = 0U; index < S61_SAVE_BLOCK2_SIZE; ++index)
        result->saveblock2[index] = read8(core, save2 + index);
    result->saveblock1_raw_hash = s61_hash_bytes(
        result->saveblock1, sizeof(result->saveblock1));
    result->saveblock1_normalized_hash = s61_hash_saveblock_normalized(
        result->saveblock1, sizeof(result->saveblock1), 1U);
    result->saveblock2_raw_hash = s61_hash_bytes(
        result->saveblock2, sizeof(result->saveblock2));
    result->saveblock2_normalized_hash = s61_hash_saveblock_normalized(
        result->saveblock2, sizeof(result->saveblock2), 2U);

    for (unsigned index = 0U; index < S61_STOCK_FLAG_BYTES; ++index) {
        result->stock_flags[index] = read8(
            core, save1 + S61_SAVE1_FLAGS_OFFSET + index);
        flag_bytes[index] = result->stock_flags[index];
    }
    for (unsigned index = 0U; index < S61_EXPANDED_FLAG_BYTES; ++index) {
        result->expanded_flags[index] = read8(
            core, WORLD_EXPANDED_FLAGS_VARS + index);
        flag_bytes[S61_STOCK_FLAG_BYTES + index]
            = result->expanded_flags[index];
    }
    result->flags_hash = s61_hash_bytes(flag_bytes, sizeof(flag_bytes));
    for (unsigned index = 0U;
         index < sizeof(result->engine_special_flags); ++index) {
        result->engine_special_flags[index] = read8(
            core, WORLD_ENGINE_SPECIAL_FLAGS + index);
    }
    result->engine_special_flags_hash = s61_hash_bytes(
        result->engine_special_flags,
        sizeof(result->engine_special_flags));
    result->trainers_hash = s61_hash_bytes(
        result->stock_flags + (S61_TRAINER_FLAG_START >> 3U),
        S61_TRAINER_COUNT / 8U);
    for (unsigned index = 0U; index < S61_STOCK_VAR_COUNT; ++index) {
        result->stock_vars[index] = read16(
            core, save1 + S61_SAVE1_VARS_OFFSET + index * 2U);
        var_bytes[index * 2U] = (uint8_t)result->stock_vars[index];
        var_bytes[index * 2U + 1U]
            = (uint8_t)(result->stock_vars[index] >> 8U);
    }
    for (unsigned index = 0U; index < S61_EXPANDED_VAR_COUNT; ++index) {
        result->expanded_vars[index] = read16(
            core, WORLD_EXPANDED_FLAGS_VARS + 0x200U + index * 2U);
        unsigned offset = (S61_STOCK_VAR_COUNT + index) * 2U;
        var_bytes[offset] = (uint8_t)result->expanded_vars[index];
        var_bytes[offset + 1U]
            = (uint8_t)(result->expanded_vars[index] >> 8U);
    }
    result->vars_hash = s61_hash_bytes(var_bytes, sizeof(var_bytes));

    uint32_t encryption_key = read32(
        core, save2 + S61_SAVE2_ENCRYPTION_KEY_OFFSET);
    uint16_t quantity_key = (uint16_t)encryption_key;
    result->money = read32(core, save1 + 0x0290U) ^ encryption_key;
    result->berry_powder = read32(
        core, save2 + S61_SAVE2_BERRY_POWDER_OFFSET) ^ encryption_key;
    if (result->berry_powder > S61_MAX_BERRY_POWDER)
        s61_die("catalog side-effect berry powder range differs");
    result->vega_coins = read16(core, save1 + 0x0294U) ^ quantity_key;
    result->cfru_coins = read32(core, WORLD_PLAYER_COINS);
    unsigned physical_slot = 0U;
    for (unsigned pocket = 0U;
         pocket < sizeof(pocket_counts) / sizeof(pocket_counts[0]); ++pocket) {
        for (unsigned slot = 0U; slot < pocket_counts[pocket]; ++slot) {
            uint32_t address = save1 + pocket_offsets[pocket] + slot * 4U;
            uint16_t id = read16(core, address);
            uint16_t quantity = read16(core, address + 2U) ^ quantity_key;
            item_bytes[physical_slot * 4U] = (uint8_t)id;
            item_bytes[physical_slot * 4U + 1U] = (uint8_t)(id >> 8U);
            item_bytes[physical_slot * 4U + 2U] = (uint8_t)quantity;
            item_bytes[physical_slot * 4U + 3U]
                = (uint8_t)(quantity >> 8U);
            ++physical_slot;
            if (id != 0U && quantity != 0U)
                ++result->bag_entry_count;
            s61_add_item_quantity(result, id, quantity);
        }
    }
    if (physical_slot != S61_ITEM_SLOT_COUNT)
        s61_die("bag pocket slot scan count differs");
    result->items_hash = s61_hash_bytes(item_bytes, sizeof(item_bytes));
    s61_sort_item_quantities(result);

    result->party_count = read8(core, BOOTSTRAP_PLAYER_COUNT);
    if (result->party_count > S61_PARTY_SLOT_COUNT)
        s61_die("live party count exceeds six slots");
    s61_sha256_core_range(
        core, BOOTSTRAP_PLAYER_PARTY,
        S61_PARTY_SLOT_COUNT * S61_PARTY_RECORD_SIZE,
        result->party_raw_sha256);
    uint32_t storage = read32(core, S61_POKEMON_STORAGE_PTR);
    if (storage < 0x02000000U
        || storage + S61_POKEMON_STORAGE_SIZE > 0x02040000U)
        s61_die("PokemonStorage pointer/range differs");
    s61_sha256_core_range(
        core, storage, S61_POKEMON_STORAGE_SIZE,
        result->storage_raw_sha256);

    result->world.x = read16(core, save1);
    result->world.y = read16(core, save1 + 2U);
    result->world.location = s61_snapshot_warp(core, save1 + 4U);
    result->world.continue_game = s61_snapshot_warp(core, save1 + 0x0CU);
    result->world.dynamic = s61_snapshot_warp(core, save1 + 0x14U);
    result->world.last_heal = s61_snapshot_warp(core, save1 + 0x1CU);
    result->world.escape = s61_snapshot_warp(core, save1 + 0x24U);
    result->world.destination = s61_snapshot_warp(
        core, WORLD_WARP_DESTINATION);
    s61_snapshot_object(core, interaction, &result->object);
    s61_snapshot_runtime_objects(core, &result->runtime_objects);
    s61_snapshot_loaded_templates(core, save1, &result->loaded_templates);
    s61_snapshot_static_object_template(
        core, interaction, result, &result->static_object_template);
    s61_snapshot_object_template(
        core, save1, interaction, result, &result->object_template);

    result->battle.active = s61_battle_active(core);
    result->battle.outcome = read8(core, BATTLE_CORE_BATTLE_OUTCOME);
    if (result->battle.active) {
        result->battle.trainer_opponent = read16(
            core, WORLD_TRAINER_OPPONENT_A);
        if (read8(core, ADDR_BATTLERS_COUNT) >= 2U)
            result->battle.enemy_species = read16(
                core, ADDR_BATTLE_MONS + BATTLE_MON_SIZE);
    }
    result->input.callback_overworld = world_overworld(core);
    result->input.controls_locked = world_script_enabled(core);
    result->input.running_state = read8(
        core, WORLD_PLAYER_AVATAR + WORLD_PLAYER_RUNNING_STATE_OFFSET);
    result->input.tile_transition_state = read8(
        core, WORLD_PLAYER_AVATAR
            + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET);
    result->input.field_input_recovered =
        result->input.callback_overworld
        && !result->input.controls_locked
        && !result->battle.active
        && result->input.running_state == 0U
        && result->input.tile_transition_state == 0U;
    result->input.battle_input_owned = result->battle.active;
}

static bool s61_catalog_object_template_contract(
    const struct S61CatalogRow *row)
{
    return strcmp(
        row->interaction_trigger,
        "TELEPORT_TO_WALK_START_REAL_WALK_TO_STANCE_FACE_AND_A") == 0;
}

static unsigned s61_catalog_owner_object_index(
    const struct S61CatalogRow *row)
{
    unsigned group = 0U;
    unsigned map = 0U;
    unsigned object_index = 0U;
    char trailing = '\0';
    if (strncmp(row->owner_key, "OBJECT:", 7U) != 0
        || sscanf(row->owner_key + 7U, "%u/%u:%u%c", &group, &map,
                  &object_index, &trailing) != 3
        || group != row->interaction.group
        || map != row->interaction.map
        || object_index >= S61_LOADED_TEMPLATE_COUNT)
        s61_die("catalog OBJECT owner key/index identity differs");
    char canonical[32U];
    int length = snprintf(
        canonical, sizeof(canonical), "OBJECT:%03u/%03u:%03u",
        group, map, object_index);
    if (length <= 0 || (size_t)length >= sizeof(canonical)
        || strcmp(canonical, row->owner_key) != 0)
        s61_die("catalog OBJECT owner key is not canonical");
    return object_index;
}

static void s61_assert_catalog_preinteraction_identity(
    const struct S61CatalogRow *row,
    const struct S61SideEffectSnapshot *snapshot,
    bool require_live_identity)
{
    if (!s61_catalog_object_template_contract(row))
        return;
    unsigned object_index = s61_catalog_owner_object_index(row);
    int16_t expected_x = (int16_t)(row->object_x + 7U);
    int16_t expected_y = (int16_t)(row->object_y + 7U);
    bool static_template_differs =
        !snapshot->static_object_template.found
        || snapshot->static_object_template.slot != (int)object_index
        || memcmp(snapshot->static_object_template.raw,
                  row->expected_template_raw,
                  sizeof(row->expected_template_raw)) != 0
        || snapshot->static_object_template.raw_hash
            != row->expected_template_hash
        || snapshot->static_object_template.local_id
            != row->interaction.local_id
        || snapshot->static_object_template.script != row->runtime_root;
    bool runtime_template_differs = !snapshot->object_template.found
        || snapshot->object_template.slot != (int)object_index
        || snapshot->object_template.local_id != row->interaction.local_id
        || snapshot->object_template.x != (int16_t)row->object_x
        || snapshot->object_template.y != (int16_t)row->object_y
        || snapshot->object_template.script != row->runtime_root;
    bool live_differs = !require_live_identity ? false
        : row->expect_visible
        ? (!snapshot->object.active || snapshot->object.invisible
           || snapshot->object.slot < 0
           || snapshot->object.current_x != expected_x
           || snapshot->object.current_y != expected_y)
        : snapshot->object.active;
    bool trainer_tower_lifecycle = row->runtime_position_producer.kind
        == S61_CATALOG_RUNTIME_POSITION_TRAINER_TOWER_ON_TRANSITION;
    bool lifecycle_differs = trainer_tower_lifecycle
        && (snapshot->map_layout_id
                != row->runtime_position_producer.lifecycle_layout_id
            || snapshot->object_template.movement_type
                != row->runtime_position_producer
                    .lifecycle_expected_movement_type);
    if (static_template_differs || runtime_template_differs || live_differs
        || lifecycle_differs) {
        fprintf(stderr,
                "catalog identity diagnostic case=%s owner_index=%u "
                "require_live=%u "
                "static=%u/%d local=%u position=%d,%d "
                "script=%08" PRIX32 " hash=%016" PRIX64 " "
                "runtime=%u/%d local=%u position=%d,%d "
                "script=%08" PRIX32 " live=%u visible=%u "
                "position=%d,%d expected_runtime=%u,%u "
                "expected_live=%d,%d expected_script=%08" PRIX32 "\n",
                row->case_id, object_index,
                require_live_identity ? 1U : 0U,
                snapshot->static_object_template.found ? 1U : 0U,
                snapshot->static_object_template.slot,
                snapshot->static_object_template.local_id,
                snapshot->static_object_template.x,
                snapshot->static_object_template.y,
                snapshot->static_object_template.script,
                snapshot->static_object_template.raw_hash,
                snapshot->object_template.found ? 1U : 0U,
                snapshot->object_template.slot,
                snapshot->object_template.local_id,
                snapshot->object_template.x,
                snapshot->object_template.y,
                snapshot->object_template.script,
                snapshot->object.active ? 1U : 0U,
                snapshot->object.active && !snapshot->object.invisible
                    ? 1U : 0U,
                snapshot->object.current_x,
                snapshot->object.current_y,
                row->object_x, row->object_y,
                expected_x, expected_y, row->runtime_root);
        fputs("catalog identity expected_static_raw=", stderr);
        for (unsigned byte = 0U;
             byte < sizeof(row->expected_template_raw); ++byte)
            fprintf(stderr, "%02X", row->expected_template_raw[byte]);
        fputs(" observed_static_raw=", stderr);
        for (unsigned byte = 0U;
             byte < sizeof(snapshot->static_object_template.raw); ++byte)
            fprintf(stderr, "%02X",
                    snapshot->static_object_template.raw[byte]);
        fputc('\n', stderr);
        s61_die("catalog live object/template identity differs before input");
    }
}

static void s61_print_catalog_preinteraction_identity(
    const struct S61CatalogRow *row,
    const struct S61SideEffectSnapshot *snapshot)
{
    if (!s61_catalog_object_template_contract(row)) {
        fputs("null", stdout);
        return;
    }
    unsigned object_index = s61_catalog_owner_object_index(row);
    const struct S61ObjectTemplateSnapshot *static_template =
        &snapshot->static_object_template;
    const struct S61ObjectTemplateSnapshot *runtime_template =
        &snapshot->object_template;
    printf("{\"owner_object_index\":%u,"
           "\"template_found\":%s,\"template_index\":%d,"
           "\"template_local_id\":%u,"
           "\"template_graphics_id\":%u,\"template_kind\":%u,"
           "\"template_position\":[%d,%d],"
           "\"template_elevation\":%u,"
           "\"template_movement_type\":%u,"
           "\"template_movement_range\":[%u,%u],"
           "\"template_trainer_type\":%u,"
           "\"template_trainer_range_or_berry_tree_id\":%u,"
           "\"template_script\":\"0x%08" PRIX32 "\","
           "\"template_hide_flag\":%u,"
           "\"template_storage\":\"gMapHeader.events.objectEvents\","
           "\"expected_raw_hex\":\"",
           object_index, static_template->found ? "true" : "false",
           static_template->slot, static_template->local_id,
           static_template->graphics_id, static_template->kind,
           static_template->x, static_template->y,
           static_template->elevation, static_template->movement_type,
           static_template->movement_range_x,
           static_template->movement_range_y,
           static_template->trainer_type,
           static_template->trainer_range_or_berry_tree_id,
           static_template->script, static_template->hide_flag);
    for (unsigned byte = 0U;
         byte < sizeof(row->expected_template_raw); ++byte)
        printf("%02X", row->expected_template_raw[byte]);
    fputs("\",\"observed_raw_hex\":\"", stdout);
    for (unsigned byte = 0U;
         byte < sizeof(static_template->raw); ++byte)
        printf("%02X", static_template->raw[byte]);
    printf("\",\"expected_raw_fnv1a64\":\"%016" PRIX64 "\","
           "\"observed_raw_fnv1a64\":\"%016" PRIX64 "\","
           "\"runtime_template_found\":%s,"
           "\"runtime_template_index\":%d,"
           "\"runtime_template_local_id\":%u,"
           "\"runtime_template_position\":[%d,%d],"
           "\"runtime_template_script\":\"0x%08" PRIX32 "\","
           "\"runtime_template_position_exact\":true,"
           "\"runtime_template_script_exact\":true,"
           "\"live_active\":%s,\"live_visible\":%s,"
           "\"live_current\":",
           row->expected_template_hash,
           static_template->raw_hash,
           runtime_template->found ? "true" : "false",
           runtime_template->slot, runtime_template->local_id,
           runtime_template->x, runtime_template->y,
           runtime_template->script,
           snapshot->object.active ? "true" : "false",
           snapshot->object.active && !snapshot->object.invisible
               ? "true" : "false");
    if (snapshot->object.active)
        printf("[%d,%d]", snapshot->object.current_x,
               snapshot->object.current_y);
    else
        fputs("null", stdout);
    fputs(",\"map_lifecycle\":", stdout);
    if (row->runtime_position_producer.kind
            == S61_CATALOG_RUNTIME_POSITION_TRAINER_TOWER_ON_TRANSITION) {
        printf("{\"kind\":\"TRAINER_TOWER_ON_TRANSITION\","
               "\"root\":\"0x%08" PRIX32 "\","
               "\"map_script_tag\":%u,"
               "\"layout_id_expected\":%u,"
               "\"layout_id_observed\":%u,"
               "\"expected_object\":[%u,%u],"
               "\"runtime_template_position\":[%d,%d],"
               "\"expected_movement_type\":%u,"
               "\"runtime_template_movement_type\":%u,"
               "\"live_expected_visible\":%s,"
               "\"live_active\":%s,\"live_current\":",
               row->runtime_position_producer.root,
               row->runtime_position_producer.map_script_tag,
               row->runtime_position_producer.lifecycle_layout_id,
               snapshot->map_layout_id, row->object_x, row->object_y,
               runtime_template->x, runtime_template->y,
               row->runtime_position_producer
                   .lifecycle_expected_movement_type,
               runtime_template->movement_type,
               row->expect_visible ? "true" : "false",
               snapshot->object.active ? "true" : "false");
        if (snapshot->object.active)
            printf("[%d,%d]", snapshot->object.current_x,
                   snapshot->object.current_y);
        else
            fputs("null", stdout);
        fputs(",\"exact\":true}", stdout);
    } else {
        fputs("null", stdout);
    }
    fputs(",\"exact\":true}", stdout);
}

static bool s61_catalog_approach_exact(
    const struct S61CatalogRow *row,
    const struct S61Capture *capture,
    const struct S61CatalogApproachObservation *observation)
{
    return observation->attempted
        && observation->walk_step_count == row->walk_key_count
        && observation->final_x == row->stance_x
        && observation->final_y == row->stance_y
        && observation->facing_after_face_input
            == observation->required_facing
        && observation->facing_changed_when_required
        && !capture->invalid_control_flow
        && capture->script_context_active_instructions == 0U
        && capture->active_frames == 0U
        && capture->count == 0U
        && capture->printer_call_count == 0U
        && capture->non_overworld_instructions == 0U
        && observation->effect_hook_hits_after
            == observation->effect_hook_hits_before
        && observation->persistent_exact;
}

static void s61_report_catalog_approach_failure(
    const struct S61CatalogRow *row,
    const struct S61Capture *capture,
    const struct S61CatalogApproachObservation *observation)
{
    fprintf(stderr,
            "catalog approach diagnostic case=%s steps=%u/%u "
            "position=%u,%u/%u,%u facing=%u/%u changed=%u "
            "invalid=%u script_instructions=%u message_frames=%u "
            "messages=%u printers=%u non_overworld_instructions=%u "
            "effect_hits=%" PRIu64 "->%" PRIu64 " "
            "save1_unexpected=%u save2_unexpected=%u flags=%u "
            "engine_flags=%u vars=%u items=%u trainers=%u economy=%u "
            "party=%u storage=%u movement=%u persistent=%u\n",
            row->case_id, observation->walk_step_count,
            row->walk_key_count,
            observation->final_x, observation->final_y,
            row->stance_x, row->stance_y,
            observation->facing_after_face_input,
            observation->required_facing,
            observation->facing_changed_when_required ? 1U : 0U,
            capture->invalid_control_flow ? 1U : 0U,
            capture->script_context_active_instructions,
            capture->active_frames, capture->count,
            capture->printer_call_count,
            capture->non_overworld_instructions,
            observation->effect_hook_hits_before,
            observation->effect_hook_hits_after,
            observation->saveblock1_unexpected_changed_bytes,
            observation->saveblock2_unexpected_changed_bytes,
            observation->flags_exact ? 1U : 0U,
            observation->engine_special_flags_exact ? 1U : 0U,
            observation->vars_exact ? 1U : 0U,
            observation->items_exact ? 1U : 0U,
            observation->trainers_exact ? 1U : 0U,
            observation->economy_exact ? 1U : 0U,
            observation->party_exact ? 1U : 0U,
            observation->storage_exact ? 1U : 0U,
            observation->movement_owned_state.exact ? 1U : 0U,
            observation->persistent_exact ? 1U : 0U);
}

static void s61_print_catalog_movement_counter(
    const struct S61CatalogMovementCounterObservation *counter,
    const char *transition)
{
    printf("{\"saveblock1_offset\":%" PRIu32 ","
           "\"before\":%" PRIu32 ",\"after\":%" PRIu32 ","
           "\"expected_after\":%" PRIu32 ","
           "\"transition\":\"%s\",\"exact\":%s}",
           counter->saveblock1_offset, counter->before, counter->after,
           counter->expected_after, transition,
           counter->exact ? "true" : "false");
}

static void s61_print_catalog_movement_owned_state(
    const struct S61CatalogMovementOwnedStateObservation *movement)
{
    printf("{\"walk_steps\":%u,\"happiness_step_counter\":",
           movement->walk_steps);
    s61_print_catalog_movement_counter(
        &movement->happiness_step_counter, "ADD_MOD_128");
    fputs(",\"poison_step_counter\":", stdout);
    s61_print_catalog_movement_counter(
        &movement->poison_step_counter, "ADD_MOD_5");
    fputs(",\"renewable_item_step_counter\":", stdout);
    s61_print_catalog_movement_counter(
        &movement->renewable_item_step_counter, "ADD_CAP_1500");
    fputs(",\"game_stat_steps\":", stdout);
    s61_print_catalog_movement_counter(
        &movement->game_stat_steps, "DECRYPT_ADD_CAP_16777215");
    fputs(",\"daycare_step_counter\":", stdout);
    s61_print_catalog_movement_counter(
        &movement->daycare_step_counter, "ADD_MOD_256");
    printf(",\"exact\":%s}", movement->exact ? "true" : "false");
}

static void s61_print_catalog_approach_observation(
    const struct S61CatalogRow *row,
    const struct S61Capture *capture,
    const struct S61CatalogApproachObservation *observation)
{
    printf("{\"capture_armed_before_first_walk_instruction\":true,"
           "\"walk_path_basis\":\"%s\","
           "\"start\":[%u,%u],\"stance\":[%u,%u],"
           "\"walk_step_count\":%u,\"step_facing\":[",
           row->walk_path_basis,
           observation->start_x, observation->start_y,
           observation->final_x, observation->final_y,
           observation->walk_step_count);
    for (unsigned index = 0U;
         index < observation->walk_step_count; ++index) {
        if (index != 0U)
            putchar(',');
        printf("{\"expected\":%u,\"observed\":%u}",
               s61_direction_facing(row->walk_keys[index]),
               observation->facing_after_each_step[index]);
    }
    printf("],\"facing\":{\"raw_owner\":\"gObjectEvents["
           "gPlayerAvatar.objectEventId]+0x18.low_nibble\","
           "\"mapping\":{\"DOWN\":1,\"UP\":2,\"LEFT\":3,"
           "\"RIGHT\":4},\"before_walk\":%u,"
           "\"after_walk\":%u,\"required\":%u,"
           "\"after_face_input\":%u,"
           "\"changed_when_required\":%s,\"exact\":true},"
           "\"transient_execution\":{"
           "\"script_context_active_instructions\":%u,"
           "\"message_active_frames\":%u,\"message_count\":%u,"
           "\"printer_call_count\":%u,"
           "\"non_overworld_instructions\":%u,"
           "\"effect_observer_enabled\":%s,"
           "\"effect_hook_hits_before\":%" PRIu64 ","
           "\"effect_hook_hits_after\":%" PRIu64 ","
           "\"invalid_control_flow\":%s,\"exact_zero\":true},"
           "\"persistent_state\":{",
           observation->facing_before_walk,
           observation->facing_after_walk,
           observation->required_facing,
           observation->facing_after_face_input,
           observation->facing_changed_when_required ? "true" : "false",
           capture->script_context_active_instructions,
           capture->active_frames, capture->count,
           capture->printer_call_count,
           capture->non_overworld_instructions,
           s61_effect_observer.enabled ? "true" : "false",
           observation->effect_hook_hits_before,
           observation->effect_hook_hits_after,
           capture->invalid_control_flow ? "true" : "false");
    printf("\"saveblock1_unexpected_changed_bytes\":%u,"
           "\"saveblock2_unexpected_changed_bytes\":%u,"
           "\"allowed_saveblock1_ranges\":["
           "{\"start\":0,\"end\":4,\"meaning\":\"player_xy\"},"
           "{\"start\":%u,\"end\":%u,"
           "\"meaning\":\"happiness_step_counter_exact_transition\"},"
           "{\"start\":%u,\"end\":%u,"
           "\"meaning\":\"poison_step_counter_exact_transition\"},"
           "{\"start\":%u,\"end\":%u,"
           "\"meaning\":\"renewable_item_step_counter_exact_transition\"},"
           "{\"start\":%u,\"end\":%u,"
           "\"meaning\":\"encrypted_game_stat_steps_exact_transition\"},"
           "{\"start\":%u,\"end\":%u,"
           "\"meaning\":\"daycare_step_counter_exact_transition\"}],"
           "\"allowed_saveblock2_ranges\":[{\"start\":%u,"
           "\"end\":%u,\"meaning\":\"play_time_vblank_owner\"}],"
           "\"movement_owned_state\":",
           observation->saveblock1_unexpected_changed_bytes,
           observation->saveblock2_unexpected_changed_bytes,
           S61_SAVE1_HAPPINESS_STEP_COUNTER_OFFSET,
           S61_SAVE1_HAPPINESS_STEP_COUNTER_OFFSET + 2U,
           S61_SAVE1_POISON_STEP_COUNTER_OFFSET,
           S61_SAVE1_POISON_STEP_COUNTER_OFFSET + 2U,
           S61_SAVE1_RENEWABLE_ITEM_STEP_COUNTER_OFFSET,
           S61_SAVE1_RENEWABLE_ITEM_STEP_COUNTER_OFFSET + 2U,
           S61_SAVE1_GAME_STAT_STEPS_OFFSET,
           S61_SAVE1_GAME_STAT_STEPS_OFFSET + 4U,
           S61_SAVE1_DAYCARE_STEP_COUNTER_OFFSET,
           S61_SAVE1_DAYCARE_STEP_COUNTER_OFFSET + 1U,
           S61_SAVE_BLOCK2_PLAY_TIME_START,
           S61_SAVE_BLOCK2_PLAY_TIME_END);
    s61_print_catalog_movement_owned_state(
        &observation->movement_owned_state);
    printf(",\"flags_exact\":%s,\"engine_special_flags_exact\":%s,"
           "\"vars_exact\":%s,\"items_exact\":%s,"
           "\"trainers_exact\":%s,\"economy_exact\":%s,"
           "\"party_exact\":%s,\"storage_exact\":%s,"
           "\"exact\":%s},\"exact\":%s}",
           observation->flags_exact ? "true" : "false",
           observation->engine_special_flags_exact ? "true" : "false",
           observation->vars_exact ? "true" : "false",
           observation->items_exact ? "true" : "false",
           observation->trainers_exact ? "true" : "false",
           observation->economy_exact ? "true" : "false",
           observation->party_exact ? "true" : "false",
           observation->storage_exact ? "true" : "false",
           observation->persistent_exact ? "true" : "false",
           s61_catalog_approach_exact(row, capture, observation)
               ? "true" : "false");
}

static bool s61_snapshot_flag(const struct S61SideEffectSnapshot *snapshot,
                              uint16_t id)
{
    if (id < 0x0900U)
        return (snapshot->stock_flags[id >> 3U] & (1U << (id & 7U))) != 0U;
    return (snapshot->expanded_flags[(id - 0x0900U) >> 3U]
            & (1U << (id & 7U))) != 0U;
}

static uint16_t s61_snapshot_var(
    const struct S61SideEffectSnapshot *snapshot, uint16_t id)
{
    if (id < 0x5000U)
        return snapshot->stock_vars[id - 0x4000U];
    return snapshot->expanded_vars[id - 0x5000U];
}

static uint32_t s61_snapshot_item(
    const struct S61SideEffectSnapshot *snapshot, uint16_t id)
{
    unsigned low = 0U;
    unsigned high = snapshot->item_count;
    while (low < high) {
        unsigned middle = low + (high - low) / 2U;
        if (snapshot->items[middle].id < id)
            low = middle + 1U;
        else
            high = middle;
    }
    return low < snapshot->item_count && snapshot->items[low].id == id
        ? snapshot->items[low].quantity : 0U;
}

static unsigned s61_walk_approach(struct mCore *core,
                                  const struct S61Interaction *fixture)
{
    struct FixtureResult movement = {0};
    uint32_t save1 = world_save1(core, s61_case_name);
    uint16_t x = read16(core, save1);
    uint16_t y = read16(core, save1 + 2U);
    unsigned moved = 0U;
    for (unsigned step = 0U; step < fixture->approach_steps; ++step) {
        if (!world_walk_to_new_tile(core, fixture->action_key,
                                    &x, &y, &movement))
            s61_die("legal approach step did not move the player");
        ++moved;
    }
    /* One blocked directional pulse establishes facing; A is separate so a
     * harness can never pass by invoking an event routine directly. */
    uint16_t before_x = read16(core, save1);
    uint16_t before_y = read16(core, save1 + 2U);
    s61_pulse(core, fixture->action_key, 2U, 12U, NULL);
    if (read16(core, save1) != before_x || read16(core, save1 + 2U) != before_y)
        s61_die("final facing pulse moved instead of meeting the target");
    return moved;
}

static uint8_t s61_direction_facing(uint16_t key)
{
    if (key == WORLD_KEY_DOWN)
        return 1U;
    if (key == WORLD_KEY_UP)
        return 2U;
    if (key == WORLD_KEY_LEFT)
        return 3U;
    if (key == WORLD_KEY_RIGHT)
        return 4U;
    s61_die("catalog facing key is not cardinal");
    return 0U;
}

static uint8_t s61_player_facing(struct mCore *core)
{
    uint8_t object_id = read8(core, WORLD_PLAYER_AVATAR + 5U);
    if (object_id >= S61_RUNTIME_OBJECT_SLOT_COUNT)
        s61_die("catalog player object ID is outside runtime slots");
    uint32_t object = WORLD_OBJECT_EVENTS + object_id * 0x24U;
    if ((read8(core, object) & 1U) == 0U)
        s61_die("catalog player object is inactive");
    uint8_t facing = read8(core, object + 0x18U) & 0x0FU;
    if (facing < 1U || facing > 4U)
        s61_die("catalog player object facing nibble is invalid");
    return facing;
}

static uint16_t s61_snapshot_u16(const uint8_t *raw, size_t offset)
{
    return (uint16_t)raw[offset]
        | ((uint16_t)raw[offset + 1U] << 8U);
}

static uint32_t s61_snapshot_u32(const uint8_t *raw, size_t offset)
{
    return (uint32_t)raw[offset]
        | ((uint32_t)raw[offset + 1U] << 8U)
        | ((uint32_t)raw[offset + 2U] << 16U)
        | ((uint32_t)raw[offset + 3U] << 24U);
}

static void s61_catalog_movement_counter(
    struct S61CatalogMovementCounterObservation *result,
    uint32_t offset, uint32_t before, uint32_t after,
    uint32_t expected_after)
{
    result->saveblock1_offset = offset;
    result->before = before;
    result->after = after;
    result->expected_after = expected_after;
    result->exact = after == expected_after;
}

static void s61_catalog_approach_movement_owned_observation(
    const struct S61SideEffectSnapshot *before,
    const struct S61SideEffectSnapshot *after, unsigned walk_steps,
    struct S61CatalogMovementOwnedStateObservation *result)
{
    uint32_t before_value = s61_snapshot_u16(
        before->saveblock1, S61_SAVE1_HAPPINESS_STEP_COUNTER_OFFSET);
    uint32_t after_value = s61_snapshot_u16(
        after->saveblock1, S61_SAVE1_HAPPINESS_STEP_COUNTER_OFFSET);
    s61_catalog_movement_counter(
        &result->happiness_step_counter,
        S61_SAVE1_HAPPINESS_STEP_COUNTER_OFFSET,
        before_value, after_value, (before_value + walk_steps) % 128U);

    before_value = s61_snapshot_u16(
        before->saveblock1, S61_SAVE1_POISON_STEP_COUNTER_OFFSET);
    after_value = s61_snapshot_u16(
        after->saveblock1, S61_SAVE1_POISON_STEP_COUNTER_OFFSET);
    s61_catalog_movement_counter(
        &result->poison_step_counter,
        S61_SAVE1_POISON_STEP_COUNTER_OFFSET,
        before_value, after_value, (before_value + walk_steps) % 5U);

    before_value = s61_snapshot_u16(
        before->saveblock1,
        S61_SAVE1_RENEWABLE_ITEM_STEP_COUNTER_OFFSET);
    after_value = s61_snapshot_u16(
        after->saveblock1,
        S61_SAVE1_RENEWABLE_ITEM_STEP_COUNTER_OFFSET);
    uint32_t renewable_expected = before_value + walk_steps;
    if (renewable_expected > 1500U)
        renewable_expected = 1500U;
    s61_catalog_movement_counter(
        &result->renewable_item_step_counter,
        S61_SAVE1_RENEWABLE_ITEM_STEP_COUNTER_OFFSET,
        before_value, after_value, renewable_expected);

    uint32_t before_key = s61_snapshot_u32(
        before->saveblock2, S61_SAVE2_ENCRYPTION_KEY_OFFSET);
    uint32_t after_key = s61_snapshot_u32(
        after->saveblock2, S61_SAVE2_ENCRYPTION_KEY_OFFSET);
    before_value = s61_snapshot_u32(
        before->saveblock1, S61_SAVE1_GAME_STAT_STEPS_OFFSET) ^ before_key;
    after_value = s61_snapshot_u32(
        after->saveblock1, S61_SAVE1_GAME_STAT_STEPS_OFFSET) ^ after_key;
    uint32_t game_stat_expected = before_value + walk_steps;
    if (game_stat_expected > 0x00FFFFFFU
        || game_stat_expected < before_value)
        game_stat_expected = 0x00FFFFFFU;
    s61_catalog_movement_counter(
        &result->game_stat_steps, S61_SAVE1_GAME_STAT_STEPS_OFFSET,
        before_value, after_value, game_stat_expected);
    result->game_stat_steps.exact = result->game_stat_steps.exact
        && before_key == after_key;

    before_value = before->saveblock1[
        S61_SAVE1_DAYCARE_STEP_COUNTER_OFFSET];
    after_value = after->saveblock1[
        S61_SAVE1_DAYCARE_STEP_COUNTER_OFFSET];
    s61_catalog_movement_counter(
        &result->daycare_step_counter,
        S61_SAVE1_DAYCARE_STEP_COUNTER_OFFSET,
        before_value, after_value,
        (uint8_t)(before_value + walk_steps));

    result->walk_steps = walk_steps;
    result->exact = result->happiness_step_counter.exact
        && result->poison_step_counter.exact
        && result->renewable_item_step_counter.exact
        && result->game_stat_steps.exact
        && result->daycare_step_counter.exact;
}

static bool s61_catalog_approach_movement_owned_offset(size_t offset)
{
    return (offset >= S61_SAVE1_HAPPINESS_STEP_COUNTER_OFFSET
            && offset < S61_SAVE1_HAPPINESS_STEP_COUNTER_OFFSET + 2U)
        || (offset >= S61_SAVE1_POISON_STEP_COUNTER_OFFSET
            && offset < S61_SAVE1_POISON_STEP_COUNTER_OFFSET + 2U)
        || (offset >= S61_SAVE1_RENEWABLE_ITEM_STEP_COUNTER_OFFSET
            && offset < S61_SAVE1_RENEWABLE_ITEM_STEP_COUNTER_OFFSET + 2U)
        || (offset >= S61_SAVE1_GAME_STAT_STEPS_OFFSET
            && offset < S61_SAVE1_GAME_STAT_STEPS_OFFSET + 4U)
        || offset == S61_SAVE1_DAYCARE_STEP_COUNTER_OFFSET;
}

static bool s61_catalog_approach_vars_exact(
    const struct S61SideEffectSnapshot *before,
    const struct S61SideEffectSnapshot *after)
{
    for (unsigned index = 0U; index < S61_STOCK_VAR_COUNT; ++index) {
        if (index == 0x21U || index == 0x22U || index == 0x23U)
            continue;
        if (before->stock_vars[index] != after->stock_vars[index])
            return false;
    }
    return memcmp(before->expanded_vars, after->expanded_vars,
                  sizeof(before->expanded_vars)) == 0;
}

static unsigned s61_catalog_approach_saveblock_delta_count(
    const uint8_t *before, const uint8_t *after, size_t size,
    unsigned block)
{
    unsigned count = 0U;
    for (size_t offset = 0U; offset < size; ++offset) {
        /* The five stock movement owners below are not silently volatile:
         * their semantic transitions are checked independently against the
         * exact number of physically completed tiles.  Only after that
         * observation are their storage bytes excluded from this residual
         * mutation count. */
        if ((block == 1U
             && (offset < 4U
                 || s61_catalog_approach_movement_owned_offset(offset)))
            || s61_saveblock_byte_is_volatile(block, offset))
            continue;
        if (before[offset] != after[offset])
            ++count;
    }
    return count;
}

static void s61_catalog_approach_persistent_observation(
    const struct S61SideEffectSnapshot *before,
    const struct S61SideEffectSnapshot *after,
    struct S61CatalogApproachObservation *result)
{
    s61_catalog_approach_movement_owned_observation(
        before, after, result->walk_step_count,
        &result->movement_owned_state);
    result->saveblock1_unexpected_changed_bytes =
        s61_catalog_approach_saveblock_delta_count(
            before->saveblock1, after->saveblock1,
            sizeof(before->saveblock1), 1U);
    result->saveblock2_unexpected_changed_bytes =
        s61_catalog_approach_saveblock_delta_count(
            before->saveblock2, after->saveblock2,
            sizeof(before->saveblock2), 2U);
    result->flags_exact = before->flags_hash == after->flags_hash;
    result->engine_special_flags_exact =
        before->engine_special_flags_hash
            == after->engine_special_flags_hash;
    result->vars_exact = s61_catalog_approach_vars_exact(before, after);
    result->items_exact = before->items_hash == after->items_hash
        && before->bag_entry_count == after->bag_entry_count;
    result->trainers_exact =
        before->trainers_hash == after->trainers_hash;
    result->economy_exact = before->money == after->money
        && before->berry_powder == after->berry_powder
        && before->vega_coins == after->vega_coins
        && before->cfru_coins == after->cfru_coins;
    result->party_exact = before->party_count == after->party_count
        && strcmp(before->party_raw_sha256, after->party_raw_sha256) == 0;
    result->storage_exact = strcmp(
        before->storage_raw_sha256, after->storage_raw_sha256) == 0;
    result->persistent_exact =
        result->saveblock1_unexpected_changed_bytes == 0U
        && result->saveblock2_unexpected_changed_bytes == 0U
        && result->movement_owned_state.exact
        && result->flags_exact
        && result->engine_special_flags_exact
        && result->vars_exact
        && result->items_exact
        && result->trainers_exact
        && result->economy_exact
        && result->party_exact
        && result->storage_exact;
}

static unsigned s61_walk_catalog_execution(
    struct mCore *core, const struct S61CatalogRow *row,
    struct S61Capture *capture,
    struct S61CatalogApproachObservation *observation)
{
    uint32_t save1 = world_save1(core, s61_case_name);
    uint16_t x = read16(core, save1);
    uint16_t y = read16(core, save1 + 2U);
    observation->attempted = true;
    observation->start_x = x;
    observation->start_y = y;
    observation->facing_before_walk = s61_player_facing(core);
    observation->required_facing = s61_direction_facing(
        row->interaction.action_key);
    if (x != row->interaction.start_x || y != row->interaction.start_y)
        s61_die("catalog physical walk did not begin at authored start");
    for (unsigned index = 0U; index < row->walk_key_count; ++index) {
        uint16_t key = row->walk_keys[index];
        if (key == WORLD_KEY_RIGHT)
            ++x;
        else if (key == WORLD_KEY_LEFT)
            --x;
        else if (key == WORLD_KEY_DOWN)
            ++y;
        else if (key == WORLD_KEY_UP)
            --y;
        else
            s61_die("catalog authored walk contains a non-cardinal key");
        if (!s61_stateful_walk_one_tile_exact(
                core, key, x, y, capture))
            s61_die("catalog authored physical walk did not move");
        uint8_t observed_facing = s61_player_facing(core);
        observation->facing_after_each_step[index] = observed_facing;
        ++observation->walk_step_count;
        if (observed_facing != s61_direction_facing(key))
            s61_die("catalog player facing differs after physical walk step");
    }
    if (x != row->stance_x || y != row->stance_y
        || observation->walk_step_count != row->walk_key_count)
        s61_die("catalog authored physical walk did not end at stance");
    observation->facing_after_walk = s61_player_facing(core);
    uint16_t before_x = x;
    uint16_t before_y = y;
    s61_step_capture_pulse(
        core, row->interaction.action_key, 2U, 12U, capture);
    if (read16(core, save1) != before_x || read16(core, save1 + 2U) != before_y)
        s61_die("catalog face pulse moved through object/counter target");
    observation->final_x = read16(core, save1);
    observation->final_y = read16(core, save1 + 2U);
    observation->facing_after_face_input = s61_player_facing(core);
    observation->facing_changed_when_required =
        observation->facing_after_walk == observation->required_facing
        || observation->facing_after_face_input
            != observation->facing_after_walk;
    if (observation->facing_after_face_input != observation->required_facing
        || !observation->facing_changed_when_required)
        s61_die("catalog blocked face input did not set required facing");
    return observation->walk_step_count;
}

static bool s61_battle_active(struct mCore *core)
{
    /* CFRU keeps the allocated battle struct and battler count as reusable
     * stale storage after CB2 has returned to the field.  They prove runtime
     * initialization only while the overworld callback does not own input. */
    return !world_overworld(core)
        && (read32(core, ADDR_NEW_BATTLE_STRUCT_POINTER) != 0U
            || read8(core, ADDR_BATTLERS_COUNT) != 0U);
}

static bool s61_drive_interaction_limited(
    struct mCore *core, uint16_t action_key, enum S61Choice choice,
    struct S61Capture *capture, bool stop_at_battle, unsigned pulse_limit,
    bool establish_facing, bool initialize_var_result)
{
    if (initialize_var_result)
        write16(core, WORLD_SPECIAL_RESULT, 0xFFFFU);
    if (establish_facing)
        s61_pulse(core, action_key, 2U, 10U, capture);
    s61_pulse(core, WORLD_KEY_A, 2U, 20U, capture);
    /* A short finite script can acquire and release the context entirely
     * inside s61_pulse.  Frame-by-frame message-state capture is therefore
     * also authoritative evidence that ordinary A input reached the owner;
     * relying on the lock value sampled after the pulse creates a false
     * negative for single-page dialogue. */
    bool saw_owner = world_script_enabled(core)
        || capture->active_frames != 0U || capture->count != 0U
        || capture->printer_call_count != 0U;
    unsigned quiet = 0U;
    for (unsigned pulse = 0U; pulse < pulse_limit; ++pulse) {
        if (world_script_enabled(core)
            || capture->active_frames != 0U || capture->count != 0U
            || capture->printer_call_count != 0U)
            saw_owner = true;
        if (s61_battle_active(core))
            return stop_at_battle && saw_owner;
        bool field_terminal = world_overworld(core)
            && !world_script_enabled(core)
            && read8(core, S61_FIELD_MESSAGE_STATE) == 0U;
        if (field_terminal) {
            if (saw_owner && ++quiet >= 6U)
                return saw_owner;
            if (saw_owner) {
                /* Do not press A again after a dialogue has genuinely
                 * released: that would immediately reopen the same NPC and
                 * make finite scripts appear stuck. */
                s61_frames(core, 0U, 15U, capture);
                continue;
            }
        } else {
            quiet = 0U;
        }
        uint16_t key = WORLD_KEY_A;
        if (choice == S61_CHOICE_ADVANCE && capture->count != 0U
            && pulse >= 8U && pulse % 4U == 3U) {
            /* Stock item-obtain/pocket notices can keep A assigned to their
             * fanfare task while B is the ordinary dismiss key.  Start every
             * owner with direction+A, then add sparse real B presses only
             * after several A advances so both standard message tasks are
             * exercised without host-calling the script. */
            key = WORLD_KEY_B;
        } else if (choice == S61_CHOICE_CANCEL && capture->count != 0U) {
            key = WORLD_KEY_B;
        } else if (choice == S61_CHOICE_NO && capture->count != 0U) {
            /* B advances preceding text safely and becomes the stock No/
             * cancel decision only when the Yes/No task owns input.  Repeat
             * until that task writes VAR_RESULT; a single timed B pulse is
             * vulnerable to text-speed and printer timing differences. */
            key = WORLD_KEY_B;
        } else if (choice == S61_CHOICE_YES
                   && capture->count != 0U && pulse >= 2U) {
            key = WORLD_KEY_A;
        }
        s61_pulse(core, key, 2U, 45U, capture);
    }
    /* The final ordinary key pulse can be the one that dismisses a long
     * multi-page/item notice.  Observe a released-key tail before declaring
     * failure; otherwise the terminal transition occurs inside the final
     * pulse and is never sampled by the loop header. */
    for (unsigned tail = 0U; tail < 12U; ++tail) {
        if (world_script_enabled(core)
            || capture->active_frames != 0U || capture->count != 0U
            || capture->printer_call_count != 0U)
            saw_owner = true;
        if (s61_battle_active(core))
            return stop_at_battle && saw_owner;
        if (world_overworld(core) && !world_script_enabled(core)
            && read8(core, S61_FIELD_MESSAGE_STATE) == 0U) {
            if (++quiet >= 6U)
                return saw_owner;
        } else {
            quiet = 0U;
        }
        s61_frames(core, 0U, 15U, capture);
    }
    return false;
}

static bool s61_drive_interaction(struct mCore *core, uint16_t action_key,
                                  enum S61Choice choice,
                                  struct S61Capture *capture,
                                  bool stop_at_battle)
{
    return s61_drive_interaction_limited(
        core, action_key, choice, capture, stop_at_battle, 160U, true, true);
}

struct S61SequenceDriveResult {
    bool terminal_seen;
    bool premature_terminal;
    unsigned steps_consumed;
    bool map_source_setup;
    bool map_predecessor_tile;
    bool map_real_warp_step;
    bool map_real_connection_step;
    bool map_engine_teleport;
    bool map_destination_loaded;
    bool map_arrival_tile;
    bool map_field_recovered_before_start;
    bool map_start_pressed;
    bool map_start_menu_opened;
    bool map_back_pressed;
    bool map_field_return_callback_dispatched;
    bool map_callback_ordered;
    bool map_input_recovered;
    unsigned map_owner_hits_before_start;
    uint8_t map_load_root_group;
    uint8_t map_load_root_map;
    uint16_t map_load_root_x;
    uint16_t map_load_root_y;
    bool map_load_root_identity_captured;
    bool event_walk_start_confirmed;
    bool event_walk_path_exact;
    bool event_walk_final_tile_confirmed;
    bool event_walk_stance_confirmed;
    unsigned trigger_real_walk_steps;
    unsigned event_walk_step_count;
    uint16_t event_walk_observed_x[S61_CATALOG_MAX_INPUT_STEPS];
    uint16_t event_walk_observed_y[S61_CATALOG_MAX_INPUT_STEPS];
};

struct S61BattleLifecycleResult {
    bool battle_started;
    bool trainer_battle;
    bool completed_via_keys;
    unsigned forced_switch_count;
    bool forced_switch_cursor_observed;
    bool forced_switch_usable_slot_selected;
    uint8_t forced_switch_cursor_initial[WORLD_MAX_FORCED_SWITCHES];
    uint8_t forced_switch_selected_slot[WORLD_MAX_FORCED_SWITCHES];
    uint16_t forced_switch_selected_hp[WORLD_MAX_FORCED_SWITCHES];
    enum {
        S61_BATTLE_ROUTE_NONE,
        S61_BATTLE_ROUTE_FIGHT,
        S61_BATTLE_ROUTE_RUN,
    } route;
    uint8_t outcome;
    bool won_or_escaped_not_loss;
    bool field_released_after_battle;
    bool start_pressed;
    bool start_menu_opened;
    bool back_pressed;
    bool map_preserved;
    bool field_input_recovered;
};

struct S61FieldRoundtripResult {
    bool controls_released;
    bool running_state_released;
    bool tile_transition_released;
    bool start_pressed;
    bool start_menu_opened;
    bool back_pressed;
    bool callback_ordered;
    bool map_preserved;
    bool field_input_recovered;
    uint32_t field_callback_before;
    uint32_t menu_callback_observed;
    uint32_t field_callback_after;
};

static bool s61_field_terminal(struct mCore *core)
{
    return world_overworld(core) && !world_script_enabled(core)
        && read8(core, S61_FIELD_MESSAGE_STATE) == 0U
        && !s61_battle_active(core);
}

static const char *s61_post_battle_resume_kind_name(
    enum S61PostBattleResumeKind kind)
{
    if (kind == S61_POST_BATTLE_STANDARD)
        return "STANDARD";
    if (kind == S61_POST_BATTLE_EXPLICIT)
        return "EXPLICIT";
    if (kind == S61_POST_BATTLE_NEXT_PC)
        return "NEXT_PC";
    return "NONE";
}

static const char *s61_battle_kind_name(enum S61BattleKind kind)
{
    if (kind == S61_BATTLE_KIND_TRAINER)
        return "TRAINER";
    if (kind == S61_BATTLE_KIND_TRAINER_TOWER)
        return "TRAINER_TOWER";
    if (kind == S61_BATTLE_KIND_SCRIPTED_WILD)
        return "SCRIPTED_WILD";
    return "UNKNOWN";
}

static bool s61_post_battle_boundary_matches(
    struct mCore *core, const struct S61PostBattleContinuationResult *result,
    uint32_t *observed_pc)
{
    if (!world_overworld(core)
        || read8(core, WORLD_SCRIPT_CONTEXT1_STATE) != 0U)
        return false;
    uint32_t pointer = read32(core, WORLD_SCRIPT_CONTEXT1_POINTER);
    if (pointer < 0x08000000U || pointer >= 0x0A000000U)
        return false;
    if (result->resume_kind == S61_POST_BATTLE_STANDARD) {
        /* FireRed's EventScript_EndTrainerBattle is exactly releaseall/end.
         * Starting here deliberately excludes the engine's preceding
         * GetTrainerBattleMode branch from the source continuation contract. */
        if (pointer + 1U >= 0x0A000000U
            || read8(core, pointer) != 0x6BU
            || read8(core, pointer + 1U) != 0x02U)
            return false;
    } else if (pointer != result->expected_resume_pc) {
        return false;
    }
    *observed_pc = pointer;
    return true;
}

static void s61_open_post_battle_capture(
    struct mCore *core, struct S61PostBattleContinuationResult *result,
    uint32_t observed_pc)
{
    if (s61_active_post_battle != NULL || result->capture_open)
        s61_die("post-battle continuation capture is already active");
    result->boundary_observed = true;
    result->observed_resume_pc = observed_pc;
    result->resume_pc_hit_count = 1U;
    result->decision_initial_value = read16(core, WORLD_SPECIAL_RESULT);
    memcpy(result->capture.baseline, s61_video,
           sizeof(result->capture.baseline));
    result->capture.track_var_result_instructions = true;
    if (result->decision_initial_value != 0xFFFFU) {
        result->capture.var_result_seen = true;
        result->capture.first_var_result = result->decision_initial_value;
        result->capture.last_var_result = result->decision_initial_value;
    }
    result->capture_open = true;
    result->last_context_active = true;
    result->last_script_pointer = observed_pc;
    s61_active_post_battle = result;
}

static void s61_wait_for_post_battle_boundary(
    struct mCore *core, const char *case_id,
    struct S61PostBattleContinuationResult *result)
{
    core->setKeys(core, 0U);
    uint32_t first_frame = core->frameCounter(core);
    while ((uint32_t)(core->frameCounter(core) - first_frame) < 1200U) {
        uint32_t observed_pc = 0U;
        if (s61_post_battle_boundary_matches(core, result, &observed_pc)) {
            s61_open_post_battle_capture(core, result, observed_pc);
            return;
        }
        uint32_t raw_pc = (uint32_t)read_register(core, "pc");
        s61_effect_observer_sample_pc(core, raw_pc);
        core->step(core);
    }
    fprintf(stderr,
            "post-battle boundary diagnostic case=%s kind=%s expected=%08"
            PRIX32 " context_state=%u context_pointer=%08" PRIX32
            " callback=%08" PRIX32 " field_terminal=%u\n",
            case_id, s61_post_battle_resume_kind_name(result->resume_kind),
            result->expected_resume_pc,
            read8(core, WORLD_SCRIPT_CONTEXT1_STATE),
            read32(core, WORLD_SCRIPT_CONTEXT1_POINTER),
            read32(core, BATTLE_CORE_MAIN_CALLBACK2),
            s61_field_terminal(core) ? 1U : 0U);
    s61_die("post-battle continuation resume boundary was not observed");
}

static bool s61_chained_battle_boundary_matches(
    struct mCore *core, const struct S61CatalogChainedBattle *expected,
    uint32_t *observed_pc)
{
    if (!world_overworld(core)
        || read8(core, WORLD_SCRIPT_CONTEXT1_STATE) != 0U)
        return false;
    uint32_t pointer = read32(core, WORLD_SCRIPT_CONTEXT1_POINTER);
    if (pointer < 0x08000000U || pointer >= 0x0A000000U)
        return false;
    if (expected->resume_kind == S61_POST_BATTLE_STANDARD) {
        if (pointer + 1U >= 0x0A000000U
            || read8(core, pointer) != 0x6BU
            || read8(core, pointer + 1U) != 0x02U)
            return false;
    } else if (pointer != expected->resume_pc) {
        return false;
    }
    *observed_pc = pointer;
    return true;
}

static void s61_wait_for_chained_battle_boundary(
    struct mCore *core, const char *case_id,
    const struct S61CatalogChainedBattle *expected,
    struct S61ChainedBattleResult *observed)
{
    core->setKeys(core, 0U);
    uint32_t first_frame = core->frameCounter(core);
    while ((uint32_t)(core->frameCounter(core) - first_frame) < 1200U) {
        uint32_t observed_pc = 0U;
        if (s61_chained_battle_boundary_matches(
                core, expected, &observed_pc)) {
            observed->observed_resume_pc = observed_pc;
            observed->resume_pc_hit_count = 1U;
            return;
        }
        uint32_t raw_pc = (uint32_t)read_register(core, "pc");
        s61_effect_observer_sample_pc(core, raw_pc);
        core->step(core);
    }
    fprintf(stderr,
            "chained battle boundary diagnostic case=%s phase=%u "
            "kind=%s resume=%s expected=%08" PRIX32
            " context_state=%u context_pointer=%08" PRIX32 "\n",
            case_id, expected->phase_index,
            s61_battle_kind_name(expected->battle_kind),
            s61_post_battle_resume_kind_name(expected->resume_kind),
            expected->resume_pc,
            read8(core, WORLD_SCRIPT_CONTEXT1_STATE),
            read32(core, WORLD_SCRIPT_CONTEXT1_POINTER));
    s61_die("chained battle continuation boundary was not observed");
}

static bool s61_complete_chained_battle_if_active(
    struct mCore *core, const char *case_id, uint8_t expected_group,
    uint8_t expected_map, const struct S61CatalogInputSequence *sequence,
    struct S61PostBattleContinuationResult *result)
{
    if (!s61_battle_active(core))
        return false;
    if (sequence == NULL
        || result->chained_battle_count >= sequence->chained_battle_count)
        s61_die("unexpected chained battle entered post-battle continuation");
    unsigned index = result->chained_battle_count;
    const struct S61CatalogChainedBattle *expected =
        &sequence->chained_battles[index];
    struct S61ChainedBattleResult *observed =
        &result->chained_battles[index];
    observed->observed = true;
    uint32_t battle_type_flags = read32(core, ADDR_BATTLE_TYPE_FLAGS);
    observed->trainer_battle =
        (battle_type_flags & WORLD_BATTLE_TYPE_TRAINER) != 0U;
    observed->observed_trainer_id = read16(core, WORLD_TRAINER_OPPONENT_A);
    bool expected_trainer_battle =
        expected->battle_kind != S61_BATTLE_KIND_SCRIPTED_WILD;
    uint16_t expected_trainer_id = expected->trainer_id_expected
        ? expected->trainer_id : 0U;
    if (observed->trainer_battle != expected_trainer_battle
        || observed->observed_trainer_id != expected_trainer_id) {
        fprintf(stderr,
                "chained battle identity diagnostic case=%s phase=%u "
                "kind=%s trainer=%u/%u trainer_battle=%u/%u\n",
                case_id, expected->phase_index,
                s61_battle_kind_name(expected->battle_kind),
                observed->observed_trainer_id, expected_trainer_id,
                observed->trainer_battle ? 1U : 0U,
                expected_trainer_battle ? 1U : 0U);
        s61_die("chained battle runtime identity differs from source");
    }
    struct Fixture fixture = {
        .name = case_id,
        .kind = FIXTURE_FACING_DIALOGUE,
        .group = expected_group,
        .map = expected_map,
    };
    struct FixtureResult battle = {0};
    world_finish_battle(core, &fixture, &battle, false);
    observed->completed_via_keys = battle.battle_completed;
    observed->outcome = battle.battle_outcome;
    observed->won_or_escaped_not_loss =
        battle.battle_outcome == WORLD_BATTLE_OUTCOME_WON;
    if (!observed->completed_via_keys
        || !observed->won_or_escaped_not_loss)
        s61_die("chained battle did not complete through normal Fight input");
    s61_wait_for_chained_battle_boundary(
        core, case_id, expected, observed);
    ++result->chained_battle_count;
    return true;
}

static void s61_drive_post_battle_continuation(
    struct mCore *core, const char *case_id,
    uint8_t expected_group, uint8_t expected_map,
    const struct S61CatalogInputSequence *sequence,
    struct S61PostBattleContinuationResult *result)
{
    unsigned step_count = sequence == NULL
        ? 0U : sequence->post_battle_step_count;
    /* Let the resumed script reach its first input wait without supplying an
     * uncontracted key.  Every instruction remains inside the phase capture. */
    s61_step_capture_frames(core, 0U, 45U, &result->capture);
    while (s61_complete_chained_battle_if_active(
        core, case_id, expected_group, expected_map, sequence, result)) {
    }
    for (unsigned index = 0U; index < step_count; ++index) {
        while (s61_complete_chained_battle_if_active(
            core, case_id, expected_group, expected_map, sequence, result)) {
        }
        if (s61_active_facility_execution != NULL
            && s61_active_facility_execution->active_boundary_observed) {
            result->premature_terminal = true;
            break;
        }
        if (s61_field_terminal(core)) {
            result->premature_terminal = true;
            break;
        }
        const struct S61CatalogInputStep *step =
            &sequence->post_battle_steps[index];
        if (step->wait_frames != 0U) {
            s61_step_capture_frames(
                core, 0U, step->wait_frames, &result->capture);
        } else {
            s61_step_capture_pulse(
                core, step->key, step->pressed, step->released,
                &result->capture);
        }
        ++result->input_steps_consumed;
        while (s61_complete_chained_battle_if_active(
            core, case_id, expected_group, expected_map, sequence, result)) {
        }
        if (result->capture.invalid_control_flow)
            break;
    }
    unsigned quiet = 0U;
    for (unsigned tail = 0U; tail < 80U && quiet < 6U; ++tail) {
        while (s61_complete_chained_battle_if_active(
            core, case_id, expected_group, expected_map, sequence, result)) {
        }
        if (s61_active_facility_execution != NULL
            && s61_active_facility_execution->active_boundary_observed)
            break;
        if (s61_field_terminal(core))
            ++quiet;
        else
            quiet = 0U;
        s61_step_capture_frames(core, 0U, 15U, &result->capture);
        while (s61_complete_chained_battle_if_active(
            core, case_id, expected_group, expected_map, sequence, result)) {
        }
        if (result->capture.invalid_control_flow)
            break;
    }
    result->field_released = quiet >= 6U && s61_field_terminal(core);
    result->facility_active_boundary =
        s61_active_facility_execution != NULL
        && s61_active_facility_execution->active_boundary_observed;
    result->effect_hook_hits_after = s61_effect_observer_total_hook_hits();
    result->capture_open = false;
    s61_active_post_battle = NULL;
    if (result->premature_terminal
        || result->input_steps_consumed != step_count
        || result->capture.invalid_control_flow
        || (!result->field_released && !result->facility_active_boundary)
        || (result->field_released && result->facility_active_boundary)
        || result->resume_pc_hit_count != 1U
        || result->chained_battle_count != (
            sequence == NULL ? 0U : sequence->chained_battle_count)) {
        fprintf(stderr,
                "post-battle continuation diagnostic case=%s kind=%s "
                "steps=%u/%u premature=%u invalid=%u field=%u hits=%u "
                "active_boundary=%u chained=%u/%u\n",
                case_id,
                s61_post_battle_resume_kind_name(result->resume_kind),
                result->input_steps_consumed, step_count,
                result->premature_terminal ? 1U : 0U,
                result->capture.invalid_control_flow ? 1U : 0U,
                result->field_released ? 1U : 0U,
                result->resume_pc_hit_count,
                result->facility_active_boundary ? 1U : 0U,
                result->chained_battle_count,
                sequence == NULL ? 0U : sequence->chained_battle_count);
        s61_die("post-battle continuation did not satisfy its exact phase");
    }
    if (result->resume_kind == S61_POST_BATTLE_STANDARD
        && (result->capture.count != 0U
            || result->capture.printer_call_count != 0U
            || result->capture.var_result_value_count != 0U))
        s61_die("standard trainer post-battle continuation is not exact empty");
}

static struct S61FieldRoundtripResult s61_field_roundtrip(
    struct mCore *core, const char *case_id,
    uint8_t expected_group, uint8_t expected_map)
{
    struct S61FieldRoundtripResult result = {0};
    uint32_t save1 = world_save1(core, case_id);
    uint8_t map_before[8U];
    s61_read_core_range(core, save1, map_before, sizeof(map_before));
    result.controls_released = s61_field_terminal(core)
        && !world_script_enabled(core)
        && read8(core, WORLD_FIELD_CONTROLS_LOCKED) == 0U;
    result.running_state_released = read8(
        core, WORLD_PLAYER_AVATAR
            + WORLD_PLAYER_RUNNING_STATE_OFFSET) == 0U;
    result.tile_transition_released = read8(
        core, WORLD_PLAYER_AVATAR
            + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET) == 0U;
    result.field_callback_before = read32(
        core, BATTLE_CORE_MAIN_CALLBACK2);
    result.start_pressed = true;
    s61_pulse(core, WORLD_KEY_START, 2U, 120U, NULL);
    result.menu_callback_observed = read32(
        core, WORLD_START_MENU_CALLBACK);
    result.start_menu_opened =
        result.menu_callback_observed == WORLD_START_MENU_INPUT;
    result.back_pressed = result.start_menu_opened;
    if (result.back_pressed)
        s61_pulse(core, WORLD_KEY_B, 2U, 180U, NULL);
    result.field_callback_after = read32(
        core, BATTLE_CORE_MAIN_CALLBACK2);
    result.callback_ordered = result.start_menu_opened
        && result.field_callback_before == result.field_callback_after;
    result.map_preserved = read8(core, save1 + 4U) == expected_group
        && read8(core, save1 + 5U) == expected_map
        && s61_core_range_equals(
            core, save1, map_before, sizeof(map_before),
            "field START/B map identity");
    result.field_input_recovered = result.back_pressed
        && s61_field_terminal(core)
        && !world_script_enabled(core)
        && read8(core, WORLD_FIELD_CONTROLS_LOCKED) == 0U
        && read8(core, WORLD_PLAYER_AVATAR
                     + WORLD_PLAYER_RUNNING_STATE_OFFSET) == 0U
        && read8(core, WORLD_PLAYER_AVATAR
                     + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET) == 0U
        && result.map_preserved;
    return result;
}

static bool s61_field_roundtrip_exact(
    const struct S61FieldRoundtripResult *result)
{
    return result->controls_released
        && result->running_state_released
        && result->tile_transition_released
        && result->start_pressed
        && result->start_menu_opened
        && result->back_pressed
        && result->callback_ordered
        && result->map_preserved
        && result->field_input_recovered
        && result->field_callback_before != 0U
        && result->field_callback_before == result->field_callback_after
        && result->menu_callback_observed == WORLD_START_MENU_INPUT;
}

static void s61_print_field_roundtrip(
    const struct S61FieldRoundtripResult *result)
{
    printf("{\"controls_released\":%s,"
           "\"running_state_released\":%s,"
           "\"tile_transition_released\":%s,"
           "\"start_pressed\":%s,\"start_menu_opened\":%s,"
           "\"menu_callback_observed\":\"0x%08" PRIX32 "\","
           "\"back_pressed\":%s,"
           "\"field_callback_before\":\"0x%08" PRIX32 "\","
           "\"field_callback_after\":\"0x%08" PRIX32 "\","
           "\"callback_ordered\":%s,\"map_preserved\":%s,"
           "\"field_input_recovered\":%s}",
           result->controls_released ? "true" : "false",
           result->running_state_released ? "true" : "false",
           result->tile_transition_released ? "true" : "false",
           result->start_pressed ? "true" : "false",
           result->start_menu_opened ? "true" : "false",
           result->menu_callback_observed,
           result->back_pressed ? "true" : "false",
           result->field_callback_before, result->field_callback_after,
           result->callback_ordered ? "true" : "false",
           result->map_preserved ? "true" : "false",
           result->field_input_recovered ? "true" : "false");
}

/* A battle-start callback is an intermediate owner, never proof that the
 * player got field control back.  Complete it only with ordinary GBA keys,
 * then prove the returned field can open and close START on the same map.
 * All catalog-owned battles use the generated six-mon level-100 fixture and
 * the normal Fight/A route.  Some fixed-wild scripts explicitly loop after a
 * successful Run, so a blanket Run policy cannot reach their field-return
 * boundary and contradicts the static GetBattleOutcome correlation. */
static struct S61BattleLifecycleResult s61_complete_battle_lifecycle(
    struct mCore *core, const char *case_id, uint8_t expected_group,
    uint8_t expected_map, const struct S61CatalogInputSequence *sequence,
    struct S61PostBattleContinuationResult *continuation)
{
    struct S61BattleLifecycleResult result = {0};
    result.battle_started = s61_battle_active(core);
    if (!result.battle_started)
        return result;
    if (continuation == NULL)
        s61_die("battle continuation result storage is required");
    memset(continuation, 0, sizeof(*continuation));
    continuation->applicable = true;
    continuation->resume_kind = sequence == NULL
        ? S61_POST_BATTLE_STANDARD : sequence->post_battle_resume_kind;
    continuation->expected_resume_pc = sequence == NULL
        ? 0U : sequence->post_battle_resume_pc;
    if (continuation->resume_kind == S61_POST_BATTLE_NONE)
        s61_die("battle started without a post-battle continuation contract");
    continuation->effect_watch_enabled = s61_effect_observer.enabled;
    continuation->effect_hook_hits_before =
        s61_effect_observer_total_hook_hits();

    uint32_t battle_type_flags = read32(core, ADDR_BATTLE_TYPE_FLAGS);
    result.trainer_battle =
        (battle_type_flags & WORLD_BATTLE_TYPE_TRAINER) != 0U;
    /* Scripted wild battles always resume at the next opcode.  Ordinary
     * trainerbattle commands use STANDARD/EXPLICIT; modes 3/9 use NEXT_PC.
     * Trainer Tower's asynchronous SPECIAL is also a trainer battle and
     * resumes after its following waitstate. */
    if (!result.trainer_battle
        && continuation->resume_kind != S61_POST_BATTLE_NEXT_PC)
        s61_die("battle kind/post-battle resume relation differs");
    bool request_run = false;
    struct Fixture fixture = {
        .name = case_id,
        .kind = FIXTURE_FACING_DIALOGUE,
        .group = expected_group,
        .map = expected_map,
    };
    struct FixtureResult battle = {0};
    world_finish_battle(core, &fixture, &battle, request_run);
    result.completed_via_keys = battle.battle_completed;
    result.outcome = battle.battle_outcome;
    result.forced_switch_count = battle.forced_switch_count;
    result.forced_switch_cursor_observed =
        battle.forced_switch_cursor_observed;
    result.forced_switch_usable_slot_selected =
        battle.forced_switch_usable_slot_selected;
    memcpy(result.forced_switch_cursor_initial,
           battle.forced_switch_cursor_initial,
           sizeof(result.forced_switch_cursor_initial));
    memcpy(result.forced_switch_selected_slot,
           battle.forced_switch_selected_slot,
           sizeof(result.forced_switch_selected_slot));
    memcpy(result.forced_switch_selected_hp,
           battle.forced_switch_selected_hp,
           sizeof(result.forced_switch_selected_hp));
    if (result.trainer_battle
        && result.outcome == WORLD_BATTLE_OUTCOME_WON) {
        result.route = S61_BATTLE_ROUTE_FIGHT;
        result.won_or_escaped_not_loss = true;
    } else if (!result.trainer_battle
               && result.outcome == WORLD_BATTLE_OUTCOME_WON) {
        result.route = S61_BATTLE_ROUTE_FIGHT;
        result.won_or_escaped_not_loss = true;
    }

    s61_wait_for_post_battle_boundary(core, case_id, continuation);
    s61_drive_post_battle_continuation(
        core, case_id, expected_group, expected_map, sequence, continuation);
    result.field_released_after_battle = continuation->field_released
        && read8(core, WORLD_FIELD_CONTROLS_LOCKED) == 0U;
    uint32_t save1 = world_save1(core, case_id);
    result.map_preserved = read8(core, save1 + 4U) == expected_group
        && read8(core, save1 + 5U) == expected_map;
    if (!result.completed_via_keys || !result.won_or_escaped_not_loss
        || result.outcome == WORLD_BATTLE_OUTCOME_LOST
        || (!result.field_released_after_battle
            && !continuation->facility_active_boundary)
        || (result.field_released_after_battle
            && continuation->facility_active_boundary)
        || !result.map_preserved) {
        fprintf(stderr,
                "post-battle field diagnostic case=%s trainer=%u route=%u "
                "completed=%u outcome=%u won_or_escape=%u field=%u "
                "map=%u/%u expected=%u/%u controls=%u script=%u "
                "message=%u forced_switches=%u\n",
                case_id, result.trainer_battle ? 1U : 0U,
                (unsigned)result.route,
                result.completed_via_keys ? 1U : 0U, result.outcome,
                result.won_or_escaped_not_loss ? 1U : 0U,
                result.field_released_after_battle ? 1U : 0U,
                read8(core, save1 + 4U), read8(core, save1 + 5U),
                expected_group, expected_map,
                read8(core, WORLD_FIELD_CONTROLS_LOCKED),
                world_script_enabled(core) ? 1U : 0U,
                read8(core, WORLD_FIELD_MESSAGE_STATE),
                result.forced_switch_count);
        s61_die("battle key completion did not return to the expected field");
    }

    if (!continuation->facility_active_boundary) {
        result.start_pressed = true;
        s61_pulse(core, S61_KEY_START, 2U, 120U, NULL);
        result.start_menu_opened =
            read32(core, S61_START_MENU_CALLBACK) == S61_START_MENU_INPUT;
        result.back_pressed = result.start_menu_opened;
        if (result.back_pressed)
            s61_pulse(core, WORLD_KEY_B, 2U, 180U, NULL);
        save1 = world_save1(core, case_id);
        result.field_input_recovered = result.back_pressed
            && s61_field_terminal(core)
            && read8(core, WORLD_FIELD_CONTROLS_LOCKED) == 0U
            && read8(core, save1 + 4U) == expected_group
            && read8(core, save1 + 5U) == expected_map;
        if (!result.start_menu_opened || !result.field_input_recovered)
            s61_die("post-battle START/B field-input recovery differs");
    }
    return result;
}

static void s61_print_battle_lifecycle(
    const struct S61BattleLifecycleResult *result)
{
    const char *route = result->route == S61_BATTLE_ROUTE_FIGHT
        ? "FIGHT" : result->route == S61_BATTLE_ROUTE_RUN ? "RUN" : "NONE";
    printf("{\"battle_started\":%s,\"trainer_battle\":%s,"
           "\"completed_via_keys\":%s,"
           "\"forced_switch_count\":%u,"
           "\"forced_switch_cursor_observed\":%s,"
           "\"forced_switch_usable_slot_selected\":%s,"
           "\"route\":\"%s\",\"outcome\":%u,"
           "\"won_or_escaped_not_loss\":%s,"
           "\"field_released_after_battle\":%s,"
           "\"start_pressed\":%s,\"start_menu_opened\":%s,"
           "\"back_pressed\":%s,\"map_preserved\":%s,"
           "\"field_input_recovered\":%s",
           result->battle_started ? "true" : "false",
           result->trainer_battle ? "true" : "false",
           result->completed_via_keys ? "true" : "false",
           result->forced_switch_count,
           result->forced_switch_cursor_observed ? "true" : "false",
           result->forced_switch_usable_slot_selected ? "true" : "false",
           route,
           result->outcome,
           result->won_or_escaped_not_loss ? "true" : "false",
           result->field_released_after_battle ? "true" : "false",
           result->start_pressed ? "true" : "false",
           result->start_menu_opened ? "true" : "false",
           result->back_pressed ? "true" : "false",
           result->map_preserved ? "true" : "false",
           result->field_input_recovered ? "true" : "false");
    printf(",\"forced_switch_cursor_initial\":[");
    for (unsigned index = 0U; index < result->forced_switch_count; ++index)
        printf("%s%u", index ? "," : "",
               result->forced_switch_cursor_initial[index]);
    printf("],\"forced_switch_selected_slots\":[");
    for (unsigned index = 0U; index < result->forced_switch_count; ++index)
        printf("%s%u", index ? "," : "",
               result->forced_switch_selected_slot[index]);
    printf("],\"forced_switch_selected_hps\":[");
    for (unsigned index = 0U; index < result->forced_switch_count; ++index)
        printf("%s%u", index ? "," : "",
               result->forced_switch_selected_hp[index]);
    printf("]}");
}

static void s61_begin_internal_control_capture(
    struct mCore *core, struct S61CatalogRow *row,
    const struct S61CatalogInputSequence *sequence,
    struct S61Capture *capture)
{
    for (unsigned index = 0U; index < row->internal_control_count; ++index) {
        row->internal_controls[index].hit_count = 0U;
        row->internal_controls[index].execution_count = 0U;
        row->internal_controls[index].active_execution_ordinal = 0U;
        row->internal_controls[index].observed_value = 0U;
        row->internal_controls[index].observed_script_pointer = 0U;
        row->internal_controls[index].window_active = false;
        row->internal_controls[index].value_mismatch = false;
    }
    for (unsigned index = 0U; index < row->external_control_count; ++index) {
        if (row->external_controls[index].kind
                == S61_CONTROL_FOSSIL_REVIVAL_STATE
            || row->external_controls[index].kind
                == S61_CONTROL_RUIN_SEAL_PREFIX)
            continue;
        row->external_controls[index].deferred_applied = false;
        row->external_controls[index].deferred_hit_count = 0U;
        row->external_controls[index].producer_observed_value = 0U;
    }
    s61_active_control_row = row;
    s61_active_control_sequence = sequence->sequence_id;
    s61_active_control_token_index = 0U;
    for (unsigned index = 0U; index < row->external_control_count; ++index) {
        if (row->external_controls[index].kind
                == S61_CONTROL_FACILITY_SESSION)
            s61_attach_facility_execution(
                core, capture, &row->external_controls[index]);
    }
}

static bool s61_internal_controls_ok(
    struct mCore *core, const struct S61CatalogRow *row,
    const struct S61CatalogInputSequence *sequence)
{
    bool ok = true;
    for (unsigned index = 0U; index < row->internal_control_count; ++index) {
        const struct S61InternalControl *control = &row->internal_controls[index];
        if (control->sequence_id != NULL
            && strcmp(control->sequence_id, sequence->sequence_id) != 0)
            continue;
        unsigned expected_execution_count = 0U;
        for (unsigned peer_index = 0U;
             peer_index < row->internal_control_count; ++peer_index) {
            const struct S61InternalControl *peer =
                &row->internal_controls[peer_index];
            bool same_sequence = control->sequence_id == NULL
                ? peer->sequence_id == NULL
                : peer->sequence_id != NULL
                    && strcmp(control->sequence_id, peer->sequence_id) == 0;
            if (same_sequence
                && control->instruction_address == peer->instruction_address
                && control->owner_address == peer->owner_address
                && control->expected_token_index
                    == peer->expected_token_index
                && strcmp(control->writer, peer->writer) == 0
                && peer->expected_execution_ordinal + 1U
                    > expected_execution_count)
                expected_execution_count =
                    peer->expected_execution_ordinal + 1U;
        }
        if (control->hit_count == 0U || control->value_mismatch
            || control->execution_count != expected_execution_count)
            ok = false;
    }
    for (unsigned index = 0U; index < row->external_control_count; ++index) {
        const struct S61ExternalControl *control =
            &row->external_controls[index];
        if (control->kind == S61_CONTROL_REMATCH_STATE
            && (!control->deferred_applied
                || control->deferred_hit_count != 1U))
            ok = false;
        if (control->kind == S61_CONTROL_SIGNED_RAM_SCRIPT) {
            bool expected_dispatch = control->values[1] != 0U;
            if ((control->deferred_hit_count != 0U) != expected_dispatch
                || !s61_signed_ram_fixture_matches(core, control, true)
                || (expected_dispatch
                    && read16(core, WORLD_SPECIAL_VAR_8004)
                        != (uint16_t)control->values[2]))
                ok = false;
        }
        if (control->kind == S61_CONTROL_FOSSIL_REVIVAL_STATE
            && (!control->deferred_applied
                || control->deferred_hit_count != 1U))
            ok = false;
        if (control->kind == S61_CONTROL_RUIN_SEAL_PREFIX
            && (!control->deferred_applied
                || control->deferred_hit_count != 1U
                || control->ruin_flag_readback_count
                    != (control->values[0] == S61_RUIN_SEAL_OBJECT_ROOT
                        ? S61_RUIN_SEAL_MAX_FLAG_COUNT
                        : S61_RUIN_SEAL_SEAL_FLAG_COUNT)))
            ok = false;
        if (control->kind == S61_CONTROL_FACILITY_SESSION
            && (!control->deferred_applied
                || control->deferred_hit_count != control->values[2]))
            ok = false;
    }
    return ok;
}

static void s61_print_internal_controls(
    const struct S61CatalogRow *row,
    const struct S61CatalogInputSequence *sequence)
{
    putchar('[');
    bool comma = false;
    for (unsigned index = 0U; index < row->internal_control_count; ++index) {
        const struct S61InternalControl *control = &row->internal_controls[index];
        if (control->sequence_id != NULL
            && strcmp(control->sequence_id, sequence->sequence_id) != 0)
            continue;
        printf("%s{\"writer\":\"%s\","
               "\"instruction_address\":\"0x%08" PRIX32 "\","
               "\"before_pc\":\"0x%08" PRIX32 "\","
               "\"after_pc\":\"0x%08" PRIX32 "\","
               "\"expected_token_index\":%u,"
               "\"expected_execution_ordinal\":%u,"
               "\"owner_address\":\"0x%08" PRIX32 "\","
               "\"expected_value\":%u,\"observed_value\":%u,"
               "\"observed_script_pointer\":\"0x%08" PRIX32 "\","
               "\"execution_count\":%u,"
               "\"hit_count\":%u,\"value_mismatch\":%s}",
               comma ? "," : "", control->writer,
               control->instruction_address, control->before_pc,
               control->after_pc, control->expected_token_index,
               control->expected_execution_ordinal,
               control->owner_address,
               control->expected_value, control->observed_value,
               control->observed_script_pointer, control->execution_count,
               control->hit_count,
               control->value_mismatch ? "true" : "false");
        comma = true;
    }
    putchar(']');
}

static void s61_print_deferred_external_controls(
    struct mCore *core, const struct S61CatalogRow *row,
    const struct S61Capture *capture)
{
    putchar('[');
    bool comma = false;
    for (unsigned index = 0U; index < row->external_control_count; ++index) {
        const struct S61ExternalControl *control =
            &row->external_controls[index];
        if (control->kind == S61_CONTROL_SIGNED_RAM_SCRIPT) {
            bool post_matches = s61_signed_ram_fixture_matches(
                core, control, true);
            printf("%s{\"kind\":\"SIGNED_RAM_SCRIPT\","
                   "\"instruction_address\":\"0x%08" PRIX32 "\","
                   "\"variant\":%u,\"expected_dispatch\":%s,"
                   "\"observed_dispatch\":%s,"
                   "\"ram_script_program_hit_count\":%u,"
                   "\"expected_var_8004\":%s,"
                   "\"observed_var_8004\":%u,"
                   "\"expected_ram_script_cleared\":%s,"
                   "\"ram_script_postcondition_exact\":%s,"
                   "\"actual_object_consumer_only\":true}",
                   comma ? "," : "", control->id,
                   (unsigned)control->values[0],
                   control->values[1] != 0U ? "true" : "false",
                   control->deferred_hit_count != 0U ? "true" : "false",
                   control->deferred_hit_count,
                   control->values[2] == UINT32_MAX ? "null" : "24997",
                   read16(core, WORLD_SPECIAL_VAR_8004),
                   control->values[3] != 0U ? "true" : "false",
                   post_matches ? "true" : "false");
            comma = true;
            continue;
        }
        if (control->kind == S61_CONTROL_FOSSIL_REVIVAL_STATE) {
            printf("%s{\"kind\":\"FOSSIL_REVIVAL_STATE\","
                   "\"scenario_id\":\"%s\",\"layout_ref\":\"%s\","
                   "\"revive_state\":%" PRIu32 ","
                   "\"which_fossil\":%" PRIu32 ","
                   "\"binary_fixture_verified\":true,"
                   "\"preinteraction_readback_exact\":true,"
                   "\"exact\":true}",
                   comma ? "," : "", control->scenario_id,
                   control->fixture_refs[0], control->values[0],
                   control->values[1]);
            comma = true;
            continue;
        }
        if (control->kind == S61_CONTROL_RUIN_SEAL_PREFIX) {
            bool object_root =
                control->values[0] == S61_RUIN_SEAL_OBJECT_ROOT;
            printf("%s{\"kind\":\"RUIN_SEAL_PREFIX\","
                   "\"root_address\":\"0x%08" PRIX32 "\","
                   "\"scenario_id\":\"%s\",\"layout_ref\":\"%s\","
                   "\"first_missing_index\":",
                   comma ? "," : "", control->values[0],
                   control->scenario_id, control->fixture_refs[0]);
            if (control->values[1] == S61_RUIN_SEAL_NULL_U16)
                printf("null");
            else
                printf("%" PRIu32, control->values[1]);
            printf(",\"all_seals\":%s,\"completed\":",
                   control->values[2] != 0U ? "true" : "false");
            if (control->values[3] == S61_RUIN_SEAL_NULL_U16)
                printf("null");
            else
                printf("%s", control->values[3] != 0U ? "true" : "false");
            printf(",\"flag_values\":[");
            for (unsigned flag = 0U;
                 flag < control->ruin_flag_readback_count; ++flag) {
                uint16_t identifier = flag < S61_RUIN_SEAL_SEAL_FLAG_COUNT
                    ? (uint16_t)(0x11CCU + flag)
                    : (uint16_t)S61_RUIN_SEAL_COMPLETION_FLAG;
                printf("%s{\"id\":%u,\"value\":%s}",
                       flag ? "," : "", (unsigned)identifier,
                       control->ruin_flag_readback[flag] != 0U
                           ? "true" : "false");
            }
            printf("],\"root_source_binding\":{"
                   "\"address\":\"0x%08" PRIX32 "\","
                   "\"byte_length\":%" PRIu32 ","
                   "\"sha256\":\"%s\","
                   "\"provenance\":"
                   "\"VEGA_AND_PINNED_STAGE60_STAGE61_FULL_SCRIPT_SPAN\"},"
                   "\"binary_fixture_verified\":true,"
                   "\"preinteraction_readback_exact\":true,"
                   "\"exact\":true}",
                   control->values[6], control->values[7],
                   control->root_source_sha256);
            if (object_root
                != (control->ruin_flag_readback_count
                    == S61_RUIN_SEAL_MAX_FLAG_COUNT))
                s61_die("catalog RUIN_SEAL_PREFIX observation count differs");
            comma = true;
            continue;
        }
        if (control->kind == S61_CONTROL_FACILITY_SESSION) {
            if (capture == NULL || capture->facility.control != control
                || capture->facility.trace_count == 0U)
                s61_die("FACILITY_SESSION runtime evidence is missing");
            const struct S61FacilityExecutionEvidence *evidence =
                &capture->facility;
            const struct S61FacilityNativeBoundary *final_boundary =
                &evidence->boundaries[evidence->trace_count - 1U];
            printf("%s{\"kind\":\"FACILITY_SESSION\","
                   "\"scenario_key\":\"%s/%s\","
                   "\"root_address\":\"0x%08" PRIX32 "\","
                   "\"layout_ref\":\"%s\","
                   "\"trace_count\":%" PRIu32 ","
                   "\"observed_trace_count\":%u,"
                   "\"native_boundary_count\":%u,"
                   "\"non_native_boundary_count\":%u,"
                   "\"trace_sha256\":\"%s\","
                   "\"transport_exact\":true,"
                   "\"raw_ewram_preimage_used\":false,"
                   "\"physical_prefix\":{"
                   "\"actual_stock_warp_walk_face_a\":true,"
                   "\"attached_before_a\":%s,"
                   "\"declared_root_hit\":true,"
                   "\"root_instruction_ordinal\":%" PRIu64 ","
                   "\"first_native_entry_ordinal\":%" PRIu64 ","
                   "\"root_before_first_native\":%s,"
                   "\"direct_native_only\":false},"
                   "\"host_writes\":{"
                   "\"lifecycle_calls\":%u,"
                   "\"phase_status_result\":%u,"
                   "\"ewram_raw\":%u},"
                   "\"native_boundaries\":[",
                   comma ? "," : "", control->family,
                   control->scenario_id, control->values[0],
                   control->fixture_refs[0],
                   control->values[2], control->deferred_hit_count,
                   evidence->native_boundary_count,
                   evidence->non_native_boundary_count,
                   control->facility_trace_sha256,
                   evidence->attached_before_a ? "true" : "false",
                   evidence->root_instruction_ordinal,
                   evidence->boundaries[0U].entry_instruction_ordinal,
                   evidence->physical_root_before_first_native
                       ? "true" : "false",
                   evidence->host_lifecycle_call_count,
                   evidence->host_phase_status_result_write_count,
                   evidence->host_ewram_raw_write_count);
            for (unsigned boundary_index = 0U;
                 boundary_index < evidence->trace_count; ++boundary_index) {
                const struct S61FacilityNativeBoundary *boundary =
                    &evidence->boundaries[boundary_index];
                const char *boundary_kind = boundary->boundary_kind
                        == S61_FACILITY_BOUNDARY_NATIVE_CALL_RETURN
                    ? "NATIVE_CALL_RETURN"
                    : boundary->boundary_kind
                            == S61_FACILITY_BOUNDARY_DECISION_BEFORE_NATIVE
                        ? "SESSION_DECISION_BEFORE_NEXT_NATIVE"
                        : "SESSION_DECISION_AT_FIELD_RELEASE";
                printf("%s{\"ordinal\":%u,\"operation\":\"%s\","
                       "\"boundary_kind\":\"%s\",\"entry_pc\":",
                       boundary_index ? "," : "", boundary_index,
                       boundary->operation, boundary_kind);
                if (boundary->boundary_kind
                        == S61_FACILITY_BOUNDARY_NATIVE_CALL_RETURN)
                    printf("\"0x%08" PRIX32 "\"", boundary->entry_pc);
                else
                    fputs("null", stdout);
                fputs(",\"return_pc\":", stdout);
                if (boundary->boundary_kind
                        == S61_FACILITY_BOUNDARY_NATIVE_CALL_RETURN)
                    printf("\"0x%08" PRIX32 "\"", boundary->return_pc);
                else
                    fputs("null", stdout);
                fputs(",\"correlation_pc\":", stdout);
                if (boundary->boundary_kind
                        == S61_FACILITY_BOUNDARY_NATIVE_CALL_RETURN)
                    fputs("null", stdout);
                else
                    printf("\"0x%08" PRIX32 "\"",
                           boundary->correlation_pc);
                char battle[16U], completion[16U], mechanic[16U];
                char reward_kind[16U], reward_window[16U], round[16U];
                printf(",\"entry_instruction_ordinal\":%" PRIu64 ","
                       "\"return_instruction_ordinal\":%" PRIu64 ","
                       "\"state\":\"%s\",\"phase\":%u,"
                       "\"status\":%u,\"result\":%u,"
                       "\"active\":%s,\"battle_index\":%s,"
                       "\"round_index\":%s,\"mechanic\":%s,"
                       "\"completion_pending\":%s,"
                       "\"reward_window\":%s,"
                       "\"reward_result_kind\":%s,\"regions\":[",
                       boundary->entry_instruction_ordinal,
                       boundary->return_instruction_ordinal,
                       boundary->state, boundary->phase,
                       boundary->status, boundary->result,
                       boundary->active ? "true" : "false",
                       s61_facility_nullable_u16(
                           boundary->battle_index, battle),
                       s61_facility_nullable_u16(
                           boundary->round_index, round),
                       s61_facility_nullable_u16(
                           boundary->mechanic, mechanic),
                       s61_facility_nullable_u16(
                           boundary->completion_pending, completion),
                       s61_facility_nullable_u16(
                           boundary->reward_window, reward_window),
                       s61_facility_nullable_u16(
                           boundary->reward_result_kind, reward_kind));
                for (unsigned region = 0U;
                     region < evidence->region_count; ++region) {
                    printf("%s{\"address\":\"0x%08" PRIX32 "\","
                           "\"size\":%" PRIu32 ","
                           "\"before_sha256\":\"%s\","
                           "\"after_sha256\":\"%s\"}",
                           region ? "," : "",
                           control->values[5U + region * 2U],
                           control->values[6U + region * 2U],
                           boundary->region_sha256_before[region],
                           boundary->region_sha256_after[region]);
                }
                printf("],\"party\":{\"size\":600,"
                       "\"before_sha256\":\"%s\","
                       "\"after_sha256\":\"%s\"},"
                       "\"storage\":{\"size\":33744,"
                       "\"before_sha256\":\"%s\","
                       "\"after_sha256\":\"%s\"},"
                       "\"entry_return_ordered\":%s,"
                       "\"record_exact\":true}",
                       boundary->party_sha256_before,
                       boundary->party_sha256_after,
                       boundary->storage_sha256_before,
                       boundary->storage_sha256_after,
                       (boundary->boundary_kind
                                == S61_FACILITY_BOUNDARY_NATIVE_CALL_RETURN
                            && boundary->entry_instruction_ordinal
                                < boundary->return_instruction_ordinal)
                           || (boundary->boundary_kind
                                   != S61_FACILITY_BOUNDARY_NATIVE_CALL_RETURN
                               && boundary->entry_instruction_ordinal
                                   == boundary->return_instruction_ordinal)
                           ? "true" : "false");
            }
            printf("],\"terminal\":{"
                   "\"cursor_exact\":%s,"
                   "\"final_active\":%s,"
                   "\"terminal_kind\":\"%s\","
                   "\"party_restored\":%s,"
                   "\"storage_restored\":%s,"
                   "\"final_region_sha256\":[",
                   evidence->terminal_cursor_exact ? "true" : "false",
                   final_boundary->active ? "true" : "false",
                   final_boundary->active
                       ? "FACILITY_ACTIVE_CONTINUATION_BOUNDARY"
                       : "FIELD_RELEASE",
                   evidence->party_restored ? "true" : "false",
                   evidence->storage_restored ? "true" : "false");
            for (unsigned region = 0U;
                 region < evidence->region_count; ++region)
                printf("%s\"%s\"", region ? "," : "",
                       evidence->final_region_sha256[region]);
            printf("],\"final_party_sha256\":\"%s\","
                   "\"final_storage_sha256\":\"%s\","
                   "\"exact\":true},"
                   "\"factory_prepare_adapter_source_bound\":true,"
                   "\"runtime_driver_completed\":%s}",
                   evidence->final_party_sha256,
                   evidence->final_storage_sha256,
                   control->deferred_applied ? "true" : "false");
            comma = true;
            continue;
        }
        if (control->kind != S61_CONTROL_REMATCH_STATE)
            continue;
        uint32_t save1 = s61_catalog_save1(core);
        printf("%s{\"kind\":\"REMATCH_STATE\",\"local_id\":%u,"
               "\"last_talked\":%u,\"saveblock1_offset\":%u,"
               "\"expected_ready_byte\":%u,"
               "\"seeded_before_stock_warp\":true,"
               "\"postwarp_readback_exact\":true,"
               "\"pre_a_readback_exact\":true,"
               "\"producer_observed_ready_byte\":%" PRIu32 ","
               "\"postinteraction_ready_byte\":%u,"
               "\"actual_object_consumer_hit_count\":%u,"
               "\"producer_window_host_writes\":0,"
               "\"host_wrote_last_talked\":false}",
               comma ? "," : "", (unsigned)control->values[1],
               read16(core, WORLD_SPECIAL_LAST_TALKED),
               (unsigned)control->values[2],
               (unsigned)control->values[3],
               control->producer_observed_value,
               read8(core, save1 + control->values[2]),
               control->deferred_hit_count);
        comma = true;
    }
    putchar(']');
}

static void s61_end_internal_control_capture(void)
{
    s61_active_control_row = NULL;
    s61_active_control_sequence = NULL;
    s61_active_control_token_index = 0U;
}

static struct S61SequenceDriveResult s61_drive_input_sequence(
    struct mCore *core, const struct S61CatalogInputSequence *sequence,
    struct S61Capture *capture, bool stop_at_battle)
{
    struct S61SequenceDriveResult result = {0};
    if (capture->facility.control != NULL) {
        /* The physical Facility root owns VAR_RESULT as well as its native
         * lifecycle state.  A harness preimage write here would make the
         * stock walk/A path indistinguishable from a host-driven session. */
        capture->facility.host_phase_status_result_write_count = 0U;
    } else if (s61_rfu_attempt.active) {
        if (read16(core, WORLD_SPECIAL_RESULT) != 0xFFFFU)
            s61_die("RFU attempt did not start from quiescent VAR_RESULT");
    } else {
        write16(core, WORLD_SPECIAL_RESULT, 0xFFFFU);
    }
    bool saw_owner = false;
    for (unsigned index = 0U; index < sequence->step_count; ++index) {
        s61_active_control_token_index = index;
        if (index != 0U && (s61_field_terminal(core)
                           || s61_battle_active(core))) {
            result.premature_terminal = true;
            break;
        }
        const struct S61CatalogInputStep *step = &sequence->steps[index];
        if (step->wait_frames != 0U)
            s61_step_capture_frames(
                core, 0U, step->wait_frames, capture);
        else
            s61_step_capture_pulse(
                core, step->key, step->pressed,
                step->released, capture);
        ++result.steps_consumed;
        if (capture->invalid_control_flow)
            break;
        if (world_script_enabled(core) || capture->active_frames != 0U
            || capture->count != 0U
            || capture->printer_call_count != 0U)
            saw_owner = true;
        if (s61_battle_active(core) && index + 1U < sequence->step_count) {
            result.premature_terminal = true;
            break;
        }
    }
    if (result.steps_consumed != sequence->step_count
        || result.premature_terminal || capture->invalid_control_flow)
        return result;
    unsigned quiet = 0U;
    for (unsigned tail = 0U; tail < 40U; ++tail) {
        if (world_script_enabled(core) || capture->active_frames != 0U
            || capture->count != 0U
            || capture->printer_call_count != 0U)
            saw_owner = true;
        if (s61_battle_active(core)) {
            result.terminal_seen = stop_at_battle && saw_owner;
            return result;
        }
        if (s61_field_terminal(core)) {
            if (saw_owner && ++quiet >= 6U) {
                result.terminal_seen = true;
                return result;
            }
        } else {
            quiet = 0U;
        }
        s61_step_capture_frames(core, 0U, 15U, capture);
        if (capture->invalid_control_flow)
            return result;
    }
    return result;
}

static void s61_sample_ball_throw(struct mCore *core,
                                  struct S61BallThrowResult *result,
                                  bool *battle_runtime_seen)
{
    bool runtime = read32(core, ADDR_NEW_BATTLE_STRUCT_POINTER) != 0U;
    if (runtime)
        *battle_runtime_seen = true;
    else if (*battle_runtime_seen)
        result->runtime_cleaned = true;
    uint8_t outcome = read8(core, BATTLE_CORE_BATTLE_OUTCOME);
    if (outcome != 0U)
        result->outcome = outcome;
    if (read8(core, BATTLE_CORE_BAG_STATE + 5U) != 0U)
        result->bag_opened = true;
    uint8_t action = read8(core, BATTLE_CORE_CHOSEN_ACTIONS);
    if (action == WORLD_BATTLE_ACTION_USE_ITEM)
        result->chosen_action = action;
}

static void s61_ball_frames(struct mCore *core,
                            struct S61BallThrowResult *result,
                            bool *battle_runtime_seen,
                            uint16_t keys, unsigned frames)
{
    core->setKeys(core, keys);
    for (unsigned frame = 0U; frame < frames; ++frame) {
        core->runFrame(core);
        s61_sample_ball_throw(core, result, battle_runtime_seen);
    }
}

static void s61_ball_pulse(struct mCore *core,
                           struct S61BallThrowResult *result,
                           bool *battle_runtime_seen,
                           uint16_t key, unsigned released)
{
    s61_ball_frames(core, result, battle_runtime_seen, key, 2U);
    s61_ball_frames(core, result, battle_runtime_seen, 0U, released);
}

static struct S61BallThrowResult s61_throw_master_ball_with_keys(
    struct mCore *core, const struct Fixture *fixture)
{
    struct S61BallThrowResult result = {0};
    bool battle_runtime_seen = false;

    world_phase = "battle-menu-real-master-ball";
    for (unsigned cycle = 0U; cycle < 480U; ++cycle) {
        s61_sample_ball_throw(core, &result, &battle_runtime_seen);
        if (result.runtime_cleaned)
            break;

        if (read8(core, WORLD_BATTLE_BUFFER_A)
                == WORLD_BATTLE_COMMAND_CHOOSE_ACTION) {
            result.choose_action_seen = true;
            uint8_t cursor = read8(core, BATTLE_CORE_ACTION_SELECTION_CURSOR);
            if (cursor > 3U)
                world_die(fixture->name,
                          "battle action cursor left the 2x2 menu");
            if (cursor == WORLD_BATTLE_ACTION_USE_ITEM) {
                s61_ball_pulse(core, &result, &battle_runtime_seen,
                               WORLD_KEY_LEFT, 24U);
                result.actual_direction_input = true;
                ++result.input_pulses;
                cursor = read8(core, BATTLE_CORE_ACTION_SELECTION_CURSOR);
            }
            if ((cursor & 2U) != 0U) {
                s61_ball_pulse(core, &result, &battle_runtime_seen,
                               WORLD_KEY_UP, 24U);
                result.actual_direction_input = true;
                ++result.input_pulses;
            }
            cursor = read8(core, BATTLE_CORE_ACTION_SELECTION_CURSOR);
            if ((cursor & 1U) == 0U) {
                s61_ball_pulse(core, &result, &battle_runtime_seen,
                               WORLD_KEY_RIGHT, 24U);
                result.actual_direction_input = true;
                ++result.input_pulses;
            }
            result.action_cursor = read8(
                core, BATTLE_CORE_ACTION_SELECTION_CURSOR);
            if (result.action_cursor != WORLD_BATTLE_ACTION_USE_ITEM)
                world_die(fixture->name,
                          "direction keys did not select the Bag action");
            s61_ball_pulse(core, &result, &battle_runtime_seen,
                           WORLD_KEY_A, BATTLE_CORE_MENU_INPUT_WAIT);
            result.actual_a_input = true;
            ++result.input_pulses;
            result.chosen_action = read8(core, BATTLE_CORE_CHOSEN_ACTIONS);
            continue;
        }

        /* Once the real Bag callback owns input, its preselected Balls
         * pocket/cursor consumes ordinary A.  All other A pulses merely
         * advance battle text/animations; no controller result is written
         * from the host. */
        if (result.bag_opened || cycle % 5U == 4U) {
            s61_ball_pulse(core, &result, &battle_runtime_seen,
                           WORLD_KEY_A, BATTLE_CORE_MENU_INPUT_WAIT);
            result.actual_a_input = true;
            ++result.input_pulses;
        } else {
            s61_ball_frames(core, &result, &battle_runtime_seen,
                            0U, 30U);
        }
    }
    if (!result.runtime_cleaned) {
        fprintf(stderr,
                "last-ball timeout pc=%08" PRIX32
                " cpsr=%08" PRIX32 " lr=%08" PRIX32
                " sp=%08" PRIX32 " callback=%08" PRIX32
                " battle_ptr=%08" PRIX32 " battlers=%u"
                " command=%u cursor=%u chosen=%u bag_state=%u/%u/%u"
                " outcome=%u sampled_outcome=%u last_ball=%u"
                " choose_seen=%u bag_seen=%u pulses=%u\n",
                (uint32_t)read_register(core, "pc"),
                (uint32_t)read_register(core, "cpsr"),
                (uint32_t)read_register(core, "lr"),
                (uint32_t)read_register(core, "sp"),
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                read32(core, ADDR_NEW_BATTLE_STRUCT_POINTER),
                read8(core, ADDR_BATTLERS_COUNT),
                read8(core, WORLD_BATTLE_BUFFER_A),
                read8(core, BATTLE_CORE_ACTION_SELECTION_CURSOR),
                read8(core, BATTLE_CORE_CHOSEN_ACTIONS),
                read8(core, BATTLE_CORE_BAG_STATE + 4U),
                read8(core, BATTLE_CORE_BAG_STATE + 5U),
                read8(core, BATTLE_CORE_BAG_STATE + 6U),
                read8(core, BATTLE_CORE_BATTLE_OUTCOME), result.outcome,
                read16(core, WORLD_LAST_USED_BALL),
                result.choose_action_seen, result.bag_opened,
                result.input_pulses);
        world_die(fixture->name,
                  "Master Ball battle did not clean its runtime");
    }
    for (unsigned settle = 0U; settle < 80U; ++settle) {
        if (world_overworld(core) && !world_script_enabled(core)) {
            s61_frames(core, 0U, 180U, NULL);
            break;
        }
        s61_pulse(core, WORLD_KEY_A, 2U, 45U, NULL);
        ++result.input_pulses;
    }
    if (!world_overworld(core) || world_script_enabled(core))
        world_die(fixture->name,
                  "caught battle did not release to an input-ready field");
    if (result.chosen_action != WORLD_BATTLE_ACTION_USE_ITEM)
        result.chosen_action = read8(core, BATTLE_CORE_CHOSEN_ACTIONS);
    if (!result.choose_action_seen || !result.bag_opened
        || !result.actual_direction_input || !result.actual_a_input
        || result.chosen_action != WORLD_BATTLE_ACTION_USE_ITEM
        || result.outcome != WORLD_BATTLE_OUTCOME_CAUGHT
        || read16(core, WORLD_LAST_USED_BALL) != WORLD_MASTER_BALL)
        world_die(fixture->name,
                  "real Bag/Master Ball input did not catch and update last ball");
    return result;
}

static void s61_stock_warp_save(struct mCore *core,
                                const struct Fixture *destination)
{
    (void)s61_call_synced(core, BOOTSTRAP_KANTO_WARP,
                         destination->group, destination->map,
                         destination->x, destination->y);
    s61_frames(core, 0U, BOOTSTRAP_FIELD_FRAMES, NULL);
    uint32_t save1 = world_save1(core, s61_case_name);
    if (read8(core, save1 + 4U) != destination->group
        || read8(core, save1 + 5U) != destination->map
        || read16(core, save1) != destination->x
        || read16(core, save1 + 2U) != destination->y
        || !world_overworld(core)) {
        fprintf(stderr,
                "stock warp debug expected=%u/%u (%u,%u) actual=%u/%u "
                "(%u,%u) overworld=%u callback=%08" PRIX32 " lock=%u\n",
                destination->group, destination->map,
                destination->x, destination->y,
                read8(core, save1 + 4U), read8(core, save1 + 5U),
                read16(core, save1), read16(core, save1 + 2U),
                world_overworld(core),
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                world_script_enabled(core));
        s61_die("stock warp did not settle at the consumer fixture");
    }
    bootstrap_prepare_save_map_view(core);
    uint32_t first_save = s61_call_save_sync(core);
    uint32_t second_save = s61_call_save_sync(core);
    if (first_save != BOOTSTRAP_STATUS_OK
        || second_save != BOOTSTRAP_STATUS_OK) {
        fprintf(stderr, "consumer save debug first=%" PRIu32
                " second=%" PRIu32 " callback=%08" PRIX32
                " lock=%u\n", first_save, second_save,
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                world_script_enabled(core));
        s61_die("two-generation consumer save failed");
    }
}

static void s61_print_capture(const struct S61Capture *capture)
{
    printf("{\"message_state_address\":\"0x%08X\","
           "\"string_address\":\"0x%08X\","
           "\"printer_entry\":\"0x%08X\","
           "\"printer_entry_preimage_hex\":"
           "\"F0B5474680B484B00A9C0B9D0C9F0906\","
           "\"template_printer_entry\":\"0x%08X\","
           "\"template_printer_entry_preimage_hex\":"
           "\"F0B5061C944609060D0E034800680028\","
           "\"execution\":{\"invalid_control_flow\":%s,"
           "\"first_invalid_pc\":",
           S61_FIELD_MESSAGE_STATE, S61_G_STRING_VAR4,
           S61_ADD_TEXT_PRINTER, S61_ADD_TEXT_PRINTER_TEMPLATE,
           capture->invalid_control_flow ? "true" : "false");
    if (capture->invalid_control_flow)
        printf("\"0x%08" PRIX32 "\"", capture->invalid_pc);
    else
        printf("null");
    printf(",\"cpsr\":");
    if (capture->invalid_control_flow)
        printf("\"0x%08" PRIX32 "\"", capture->invalid_cpsr);
    else
        printf("null");
    printf(",\"lr\":");
    if (capture->invalid_control_flow)
        printf("\"0x%08" PRIX32 "\"", capture->invalid_lr);
    else
        printf("null");
    printf("},\"instruction_observation\":{"
           "\"script_context_active_instructions\":%u,"
           "\"first_script_context_pointer\":",
           capture->script_context_active_instructions);
    if (capture->script_context_active_instructions != 0U)
        printf("\"0x%08" PRIX32 "\"",
               capture->first_script_context_pointer);
    else
        fputs("null", stdout);
    printf(",\"non_overworld_instructions\":%u,"
           "\"first_non_overworld_callback\":",
           capture->non_overworld_instructions);
    if (capture->non_overworld_instructions != 0U)
        printf("\"0x%08" PRIX32 "\"",
               capture->first_non_overworld_callback);
    else
        fputs("null", stdout);
    printf("},"
           "\"active_frames\":%u,"
           "\"state_counts\":[%u,%u,%u,%u],\"var_result\":{"
           "\"address\":\"0x%08X\",\"seen\":%s,\"first\":",
           capture->active_frames,
           capture->state_counts[0], capture->state_counts[1],
           capture->state_counts[2], capture->state_counts[3],
           WORLD_SPECIAL_RESULT,
           capture->var_result_seen ? "true" : "false");
    if (capture->var_result_seen)
        printf("%u", capture->first_var_result);
    else
        printf("null");
    printf(",\"last\":");
    if (capture->var_result_seen)
        printf("%u", capture->last_var_result);
    else
        printf("null");
    printf(",\"changes\":%u,\"values\":[", capture->var_result_changes);
    for (unsigned index = 0U;
         index < capture->var_result_value_count; ++index) {
        if (index != 0U)
            putchar(',');
        printf("%u", capture->var_result_values[index]);
    }
    printf("]},\"framebuffer\":{"
           "\"first_fnv1a64\":\"%016" PRIX64 "\","
           "\"last_fnv1a64\":\"%016" PRIX64 "\","
           "\"changed_frames\":%u,"
           "\"maximum_baseline_pixel_difference\":%u},\"messages\":[",
           capture->first_framebuffer_hash, capture->last_framebuffer_hash,
           capture->framebuffer_changes,
           capture->maximum_baseline_pixel_difference);
    for (unsigned index = 0U; index < capture->count; ++index) {
        const struct S61Message *message = &capture->messages[index];
        if (index != 0U)
            putchar(',');
        printf("{\"state\":%u,\"size\":%u,\"raw_hex\":\"",
               message->state, message->size);
        for (unsigned byte = 0U; byte < message->size; ++byte)
            printf("%02X", message->raw[byte]);
        printf("\",\"raw_fnv1a64\":\"%016" PRIX64 "\","
               "\"framebuffer_fnv1a64\":\"%016" PRIX64 "\"}",
               message->raw_hash, message->framebuffer_hash);
    }
    printf("],\"printer_calls\":[");
    for (unsigned index = 0U;
         index < capture->printer_call_count; ++index) {
        const struct S61PrinterCall *call = &capture->printer_calls[index];
        if (index != 0U)
            putchar(',');
        printf("{\"frame\":%u,\"instruction_address\":\"0x%08" PRIX32
               "\",\"caller_instruction_address\":"
               "\"0x%08" PRIX32 "\",\"window\":%" PRIu32
               ",\"font\":%" PRIu32 ",\"text_pointer\":"
               "\"0x%08" PRIX32 "\",\"speed\":%" PRIu32
               ",\"size\":%u,\"raw_hex\":\"",
               call->frame, call->instruction_address,
               call->caller_instruction_address,
               call->window, call->font,
               call->text_pointer, call->speed, call->size);
        for (unsigned byte = 0U; byte < call->size; ++byte)
            printf("%02X", call->raw[byte]);
        printf("\",\"raw_fnv1a64\":\"%016" PRIX64 "\"}",
               call->raw_hash);
    }
    printf("]}");
}

static void s61_print_post_battle_continuation(
    const struct S61PostBattleContinuationResult *result,
    const struct S61CatalogInputSequence *sequence)
{
    if (result == NULL || !result->applicable) {
        fputs("null", stdout);
        return;
    }
    if (result->effect_hook_hits_after < result->effect_hook_hits_before)
        s61_die("post-battle effect hook counter moved backwards");
    unsigned step_count = sequence == NULL
        ? 0U : sequence->post_battle_step_count;
    printf("{\"phase\":\"POST_BATTLE_CONTINUATION\","
           "\"resume_kind\":\"%s\",\"boundary_observed\":%s,"
           "\"expected_resume_pc\":",
           s61_post_battle_resume_kind_name(result->resume_kind),
           result->boundary_observed ? "true" : "false");
    if (result->resume_kind == S61_POST_BATTLE_STANDARD)
        fputs("null", stdout);
    else
        printf("\"0x%08" PRIX32 "\"", result->expected_resume_pc);
    printf(",\"observed_resume_pc\":\"0x%08" PRIX32 "\","
           "\"resume_pc_hit_count\":%u,\"input_tokens\":[",
           result->observed_resume_pc, result->resume_pc_hit_count);
    for (unsigned index = 0U; index < step_count; ++index)
        printf("%s\"%s\"", index == 0U ? "" : ",",
               sequence->post_battle_steps[index].token);
    printf("],\"input_step_count\":%u,\"input_steps_consumed\":%u,"
           "\"premature_terminal\":%s,\"terminal\":\"%s\","
           "\"field_released\":%s,\"capture\":",
           step_count, result->input_steps_consumed,
           result->premature_terminal ? "true" : "false",
           result->field_released ? "FIELD_RELEASE"
               : result->facility_active_boundary
                   ? "FACILITY_ACTIVE_CONTINUATION_BOUNDARY" : "NONE",
           result->field_released ? "true" : "false");
    s61_print_capture(&result->capture);
    printf(",\"decision_watch\":{"
           "\"special_result_address\":\"0x%08X\","
           "\"initial_value\":%u,\"values\":[",
           WORLD_SPECIAL_RESULT, result->decision_initial_value);
    for (unsigned index = 0U;
         index < result->capture.var_result_value_count; ++index)
        printf("%s%u", index == 0U ? "" : ",",
               result->capture.var_result_values[index]);
    printf("],\"change_count\":%u},\"effect_watch\":{"
           "\"enabled\":%s,\"hook_hits_before\":%" PRIu64 ","
           "\"hook_hits_after\":%" PRIu64 ",\"hook_hit_delta\":%" PRIu64
           "}",
           result->capture.var_result_value_count,
           result->effect_watch_enabled ? "true" : "false",
           result->effect_hook_hits_before, result->effect_hook_hits_after,
           result->effect_hook_hits_after - result->effect_hook_hits_before);
    printf(",\"chained_battles\":[");
    for (unsigned index = 0U; index < result->chained_battle_count; ++index) {
        const struct S61CatalogChainedBattle *expected =
            &sequence->chained_battles[index];
        const struct S61ChainedBattleResult *observed =
            &result->chained_battles[index];
        if (index != 0U)
            putchar(',');
        printf("{\"phase_index\":%u,\"battle_kind\":\"%s\","
               "\"source_start_instruction_address\":\"0x%08" PRIX32
               "\",\"expected_trainer_id\":",
               expected->phase_index,
               s61_battle_kind_name(expected->battle_kind),
               expected->source_start_instruction_address);
        if (expected->trainer_id_expected)
            printf("%u", expected->trainer_id);
        else
            fputs("null", stdout);
        printf(",\"trainer_battle\":%s,\"observed_trainer_id\":%u,"
               "\"completed_via_keys\":%s,\"outcome\":%u,"
               "\"won_or_escaped_not_loss\":%s,\"resume_kind\":\"%s\","
               "\"expected_resume_pc\":",
               observed->trainer_battle ? "true" : "false",
               observed->observed_trainer_id,
               observed->completed_via_keys ? "true" : "false",
               observed->outcome,
               observed->won_or_escaped_not_loss ? "true" : "false",
               s61_post_battle_resume_kind_name(expected->resume_kind));
        if (expected->resume_kind == S61_POST_BATTLE_STANDARD)
            fputs("null", stdout);
        else
            printf("\"0x%08" PRIX32 "\"", expected->resume_pc);
        printf(",\"observed_resume_pc\":\"0x%08" PRIX32
               "\",\"resume_pc_hit_count\":%u}",
               observed->observed_resume_pc,
               observed->resume_pc_hit_count);
    }
    printf("]}");
}

static struct S61Capture s61_new_capture(const char *directory,
                                         const char *label,
                                         char *artifact, size_t size)
{
    struct S61Capture capture = {0};
    int length = snprintf(artifact, size, "%s/%s", directory, label);
    if (length <= 0 || (size_t)length >= size)
        s61_die("artifact prefix formatting failed");
    capture.artifact_prefix = artifact;
    memcpy(capture.baseline, s61_video, sizeof(capture.baseline));
    return capture;
}

static void s61_write_peak_frame(const struct S61Capture *capture,
                                 const char *suffix)
{
    if (capture->artifact_prefix == NULL
        || capture->maximum_baseline_pixel_difference == 0U)
        return;
    char path[4096];
    int length = snprintf(path, sizeof(path), "%s-%s",
                          capture->artifact_prefix, suffix);
    if (length <= 0 || (size_t)length >= sizeof(path))
        s61_die("peak framebuffer path formatting failed");
    s61_write_framebuffer_ppm(
        path, capture->maximum_difference_frame,
        "INTERACTION_PEAK_FRAME");
}

static void s61_acquire_flute(struct mCore *core,
                              const struct S61Config *config,
                              struct S61Capture *capture,
                              unsigned *walked)
{
    if (!s61_object_visible(core, &config->giver))
        s61_die("flute producer is not visible before acquisition");
    *walked += s61_walk_approach(core, &config->giver);
    if (!s61_drive_interaction(core, config->giver.action_key,
                               S61_CHOICE_CANCEL, capture, false)) {
        fprintf(stderr,
                "flute giver debug messages=%u active=%u state=%u lock=%u "
                "callback=%08" PRIX32 " flag=%u item=%u result=%u\n",
                capture->count, capture->active_frames,
                read8(core, S61_FIELD_MESSAGE_STATE),
                world_script_enabled(core),
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                s61_flag(core, config->flute_flag),
                s61_item(core, config->flute_item),
                read16(core, WORLD_SPECIAL_RESULT));
        s61_die("normal flute-giver interaction did not return to field");
    }
    if (s61_flag(core, config->flute_flag) != 1U
        || s61_item(core, config->flute_item) != 1U)
        s61_die("normal flute-giver dialogue did not commit item and flag");
}

static void s61_case_missing_flute(const char *rom_path,
                                   const char *directory,
                                   const struct S61Config *config)
{
    char save_path[4096];
    char artifact[4096];
    struct Fixture fixture = s61_world_fixture(
        "snorlax_missing_flute", &config->snorlax);
    s61_save_path(save_path, sizeof(save_path), directory, fixture.name);
    s61_generate(rom_path, save_path, &fixture);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &fixture);
    bool visible_before = s61_object_visible(core, &config->snorlax);
    unsigned walked = s61_walk_approach(core, &config->snorlax);
    struct S61Capture capture = s61_new_capture(
        directory, fixture.name, artifact, sizeof(artifact));
    bool released = s61_drive_interaction(
        core, config->snorlax.action_key, S61_CHOICE_ADVANCE,
        &capture, false);
    bool pass = visible_before && walked != 0U && released
        && !s61_battle_active(core)
        && s61_flag(core, config->flute_flag) == 0U
        && s61_flag(core, config->snorlax_hidden_flag) == 0U
        && s61_object_visible(core, &config->snorlax)
        && capture.count != 0U;
    if (!pass) {
        fprintf(stderr,
                "missing debug visible=%u walked=%u released=%u battle=%u "
                "flute=%u hidden=%u visible_after=%u messages=%u active=%u "
                "state=%u lock=%u callback=%08" PRIX32 "\n",
                visible_before, walked, released, s61_battle_active(core),
                s61_flag(core, config->flute_flag),
                s61_flag(core, config->snorlax_hidden_flag),
                s61_object_visible(core, &config->snorlax), capture.count,
                capture.active_frames, read8(core, S61_FIELD_MESSAGE_STATE),
                world_script_enabled(core),
                read32(core, BATTLE_CORE_MAIN_CALLBACK2));
        s61_die("missing-flute branch changed state, hid the object, or showed no text");
    }
    printf("{\"schema_version\":2,\"status\":\"PASS\","
           "\"case\":\"snorlax_missing_flute\","
           "\"natural_continue\":true,\"stock_warp_save\":true,"
           "\"actual_walk_steps\":%u,\"direction_plus_a\":true,"
           "\"object_visible_before\":true,\"object_visible_after\":true,"
           "\"flute_flag\":0,\"hidden_flag\":0,\"battle_started\":false,"
           "\"capture\":", walked);
    s61_print_capture(&capture);
    printf(",\"warnings\":0}\n");
    bootstrap_close_core(core);
}

static void s61_case_producer_consumer(const char *rom_path,
                                       const char *directory,
                                       const struct S61Config *config)
{
    char save_path[4096];
    char producer_artifact[4096];
    char no_artifact[4096];
    char yes_artifact[4096];
    struct Fixture giver = s61_world_fixture(
        "producer_snorlax_flee_revisit", &config->giver);
    struct Fixture snorlax = s61_world_fixture(
        "producer_snorlax_flee_revisit", &config->snorlax);
    s61_save_path(save_path, sizeof(save_path), directory, giver.name);
    s61_generate(rom_path, save_path, &giver);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &giver);
    unsigned walked = 0U;
    struct S61Capture producer_capture = s61_new_capture(
        directory, "producer-flute", producer_artifact,
        sizeof(producer_artifact));
    s61_acquire_flute(core, config, &producer_capture, &walked);

    s61_stock_warp_save(core, &snorlax);
    bootstrap_close_core(core);
    core = s61_open_fresh(rom_path, save_path, &snorlax);
    bool visible_before = s61_object_visible(core, &config->snorlax);
    walked += s61_walk_approach(core, &config->snorlax);

    struct S61Capture no_capture = s61_new_capture(
        directory, "snorlax-no", no_artifact, sizeof(no_artifact));
    bool no_released = s61_drive_interaction(
        core, config->snorlax.action_key, S61_CHOICE_NO,
        &no_capture, false);
    uint16_t no_result = read16(core, WORLD_SPECIAL_RESULT);
    bool no_preserved = visible_before && no_released
        && !s61_battle_active(core)
        && s61_flag(core, config->snorlax_hidden_flag) == 0U
        && s61_object_visible(core, &config->snorlax);
    if (!no_preserved) {
        fprintf(stderr,
                "snorlax No debug released=%u battle=%u result=%u "
                "hidden=%u visible=%u messages=%u state=%u lock=%u\n",
                no_released, s61_battle_active(core), no_result,
                s61_flag(core, config->snorlax_hidden_flag),
                s61_object_visible(core, &config->snorlax),
                no_capture.count, read8(core, S61_FIELD_MESSAGE_STATE),
                world_script_enabled(core));
        s61_die("No branch did not preserve the sleeping Snorlax");
    }

    struct S61Capture yes_capture = s61_new_capture(
        directory, "snorlax-yes", yes_artifact, sizeof(yes_artifact));
    bool yes_started = s61_drive_interaction(
        core, config->snorlax.action_key, S61_CHOICE_YES,
        &yes_capture, true);
    if (!yes_started || !s61_battle_active(core))
        s61_die("Yes branch did not enter a battle through ordinary input");
    struct FixtureResult battle = {0};
    world_record_wild(core, &snorlax, &battle);
    if (battle.first_wild_species != config->snorlax_species)
        s61_die("Snorlax event generated the wrong canonical species");
    world_finish_battle(core, &snorlax, &battle, true);
    bool battle_fled = battle.battle_completed
        && battle.battle_outcome == WORLD_BATTLE_OUTCOME_RAN;
    if (!battle_fled)
        s61_die("Snorlax Run input did not produce B_OUTCOME_RAN");
    world_wait_player_ready(core, &snorlax);
    bool hidden_after_flee = !s61_object_visible(core, &config->snorlax);
    unsigned hidden_flag_after_flee = s61_flag(
        core, config->snorlax_hidden_flag);
    if (hidden_after_flee != config->snorlax_hides_after_flee
        || (hidden_flag_after_flee != 0U) != config->snorlax_hides_after_flee)
        s61_die("flee/revisit object visibility differs from fixture policy");

    /* Revisit via a real warp/load, then persist it through a new save and a
     * second fresh-core Continue. */
    s61_stock_warp_save(core, &snorlax);
    bool revisit_hidden = !s61_object_visible(core, &config->snorlax);
    bootstrap_close_core(core);
    core = s61_open_fresh(rom_path, save_path, &snorlax);
    bool save_load_hidden = !s61_object_visible(core, &config->snorlax);
    unsigned saved_hidden_flag = s61_flag(core, config->snorlax_hidden_flag);
    bool pass = visible_before && walked >= 2U
        && producer_capture.count != 0U && no_capture.count != 0U
        && yes_capture.count != 0U && battle.battle_seen
        && battle_fled
        && revisit_hidden == config->snorlax_hides_after_flee
        && save_load_hidden == config->snorlax_hides_after_flee
        && (saved_hidden_flag != 0U) == config->snorlax_hides_after_flee;
    if (!pass)
        s61_die("producer-consumer flee/revisit/save-load contract failed");

    printf("{\"schema_version\":2,\"status\":\"PASS\","
           "\"case\":\"producer_snorlax_flee_revisit\","
           "\"natural_continue\":true,\"producer_via_normal_dialogue\":true,"
           "\"stock_warp_save\":true,\"fresh_consumer_continue\":true,"
           "\"actual_walk_steps\":%u,\"direction_plus_a\":true,"
           "\"flute_item\":1,\"flute_flag\":1,"
           "\"no_branch_result\":%u,\"no_branch_preserved\":true,"
           "\"yes_branch_battle\":true,"
           "\"battle_species\":%u,\"battle_outcome\":%u,"
           "\"battle_fled\":true,"
           "\"hidden_after_flee\":%s,\"revisit_hidden\":%s,"
           "\"save_load_hidden\":%s,\"hidden_flag\":%u,"
           "\"captures\":{\"producer\":",
           walked, no_result, battle.first_wild_species,
           battle.battle_outcome,
           hidden_after_flee ? "true" : "false",
           revisit_hidden ? "true" : "false",
           save_load_hidden ? "true" : "false", saved_hidden_flag);
    s61_print_capture(&producer_capture);
    printf(",\"no\":");
    s61_print_capture(&no_capture);
    printf(",\"yes\":");
    s61_print_capture(&yes_capture);
    printf("},\"warnings\":0}\n");
    bootstrap_close_core(core);
}

static struct S61Capture s61_run_fuji_branch(
    const char *rom_path, const char *directory, const struct S61Config *config,
    bool acquire, const char *suffix, unsigned *walked_out,
    unsigned *flute_flag_out)
{
    char save_path[4096];
    char artifact[4096];
    struct Fixture initial = s61_world_fixture(
        suffix, acquire ? &config->giver : &config->fuji);
    struct Fixture fuji = s61_world_fixture(suffix, &config->fuji);
    s61_save_path(save_path, sizeof(save_path), directory, suffix);
    s61_generate(rom_path, save_path, &initial);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &initial);
    unsigned walked = 0U;
    if (acquire) {
        char producer_artifact[4096];
        struct S61Capture producer = s61_new_capture(
            directory, "fuji-producer", producer_artifact,
            sizeof(producer_artifact));
        s61_acquire_flute(core, config, &producer, &walked);
        if (producer.count == 0U)
            s61_die("Fuji after-state producer showed no rendered text");
        s61_stock_warp_save(core, &fuji);
        bootstrap_close_core(core);
        core = s61_open_fresh(rom_path, save_path, &fuji);
    }
    if (!s61_object_visible(core, &config->fuji))
        s61_die("Fuji fixture object is not visible");
    walked += s61_walk_approach(core, &config->fuji);
    struct S61Capture capture = s61_new_capture(
        directory, suffix, artifact, sizeof(artifact));
    if (!s61_drive_interaction(core, config->fuji.action_key,
                               S61_CHOICE_ADVANCE, &capture, false)
        || capture.count == 0U || s61_battle_active(core))
        s61_die("Fuji branch did not show finite contextual dialogue");
    *walked_out = walked;
    *flute_flag_out = s61_flag(core, config->flute_flag);
    if ((*flute_flag_out != 0U) != acquire)
        s61_die("Fuji context does not reflect producer-derived flute state");
    bootstrap_close_core(core);
    return capture;
}

static void s61_case_fuji_matrix(const char *rom_path,
                                 const char *directory,
                                 const struct S61Config *config)
{
    unsigned before_walked = 0U;
    unsigned after_walked = 0U;
    unsigned before_flag = 0U;
    unsigned after_flag = 0U;
    struct S61Capture before = s61_run_fuji_branch(
        rom_path, directory, config, false, "fuji-before",
        &before_walked, &before_flag);
    struct S61Capture after = s61_run_fuji_branch(
        rom_path, directory, config, true, "fuji-after",
        &after_walked, &after_flag);
    if (before.count == 0U || after.count == 0U
        || before.messages[0].raw_hash == after.messages[0].raw_hash)
        s61_die("Fuji before/after dialogue did not expose distinct context");
    printf("{\"schema_version\":2,\"status\":\"PASS\","
           "\"case\":\"fuji_before_after\","
           "\"producer_via_normal_dialogue\":true,"
           "\"before_flute_flag\":%u,\"after_flute_flag\":%u,"
           "\"actual_walk_steps\":%u,\"dialogue_distinct\":true,"
           "\"captures\":{\"before\":", before_flag, after_flag,
           before_walked + after_walked);
    s61_print_capture(&before);
    printf(",\"after\":");
    s61_print_capture(&after);
    printf("},\"warnings\":0}\n");
}

static void s61_case_flag_matrix(const char *rom_path,
                                 const char *directory,
                                 const struct S61Config *config)
{
    char save_path[4096];
    struct Fixture snorlax = s61_world_fixture(
        "snorlax_flag_visibility_matrix", &config->snorlax);
    s61_save_path(save_path, sizeof(save_path), directory, snorlax.name);
    s61_generate(rom_path, save_path, &snorlax);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &snorlax);
    bool clear_visible = s61_object_visible(core, &config->snorlax);
    (void)s61_call_synced(core, WORLD_FLAG_SET,
                         config->snorlax_hidden_flag, 0U, 0U, 0U);
    if (s61_flag(core, config->snorlax_hidden_flag) != 1U)
        s61_die("expanded hidden flag setter did not commit");
    s61_stock_warp_save(core, &snorlax);
    bootstrap_close_core(core);
    core = s61_open_fresh(rom_path, save_path, &snorlax);
    bool set_hidden = !s61_object_visible(core, &config->snorlax);
    bool pass = clear_visible && set_hidden;
    if (!pass)
        s61_die("direct supplementary flag visibility matrix failed");
    printf("{\"schema_version\":2,\"status\":\"PASS\","
           "\"case\":\"snorlax_flag_visibility_matrix\","
           "\"supplementary_direct_state_setup\":true,"
           "\"not_primary_producer_consumer_test\":true,"
           "\"clear_visible\":true,\"set_hidden_after_save_load\":true,"
           "\"warnings\":0}\n");
    bootstrap_close_core(core);
}

static void s61_read_text(struct mCore *core, uint32_t address,
                          uint8_t *raw, size_t *size)
{
    *size = 0U;
    while (*size < S61_MAX_MESSAGE_BYTES) {
        raw[*size] = read8(core, address + (uint32_t)*size);
        ++*size;
        if (raw[*size - 1U] == 0xFFU)
            return;
    }
    s61_die("map name did not terminate within the capture bound");
}

static struct S61MapPopupRow s61_parse_map_popup_row(char *line)
{
    char *fields[S61_MAP_POPUP_FIELD_COUNT];
    if (s61_split_catalog_fields(
            line, fields, S61_MAP_POPUP_FIELD_COUNT)
            != S61_MAP_POPUP_FIELD_COUNT)
        s61_die("map popup TSV field count differs");
    struct S61MapPopupRow row = {0};
    row.case_id = fields[0];
    if (!s61_catalog_identifier(row.case_id, true))
        s61_die("map popup case identifier is unsafe");
    row.group = (uint8_t)s61_parse_catalog_uint(
        fields[1], "group", 255U);
    row.map = (uint8_t)s61_parse_catalog_uint(
        fields[2], "map", 255U);
    row.source_group = (uint8_t)s61_parse_catalog_uint(
        fields[3], "source_group", 255U);
    row.source_map = (uint8_t)s61_parse_catalog_uint(
        fields[4], "source_map", 255U);
    row.source_warp = (uint8_t)s61_parse_catalog_uint(
        fields[5], "source_warp", 255U);
    row.predecessor_x = (uint16_t)s61_parse_catalog_uint(
        fields[6], "predecessor_x", 65535U);
    row.predecessor_y = (uint16_t)s61_parse_catalog_uint(
        fields[7], "predecessor_y", 65535U);
    row.trigger_x = (uint16_t)s61_parse_catalog_uint(
        fields[8], "trigger_x", 65535U);
    row.trigger_y = (uint16_t)s61_parse_catalog_uint(
        fields[9], "trigger_y", 65535U);
    row.trigger_key = (uint16_t)s61_parse_catalog_uint(
        fields[10], "trigger_key", 1023U);
    row.destination_warp = (uint8_t)s61_parse_catalog_uint(
        fields[11], "destination_warp", 255U);
    row.arrival_x = (uint16_t)s61_parse_catalog_uint(
        fields[12], "arrival_x", 65535U);
    row.arrival_y = (uint16_t)s61_parse_catalog_uint(
        fields[13], "arrival_y", 65535U);
    row.runtime_section = (uint8_t)s61_parse_catalog_uint(
        fields[14], "runtime_section", 255U);
    row.resolver_source_section = (uint8_t)s61_parse_catalog_uint(
        fields[15], "resolver_source_section", 255U);
    row.expected_name_pointer = s61_parse_catalog_uint(
        fields[16], "expected_name_pointer", UINT32_MAX);
    row.expected_name_size = (uint16_t)s61_parse_catalog_uint(
        fields[17], "expected_name_size", S61_MAX_MESSAGE_BYTES);
    row.physical_provenance = fields[18];
    if (!(row.trigger_key == WORLD_KEY_UP
          || row.trigger_key == WORLD_KEY_DOWN
          || row.trigger_key == WORLD_KEY_LEFT
          || row.trigger_key == WORLD_KEY_RIGHT)
        || row.expected_name_pointer < 0x08000000U
        || row.expected_name_pointer >= 0x0A000000U
        || row.expected_name_size < 2U
            || (strcmp(row.physical_provenance,
                   "IMPORTED_KANTO_CANONICAL") != 0
            && strcmp(row.physical_provenance,
                      "VEGA_STOCK_PHYSICAL") != 0))
        s61_die("map popup TSV semantic field differs");
    return row;
}

static void s61_case_popup(const char *rom_path, const char *directory,
                           const struct S61Config *config)
{
    (void)config;
    const char *tsv_path = getenv("S61_MAP_POPUP_TSV");
    if (tsv_path == NULL || tsv_path[0] == '\0')
        s61_die("S61_MAP_POPUP_TSV is required");
    FILE *stream = fopen(tsv_path, "rb");
    if (stream == NULL)
        s61_die("map popup TSV could not be opened");
    char line[8192];
    if (fgets(line, sizeof(line), stream) == NULL)
        s61_die("map popup TSV is empty");
    size_t header_size = strlen(line);
    while (header_size != 0U
           && (line[header_size - 1U] == '\n'
               || line[header_size - 1U] == '\r'))
        line[--header_size] = '\0';
    if (strcmp(line, S61_MAP_POPUP_HEADER) != 0)
        s61_die("map popup TSV header differs");
    printf("{\"schema_version\":3,\"status\":\"PASS\","
           "\"case\":\"map_popup\",\"fresh_core_per_map\":true,"
           "\"actual_incoming_warp_by_player_input\":true,"
           "\"results\":[");
    unsigned count = 0U;
    while (fgets(line, sizeof(line), stream) != NULL) {
        if (strchr(line, '\n') == NULL && !feof(stream))
            s61_die("map popup TSV line exceeds bound");
        struct S61MapPopupRow row = s61_parse_map_popup_row(line);
        s61_case_name = row.case_id;
        bootstrap_phase = row.case_id;
        struct S61Interaction source = {
            row.source_group, row.source_map,
            row.predecessor_x, row.predecessor_y,
            row.trigger_key, 0U, 0U,
        };
        struct Fixture fixture = s61_world_fixture(row.case_id, &source);
        char save_path[4096];
        char artifact[4096];
        s61_save_path(save_path, sizeof(save_path), directory, row.case_id);
        s61_generate(rom_path, save_path, &fixture);
        struct mCore *core = s61_open_fresh(rom_path, save_path, &fixture);
        struct S61Capture capture = s61_new_capture(
            directory, row.case_id, artifact, sizeof(artifact));
        uint64_t before = bootstrap_framebuffer_hash(s61_video);
        bool trigger_seen = false;
        bool destination_seen = false;
        unsigned transition_frames = 0U;
        for (; transition_frames < 3600U; ++transition_frames) {
            /* Popup text is rendered outside gStringVar4.  Instruction-step
             * the physical transition so the exact AddTextPrinter r2 owner
             * is observed; frame-only emulation would miss the call. */
            s61_step_capture_frames(core, row.trigger_key, 1U, &capture);
            uint32_t save1 = world_save1(core, row.case_id);
            uint8_t group = read8(core, save1 + 4U);
            uint8_t map = read8(core, save1 + 5U);
            if (group == row.source_group && map == row.source_map
                && read16(core, save1) == row.trigger_x
                && read16(core, save1 + 2U) == row.trigger_y)
                trigger_seen = true;
            if (group == row.group && map == row.map) {
                destination_seen = true;
                core->setKeys(core, 0U);
                break;
            }
        }
        if (!trigger_seen || !destination_seen)
            s61_die("map popup actual incoming warp was not traversed");
        s61_step_capture_frames(core, 0U, 900U, &capture);
        struct Fixture destination = {
            row.case_id, FIXTURE_FACING_DIALOGUE,
            row.group, row.map, row.arrival_x, row.arrival_y,
            row.trigger_key, 0U, 0U, 0U, 0U,
        };
        world_wait_player_ready(core, &destination);
        uint32_t save1 = world_save1(core, row.case_id);
        uint8_t live_section = (uint8_t)s61_call_synced(
            core, S61_GET_CURRENT_MAP_SECTION, 0U, 0U, 0U, 0U);
        for (unsigned byte = 0U; byte < 64U; ++byte)
            write8(core, S61_NAME_SCRATCH + byte, 0U);
        (void)s61_call_synced(core, S61_GET_MAP_NAME,
                             S61_NAME_SCRATCH, live_section, 0U, 0U);
        uint8_t resolver_raw[S61_MAX_MESSAGE_BYTES];
        uint8_t pointer_raw[S61_MAX_MESSAGE_BYTES];
        size_t resolver_size = 0U;
        size_t pointer_size = 0U;
        s61_read_text(core, S61_NAME_SCRATCH,
                      resolver_raw, &resolver_size);
        s61_read_text(core, row.expected_name_pointer,
                      pointer_raw, &pointer_size);
        bool popup_printer_raw_matched = false;
        uint32_t popup_printer_frame = 0U;
        for (unsigned call_index = 0U;
             call_index < capture.printer_call_count; ++call_index) {
            const struct S61PrinterCall *call =
                &capture.printer_calls[call_index];
            if (call->size == pointer_size
                && memcmp(call->raw, pointer_raw, pointer_size) == 0) {
                popup_printer_raw_matched = true;
                popup_printer_frame = call->frame;
                break;
            }
        }
        uint64_t after = bootstrap_framebuffer_hash(s61_video);
        bool input_recovered = world_overworld(core)
            && !world_script_enabled(core);
        bool popup_contract_matches = read8(core, save1 + 4U) == row.group
            && read8(core, save1 + 5U) == row.map
            && read16(core, save1) == row.arrival_x
            && read16(core, save1 + 2U) == row.arrival_y
            && live_section == row.runtime_section
            && resolver_size == row.expected_name_size
            && pointer_size == row.expected_name_size
            && memcmp(resolver_raw, pointer_raw, pointer_size) == 0
            && popup_printer_raw_matched
            && capture.framebuffer_changes != 0U
            && capture.maximum_baseline_pixel_difference >= 2000U
            && input_recovered;
        if (!popup_contract_matches) {
            fprintf(stderr,
                    "MAP_POPUP_DIAGNOSTIC case=%s map=%u/%u expected=%u/%u "
                    "xy=%u,%u expected_xy=%u,%u live_section=%u "
                    "expected_section=%u resolver_size=%zu pointer_size=%zu "
                    "expected_size=%u raw_equal=%u printer_match=%u "
                    "printer_calls=%u changed_frames=%u max_pixel_diff=%u "
                    "input_recovered=%u trigger_seen=%u destination_seen=%u "
                    "transition_frames=%u\n",
                    row.case_id, read8(core, save1 + 4U),
                    read8(core, save1 + 5U), row.group, row.map,
                    read16(core, save1), read16(core, save1 + 2U),
                    row.arrival_x, row.arrival_y, live_section,
                    row.runtime_section, resolver_size, pointer_size,
                    row.expected_name_size,
                    resolver_size == pointer_size
                        && memcmp(resolver_raw, pointer_raw, pointer_size) == 0,
                    popup_printer_raw_matched,
                    capture.printer_call_count, capture.framebuffer_changes,
                    capture.maximum_baseline_pixel_difference,
                    input_recovered, trigger_seen, destination_seen,
                    transition_frames + 1U);
        }
        if (!popup_contract_matches)
            s61_die("map popup visual/resolver/provenance contract differs");
        s61_write_peak_frame(&capture, "peak");
        printf("%s{\"case_id\":\"%s\",\"map\":\"%u/%u\","
               "\"source\":\"%u/%u/%u\","
               "\"actual_trigger_tile\":[%u,%u],"
               "\"destination_warp_id\":%u,\"landing\":[%u,%u],"
               "\"runtime_section\":%u,"
               "\"resolver_source_section\":%u,"
               "\"physical_provenance\":\"%s\","
               "\"expected_name_pointer\":\"0x%08" PRIX32 "\","
               "\"popup_printer_raw_matched\":true,"
               "\"popup_printer_frame\":%" PRIu32 ","
               "\"resolver_raw_hex\":\"",
               count == 0U ? "" : ",", row.case_id,
               row.group, row.map, row.source_group, row.source_map,
               row.source_warp, row.trigger_x, row.trigger_y,
               row.destination_warp, read16(core, save1),
               read16(core, save1 + 2U), live_section,
               row.resolver_source_section, row.physical_provenance,
               row.expected_name_pointer, popup_printer_frame);
        for (size_t byte = 0U; byte < resolver_size; ++byte)
            printf("%02X", resolver_raw[byte]);
        printf("\",\"pointer_raw_hex\":\"");
        for (size_t byte = 0U; byte < pointer_size; ++byte)
            printf("%02X", pointer_raw[byte]);
        printf("\",\"framebuffer_before_fnv1a64\":\"%016" PRIX64 "\","
               "\"framebuffer_after_fnv1a64\":\"%016" PRIX64 "\","
               "\"changed_frames\":%u,\"transition_frames\":%u,"
               "\"input_recovered\":true,\"capture\":",
               before, after, capture.framebuffer_changes,
               transition_frames + 1U);
        s61_print_capture(&capture);
        putchar('}');
        ++count;
        bootstrap_close_core(core);
    }
    fclose(stream);
    if (count != 7U)
        s61_die("map popup exact seven physical cases not executed");
    printf("],\"fixture_count\":7,\"failed\":0,\"untested\":0,"
           "\"warnings\":0}\n");
}

static uint16_t s61_key_name(const char *name)
{
    if (strcmp(name, "A") == 0)
        return WORLD_KEY_A;
    if (strcmp(name, "B") == 0)
        return WORLD_KEY_B;
    if (strcmp(name, "START") == 0)
        return S61_KEY_START;
    if (strcmp(name, "SELECT") == 0)
        return S61_KEY_SELECT;
    if (strcmp(name, "UP") == 0)
        return WORLD_KEY_UP;
    if (strcmp(name, "DOWN") == 0)
        return WORLD_KEY_DOWN;
    if (strcmp(name, "LEFT") == 0)
        return WORLD_KEY_LEFT;
    if (strcmp(name, "RIGHT") == 0)
        return WORLD_KEY_RIGHT;
    s61_die("Fly sequence contains an unknown GBA key");
    return 0U;
}

static unsigned s61_parse_sequence(struct S61KeyStep *steps, unsigned capacity)
{
    const char *source = getenv("S61_FLY_MAP_SEQUENCE");
    char buffer[4096];
    if (source == NULL || source[0] == '\0')
        source = "UP:2:60,UP:2:60,UP:2:60,UP:2:60,"
                 "A:2:600,A:2:600";
    if (strlen(source) >= sizeof(buffer))
        s61_die("Fly sequence exceeds its bounded input buffer");
    strcpy(buffer, source);
    unsigned count = 0U;
    char *cursor = buffer;
    while (*cursor != '\0') {
        if (count >= capacity)
            s61_die("Fly sequence has too many steps");
        char *comma = strchr(cursor, ',');
        if (comma != NULL)
            *comma = '\0';
        char *first = strchr(cursor, ':');
        char *second = first == NULL ? NULL : strchr(first + 1, ':');
        if (first == NULL || second == NULL)
            s61_die("Fly sequence step must be KEY:PRESSED:RELEASED");
        *first = '\0';
        *second = '\0';
        for (char *letter = cursor; *letter != '\0'; ++letter)
            *letter = (char)toupper((unsigned char)*letter);
        steps[count].key = s61_key_name(cursor);
        char *end_pressed = NULL;
        char *end_released = NULL;
        unsigned long pressed = strtoul(first + 1, &end_pressed, 10);
        unsigned long released = strtoul(second + 1, &end_released, 10);
        if (*end_pressed != '\0' || *end_released != '\0'
            || pressed == 0U || pressed > 60U || released > 3600U)
            s61_die("Fly sequence frame count is invalid");
        steps[count].pressed = (unsigned)pressed;
        steps[count].released = (unsigned)released;
        ++count;
        if (comma == NULL)
            break;
        cursor = comma + 1;
    }
    return count;
}

static bool s61_enter_party_menu(struct mCore *core,
                                 struct S61Capture *capture)
{
    s61_pulse(core, S61_KEY_START, 2U, 90U, capture);
    if (read32(core, S61_START_MENU_CALLBACK) != S61_START_MENU_INPUT)
        return false;
    uint8_t count = read8(core, S61_START_MENU_COUNT);
    uint8_t cursor = read8(core, S61_START_MENU_CURSOR);
    uint8_t pokemon = 0xFFU;
    if (count == 0U || count > 9U || cursor >= count)
        return false;
    for (uint8_t index = 0U; index < count; ++index) {
        if (read8(core, S61_START_MENU_ORDER + index) == 1U) {
            pokemon = index;
            break;
        }
    }
    if (pokemon == 0xFFU)
        return false;
    unsigned down = (unsigned)(pokemon + count - cursor) % count;
    unsigned up = (unsigned)(cursor + count - pokemon) % count;
    uint16_t key = down <= up ? WORLD_KEY_DOWN : WORLD_KEY_UP;
    unsigned amount = down <= up ? down : up;
    for (unsigned step = 0U; step < amount; ++step)
        s61_pulse(core, key, 2U, 30U, capture);
    s61_pulse(core, WORLD_KEY_A, 2U, 600U, capture);
    return read8(core, S61_PARTY_MENU + S61_PARTY_MENU_SLOT) == 0U
        && !world_overworld(core);
}

static void s61_case_fly(const char *rom_path, const char *directory,
                         const struct S61Config *config)
{
    char save_path[4096];
    char artifact[4096];
    struct S61Interaction source = {
        config->fly_origin_group, config->fly_origin_map,
        config->fly_origin_x, config->fly_origin_y, WORLD_KEY_DOWN, 0U, 0U,
    };
    struct Fixture fixture = s61_world_fixture("fly_normal_menu", &source);
    s61_save_path(save_path, sizeof(save_path), directory, fixture.name);
    s61_generate(rom_path, save_path, &fixture);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &fixture);

    for (unsigned badge = 0U; badge < S61_FLAG_BADGE_COUNT; ++badge)
        (void)s61_call_synced(core, WORLD_FLAG_SET,
                             S61_FLAG_BADGE_1 + badge, 0U, 0U, 0U);
    if (!world_overworld(core))
        s61_die("Fly badge preparation left the input-ready field");
    (void)s61_call_synced(core, WORLD_FLAG_SET,
                         S61_FLAG_POKEMON_GET, 0U, 0U, 0U);
    if (!world_overworld(core))
        s61_die("Fly Pokemon-get preparation left the input-ready field");
    (void)s61_call_synced(core, WORLD_FLAG_SET,
                         config->fly_visited_flag, 0U, 0U, 0U);
    if (s61_flag(core, config->fly_visited_flag) != 1U)
        s61_die("Fly destination visited-flag preparation failed");
    if (s61_call_synced(core, BATTLE_CORE_ADD_BAG_ITEM,
                       S61_FLY_HM_ITEM, 1U, 0U, 0U) == 0U)
        s61_die("Fly HM ownership preparation failed");
    if (!world_overworld(core))
        s61_die("Fly HM preparation left the input-ready field");
    /* The generated six-mon save already gives slot 0 nonzero PP1.  Writing
     * PP1 again is unnecessary and previously introduced a second host-call
     * scheduler boundary; only replace MOVE1 and prove usability through the
     * normal Party/Fly UI below. */
    s61_set_mon_data_u32(core, BOOTSTRAP_PLAYER_PARTY,
                         MON_DATA_MOVE1, S61_FLY_MOVE);
    world_wait_player_ready(core, &fixture);
    if (!world_overworld(core)) {
        fprintf(stderr, "Fly preparation debug main=%08" PRIX32
                " pc=%08" PRIX32 " cpsr=%08" PRIX32 "\n",
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                (uint32_t)read_register(core, "pc"),
                (uint32_t)read_register(core, "cpsr"));
        s61_die("Fly host preparation left the input-ready field");
    }

    struct S61Capture capture = s61_new_capture(
        directory, fixture.name, artifact, sizeof(artifact));
    /* Fly is a framebuffer/transition/input-owner oracle.  Party/Town Map
     * UI routes include printer wrappers with non-text stack arguments; text
     * semantics are covered by catalog cases and are intentionally excluded
     * here to avoid treating those wrapper calls as message owners. */
    capture.suppress_semantic_content = true;
    uint64_t field_hash = bootstrap_framebuffer_hash(s61_video);
    if (!s61_enter_party_menu(core, &capture)) {
        fprintf(stderr,
                "Fly party debug start_callback=%08" PRIX32
                " count=%u cursor=%u party_slot=%u overworld=%u "
                "main=%08" PRIX32 " lock=%u message=%u\n",
                read32(core, S61_START_MENU_CALLBACK),
                read8(core, S61_START_MENU_COUNT),
                read8(core, S61_START_MENU_CURSOR),
                read8(core, S61_PARTY_MENU + S61_PARTY_MENU_SLOT),
                world_overworld(core),
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                world_script_enabled(core),
                read8(core, S61_FIELD_MESSAGE_STATE));
        s61_die("normal Start-menu path did not enter the party screen");
    }
    /* Select slot zero, move to the fixture-declared Fly context row, then let
     * the configurable sequence navigate the real Town Map.  No
     * SetFlyWarpDestination or region-map owner is host-called. */
    s61_pulse(core, WORLD_KEY_A, 2U, 120U, &capture);
    for (unsigned step = 0U; step < config->fly_context_down; ++step)
        s61_pulse(core, WORLD_KEY_DOWN, 2U, 45U, &capture);
    s61_pulse(core, WORLD_KEY_A, 2U, 900U, &capture);
    uint64_t town_map_hash = bootstrap_framebuffer_hash(s61_video);
    if (town_map_hash == field_hash || world_overworld(core))
        s61_die("normal party field-move path did not open a visible Fly map");
    char town_map_artifact[4096];
    int town_map_length = snprintf(town_map_artifact, sizeof(town_map_artifact),
                                   "%s-town-map", artifact);
    if (town_map_length <= 0
        || (size_t)town_map_length >= sizeof(town_map_artifact))
        s61_die("Town Map artifact path formatting failed");
    s61_write_framebuffer_ppm(
        town_map_artifact, s61_video, "FLY_TOWN_MAP_FRAME");
    struct S61KeyStep steps[S61_MAX_SEQUENCE_STEPS];
    unsigned step_count = s61_parse_sequence(steps, S61_MAX_SEQUENCE_STEPS);
    for (unsigned index = 0U; index < step_count; ++index)
        s61_pulse(core, steps[index].key, steps[index].pressed,
                  steps[index].released, &capture);
    char fly_final_artifact[4096];
    int fly_final_length = snprintf(fly_final_artifact,
                                    sizeof(fly_final_artifact),
                                    "%s-final", artifact);
    if (fly_final_length <= 0
        || (size_t)fly_final_length >= sizeof(fly_final_artifact))
        s61_die("Fly final artifact path formatting failed");
    s61_write_framebuffer_ppm(
        fly_final_artifact, s61_video, "FLY_DESTINATION_FRAME");
    uint32_t save1 = world_save1(core, fixture.name);
    uint8_t final_group = read8(core, save1 + 4U);
    uint8_t final_map = read8(core, save1 + 5U);
    uint16_t final_x = read16(core, save1);
    uint16_t final_y = read16(core, save1 + 2U);
    bool expected_destination = config->fly_destination_group == 0xFFU
        || (final_group == config->fly_destination_group
            && final_map == config->fly_destination_map
            && final_x == config->fly_destination_x
            && final_y == config->fly_destination_y);
    bool warped = final_group != fixture.group || final_map != fixture.map;
    bool landing_overworld = world_overworld(core);
    bool landing_script_released = !world_script_enabled(core);
    bool landing_controls_unlocked =
        read8(core, WORLD_FIELD_CONTROLS_LOCKED) == 0U;
    bool landing_field_ready = s61_field_terminal(core)
        && landing_overworld && landing_script_released
        && landing_controls_unlocked;
    if (!expected_destination || !warped || !landing_field_ready) {
        fprintf(stderr,
                "Fly debug origin=%u/%u final=%u/%u@%u,%u "
                "expected=%u/%u@%u,%u "
                "overworld=%u callback=%08" PRIX32
                " lock=%u field_ready=%u steps=%u\n",
                fixture.group, fixture.map, final_group, final_map,
                final_x, final_y,
                config->fly_destination_group,
                config->fly_destination_map,
                config->fly_destination_x, config->fly_destination_y,
                world_overworld(core),
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                world_script_enabled(core), landing_field_ready ? 1U : 0U,
                step_count);
        s61_die("normal Fly selection did not settle at the expected destination");
    }
    s61_step_capture_pulse(core, WORLD_KEY_START, 2U, 120U, &capture);
    bool start_menu_opened =
        read32(core, S61_START_MENU_CALLBACK) == S61_START_MENU_INPUT;
    bool back_pressed = start_menu_opened;
    if (back_pressed)
        s61_step_capture_pulse(core, WORLD_KEY_B, 2U, 180U, &capture);
    save1 = world_save1(core, fixture.name);
    bool field_input_recovered = back_pressed && s61_field_terminal(core)
        && read8(core, WORLD_FIELD_CONTROLS_LOCKED) == 0U
        && read8(core, save1 + 4U) == final_group
        && read8(core, save1 + 5U) == final_map
        && read16(core, save1) == final_x
        && read16(core, save1 + 2U) == final_y;
    if (!start_menu_opened || !field_input_recovered)
        s61_die("Fly landing START/B field-input recovery differs");
    printf("{\"schema_version\":3,\"status\":\"PASS\","
           "\"case\":\"fly_normal_menu\","
           "\"preparation_only_host_writes\":true,"
           "\"start_party_town_map_via_keys\":true,"
           "\"town_map_visible\":true,\"context_down_steps\":%u,"
           "\"sequence_steps\":%u,"
           "\"origin\":\"%u/%u\",\"destination\":\"%u/%u\","
           "\"landing\":[%u,%u],"
           "\"landing_overworld\":true,"
           "\"landing_script_released\":true,"
           "\"landing_controls_unlocked\":true,"
           "\"start_pressed\":true,\"start_menu_opened\":true,"
           "\"back_pressed\":true,\"field_input_recovered\":true,"
           "\"field_framebuffer_fnv1a64\":\"%016" PRIX64 "\","
           "\"town_map_framebuffer_fnv1a64\":\"%016" PRIX64 "\","
           "\"capture\":", config->fly_context_down, step_count,
           fixture.group, fixture.map,
           final_group, final_map, final_x, final_y,
           field_hash, town_map_hash);
    s61_print_capture(&capture);
    printf(",\"warnings\":0}\n");
    bootstrap_close_core(core);
}

static unsigned s61_parse_catalog_uint(const char *text_value,
                                       const char *label,
                                       unsigned maximum)
{
    char *end = NULL;
    errno = 0;
    unsigned long value = strtoul(text_value, &end, 0);
    if (errno != 0 || end == text_value || *end != '\0' || value > maximum) {
        fprintf(stderr, "catalog numeric field %s=%s is invalid\n",
                label, text_value);
        s61_die("catalog numeric field is invalid");
    }
    return (unsigned)value;
}

static bool s61_catalog_identifier(const char *value, bool path_chars)
{
    if (value[0] == '\0')
        return false;
    for (const unsigned char *cursor = (const unsigned char *)value;
         *cursor != '\0'; ++cursor) {
        if (isalnum(*cursor) || *cursor == '_' || *cursor == '-'
            || *cursor == '.')
            continue;
        if (path_chars && (*cursor == '/' || *cursor == ':'))
            continue;
        return false;
    }
    return true;
}

static unsigned s61_split_catalog_fields(char *line, char **fields,
                                         unsigned capacity)
{
    size_t size = strlen(line);
    while (size != 0U && (line[size - 1U] == '\n' || line[size - 1U] == '\r'))
        line[--size] = '\0';
    unsigned count = 0U;
    char *cursor = line;
    for (;;) {
        if (count >= capacity)
            s61_die("catalog TSV has too many fields");
        fields[count++] = cursor;
        char *tab = strchr(cursor, '\t');
        if (tab == NULL)
            break;
        *tab = '\0';
        cursor = tab + 1;
    }
    return count;
}

static enum S61Choice s61_catalog_choice(const char *value)
{
    if (strcmp(value, "ADVANCE") == 0)
        return S61_CHOICE_ADVANCE;
    if (strcmp(value, "NO") == 0)
        return S61_CHOICE_NO;
    if (strcmp(value, "YES") == 0)
        return S61_CHOICE_YES;
    if (strcmp(value, "CANCEL") == 0)
        return S61_CHOICE_CANCEL;
    s61_die("catalog choice is invalid");
    return S61_CHOICE_ADVANCE;
}

static enum S61CatalogTerminal s61_catalog_terminal(const char *value)
{
    if (strcmp(value, "FIELD_RELEASE") == 0)
        return S61_TERMINAL_FIELD_RELEASE;
    if (strcmp(value, "BATTLE_START") == 0)
        return S61_TERMINAL_BATTLE_START;
    if (strcmp(value, "CALIBRATE") == 0)
        return S61_TERMINAL_CALIBRATE;
    if (strcmp(value, "NO_INTERACTION_HIDDEN") == 0)
        return S61_TERMINAL_HIDDEN;
    s61_die("catalog terminal is invalid");
    return S61_TERMINAL_FIELD_RELEASE;
}

static void s61_parse_catalog_values(char *value,
                                     struct S61ValueState *states,
                                     unsigned *count,
                                     unsigned capacity,
                                     unsigned maximum,
                                     const char *label)
{
    if (strcmp(value, "-") == 0)
        return;
    char *cursor = value;
    while (*cursor != '\0') {
        if (*count >= capacity)
            s61_die("catalog state category exceeds its bounded capacity");
        char *comma = strchr(cursor, ',');
        if (comma != NULL)
            *comma = '\0';
        char *equals = strchr(cursor, '=');
        if (equals == NULL || strchr(equals + 1, '=') != NULL)
            s61_die("catalog state must use ID=VALUE");
        *equals = '\0';
        unsigned identifier = s61_parse_catalog_uint(cursor, label, 65535U);
        unsigned state = s61_parse_catalog_uint(
            equals + 1, "state value", maximum);
        for (unsigned index = 0U; index < *count; ++index) {
            if (states[index].id == identifier)
                s61_die("catalog state category repeats an ID");
        }
        states[*count].id = (uint16_t)identifier;
        states[*count].value = (uint16_t)state;
        ++*count;
        if (comma == NULL)
            break;
        cursor = comma + 1;
    }
}

static void s61_parse_catalog_flags(char *value,
                                    struct S61CatalogRow *row)
{
    struct S61ValueState states[S61_CATALOG_MAX_FLAGS] = {{0}};
    unsigned count = 0U;
    s61_parse_catalog_values(value, states, &count,
                             S61_CATALOG_MAX_FLAGS, 1U, "flag");
    for (unsigned index = 0U; index < count; ++index) {
        row->flags[index].flag = states[index].id;
        row->flags[index].value = states[index].value != 0U;
    }
    row->flag_count = count;
}

static struct S61CatalogInputStep s61_parse_catalog_input_step(char *token)
{
    struct S61CatalogInputStep step = {
        .token = token,
        .pressed = 2U,
        .released = 45U,
    };
    if (strcmp(token, "A") == 0 || strcmp(token, "ADVANCE_TEXT") == 0)
        step.key = WORLD_KEY_A;
    else if (strcmp(token, "B") == 0)
        step.key = WORLD_KEY_B;
    else if (strcmp(token, "UP") == 0)
        step.key = WORLD_KEY_UP;
    else if (strcmp(token, "DOWN") == 0)
        step.key = WORLD_KEY_DOWN;
    else if (strcmp(token, "LEFT") == 0)
        step.key = WORLD_KEY_LEFT;
    else if (strcmp(token, "RIGHT") == 0)
        step.key = WORLD_KEY_RIGHT;
    else if (strcmp(token, "START") == 0)
        step.key = S61_KEY_START;
    else if (strcmp(token, "SELECT") == 0)
        step.key = S61_KEY_SELECT;
    else if (strncmp(token, "WAIT_", 5U) == 0) {
        step.pressed = 0U;
        step.released = 0U;
        step.wait_frames = s61_parse_catalog_uint(
            token + 5U, "input wait frames", 3600U);
        if (step.wait_frames == 0U)
            s61_die("catalog WAIT_0 input step is invalid");
    } else if (s61_event_runtime_catalog_parse
               && (strcmp(token, "WALK_TO_ADJACENT") == 0
                   || strcmp(token, "FACE_REQUIRED_DIRECTION") == 0
                   || strcmp(token, "WALK_FROM_ADJACENT_ONTO_COORD") == 0
                   || strcmp(token, "WALK_ONTO_WARP") == 0
                   || strcmp(token, "WAIT_MAP_LOAD") == 0
                   || strcmp(token, "WALK_ACROSS_CONNECTION") == 0
                   || strcmp(token,
                             "ENGINE_PLAYER_TELEPORT_MAP_LOAD") == 0
                   || strcmp(token, "WAIT_FIRST_ROOT_HIT") == 0
                   || strcmp(token, "WALK_ONTO_COORD") == 0
                   || strcmp(token, "USE_ITEMFINDER") == 0)) {
        /* Physical trigger markers are consumed by the event dispatcher,
         * never translated into synthetic GBA keys here. */
        step.key = 0U;
        step.pressed = 0U;
        step.released = 0U;
    } else {
        s61_die("catalog input token is invalid");
    }
    return step;
}

static bool s61_control_fixture_ref(const char *value);

static enum S61PostBattleResumeKind
s61_parse_post_battle_resume_kind(const char *value)
{
    if (strcmp(value, "NONE") == 0)
        return S61_POST_BATTLE_NONE;
    if (strcmp(value, "STANDARD") == 0)
        return S61_POST_BATTLE_STANDARD;
    if (strcmp(value, "EXPLICIT") == 0)
        return S61_POST_BATTLE_EXPLICIT;
    if (strcmp(value, "NEXT_PC") == 0)
        return S61_POST_BATTLE_NEXT_PC;
    s61_die("catalog post-battle resume kind is invalid");
    return S61_POST_BATTLE_NONE;
}

static enum S61BattleKind s61_parse_battle_kind(const char *value)
{
    if (strcmp(value, "TRAINER") == 0)
        return S61_BATTLE_KIND_TRAINER;
    if (strcmp(value, "TRAINER_TOWER") == 0)
        return S61_BATTLE_KIND_TRAINER_TOWER;
    if (strcmp(value, "SCRIPTED_WILD") == 0)
        return S61_BATTLE_KIND_SCRIPTED_WILD;
    s61_die("catalog chained battle kind is invalid");
    return S61_BATTLE_KIND_TRAINER;
}

static void s61_parse_catalog_input_sequences(char *value,
                                              struct S61CatalogRow *row)
{
    if (strcmp(value, "-") == 0)
        return;
    char *sequence_cursor = value;
    while (*sequence_cursor != '\0') {
        if (row->input_sequence_count >= S61_CATALOG_MAX_INPUT_SEQUENCES)
            s61_die("catalog input sequence count exceeds bound");
        char *semicolon = strchr(sequence_cursor, ';');
        if (semicolon != NULL)
            *semicolon = '\0';
        char *first_at = strchr(sequence_cursor, '@');
        char *second_at = first_at == NULL ? NULL : strchr(first_at + 1, '@');
        char *third_at = second_at == NULL ? NULL : strchr(second_at + 1, '@');
        char *fourth_at = third_at == NULL ? NULL : strchr(third_at + 1, '@');
        char *fifth_at = fourth_at == NULL ? NULL : strchr(fourth_at + 1, '@');
        char *sixth_at = fifth_at == NULL ? NULL : strchr(fifth_at + 1, '@');
        char *seventh_at = sixth_at == NULL ? NULL : strchr(sixth_at + 1, '@');
        char *eighth_at = seventh_at == NULL ? NULL : strchr(seventh_at + 1, '@');
        if (first_at == NULL || second_at == NULL || third_at == NULL
            || fourth_at == NULL || fifth_at == NULL || sixth_at == NULL
            || seventh_at == NULL || eighth_at == NULL
            || strchr(eighth_at + 1, '@') != NULL)
            s61_die(
                "catalog input sequence must use "
                "ID@BRANCH@VISIBLE@SILENT_BASIS_SHA@STEPS@"
                "RESUME_KIND@RESUME_PC@POST_BATTLE_STEPS@"
                "CHAINED_BATTLES");
        *first_at = '\0';
        *second_at = '\0';
        *third_at = '\0';
        *fourth_at = '\0';
        *fifth_at = '\0';
        *sixth_at = '\0';
        *seventh_at = '\0';
        *eighth_at = '\0';
        struct S61CatalogInputSequence *sequence =
            &row->input_sequences[row->input_sequence_count];
        sequence->sequence_id = sequence_cursor;
        sequence->expected_branch_token = first_at + 1;
        if (!s61_catalog_identifier(sequence->sequence_id, false)
            || !s61_catalog_identifier(
                sequence->expected_branch_token, true))
            s61_die("catalog sequence/branch identifier is invalid");
        for (unsigned index = 0U; index < row->input_sequence_count; ++index) {
            if (strcmp(row->input_sequences[index].sequence_id,
                       sequence->sequence_id) == 0)
                s61_die("catalog input sequence ID repeats");
        }
        sequence->visible_text_expected = s61_parse_catalog_uint(
            second_at + 1, "visible_text_expected", 1U) != 0U;
        sequence->silent_basis_sha256 = third_at + 1;
        if ((sequence->visible_text_expected
                && strcmp(sequence->silent_basis_sha256, "-") != 0)
            || (!sequence->visible_text_expected
                && !s61_control_fixture_ref(
                    sequence->silent_basis_sha256)))
            s61_die("catalog visible/silent text basis contract differs");
        char *step_cursor = fourth_at + 1;
        while (*step_cursor != '\0') {
            if (sequence->step_count >= S61_CATALOG_MAX_INPUT_STEPS)
                s61_die("catalog input sequence step count exceeds bound");
            char *comma = strchr(step_cursor, ',');
            if (comma != NULL)
                *comma = '\0';
            sequence->steps[sequence->step_count++] =
                s61_parse_catalog_input_step(step_cursor);
            if (comma == NULL)
                break;
            step_cursor = comma + 1;
        }
        if (sequence->step_count == 0U
            || (!s61_event_runtime_catalog_parse
                && (sequence->steps[0].key != WORLD_KEY_A
                    || sequence->steps[0].wait_frames != 0U)))
            s61_die("catalog sequence must begin with ordinary interaction A");
        sequence->post_battle_resume_kind =
            s61_parse_post_battle_resume_kind(fifth_at + 1);
        const char *resume_pc = sixth_at + 1;
        if (sequence->post_battle_resume_kind == S61_POST_BATTLE_EXPLICIT
            || sequence->post_battle_resume_kind == S61_POST_BATTLE_NEXT_PC) {
            sequence->post_battle_resume_pc = s61_parse_catalog_uint(
                resume_pc, "post-battle resume PC", 0x09FFFFFFU);
            if (sequence->post_battle_resume_pc < 0x08000000U)
                s61_die("catalog post-battle resume PC is outside ROM");
        } else if (strcmp(resume_pc, "-") != 0) {
            s61_die("catalog NONE/STANDARD post-battle resume PC must be dash");
        }
        char *post_step_cursor = seventh_at + 1;
        if (strcmp(post_step_cursor, "-") != 0) {
            while (*post_step_cursor != '\0') {
                if (sequence->post_battle_step_count
                        >= S61_CATALOG_MAX_INPUT_STEPS)
                    s61_die("catalog post-battle step count exceeds bound");
                char *comma = strchr(post_step_cursor, ',');
                if (comma != NULL)
                    *comma = '\0';
                struct S61CatalogInputStep step =
                    s61_parse_catalog_input_step(post_step_cursor);
                if (step.key == 0U && step.wait_frames == 0U)
                    s61_die("catalog post-battle physical marker is invalid");
                sequence->post_battle_steps[
                    sequence->post_battle_step_count++] = step;
                if (comma == NULL)
                    break;
                post_step_cursor = comma + 1;
            }
        }
        char *battle_cursor = eighth_at + 1;
        if (strcmp(battle_cursor, "-") != 0) {
            while (*battle_cursor != '\0') {
                if (sequence->chained_battle_count
                        >= S61_CATALOG_MAX_CHAINED_BATTLES)
                    s61_die("catalog chained battle count exceeds bound");
                char *comma = strchr(battle_cursor, ',');
                if (comma != NULL)
                    *comma = '\0';
                char *first_pipe = strchr(battle_cursor, '|');
                char *second_pipe = first_pipe == NULL ? NULL
                    : strchr(first_pipe + 1, '|');
                char *third_pipe = second_pipe == NULL ? NULL
                    : strchr(second_pipe + 1, '|');
                char *fourth_pipe = third_pipe == NULL ? NULL
                    : strchr(third_pipe + 1, '|');
                char *fifth_pipe = fourth_pipe == NULL ? NULL
                    : strchr(fourth_pipe + 1, '|');
                if (first_pipe == NULL || second_pipe == NULL
                    || third_pipe == NULL || fourth_pipe == NULL
                    || fifth_pipe == NULL
                    || strchr(fifth_pipe + 1, '|') != NULL)
                    s61_die("catalog chained battle must use six fields");
                *first_pipe = '\0';
                *second_pipe = '\0';
                *third_pipe = '\0';
                *fourth_pipe = '\0';
                *fifth_pipe = '\0';
                struct S61CatalogChainedBattle *battle =
                    &sequence->chained_battles[
                        sequence->chained_battle_count];
                battle->phase_index = s61_parse_catalog_uint(
                    battle_cursor, "chained battle phase", 32U);
                if (battle->phase_index
                        != sequence->chained_battle_count + 2U)
                    s61_die("catalog chained battle phase is not ordered");
                battle->battle_kind = s61_parse_battle_kind(first_pipe + 1);
                const char *trainer_id = second_pipe + 1;
                if (strcmp(trainer_id, "-") != 0) {
                    battle->trainer_id_expected = true;
                    battle->trainer_id = (uint16_t)s61_parse_catalog_uint(
                        trainer_id, "chained battle trainer ID", 0x2FFU);
                }
                battle->source_start_instruction_address =
                    s61_parse_catalog_uint(
                        third_pipe + 1, "chained battle source instruction",
                        0x09FFFFFFU);
                if (battle->source_start_instruction_address < 0x08000000U)
                    s61_die("chained battle source instruction outside ROM");
                battle->resume_kind = s61_parse_post_battle_resume_kind(
                    fourth_pipe + 1);
                const char *battle_resume_pc = fifth_pipe + 1;
                if (battle->resume_kind == S61_POST_BATTLE_STANDARD) {
                    if (strcmp(battle_resume_pc, "-") != 0)
                        s61_die("chained STANDARD resume PC must be dash");
                } else {
                    battle->resume_pc = s61_parse_catalog_uint(
                        battle_resume_pc, "chained battle resume PC",
                        0x09FFFFFFU);
                    if (battle->resume_pc < 0x08000000U)
                        s61_die("chained battle resume PC outside ROM");
                }
                if ((battle->battle_kind == S61_BATTLE_KIND_TRAINER)
                        != battle->trainer_id_expected
                    || (battle->battle_kind == S61_BATTLE_KIND_TRAINER
                        && battle->resume_kind != S61_POST_BATTLE_STANDARD
                        && battle->resume_kind != S61_POST_BATTLE_EXPLICIT
                        && battle->resume_kind != S61_POST_BATTLE_NEXT_PC)
                    || (battle->battle_kind != S61_BATTLE_KIND_TRAINER
                        && battle->resume_kind != S61_POST_BATTLE_NEXT_PC))
                    s61_die("catalog chained battle kind/resume ABI differs");
                ++sequence->chained_battle_count;
                if (comma == NULL)
                    break;
                battle_cursor = comma + 1;
            }
        }
        bool battle_contract = sequence->post_battle_resume_kind
            != S61_POST_BATTLE_NONE;
        if (battle_contract != (row->terminal == S61_TERMINAL_BATTLE_START))
            s61_die("catalog post-battle contract/terminal differs");
        if ((sequence->post_battle_resume_kind == S61_POST_BATTLE_NONE
             || sequence->post_battle_resume_kind
                    == S61_POST_BATTLE_STANDARD)
            && sequence->post_battle_step_count != 0U)
            s61_die("catalog NONE/STANDARD post-battle steps must be empty");
        if ((!battle_contract && sequence->chained_battle_count != 0U)
            || (sequence->post_battle_resume_kind
                    == S61_POST_BATTLE_STANDARD
                && sequence->chained_battle_count != 0U))
            s61_die("catalog chained battle parent continuation differs");
        ++row->input_sequence_count;
        if (semicolon == NULL)
            break;
        sequence_cursor = semicolon + 1;
    }
}

static unsigned s61_split_control_fields(char *value, char separator,
                                         char **fields, unsigned capacity)
{
    unsigned count = 0U;
    char *cursor = value;
    for (;;) {
        if (count >= capacity)
            s61_die("catalog control field count exceeds bound");
        fields[count++] = cursor;
        char *next = strchr(cursor, separator);
        if (next == NULL)
            break;
        *next = '\0';
        cursor = next + 1;
    }
    return count;
}

static bool s61_control_fixture_ref(const char *value)
{
    if (strlen(value) != 64U)
        return false;
    for (const unsigned char *cursor = (const unsigned char *)value;
         *cursor != '\0'; ++cursor) {
        if (!isdigit(*cursor) && !(*cursor >= 'a' && *cursor <= 'f'))
            return false;
    }
    return true;
}

static bool s61_control_lower_hex(const char *value, size_t digits)
{
    if (strlen(value) != digits)
        return false;
    for (const unsigned char *cursor = (const unsigned char *)value;
         *cursor != '\0'; ++cursor)
        if (!isdigit(*cursor) && !(*cursor >= 'a' && *cursor <= 'f'))
            return false;
    return true;
}

static bool s61_control_decode_lower_hex(
    const char *value, uint8_t *raw, size_t size)
{
    if (!s61_control_lower_hex(value, size * 2U))
        return false;
    for (size_t index = 0U; index < size; ++index) {
        unsigned high = isdigit((unsigned char)value[index * 2U])
            ? (unsigned)(value[index * 2U] - '0')
            : (unsigned)(value[index * 2U] - 'a' + 10);
        unsigned low = isdigit((unsigned char)value[index * 2U + 1U])
            ? (unsigned)(value[index * 2U + 1U] - '0')
            : (unsigned)(value[index * 2U + 1U] - 'a' + 10);
        raw[index] = (uint8_t)((high << 4U) | low);
    }
    return true;
}

