        return S61_CONTROL_FLAG;
    if (strcmp(value, "ENGINE_SPECIAL_FLAG") == 0)
        return S61_CONTROL_ENGINE_SPECIAL_FLAG;
    if (strcmp(value, "VAR") == 0)
        return S61_CONTROL_VAR;
    if (strcmp(value, "TRAINER") == 0)
        return S61_CONTROL_TRAINER;
