static uint32_t s61_control_value(char *text_value, unsigned maximum,
                                  const char *label)
{
    return (uint32_t)s61_parse_catalog_uint(text_value, label, maximum);
}

static bool s61_control_scenario_id(const char *value)
{
    size_t length = strlen(value);
    if (length == 0U || length > 128U)
        return false;
    for (const unsigned char *cursor = (const unsigned char *)value;
         *cursor != '\0'; ++cursor) {
        if (!isalnum(*cursor) && *cursor != '_' && *cursor != '.'
            && *cursor != '-')
            return false;
    }
    return true;
}

static bool s61_rfu_session_registry_tuple(
    const struct S61ExternalControl *control)
{
    if ((control->id != 363U && control->id != 364U)
        || control->scenario_id == NULL || control->value_count != 6U)
        return false;
    uint32_t endpoints = control->values[0];
    uint32_t mode = control->values[1];
    uint32_t result_count = control->values[2];
    uint32_t first = control->values[3];
    uint32_t second = control->values[4];
    uint32_t fault = control->values[5];
    if (mode > 1U || result_count < 1U || result_count > 2U
        || (result_count == 1U && second != 65535U)
        || (result_count == 2U && first != 8U))
        return false;
    const char *suffix = NULL;
    if (result_count == 1U && first == 1U)
        suffix = "result1";
    else if (result_count == 1U && first == 5U)
        suffix = "result5";
    else if (result_count == 1U && first == 6U && control->id == 364U)
        suffix = "result6";
    else if (result_count == 2U && second == 1U)
        suffix = "retry-result1";
    else if (result_count == 2U && second == 5U)
        suffix = "retry-result5";
    else if (result_count == 2U && second == 6U && control->id == 364U)
        suffix = "retry-result6";
    if (suffix == NULL)
        return false;
    uint32_t expected_endpoints =
        result_count == 1U && first == 5U ? 1U : mode == 0U ? 2U : 3U;
    uint32_t expected_fault =
        result_count == 2U && second == 6U ? 3U
        : result_count == 2U ? 2U
        : first == 6U ? 1U : 0U;
    if (endpoints != expected_endpoints || fault != expected_fault)
        return false;
    char expected[128U];
    int length = snprintf(
        expected, sizeof(expected), "mode%" PRIu32 "-%s-%s", mode,
        control->id == 363U ? "leader" : "join", suffix);
    return length > 0 && (size_t)length < sizeof(expected)
        && strcmp(control->scenario_id, expected) == 0;
}

static bool s61_center_link_session_registry_tuple(
    const struct S61ExternalControl *control)
{
    if (control->kind != S61_CONTROL_CENTER_LINK_SESSION
        || (control->id != 363U && control->id != 364U)
        || control->scenario_id == NULL || control->activity == NULL
        || control->topology_policy == NULL || control->value_count != 8U)
        return false;
    uint32_t endpoints = control->values[0];
    uint32_t link_group = control->values[1];
    uint32_t result_count = control->values[2];
    uint32_t first = control->values[3];
    uint32_t second = control->values[4];
    uint32_t fault = control->values[5];
    uint32_t capacity_min = control->values[6];
    uint32_t capacity_max = control->values[7];
    const char *activity = NULL;
    uint32_t expected_min = 0U;
    uint32_t expected_max = 0U;
    switch (link_group) {
    case 0U:
        activity = "single-battle";
        expected_min = expected_max = 2U;
        break;
    case 1U:
        activity = "double-battle";
        expected_min = expected_max = 2U;
        break;
    case 2U:
        activity = "multi-battle";
        expected_min = expected_max = 4U;
        break;
    case 3U:
        activity = "trade";
        expected_min = expected_max = 2U;
        break;
    case 5U:
        activity = "berry-crush";
        expected_min = 2U;
        expected_max = 5U;
        break;
    default:
        return false;
    }
    if (capacity_min != expected_min || capacity_max != expected_max
        || strcmp(control->activity, activity) != 0
        || result_count < 1U || result_count > 2U
        || (result_count == 1U && second != 65535U)
        || (result_count == 2U && first != 8U))
        return false;
    const char *suffix = NULL;
    if (result_count == 1U && first == 1U)
        suffix = "result1";
    else if (result_count == 1U && first == 5U)
        suffix = "result5";
    else if (result_count == 1U && first == 6U && control->id == 364U)
        suffix = "result6";
    else if (result_count == 2U && second == 1U)
        suffix = "retry-result1";
    else if (result_count == 2U && second == 5U)
        suffix = "retry-result5";
    else if (result_count == 2U && second == 6U && control->id == 364U)
        suffix = "retry-result6";
    if (suffix == NULL)
        return false;
    uint32_t expected_endpoints = result_count == 1U && first == 5U
        ? 1U : expected_min;
    const char *expected_policy = result_count == 1U && first == 5U
        ? "LOCAL_CANCEL_BEFORE_DISCOVERY"
        : expected_min == expected_max
            ? "EXACT_SOURCE_CAPACITY"
            : "MINIMUM_SOURCE_VALID_REPRESENTATIVE";
    uint32_t expected_fault = result_count == 2U && second == 6U ? 3U
        : result_count == 2U ? 2U : first == 6U ? 1U : 0U;
    if (endpoints != expected_endpoints || fault != expected_fault
        || strcmp(control->topology_policy, expected_policy) != 0)
        return false;
    char expected[128U];
    int length = snprintf(
        expected, sizeof(expected), "group%" PRIu32 "-%s-%s",
        link_group, control->id == 363U ? "leader" : "join", suffix);
    return length > 0 && (size_t)length < sizeof(expected)
        && strcmp(control->scenario_id, expected) == 0;
}

static bool s61_link_session_registry_tuple(
    const struct S61ExternalControl *control)
{
    return control != NULL
        && (control->kind == S61_CONTROL_RFU_SESSION
            ? s61_rfu_session_registry_tuple(control)
            : s61_center_link_session_registry_tuple(control));
}

