static bool s61_gift_storage_scenario_box(const char *scenario_id,
                                          const char *prefix,
                                          unsigned *box)
{
    size_t prefix_size = strlen(prefix);
    if (strncmp(scenario_id, prefix, prefix_size) != 0
        || strlen(scenario_id) != prefix_size + 2U
        || !isdigit((unsigned char)scenario_id[prefix_size])
        || !isdigit((unsigned char)scenario_id[prefix_size + 1U]))
        return false;
    *box = (unsigned)(scenario_id[prefix_size] - '0') * 10U
        + (unsigned)(scenario_id[prefix_size + 1U] - '0');
    return *box < 14U;
}

static bool s61_gift_storage_transaction_registry_tuple(
    const struct S61ExternalControl *control)
{
    static const char player_name[] = "cebfcdceffffff";
    uint8_t generated_100[100U];
    uint8_t generated_80[80U];
    char generated_100_sha[65U];
    char generated_80_sha[65U];
    if (control->id != 0U || control->scenario_id == NULL
        || control->equivalence_class == NULL
        || control->fixture_refs[0] == NULL
        || control->party_sha256 == NULL || control->storage_sha256 == NULL
        || control->player_name_hex == NULL
        || control->generated_mon_100_raw_hex == NULL
        || control->generated_mon_80_raw_hex == NULL
        || control->generated_mon_100_sha256 == NULL
        || control->generated_mon_80_sha256 == NULL
        || control->value_count != 19U
        || !s61_control_fixture_ref(control->fixture_refs[0])
        || !s61_control_fixture_ref(control->party_sha256)
        || !s61_control_fixture_ref(control->storage_sha256)
        || strcmp(control->player_name_hex, player_name) != 0
        || !s61_control_decode_lower_hex(
               control->generated_mon_100_raw_hex,
               generated_100, sizeof(generated_100))
        || !s61_control_decode_lower_hex(
               control->generated_mon_80_raw_hex,
               generated_80, sizeof(generated_80))
        || memcmp(generated_100, generated_80, sizeof(generated_80)) != 0
        || generated_100[0] != 0xD0U || generated_100[1] != 0xFEU
        || generated_100[2] != 0x6CU || generated_100[3] != 0xE7U
        || generated_100[4] != 0x78U || generated_100[5] != 0x56U
        || generated_100[6] != 0x34U || generated_100[7] != 0x12U
        || generated_100[42U] != 4U
        || generated_100[69U] != control->values[16]
        || !s61_control_fixture_ref(control->generated_mon_100_sha256)
        || !s61_control_fixture_ref(control->generated_mon_80_sha256)
        || control->values[10] != 4U || control->values[11] != 30U
        || control->values[12]
            != S61_GIFT_STORAGE_TRANSACTION_RNG_SEED
        || control->values[13] != 0x1BF2782AU
        || control->values[14] != 0U
        || control->values[15]
            != S61_GIFT_STORAGE_TRANSACTION_PLAYER_TRAINER_ID
        || control->values[16] > 0xFFU
        || control->values[17] < 0x08000000U
        || control->values[17] >= 0x0A000000U
        || control->values[18] == 0U || control->values[18] > 416U)
        return false;
    for (unsigned index = 0U; index < ARRAY_LEN(
             control->pokedex_preimage_sha256); ++index)
        if (control->pokedex_preimage_sha256[index] == NULL
            || !s61_control_fixture_ref(
                control->pokedex_preimage_sha256[index]))
            return false;
    s61_effect_sha256(
        generated_100, sizeof(generated_100), generated_100_sha);
    s61_effect_sha256(
        generated_80, sizeof(generated_80), generated_80_sha);
    if (strcmp(generated_100_sha,
               control->generated_mon_100_sha256) != 0
        || strcmp(generated_80_sha,
                  control->generated_mon_80_sha256) != 0)
        return false;
    const uint32_t null_value = 65535U;
    if (strcmp(control->scenario_id, "party_space") == 0)
        return strcmp(control->equivalence_class, "PARTY_SPACE") == 0
            && control->values[0] == 5U
            && control->values[1] == 0U && control->values[2] == 0U
            && control->values[3] == 0U && control->values[4] == 0U
            && control->values[5] == null_value
            && control->values[6] == null_value
            && control->values[7] == null_value
            && control->values[8] == 0U && control->values[9] == 0U;
    if (strcmp(control->scenario_id, "storage_full") == 0)
        return strcmp(control->equivalence_class, "STORAGE_FULL") == 0
            && control->values[0] == 6U
            && control->values[1] == 0U && control->values[2] == 0U
            && control->values[3] == 0U && control->values[4] == 2U
            && control->values[5] == 0U
            && control->values[6] == null_value
            && control->values[7] == null_value
            && control->values[8] == 0U && control->values[9] == 0U;
    unsigned box = 0U;
    if (s61_gift_storage_scenario_box(
            control->scenario_id, "pc_current_box_", &box))
        return strcmp(control->equivalence_class, "PC_CURRENT_BOX") == 0
            && control->values[0] == 6U
            && control->values[1] == box && control->values[2] == box
            && control->values[3] == 0U && control->values[4] == 1U
            && control->values[5] == box && control->values[6] == box
            && control->values[7] == 0U && control->values[8] == box
            && control->values[9] == 0U;
    if (s61_gift_storage_scenario_box(
            control->scenario_id, "pc_next_box_", &box)) {
        uint32_t target = (box + 1U) % 14U;
        const char *expected_class = box == 13U
            ? "PC_NEXT_BOX_WRAP" : "PC_NEXT_BOX";
        return strcmp(control->equivalence_class, expected_class) == 0
            && control->values[0] == 6U
            && control->values[1] == box && control->values[2] == box
            && control->values[3] == 0U && control->values[4] == 1U
            && control->values[5] == box && control->values[6] == target
            && control->values[7] == 0U && control->values[8] == target
            && control->values[9] == 0U;
    }
    return false;
}

static bool s61_fossil_revival_scenario_tuple(
    const char *scenario_id, uint32_t revive_state, uint32_t which_fossil,
    uint8_t *prefix_class, uint8_t flags[S61_FOSSIL_REVIVAL_FLAG_COUNT],
    uint16_t items[S61_FOSSIL_REVIVAL_ITEM_COUNT])
{
    unsigned available = 0U;
    bool all_revived = false;
    if (strcmp(scenario_id, "idle_none") == 0) {
        available = 0U;
    } else if (strcmp(scenario_id, "idle_available_helix") == 0) {
        available = 1U;
    } else if (strcmp(scenario_id, "idle_available_dome") == 0) {
        available = 2U;
    } else if (strcmp(scenario_id, "idle_available_amber") == 0) {
        available = 4U;
    } else if (strcmp(
                   scenario_id, "idle_available_helix_amber") == 0) {
        available = 5U;
    } else if (strcmp(
                   scenario_id, "idle_available_dome_amber") == 0) {
        available = 6U;
    } else if (strcmp(scenario_id, "idle_all_revived") == 0) {
        available = 5U;
        all_revived = true;
    } else if (strcmp(scenario_id, "reviving_helix") == 0) {
        available = 1U;
    } else if (strcmp(scenario_id, "reviving_dome") == 0) {
        available = 2U;
    } else if (strcmp(scenario_id, "reviving_amber") == 0) {
        available = 4U;
    } else if (strcmp(scenario_id, "ready_helix") == 0) {
        available = 1U;
    } else if (strcmp(scenario_id, "ready_dome") == 0) {
        available = 2U;
    } else if (strcmp(scenario_id, "ready_amber") == 0) {
        available = 4U;
    } else {
        return false;
    }
    uint32_t expected_state = strncmp(scenario_id, "reviving_", 9U) == 0
        ? 1U : strncmp(scenario_id, "ready_", 6U) == 0 ? 2U : 0U;
    uint32_t expected_which = expected_state == 0U ? 0U
        : available == 1U ? 1U : available == 2U ? 2U : 3U;
    if (revive_state != expected_state || which_fossil != expected_which)
        return false;
    *prefix_class = all_revived ? 3U : expected_state == 0U ? 0U
        : expected_state == 1U ? 1U : 2U;
    /* Fixed sorted order: got Amber/Dome/Helix, revived Dome/Helix/Amber. */
    flags[0] = (available & 4U) != 0U;
    flags[1] = (available & 2U) != 0U;
    flags[2] = (available & 1U) != 0U;
    flags[3] = all_revived && (available & 2U) != 0U;
    flags[4] = all_revived && (available & 1U) != 0U;
    flags[5] = all_revived && (available & 4U) != 0U;
    /* Fixed sorted order: Amber, Helix, Dome. */
    items[0] = expected_state == 0U && !all_revived
        && (available & 4U) != 0U;
    items[1] = expected_state == 0U && !all_revived
        && (available & 1U) != 0U;
    items[2] = expected_state == 0U && !all_revived
        && (available & 2U) != 0U;
    return true;
}

static bool s61_fossil_revival_registry_tuple(
    const struct S61ExternalControl *control)
{
    uint8_t prefix_class = 0U;
    uint8_t flags[S61_FOSSIL_REVIVAL_FLAG_COUNT];
    uint16_t items[S61_FOSSIL_REVIVAL_ITEM_COUNT];
    return control->id == 0U && control->scenario_id != NULL
        && control->value_count == 2U
        && control->fixture_refs[0] != NULL
        && s61_control_fixture_ref(control->fixture_refs[0])
        && s61_fossil_revival_scenario_tuple(
            control->scenario_id, control->values[0], control->values[1],
            &prefix_class, flags, items);
}

static bool s61_ruin_seal_scenario_tuple(
    uint32_t root, const char *scenario_id, uint32_t *first_missing,
    uint32_t *all_seals, uint32_t *completed, uint32_t *seal_mask)
{
    bool object_root = root == S61_RUIN_SEAL_OBJECT_ROOT;
    if (!object_root && root != S61_RUIN_SEAL_COORD_ROOT)
        return false;
    if (strncmp(scenario_id, "missing_", 8U) == 0
        && strlen(scenario_id) == 10U
        && isdigit((unsigned char)scenario_id[8])
        && isdigit((unsigned char)scenario_id[9])) {
        unsigned missing = (unsigned)(scenario_id[8] - '0') * 10U
            + (unsigned)(scenario_id[9] - '0');
        if (missing >= S61_RUIN_SEAL_SEAL_FLAG_COUNT)
            return false;
        *first_missing = missing;
        *all_seals = 0U;
        *completed = object_root ? 0U : S61_RUIN_SEAL_NULL_U16;
        *seal_mask = missing == 0U ? 0U : (1U << missing) - 1U;
        return true;
    }
    *first_missing = S61_RUIN_SEAL_NULL_U16;
    *all_seals = 1U;
    *seal_mask = (1U << S61_RUIN_SEAL_SEAL_FLAG_COUNT) - 1U;
    if (object_root && strcmp(scenario_id, "all_seals_pending") == 0) {
        *completed = 0U;
        return true;
    }
    if (object_root && strcmp(scenario_id, "completed") == 0) {
        *completed = 1U;
        return true;
    }
    if (!object_root && strcmp(scenario_id, "all_seals") == 0) {
        *completed = S61_RUIN_SEAL_NULL_U16;
        return true;
    }
    return false;
}

