static uint8_t s61_gift_storage_equivalence_code(const char *value)
{
    if (strcmp(value, "PARTY_SPACE") == 0)
        return 0U;
    if (strcmp(value, "PC_CURRENT_BOX") == 0)
        return 1U;
    if (strcmp(value, "PC_NEXT_BOX") == 0)
        return 2U;
    if (strcmp(value, "PC_NEXT_BOX_WRAP") == 0)
        return 3U;
    if (strcmp(value, "STORAGE_FULL") == 0)
        return 4U;
    s61_die("catalog GIFT_STORAGE_TRANSACTION equivalence class differs");
    return UINT8_MAX;
}

static uint32_t s61_gift_storage_transaction_storage(struct mCore *core)
{
    uint32_t storage = read32(core, S61_POKEMON_STORAGE_PTR);
    if (storage < 0x02000000U
        || storage + S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE > 0x02040000U
        || (storage & 3U) != 0U)
        s61_die("catalog GIFT_STORAGE_TRANSACTION storage pointer is invalid");
    return storage;
}

static uint8_t *s61_load_gift_storage_transaction_fixture(
    const struct S61ExternalControl *control)
{
    static const uint8_t magic[8U] = {
        'S', '6', '1', 'G', 'S', 'T', '0', '1',
    };
    static const uint8_t player_name[
        S61_GIFT_STORAGE_TRANSACTION_PLAYER_NAME_SIZE] = {
            0xCEU, 0xBFU, 0xCDU, 0xCEU, 0xFFU, 0xFFU, 0xFFU,
        };
    uint8_t *raw = s61_load_control_fixture(
        control->fixture_refs[0], S61_GIFT_STORAGE_TRANSACTION_FIXTURE_SIZE);
    uint8_t expected_scenario[S61_GIFT_STORAGE_TRANSACTION_SCENARIO_SIZE] = {0};
    size_t scenario_size = strlen(control->scenario_id);
    if (scenario_size >= sizeof(expected_scenario)) {
        free(raw);
        s61_die("catalog GIFT_STORAGE_TRANSACTION scenario exceeds binary ABI");
    }
    memcpy(expected_scenario, control->scenario_id, scenario_size);
    const uint8_t *party = raw + S61_GIFT_STORAGE_TRANSACTION_HEADER_SIZE;
    const uint8_t *storage = party + S61_GIFT_STORAGE_TRANSACTION_PARTY_SIZE;
    const uint8_t *pokedex =
        storage + S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE;
    char party_sha[65U];
    char storage_sha[65U];
    char pokedex_sha[S61_GIFT_STORAGE_TRANSACTION_POKEDEX_OWNER_COUNT][65U];
    s61_effect_sha256(
        party, S61_GIFT_STORAGE_TRANSACTION_PARTY_SIZE, party_sha);
    s61_effect_sha256(
        storage, S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE, storage_sha);
    for (unsigned index = 0U;
         index < S61_GIFT_STORAGE_TRANSACTION_POKEDEX_OWNER_COUNT; ++index)
        s61_effect_sha256(
            pokedex + index * S61_POKEDEX_BITMAP_SIZE,
            S61_POKEDEX_BITMAP_SIZE, pokedex_sha[index]);
    bool header_reserved_zero = true;
    for (unsigned index = S61_GIFT_STORAGE_TRANSACTION_HEADER_RESERVED_OFFSET;
         index < S61_GIFT_STORAGE_TRANSACTION_HEADER_SIZE; ++index)
        header_reserved_zero = header_reserved_zero && raw[index] == 0U;
    bool pokedex_zero = true;
    for (unsigned index = 0U;
         index < S61_GIFT_STORAGE_TRANSACTION_POKEDEX_OWNER_COUNT
                    * S61_POKEDEX_BITMAP_SIZE; ++index)
        pokedex_zero = pokedex_zero && pokedex[index] == 0U;
    if (memcmp(raw, magic, sizeof(magic)) != 0
        || !s61_sha_bytes_match(
               raw + S61_GIFT_STORAGE_TRANSACTION_LAYOUT_SHA_OFFSET,
               control->fixture_refs[0])
        || !s61_sha_bytes_match(
               raw + S61_GIFT_STORAGE_TRANSACTION_PARTY_SHA_OFFSET,
               control->party_sha256)
        || !s61_sha_bytes_match(
               raw + S61_GIFT_STORAGE_TRANSACTION_STORAGE_SHA_OFFSET,
               control->storage_sha256)
        || strcmp(party_sha, control->party_sha256) != 0
        || strcmp(storage_sha, control->storage_sha256) != 0
        || strcmp(pokedex_sha[0], control->pokedex_preimage_sha256[0]) != 0
        || strcmp(pokedex_sha[1], control->pokedex_preimage_sha256[1]) != 0
        || strcmp(pokedex_sha[2], control->pokedex_preimage_sha256[2]) != 0
        || strcmp(pokedex_sha[3], control->pokedex_preimage_sha256[3]) != 0
        || memcmp(
               raw + S61_GIFT_STORAGE_TRANSACTION_SCENARIO_OFFSET,
               expected_scenario, sizeof(expected_scenario)) != 0
        || raw[S61_GIFT_STORAGE_TRANSACTION_CLASS_OFFSET]
            != s61_gift_storage_equivalence_code(control->equivalence_class)
        || raw[S61_GIFT_STORAGE_TRANSACTION_PARTY_COUNT_OFFSET]
            != control->values[0]
        || raw[S61_GIFT_STORAGE_TRANSACTION_CURRENT_BOX_OFFSET]
            != control->values[1]
        || raw[S61_GIFT_STORAGE_TRANSACTION_SHOWN_FULL_BEFORE_OFFSET]
            != control->values[3]
        || raw[S61_GIFT_STORAGE_TRANSACTION_EXPECTED_RESULT_OFFSET]
            != control->values[4]
        || raw[S61_GIFT_STORAGE_TRANSACTION_SHOWN_FULL_AFTER_OFFSET]
            != control->values[9]
        || raw[S61_GIFT_STORAGE_TRANSACTION_SYNCHRONIZE_OFFSET] != 0U
        || raw[S61_GIFT_STORAGE_TRANSACTION_CUSTOM_FLAGS_OFFSET] != 0U
        || raw[S61_GIFT_STORAGE_TRANSACTION_SHINY_CHARM_OFFSET] != 0U
        || raw[S61_GIFT_STORAGE_TRANSACTION_FISHING_STREAK_OFFSET] != 0U
        || raw[S61_GIFT_STORAGE_TRANSACTION_PLAYER_GENDER_OFFSET] != 0U
        || raw[S61_GIFT_STORAGE_TRANSACTION_MAP_SECTION_OFFSET]
            != S61_GIFT_STORAGE_TRANSACTION_SWEEP_MAP_SECTION
        || s61_control_le16(
               raw + S61_GIFT_STORAGE_TRANSACTION_VAR_BEFORE_OFFSET)
            != control->values[2]
        || s61_control_le16(
               raw + S61_GIFT_STORAGE_TRANSACTION_ORIGINAL_BOX_OFFSET)
            != control->values[5]
        || s61_control_le16(
               raw + S61_GIFT_STORAGE_TRANSACTION_MON_BOX_ID_OFFSET)
            != control->values[6]
        || s61_control_le16(
               raw + S61_GIFT_STORAGE_TRANSACTION_MON_BOX_POS_OFFSET)
            != control->values[7]
        || s61_control_le16(
               raw + S61_GIFT_STORAGE_TRANSACTION_VAR_AFTER_OFFSET)
            != control->values[8]
        || s61_control_le16(
               raw + S61_GIFT_STORAGE_TRANSACTION_MON_BOX_ID_PRE_OFFSET)
            != 65535U
        || s61_control_le16(
               raw + S61_GIFT_STORAGE_TRANSACTION_MON_BOX_POS_PRE_OFFSET)
            != 65535U
        || s61_control_le16(
               raw + S61_GIFT_STORAGE_TRANSACTION_RESERVED_OFFSET) != 0U
        || s61_control_le32(
               raw + S61_GIFT_STORAGE_TRANSACTION_RNG_OFFSET)
            != S61_GIFT_STORAGE_TRANSACTION_RNG_SEED
        || s61_control_le32(
               raw + S61_GIFT_STORAGE_TRANSACTION_TRAINER_ID_OFFSET)
            != S61_GIFT_STORAGE_TRANSACTION_PLAYER_TRAINER_ID
        || s61_control_le32(
               raw + S61_GIFT_STORAGE_TRANSACTION_MAP_ROOT_OFFSET)
            != S61_GIFT_STORAGE_TRANSACTION_SWEEP_MAP_ROOT
        || control->values[16]
            != S61_GIFT_STORAGE_TRANSACTION_SWEEP_MAP_SECTION
        || control->values[17]
            != S61_GIFT_STORAGE_TRANSACTION_SWEEP_MAP_HEADER
        || memcmp(
               raw + S61_GIFT_STORAGE_TRANSACTION_PLAYER_NAME_OFFSET,
               player_name, sizeof(player_name)) != 0
        || !header_reserved_zero || !pokedex_zero
        || storage[0] != control->values[1]) {
        free(raw);
        s61_die("catalog GIFT_STORAGE_TRANSACTION binary/hash/field differs");
    }
    return raw;
}

static void __attribute__((unused)) s61_verify_gift_storage_transaction_fixture(
    struct mCore *core, const struct S61ExternalControl *control)
{
    uint8_t *raw = s61_load_gift_storage_transaction_fixture(control);
    const uint8_t *party = raw + S61_GIFT_STORAGE_TRANSACTION_HEADER_SIZE;
    const uint8_t *storage_image =
        party + S61_GIFT_STORAGE_TRANSACTION_PARTY_SIZE;
    const uint8_t *pokedex =
        storage_image + S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE;
    uint32_t storage = s61_gift_storage_transaction_storage(core);
    uint32_t save1 = s61_catalog_save1(core);
    uint32_t save2 = s61_catalog_save2(core);
    uint8_t physical_map_header[0x1CU];
    s61_read_core_range(
        core, S61_GIFT_STORAGE_TRANSACTION_SWEEP_MAP_HEADER,
        physical_map_header, sizeof(physical_map_header));
    uint8_t raw_flag = read8(core, save1 + 0x0FE8U);
    bool exact = read8(core, BOOTSTRAP_PLAYER_COUNT) == control->values[0]
        && s61_core_range_equals(
            core, BOOTSTRAP_PLAYER_PARTY, party,
            S61_GIFT_STORAGE_TRANSACTION_PARTY_SIZE,
            "catalog GIFT_STORAGE_TRANSACTION party")
        && s61_core_range_equals(
            core, storage, storage_image,
            S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE,
            "catalog GIFT_STORAGE_TRANSACTION storage")
        && s61_call_synced(
            core, WORLD_STORAGE_GET_CURRENT_BOX, 0U, 0U, 0U, 0U)
            == control->values[1]
        && s61_call_synced(
            core, WORLD_VAR_GET, WORLD_VAR_PC_BOX_TO_SEND_MON, 0U, 0U, 0U)
            == control->values[2]
        && read16(core, save1 + S61_GIVEEGG_PC_BOX_VAR_OFFSET)
            == control->values[2]
        && (s61_flag(core, WORLD_FLAG_SHOWN_BOX_WAS_FULL_MESSAGE) != 0U)
            == (control->values[3] != 0U)
        && (((raw_flag >> 3U) & 1U) != 0U)
            == (control->values[3] != 0U)
        && s61_call_synced(
            core, WORLD_GET_PC_BOX_TO_SEND_MON, 0U, 0U, 0U, 0U)
            == control->values[2]
        && (s61_call_synced(
                core, WORLD_SHOULD_SHOW_BOX_WAS_FULL_MESSAGE,
                0U, 0U, 0U, 0U) != 0U)
            == (control->values[3] != 0U)
        && read16(core, WORLD_SPECIAL_MON_BOX_ID) == 65535U
        && read16(core, WORLD_SPECIAL_MON_BOX_POS) == 65535U
        && read8(core, save2 + 8U) == 0U
        && ((uint32_t)read8(core, save2 + 0xAU)
            | ((uint32_t)read8(core, save2 + 0xBU) << 8U)
            | ((uint32_t)read8(core, save2 + 0xCU) << 16U)
            | ((uint32_t)read8(core, save2 + 0xDU) << 24U))
            == S61_GIFT_STORAGE_TRANSACTION_PLAYER_TRAINER_ID
        && s61_core_range_equals(
            core, WORLD_MAP_HEADER, physical_map_header,
            sizeof(physical_map_header),
            "catalog GIFT_STORAGE_TRANSACTION physical map header")
        && read8(core, WORLD_MAP_HEADER + 0x14U)
            == S61_GIFT_STORAGE_TRANSACTION_SWEEP_MAP_SECTION
        && s61_core_range_equals(
            core, save2, raw + S61_GIFT_STORAGE_TRANSACTION_PLAYER_NAME_OFFSET,
            S61_GIFT_STORAGE_TRANSACTION_PLAYER_NAME_SIZE,
            "catalog GIFT_STORAGE_TRANSACTION player name")
        && s61_core_range_equals(
            core, save2 + S61_POKEDEX_OWNED_OFFSET,
            pokedex, S61_POKEDEX_BITMAP_SIZE,
            "catalog GIFT_STORAGE_TRANSACTION pokedex owned")
        && s61_core_range_equals(
            core, save2 + S61_POKEDEX_SEEN_OFFSET,
            pokedex + S61_POKEDEX_BITMAP_SIZE, S61_POKEDEX_BITMAP_SIZE,
            "catalog GIFT_STORAGE_TRANSACTION pokedex seen")
        && s61_core_range_equals(
            core, save1 + S61_POKEDEX_SEEN1_OFFSET,
            pokedex + 2U * S61_POKEDEX_BITMAP_SIZE,
            S61_POKEDEX_BITMAP_SIZE,
            "catalog GIFT_STORAGE_TRANSACTION pokedex seen1")
        && s61_core_range_equals(
            core, save1 + S61_POKEDEX_SEEN2_OFFSET,
            pokedex + 3U * S61_POKEDEX_BITMAP_SIZE,
            S61_POKEDEX_BITMAP_SIZE,
            "catalog GIFT_STORAGE_TRANSACTION pokedex seen2");
    free(raw);
    if (!exact) {
        fprintf(stderr,
                "GIFT_STORAGE apply diagnostic count=%u/%" PRIu32
                " current=%" PRIu32 "/%" PRIu32
                " var=%" PRIu32 "/%u/%" PRIu32
                " flag=%u/%u/%" PRIu32
                " latches=%u/%u rng=%08" PRIX32
                " gender=%u tid=%08" PRIX32 " section=%u\n",
                read8(core, BOOTSTRAP_PLAYER_COUNT), control->values[0],
                s61_call_synced(
                    core, WORLD_STORAGE_GET_CURRENT_BOX, 0U, 0U, 0U, 0U),
                control->values[1],
                s61_call_synced(
                    core, WORLD_VAR_GET, WORLD_VAR_PC_BOX_TO_SEND_MON,
                    0U, 0U, 0U),
                read16(core, save1 + S61_GIVEEGG_PC_BOX_VAR_OFFSET),
                s61_call_synced(
                    core, WORLD_GET_PC_BOX_TO_SEND_MON, 0U, 0U, 0U, 0U),
                s61_flag(core, WORLD_FLAG_SHOWN_BOX_WAS_FULL_MESSAGE) != 0U,
                ((read8(core, save1 + 0x0FE8U) >> 3U) & 1U) != 0U,
                s61_call_synced(
                    core, WORLD_SHOULD_SHOW_BOX_WAS_FULL_MESSAGE,
                    0U, 0U, 0U, 0U),
                read16(core, WORLD_SPECIAL_MON_BOX_ID),
                read16(core, WORLD_SPECIAL_MON_BOX_POS),
                read32(core, WORLD_RNG_VALUE), read8(core, save2 + 8U),
                (uint32_t)read8(core, save2 + 0xAU)
                    | ((uint32_t)read8(core, save2 + 0xBU) << 8U)
                    | ((uint32_t)read8(core, save2 + 0xCU) << 16U)
                    | ((uint32_t)read8(core, save2 + 0xDU) << 24U),
                read8(core, WORLD_MAP_HEADER + 0x14U));
        s61_die("catalog GIFT_STORAGE_TRANSACTION apply/readback differs");
    }
}

static void __attribute__((unused)) s61_apply_gift_storage_transaction_fixture(
    struct mCore *core, const struct S61ExternalControl *control)
{
    uint8_t *raw = s61_load_gift_storage_transaction_fixture(control);
    const uint8_t *party = raw + S61_GIFT_STORAGE_TRANSACTION_HEADER_SIZE;
    const uint8_t *storage_image =
        party + S61_GIFT_STORAGE_TRANSACTION_PARTY_SIZE;
    const uint8_t *pokedex =
        storage_image + S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE;
    uint32_t storage = s61_gift_storage_transaction_storage(core);
    uint32_t save1 = s61_catalog_save1(core);
    uint32_t save2 = s61_catalog_save2(core);
    for (unsigned index = 0U;
         index < S61_GIFT_STORAGE_TRANSACTION_PARTY_SIZE; ++index)
        write8(core, BOOTSTRAP_PLAYER_PARTY + index, party[index]);
    write8(core, BOOTSTRAP_PLAYER_COUNT, (uint8_t)control->values[0]);
    for (unsigned index = 0U;
         index < S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE; ++index)
        write8(core, storage + index, storage_image[index]);
    (void)s61_call_synced(
        core, WORLD_STORAGE_SET_CURRENT_BOX, control->values[1], 0U, 0U, 0U);
    (void)s61_call_synced(
        core, WORLD_VAR_SET, WORLD_VAR_PC_BOX_TO_SEND_MON,
        control->values[2], 0U, 0U);
    if (control->values[3] != 0U)
        (void)s61_call_synced(
            core, WORLD_FLAG_SET, WORLD_FLAG_SHOWN_BOX_WAS_FULL_MESSAGE,
            0U, 0U, 0U);
    else
        (void)s61_call_synced(
            core, WORLD_FLAG_CLEAR, WORLD_FLAG_SHOWN_BOX_WAS_FULL_MESSAGE,
            0U, 0U, 0U);
    (void)s61_call_synced(
        core, WORLD_SET_PC_BOX_TO_SEND_MON, control->values[2], 0U, 0U, 0U);
    for (unsigned index = 0U;
         index < S61_GIFT_STORAGE_TRANSACTION_PLAYER_NAME_SIZE; ++index)
        write8(
            core, save2 + index,
            raw[S61_GIFT_STORAGE_TRANSACTION_PLAYER_NAME_OFFSET + index]);
    write8(core, save2 + 8U, 0U);
    write32_bytes(
        core, save2 + 0xAU,
        S61_GIFT_STORAGE_TRANSACTION_PLAYER_TRAINER_ID);
    /* The map section is not a fixture field to manufacture in RAM.  The
     * dedicated sweep boots physical OBJECT:010/015:002 and the complete
     * copied MapHeader is checked against its final-ROM owner above. */
    for (unsigned index = 0U; index < S61_POKEDEX_BITMAP_SIZE; ++index) {
        write8(core, save2 + S61_POKEDEX_OWNED_OFFSET + index,
               pokedex[index]);
        write8(core, save2 + S61_POKEDEX_SEEN_OFFSET + index,
               pokedex[S61_POKEDEX_BITMAP_SIZE + index]);
        write8(core, save1 + S61_POKEDEX_SEEN1_OFFSET + index,
               pokedex[2U * S61_POKEDEX_BITMAP_SIZE + index]);
        write8(core, save1 + S61_POKEDEX_SEEN2_OFFSET + index,
               pokedex[3U * S61_POKEDEX_BITMAP_SIZE + index]);
    }
    write16(core, WORLD_SPECIAL_MON_BOX_ID, 65535U);
    write16(core, WORLD_SPECIAL_MON_BOX_POS, 65535U);
    free(raw);
    /* VAR_RESULT is exclusively owned by the real opcode 0x79 producer. */
    s61_verify_gift_storage_transaction_fixture(core, control);
    /* API readback above may advance the overworld scheduler and therefore
     * the global RNG.  Seed the fixed producer preimage only after every
     * synchronized getter has completed, then read it back without another
     * scheduler boundary. */
    write32_bytes(
        core, WORLD_RNG_VALUE, S61_GIFT_STORAGE_TRANSACTION_RNG_SEED);
    if (read32(core, WORLD_RNG_VALUE)
            != S61_GIFT_STORAGE_TRANSACTION_RNG_SEED)
        s61_die("catalog GIFT_STORAGE_TRANSACTION RNG readback differs");
}

struct S61GiftStorageTransactionSnapshot {
    uint8_t *party;
    uint8_t *storage;
    uint8_t *save1;
    uint8_t *save2;
    uint8_t party_count;
    uint8_t current_box;
    uint16_t var_pc_box;
    uint16_t mon_box_id;
    uint16_t mon_box_pos;
    uint16_t special_result;
    uint32_t rng_state;
    bool shown_full;
};

static void __attribute__((unused)) s61_capture_gift_storage_transaction(
    struct mCore *core, struct S61GiftStorageTransactionSnapshot *snapshot)
{
    memset(snapshot, 0, sizeof(*snapshot));
    snapshot->party = malloc(S61_GIFT_STORAGE_TRANSACTION_PARTY_SIZE);
    snapshot->storage = malloc(S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE);
    snapshot->save1 = malloc(S61_SAVE_BLOCK1_SIZE);
    snapshot->save2 = malloc(S61_SAVE_BLOCK2_SIZE);
    if (snapshot->party == NULL || snapshot->storage == NULL
        || snapshot->save1 == NULL || snapshot->save2 == NULL)
        s61_die("GIFT_STORAGE_TRANSACTION snapshot allocation failed");
    uint32_t storage = s61_gift_storage_transaction_storage(core);
    uint32_t save1 = s61_catalog_save1(core);
    uint32_t save2 = s61_catalog_save2(core);
    s61_read_core_range(
        core, BOOTSTRAP_PLAYER_PARTY, snapshot->party,
        S61_GIFT_STORAGE_TRANSACTION_PARTY_SIZE);
    s61_read_core_range(
        core, storage, snapshot->storage,
        S61_GIFT_STORAGE_TRANSACTION_STORAGE_SIZE);
    s61_read_core_range(core, save1, snapshot->save1, S61_SAVE_BLOCK1_SIZE);
    s61_read_core_range(core, save2, snapshot->save2, S61_SAVE_BLOCK2_SIZE);
    snapshot->party_count = read8(core, BOOTSTRAP_PLAYER_COUNT);
    snapshot->current_box = snapshot->storage[0];
    snapshot->var_pc_box = read16(
        core, save1 + S61_GIVEEGG_PC_BOX_VAR_OFFSET);
    snapshot->shown_full =
        ((snapshot->save1[0x0FE8U] >> 3U) & 1U) != 0U;
    snapshot->mon_box_id = read16(core, WORLD_SPECIAL_MON_BOX_ID);
    snapshot->mon_box_pos = read16(core, WORLD_SPECIAL_MON_BOX_POS);
    snapshot->special_result = read16(core, WORLD_SPECIAL_RESULT);
    snapshot->rng_state = read32(core, WORLD_RNG_VALUE);
}

static void __attribute__((unused)) s61_free_gift_storage_transaction_snapshot(
    struct S61GiftStorageTransactionSnapshot *snapshot)
{
    free(snapshot->save2);
    free(snapshot->save1);
    free(snapshot->storage);
    free(snapshot->party);
    memset(snapshot, 0, sizeof(*snapshot));
}

static uint8_t *s61_load_fossil_revival_fixture(
    const struct S61ExternalControl *control)
{
    static const uint8_t magic[8U] = {
        'S', '6', '1', 'F', 'S', 'R', '0', '1',
    };
    static const char source_sha[] =
        "8afc38f502fd909a1bb220a919ac107ce8b39e98e29731d654f6edef749828ce";
    static const uint16_t flag_ids[S61_FOSSIL_REVIVAL_FLAG_COUNT] = {
        0x1870U, 0x187DU, 0x187EU, 0x18A5U, 0x18A6U, 0x18A7U,
    };
    static const uint16_t item_ids[S61_FOSSIL_REVIVAL_ITEM_COUNT] = {
        0x0245U, 0x0247U, 0x0248U,
    };
    uint8_t expected_scenario[S61_FOSSIL_REVIVAL_SCENARIO_SIZE] = {0};
    uint8_t expected_flags[S61_FOSSIL_REVIVAL_FLAG_COUNT];
    uint16_t expected_items[S61_FOSSIL_REVIVAL_ITEM_COUNT];
    uint8_t expected_prefix = 0U;
    size_t scenario_size = strlen(control->scenario_id);
    if (scenario_size >= sizeof(expected_scenario)
        || !s61_fossil_revival_scenario_tuple(
            control->scenario_id, control->values[0], control->values[1],
            &expected_prefix, expected_flags, expected_items))
        s61_die("catalog FOSSIL_REVIVAL scenario exceeds binary ABI");
    memcpy(expected_scenario, control->scenario_id, scenario_size);
    uint8_t *raw = s61_load_control_fixture(
        control->fixture_refs[0], S61_FOSSIL_REVIVAL_FIXTURE_SIZE);
    bool exact = memcmp(raw, magic, sizeof(magic)) == 0
        && s61_sha_bytes_match(
            raw + S61_FOSSIL_REVIVAL_LAYOUT_SHA_OFFSET,
            control->fixture_refs[0])
        && s61_sha_bytes_match(
            raw + S61_FOSSIL_REVIVAL_SOURCE_SHA_OFFSET, source_sha)
        && memcmp(
            raw + S61_FOSSIL_REVIVAL_SCENARIO_OFFSET,
            expected_scenario, sizeof(expected_scenario)) == 0
        && s61_control_le16(
            raw + S61_FOSSIL_REVIVAL_REVIVE_STATE_OFFSET)
                == control->values[0]
        && s61_control_le16(raw + S61_FOSSIL_REVIVAL_WHICH_OFFSET)
                == control->values[1]
        && raw[S61_FOSSIL_REVIVAL_PREFIX_CLASS_OFFSET] == expected_prefix;
    for (unsigned index = S61_FOSSIL_REVIVAL_RESERVED_OFFSET;
         index < S61_FOSSIL_REVIVAL_FLAGS_OFFSET; ++index)
        exact = exact && raw[index] == 0U;
    for (unsigned index = 0U;
         index < S61_FOSSIL_REVIVAL_FLAG_COUNT; ++index) {
        const uint8_t *row = raw + S61_FOSSIL_REVIVAL_FLAGS_OFFSET
            + index * 4U;
        exact = exact && s61_control_le16(row) == flag_ids[index]
            && row[2] == expected_flags[index] && row[3] == 0U;
    }
    for (unsigned index = 0U;
         index < S61_FOSSIL_REVIVAL_ITEM_COUNT; ++index) {
        const uint8_t *row = raw + S61_FOSSIL_REVIVAL_ITEMS_OFFSET
            + index * 4U;
        exact = exact && s61_control_le16(row) == item_ids[index]
            && s61_control_le16(row + 2U) == expected_items[index];
    }
    if (!exact) {
        free(raw);
        s61_die("catalog FOSSIL_REVIVAL binary/hash/field differs");
    }
    return raw;
}

static bool s61_fossil_item_count_exact(
    struct mCore *core, uint16_t item, uint16_t count)
{
    bool enough = count == 0U || s61_call_synced(
        core, BATTLE_CORE_CHECK_BAG_HAS_ITEM, item, count, 0U, 0U) != 0U;
    bool too_many = s61_call_synced(
        core, BATTLE_CORE_CHECK_BAG_HAS_ITEM,
        item, (uint32_t)count + 1U, 0U, 0U) != 0U;
    return enough && !too_many;
}

static void s61_verify_fossil_revival_fixture(
    struct mCore *core, const struct S61ExternalControl *control)
{
    uint8_t *raw = s61_load_fossil_revival_fixture(control);
    bool exact = s61_call_synced(
            core, WORLD_VAR_GET, 0x5177U, 0U, 0U, 0U)
            == control->values[0]
        && s61_call_synced(core, WORLD_VAR_GET, 0x5176U, 0U, 0U, 0U)
            == control->values[1];
    for (unsigned index = 0U;
         index < S61_FOSSIL_REVIVAL_FLAG_COUNT; ++index) {
        const uint8_t *row = raw + S61_FOSSIL_REVIVAL_FLAGS_OFFSET
            + index * 4U;
        exact = exact && ((s61_flag(core, s61_control_le16(row)) != 0U)
                          == (row[2] != 0U));
    }
    for (unsigned index = 0U;
         index < S61_FOSSIL_REVIVAL_ITEM_COUNT; ++index) {
        const uint8_t *row = raw + S61_FOSSIL_REVIVAL_ITEMS_OFFSET
            + index * 4U;
        exact = exact && s61_fossil_item_count_exact(
            core, s61_control_le16(row), s61_control_le16(row + 2U));
    }
    free(raw);
    if (!exact)
        s61_die("catalog FOSSIL_REVIVAL apply/readback differs");
}

static void s61_apply_fossil_revival_fixture(
    struct mCore *core, struct S61ExternalControl *control)
{
    uint8_t *raw = s61_load_fossil_revival_fixture(control);
    (void)s61_call_synced(
        core, WORLD_VAR_SET, 0x5177U, control->values[0], 0U, 0U);
    (void)s61_call_synced(
        core, WORLD_VAR_SET, 0x5176U, control->values[1], 0U, 0U);
    for (unsigned index = 0U;
         index < S61_FOSSIL_REVIVAL_FLAG_COUNT; ++index) {
        const uint8_t *row = raw + S61_FOSSIL_REVIVAL_FLAGS_OFFSET
            + index * 4U;
        (void)s61_call_synced(
            core, row[2] != 0U ? WORLD_FLAG_SET : WORLD_FLAG_CLEAR,
            s61_control_le16(row), 0U, 0U, 0U);
    }
    for (unsigned index = 0U;
         index < S61_FOSSIL_REVIVAL_ITEM_COUNT; ++index) {
        const uint8_t *row = raw + S61_FOSSIL_REVIVAL_ITEMS_OFFSET
            + index * 4U;
        uint16_t item = s61_control_le16(row);
        uint16_t count = s61_control_le16(row + 2U);
        unsigned removed = 0U;
        while (s61_item(core, item) != 0U) {
            if (++removed > 999U || s61_call_synced(
                    core, WORLD_REMOVE_BAG_ITEM, item, 1U, 0U, 0U) == 0U)
                s61_die("catalog FOSSIL_REVIVAL item clear did not converge");
        }
        if (count != 0U && s61_call_synced(
                core, BATTLE_CORE_ADD_BAG_ITEM,
                item, count, 0U, 0U) == 0U)
            s61_die("catalog FOSSIL_REVIVAL item apply failed");
    }
    free(raw);
    s61_verify_fossil_revival_fixture(core, control);
    control->deferred_applied = true;
    control->deferred_hit_count = 1U;
}

static uint8_t *s61_load_ruin_seal_fixture(
    struct mCore *core, const struct S61ExternalControl *control)
{
    static const uint8_t magic[8U] = {
        'S', '6', '1', 'R', 'S', 'P', '0', '1',
    };
    uint8_t expected_scenario[S61_RUIN_SEAL_SCENARIO_SIZE] = {0};
    uint32_t expected_first = 0U;
    uint32_t expected_all = 0U;
    uint32_t expected_completed = 0U;
    uint32_t expected_mask = 0U;
    size_t scenario_size = strlen(control->scenario_id);
    if (scenario_size >= sizeof(expected_scenario)
        || !s61_ruin_seal_scenario_tuple(
            control->values[0], control->scenario_id, &expected_first,
            &expected_all, &expected_completed, &expected_mask))
        s61_die("catalog RUIN_SEAL_PREFIX scenario exceeds binary ABI");
    memcpy(expected_scenario, control->scenario_id, scenario_size);
    bool object_root = control->values[0] == S61_RUIN_SEAL_OBJECT_ROOT;
    uint16_t expected_completion = object_root
        ? S61_RUIN_SEAL_COMPLETION_FLAG : S61_RUIN_SEAL_NULL_U16;
    uint16_t expected_row_count = object_root
        ? S61_RUIN_SEAL_MAX_FLAG_COUNT : S61_RUIN_SEAL_SEAL_FLAG_COUNT;
    char actual_root_sha[65U];
    s61_sha256_core_range(
        core, control->values[6], control->values[7], actual_root_sha);
    uint8_t *raw = s61_load_control_fixture(
        control->fixture_refs[0], S61_RUIN_SEAL_FIXTURE_SIZE);
    bool exact = memcmp(raw, magic, sizeof(magic)) == 0
        && s61_sha_bytes_match(
            raw + S61_RUIN_SEAL_LAYOUT_SHA_OFFSET,
            control->fixture_refs[0])
        && s61_sha_bytes_match(
            raw + S61_RUIN_SEAL_ROOT_SHA_OFFSET,
            control->root_source_sha256)
        && strcmp(actual_root_sha, control->root_source_sha256) == 0
        && memcmp(
            raw + S61_RUIN_SEAL_SCENARIO_OFFSET,
            expected_scenario, sizeof(expected_scenario)) == 0
        && s61_control_le32(raw + S61_RUIN_SEAL_ROOT_OFFSET)
            == control->values[0]
        && s61_control_le32(raw + S61_RUIN_SEAL_BINDING_ADDRESS_OFFSET)
            == control->values[6]
        && s61_control_le32(raw + S61_RUIN_SEAL_BINDING_LENGTH_OFFSET)
            == control->values[7]
        && s61_control_le16(raw + S61_RUIN_SEAL_FIRST_MISSING_OFFSET)
            == expected_first
        && s61_control_le16(raw + S61_RUIN_SEAL_SEAL_COUNT_OFFSET)
            == S61_RUIN_SEAL_SEAL_FLAG_COUNT
        && s61_control_le16(raw + S61_RUIN_SEAL_COMPLETION_FLAG_OFFSET)
            == expected_completion
        && s61_control_le16(raw + S61_RUIN_SEAL_FLAG_ROW_COUNT_OFFSET)
            == expected_row_count
        && raw[S61_RUIN_SEAL_ALL_SEALS_OFFSET] == expected_all
        && raw[S61_RUIN_SEAL_COMPLETED_OFFSET]
            == (expected_completed == S61_RUIN_SEAL_NULL_U16
                ? 0xFFU : expected_completed)
        && raw[S61_RUIN_SEAL_CONTROL_ID_OFFSET] == control->id
        && raw[S61_RUIN_SEAL_RESERVED_OFFSET] == 0U;
    for (unsigned index = 0U;
         index < S61_RUIN_SEAL_MAX_FLAG_COUNT; ++index) {
        const uint8_t *row = raw + S61_RUIN_SEAL_FLAGS_OFFSET + index * 4U;
        uint16_t expected_id = index < S61_RUIN_SEAL_SEAL_FLAG_COUNT
            ? (uint16_t)(0x11CCU + index)
            : expected_completion;
        uint8_t expected_value = index < S61_RUIN_SEAL_SEAL_FLAG_COUNT
            ? (uint8_t)((expected_mask >> index) & 1U)
            : (uint8_t)(object_root && expected_completed != 0U);
        exact = exact && s61_control_le16(row) == expected_id
            && row[2] == expected_value && row[3] == 0U;
    }
    if (!exact) {
        free(raw);
        s61_die("catalog RUIN_SEAL_PREFIX binary/root/scenario differs");
    }
    return raw;
}

static void s61_verify_ruin_seal_fixture(
    struct mCore *core, const struct S61ExternalControl *control)
{
    uint8_t *raw = s61_load_ruin_seal_fixture(core, control);
    unsigned count = s61_control_le16(
        raw + S61_RUIN_SEAL_FLAG_ROW_COUNT_OFFSET);
    bool exact = count == (control->values[0] == S61_RUIN_SEAL_OBJECT_ROOT
        ? S61_RUIN_SEAL_MAX_FLAG_COUNT : S61_RUIN_SEAL_SEAL_FLAG_COUNT);
    for (unsigned index = 0U; index < count; ++index) {
        const uint8_t *row = raw + S61_RUIN_SEAL_FLAGS_OFFSET + index * 4U;
        exact = exact && ((s61_flag(core, s61_control_le16(row)) != 0U)
                          == (row[2] != 0U));
    }
    free(raw);
    if (!exact)
        s61_die("catalog RUIN_SEAL_PREFIX apply/readback differs");
}

static void s61_apply_ruin_seal_fixture(
    struct mCore *core, struct S61ExternalControl *control)
{
    uint8_t *raw = s61_load_ruin_seal_fixture(core, control);
    unsigned count = s61_control_le16(
        raw + S61_RUIN_SEAL_FLAG_ROW_COUNT_OFFSET);
    if (count > ARRAY_LEN(control->ruin_flag_readback)) {
        free(raw);
        s61_die("catalog RUIN_SEAL_PREFIX readback count exceeds bound");
    }
    for (unsigned index = 0U; index < count; ++index) {
        const uint8_t *row = raw + S61_RUIN_SEAL_FLAGS_OFFSET + index * 4U;
        (void)s61_call_synced(
            core, row[2] != 0U ? WORLD_FLAG_SET : WORLD_FLAG_CLEAR,
            s61_control_le16(row), 0U, 0U, 0U);
    }
    for (unsigned index = 0U; index < count; ++index) {
        const uint8_t *row = raw + S61_RUIN_SEAL_FLAGS_OFFSET + index * 4U;
        control->ruin_flag_readback[index] =
            s61_flag(core, s61_control_le16(row)) != 0U;
    }
    control->ruin_flag_readback_count = count;
    free(raw);
    s61_verify_ruin_seal_fixture(core, control);
    control->deferred_applied = true;
    control->deferred_hit_count = 1U;
}

static uint8_t *s61_load_facility_session_fixture(
    const struct S61ExternalControl *control)
{
    static const uint8_t magic[8U] = {
        'S', '6', '1', 'F', 'A', 'C', '0', '1',
    };
    size_t payload_size = control->values[14];
    size_t total_size = S61_FACILITY_SESSION_HEADER_SIZE + payload_size;
    uint8_t *raw = s61_load_control_fixture(
        control->fixture_refs[0], total_size);
    char payload_sha256[65];
    s61_effect_sha256(
        raw + S61_FACILITY_SESSION_HEADER_SIZE,
        payload_size, payload_sha256);
    unsigned family_code = strcmp(control->family, "mirage") == 0 ? 0U
        : strcmp(control->family, "factory") == 0 ? 1U : 2U;
    unsigned reception_code = strcmp(control->reception_branch, "-") == 0
        ? 0U : strcmp(control->reception_branch, "FACTORY") == 0 ? 1U : 2U;
    bool exact = memcmp(raw, magic, sizeof(magic)) == 0
        && s61_sha_bytes_match(
            raw + S61_FACILITY_SESSION_LAYOUT_SHA_OFFSET,
            control->fixture_refs[0])
        && strcmp(payload_sha256, control->fixture_refs[0]) == 0
        && s61_sha_bytes_match(
            raw + S61_FACILITY_SESSION_REGISTRY_SHA_OFFSET,
            control->facility_registry_sha256)
        && s61_sha_bytes_match(
            raw + S61_FACILITY_SESSION_TRACE_SHA_OFFSET,
            control->facility_trace_sha256)
        && s61_sha_bytes_match(
            raw + S61_FACILITY_SESSION_RESUME_SHA_OFFSET,
            control->facility_resume_sha256)
        && s61_sha_bytes_match(
            raw + S61_FACILITY_SESSION_FIELDS_SHA_OFFSET,
            control->facility_fields_sha256)
        && s61_sha_bytes_match(
            raw + S61_FACILITY_SESSION_SOURCE_SHA_OFFSET,
            control->facility_source_binding_sha256)
        && s61_sha_bytes_match(
            raw + S61_FACILITY_SESSION_INITIALIZATION_SHA_OFFSET,
            control->facility_initialization_sha256)
        && s61_control_le32(
            raw + S61_FACILITY_SESSION_PAYLOAD_SIZE_OFFSET) == payload_size
        && s61_control_le32(raw + S61_FACILITY_SESSION_ROOT_OFFSET)
            == control->values[0]
        && s61_control_le16(raw + S61_FACILITY_SESSION_ORDINAL_OFFSET)
            == control->values[1]
        && s61_control_le16(raw + S61_FACILITY_SESSION_TRACE_COUNT_OFFSET)
            == control->values[2]
        && s61_control_le16(raw + S61_FACILITY_SESSION_RESUME_COUNT_OFFSET)
            == control->values[3]
        && raw[S61_FACILITY_SESSION_FAMILY_OFFSET] == family_code
        && raw[S61_FACILITY_SESSION_RECEPTION_OFFSET] == reception_code
        && raw[S61_FACILITY_SESSION_CONTROL_ID_OFFSET] == control->id
        && raw[S61_FACILITY_SESSION_REGION_COUNT_OFFSET]
            == control->values[4]
        && raw[S61_FACILITY_SESSION_SOURCE_COUNT_OFFSET]
            == control->values[11]
        && raw[S61_FACILITY_SESSION_EXPORT_COUNT_OFFSET]
            == control->values[12]
        && raw[S61_FACILITY_SESSION_PREPARE_WRAPPER_OFFSET]
            == control->values[13]
        && raw[S61_FACILITY_SESSION_RESERVED_OFFSET] == 0U
        && raw[S61_FACILITY_SESSION_RESERVED_OFFSET + 1U] == 0U
        && raw[S61_FACILITY_SESSION_RESERVED_OFFSET + 2U] == 0U
        && payload_size >= 2U
        && raw[S61_FACILITY_SESSION_HEADER_SIZE] == '{'
        && raw[total_size - 1U] == '\n';
    for (unsigned index = 0U; index < 6U; ++index)
        exact = exact && s61_control_le32(
            raw + S61_FACILITY_SESSION_REGIONS_OFFSET + index * 4U)
                == control->values[5U + index];
    if (!exact) {
        free(raw);
        s61_die("catalog FACILITY_SESSION binary/hash/manifest differs");
    }
    return raw;
}

static void s61_verify_facility_session_transport(
    const struct S61ExternalControl *control)
{
    /* Metadata identities: FactoryHighModesV2_PrepareBattleStage61Adapter
     * and Stage61Facility_TestSetFactoryPrepareFault.  Metadata/environment
     * values are even entry addresses; only a real call site Thumbizes one. */
    uint32_t adapter = (uint32_t)s61_uint_env(
        "S61_FACTORY_PREPARE_BATTLE_STAGE61_ADAPTER_SYMBOL",
        0U, UINT32_MAX);
    uint32_t arm = (uint32_t)s61_uint_env(
        "S61_FACILITY_TEST_SET_FACTORY_PREPARE_FAULT_SYMBOL",
        0U, UINT32_MAX);
    if (adapter < 0x09000000U || adapter >= 0x0A000000U
        || arm < 0x09000000U || arm >= 0x0A000000U
        || (adapter & 1U) != 0U || (arm & 1U) != 0U)
        s61_die("SOURCE_BOUND_PREPARE_FAULT_WRAPPER_REQUIRED");
    uint8_t *raw = s61_load_facility_session_fixture(control);
    free(raw);
}

