static void s61_facility_snapshot_hashes(
    struct mCore *core, struct S61FacilityExecutionEvidence *evidence,
    char region_sha256[3U][65U], char party_sha256[65U],
    char storage_sha256[65U])
{
    const struct S61ExternalControl *control = evidence->control;
    for (unsigned index = 0U; index < evidence->region_count; ++index) {
        uint32_t address = control->values[5U + index * 2U];
        uint32_t size = control->values[6U + index * 2U];
        if (address < 0x02000000U || address + size > 0x02040000U
            || size == 0U)
            s61_die("FACILITY_SESSION EWRAM region is outside RAM");
        s61_sha256_core_range(
            core, address, size, region_sha256[index]);
    }
    s61_sha256_core_range(
        core, BOOTSTRAP_PLAYER_PARTY, 600U, party_sha256);
    uint32_t storage = read32(core, S61_POKEMON_STORAGE_PTR);
    if (storage < 0x02000000U
        || storage + S61_POKEMON_STORAGE_SIZE > 0x02040000U
        || (storage & 3U) != 0U)
        s61_die("FACILITY_SESSION PokemonStorage pointer is invalid");
    s61_sha256_core_range(
        core, storage, S61_POKEMON_STORAGE_SIZE, storage_sha256);
}

static const char *s61_facility_expected_operation(
    const struct S61FacilityExecutionEvidence *evidence,
    char operation[40U], const char **record_end)
{
    const char *cursor = evidence->trace_cursor;
    if (cursor == NULL || evidence->trace_end == NULL
        || cursor >= evidence->trace_end || *cursor != '{')
        s61_die("FACILITY_SESSION expected trace cursor is not a record");
    const char *end = strchr(cursor, '}');
    const char *prefix = strstr(cursor, "\"operation\":\"");
    if (end == NULL || end >= evidence->trace_end
        || prefix == NULL || prefix >= end)
        s61_die("FACILITY_SESSION expected trace record is malformed");
    prefix += strlen("\"operation\":\"");
    const char *suffix = strchr(prefix, '"');
    size_t length = suffix == NULL ? 0U : (size_t)(suffix - prefix);
    if (suffix == NULL || suffix > end || length == 0U || length >= 40U)
        s61_die("FACILITY_SESSION expected operation is malformed");
    memcpy(operation, prefix, length);
    operation[length] = '\0';
    *record_end = end;
    return operation;
}

static const char *s61_facility_nullable_u16(
    uint16_t value, char buffer[16U])
{
    if (value == S61_FACILITY_SESSION_NULL_U16)
        return "null";
    (void)snprintf(buffer, 16U, "%u", (unsigned)value);
    return buffer;
}

static void s61_facility_observed_state(
    struct mCore *core, struct S61FacilityExecutionEvidence *evidence,
    struct S61FacilityNativeBoundary *boundary)
{
    uint32_t base;
    uint16_t phase;
    if (evidence->family == S61_FACILITY_RUNTIME_MIRAGE) {
        base = 0x0203EE00U;
        phase = read8(core, base + 0x3EU);
        boundary->status = read16(core, base + 0x1CU);
        boundary->active = read8(core, base + 0x28U) != 0U;
        const char *state = phase == 0U ? "IDLE"
            : phase == 1U ? "SELECTION" : phase == 2U ? "ACTIVE"
            : phase == 3U ? "PREPARED" : phase == 4U ? "BATTLE" : NULL;
        if (state == NULL)
            s61_die("FACILITY_SESSION Mirage phase is outside ABI");
        (void)snprintf(boundary->state, sizeof(boundary->state), "%s", state);
        bool battle_step = strcmp(boundary->operation,
                                  "CommitRound4Mechanic") == 0
            || strcmp(boundary->operation, "PrepareBattle") == 0
            || strcmp(boundary->operation, "FinalizeBattleCopy") == 0
            || strcmp(boundary->operation, "AfterBattle") == 0;
        if (battle_step) {
            boundary->battle_index = (uint16_t)(
                evidence->entry_round * 7U
                + evidence->entry_battle_in_round);
            boundary->round_index = evidence->entry_round;
            boundary->mechanic = evidence->entry_mechanic;
        } else if (strcmp(boundary->operation, "CommitSelection") == 0
                   && boundary->active) {
            boundary->mechanic = read8(core, base + 0x2BU);
        }
    } else if (evidence->family == S61_FACILITY_RUNTIME_FACTORY) {
        base = 0x0203F220U;
        phase = read8(core, base + 0x6AU);
        boundary->status = read16(core, base + 0x20U);
        boundary->active = read8(core, base + 0x62U) != 0U;
        const char *state = strcmp(
            boundary->operation, "FieldReception") == 0 ? "RECEPTION"
            : phase == 0U ? "IDLE" : phase == 2U ? "DRAFT"
            : phase == 3U ? "ACTIVE" : phase == 4U ? "BATTLE" : NULL;
        if (state == NULL)
            s61_die("FACILITY_SESSION Factory phase is outside ABI");
        (void)snprintf(boundary->state, sizeof(boundary->state), "%s", state);
    } else if (evidence->family == S61_FACILITY_RUNTIME_CODEX) {
        base = 0x0203FA00U;
        phase = read16(core, base + 0x10U);
        boundary->status = read16(core, base + 0x12U);
        boundary->active = read8(core, base + 0x14U) != 0U;
        boundary->completion_pending = read16(core, base + 0x1EU);
        boundary->reward_window = read8(core, 0x0203D800U + 0x14U);
        uint8_t reward_kind = read8(core, 0x0203D800U + 0x16U);
        if (reward_kind != 0U)
            boundary->reward_result_kind = reward_kind;
        const char *state = phase == 1U ? "IDLE"
            : phase == 4U ? "AWAITING_PLAYER_SELECTION"
            : phase == 9U ? "BATTLE_RESOLVING"
            : phase == 10U ? "RESULT" : NULL;
        if (state == NULL)
            s61_die("FACILITY_SESSION Codex phase is outside ABI");
        (void)snprintf(boundary->state, sizeof(boundary->state), "%s", state);
    } else {
        s61_die("FACILITY_SESSION family is outside runtime ABI");
    }
    boundary->phase = (uint8_t)phase;
    boundary->result = read16(core, WORLD_SPECIAL_RESULT);
}

static bool s61_facility_operation_is_non_native(const char *operation)
{
    return strcmp(operation, "ReceptionDecision") == 0
        || strcmp(operation, "DraftDecision") == 0
        || strcmp(operation, "RoundDecisionContinue") == 0
        || strcmp(operation, "RoundDecisionRetire") == 0
        || strcmp(operation, "RewardClose") == 0;
}

static bool s61_facility_instruction_is_native(
    const struct S61FacilityExecutionEvidence *evidence,
    uint32_t instruction_pc)
{
    for (unsigned index = 0U;
         index < evidence->native_entry_count; ++index) {
        if (s61_facility_native_specs[index].family == evidence->family
            && evidence->native_entries[index] == instruction_pc)
            return true;
    }
    return false;
}

static void s61_facility_compare_trace_record(
    struct S61FacilityExecutionEvidence *evidence,
    const struct S61FacilityNativeBoundary *boundary)
{
    char expected_operation[40U];
    const char *record_end = NULL;
    (void)s61_facility_expected_operation(
        evidence, expected_operation, &record_end);
    if (strcmp(expected_operation, boundary->operation) != 0)
        s61_die("FACILITY_SESSION native operation order differs");
    char battle[16U], completion[16U], mechanic[16U], reward_kind[16U];
    char reward_window[16U], round[16U];
    char observed[512U];
    int length = snprintf(
        observed, sizeof(observed),
        "{\"active\":%s,\"battle_index\":%s,"
        "\"completion_pending\":%s,\"mechanic\":%s,"
        "\"operation\":\"%s\",\"phase\":%u,\"result\":%u,"
        "\"reward_result_kind\":%s,\"reward_window\":%s,"
        "\"round_index\":%s,\"state\":\"%s\",\"status\":%u}",
        boundary->active ? "true" : "false",
        s61_facility_nullable_u16(boundary->battle_index, battle),
        s61_facility_nullable_u16(
            boundary->completion_pending, completion),
        s61_facility_nullable_u16(boundary->mechanic, mechanic),
        boundary->operation, boundary->phase, boundary->result,
        s61_facility_nullable_u16(
            boundary->reward_result_kind, reward_kind),
        s61_facility_nullable_u16(boundary->reward_window, reward_window),
        s61_facility_nullable_u16(boundary->round_index, round),
        boundary->state, boundary->status);
    size_t expected_length = (size_t)(record_end - evidence->trace_cursor + 1);
    if (length <= 0 || (size_t)length >= sizeof(observed)
        || (size_t)length != expected_length
        || memcmp(evidence->trace_cursor, observed, expected_length) != 0)
        s61_die("FACILITY_SESSION native state/result record differs");
    evidence->trace_cursor = record_end + 1;
    if (evidence->trace_cursor < evidence->trace_end
        && *evidence->trace_cursor == ',')
        ++evidence->trace_cursor;
}

static void s61_facility_consume_non_native(
    struct mCore *core, struct S61FacilityExecutionEvidence *evidence,
    uint32_t correlation_pc, enum S61FacilityBoundaryKind boundary_kind)
{
    if (evidence->trace_count >= S61_FACILITY_SESSION_MAX_TRACE)
        s61_die("FACILITY_SESSION decision trace buffer overflow");
    char operation[40U];
    const char *record_end = NULL;
    (void)s61_facility_expected_operation(evidence, operation, &record_end);
    if (!s61_facility_operation_is_non_native(operation))
        s61_die("FACILITY_SESSION expected decision record differs");
    struct S61FacilityNativeBoundary *boundary =
        &evidence->boundaries[evidence->trace_count];
    memset(boundary, 0, sizeof(*boundary));
    boundary->battle_index = S61_FACILITY_SESSION_NULL_U16;
    boundary->round_index = S61_FACILITY_SESSION_NULL_U16;
    boundary->mechanic = S61_FACILITY_SESSION_NULL_U16;
    boundary->completion_pending = S61_FACILITY_SESSION_NULL_U16;
    boundary->reward_window = S61_FACILITY_SESSION_NULL_U16;
    boundary->reward_result_kind = S61_FACILITY_SESSION_NULL_U16;
    boundary->boundary_kind = (uint8_t)boundary_kind;
    boundary->correlation_pc = correlation_pc;
    boundary->entry_instruction_ordinal = evidence->instruction_ordinal;
    boundary->return_instruction_ordinal = evidence->instruction_ordinal;
    (void)snprintf(
        boundary->operation, sizeof(boundary->operation), "%s", operation);
    s61_facility_snapshot_hashes(
        core, evidence, boundary->region_sha256_before,
        boundary->party_sha256_before, boundary->storage_sha256_before);
    s61_facility_observed_state(core, evidence, boundary);
    s61_facility_snapshot_hashes(
        core, evidence, boundary->region_sha256_after,
        boundary->party_sha256_after, boundary->storage_sha256_after);
    s61_facility_compare_trace_record(evidence, boundary);
    ++evidence->trace_count;
    ++evidence->non_native_boundary_count;
}

static void s61_attach_facility_execution(
    struct mCore *core, struct S61Capture *capture,
    struct S61ExternalControl *control)
{
    struct S61FacilityExecutionEvidence *evidence = &capture->facility;
    if (evidence->control != NULL || s61_active_facility_execution != NULL)
        s61_die("catalog has multiple FACILITY_SESSION controls per attempt");
    if (control->values[0] != capture->event_root_script_pointer
        || control->values[2] == 0U
        || control->values[2] > S61_FACILITY_SESSION_MAX_TRACE
        || control->values[4] == 0U
        || control->values[4] > S61_FACILITY_SESSION_MAX_REGIONS)
        s61_die("FACILITY_SESSION runtime root/trace/region tuple differs");
    evidence->control = control;
    evidence->root_capture = capture;
    evidence->family = strcmp(control->family, "mirage") == 0
        ? S61_FACILITY_RUNTIME_MIRAGE
        : strcmp(control->family, "factory") == 0
            ? S61_FACILITY_RUNTIME_FACTORY
            : strcmp(control->family, "codex") == 0
                ? S61_FACILITY_RUNTIME_CODEX : S61_FACILITY_RUNTIME_NONE;
    if (evidence->family == S61_FACILITY_RUNTIME_NONE)
        s61_die("FACILITY_SESSION runtime family differs");
    evidence->fixture_raw = s61_load_facility_session_fixture(control);
    size_t payload_size = control->values[14];
    uint8_t *terminated = realloc(
        evidence->fixture_raw,
        S61_FACILITY_SESSION_HEADER_SIZE + payload_size + 1U);
    if (terminated == NULL)
        s61_die("FACILITY_SESSION payload termination allocation failed");
    evidence->fixture_raw = terminated;
    char *payload = (char *)terminated + S61_FACILITY_SESSION_HEADER_SIZE;
    payload[payload_size] = '\0';
    const char *trace = strstr(payload, "\"trace\":[");
    if (trace == NULL || strstr(trace + 1U, "\"trace\":[") != NULL)
        s61_die("FACILITY_SESSION canonical trace member is not unique");
    trace += strlen("\"trace\":[");
    const char *trace_end = strstr(trace, "],\"trace_count\":");
    if (trace_end == NULL || trace_end <= trace)
        s61_die("FACILITY_SESSION canonical trace terminal is missing");
    evidence->trace_cursor = trace;
    evidence->trace_end = trace_end;
    evidence->trace_exact = true;
    evidence->attached_before_a = capture->event_root_script_pointer_hits == 0U;
    evidence->region_count = control->values[4];
    evidence->native_entry_count = ARRAY_LEN(s61_facility_native_specs);
    for (unsigned index = 0U;
         index < evidence->native_entry_count; ++index) {
        uint32_t entry = (uint32_t)s61_uint_env(
            s61_facility_native_specs[index].environment_name,
            0U, UINT32_MAX);
        if (entry < 0x09000000U || entry >= 0x0A000000U
            || (entry & 1U) != 0U)
            s61_die("FACILITY_SESSION native symbol binding differs");
        evidence->native_entries[index] = entry;
    }
    if (evidence->native_entries[12U] != (uint32_t)s61_uint_env(
            "S61_FACTORY_PREPARE_BATTLE_STAGE61_ADAPTER_SYMBOL",
            0U, UINT32_MAX))
        s61_die("FACILITY_SESSION PrepareBattle adapter alias differs");
    s61_facility_snapshot_hashes(
        core, evidence, evidence->initial_region_sha256,
        evidence->initial_party_sha256,
        evidence->initial_storage_sha256);
    s61_active_facility_execution = evidence;
}

static void s61_sample_facility_execution(
    struct mCore *core, struct S61Capture *capture,
    uint32_t instruction_pc)
{
    struct S61FacilityExecutionEvidence *evidence =
        s61_active_facility_execution;
    (void)capture;
    if (evidence == NULL || evidence->control == NULL)
        return;
    ++evidence->instruction_ordinal;
    if (evidence->call_active
        && instruction_pc == evidence->active_return_pc) {
        if (evidence->trace_count >= S61_FACILITY_SESSION_MAX_TRACE)
            s61_die("FACILITY_SESSION native trace buffer overflow");
        struct S61FacilityNativeBoundary *boundary =
            &evidence->boundaries[evidence->trace_count];
        boundary->return_instruction_ordinal =
            evidence->instruction_ordinal;
        s61_facility_observed_state(core, evidence, boundary);
        s61_facility_snapshot_hashes(
            core, evidence, boundary->region_sha256_after,
            boundary->party_sha256_after,
            boundary->storage_sha256_after);
        s61_facility_compare_trace_record(evidence, boundary);
        ++evidence->trace_count;
        ++evidence->native_boundary_count;
        evidence->call_active = false;
        evidence->active_operation = NULL;
        evidence->active_return_pc = 0U;
        if (evidence->trace_cursor == evidence->trace_end
            && boundary->active) {
            bool declared = evidence->family == S61_FACILITY_RUNTIME_FACTORY
                && ((strcmp(evidence->control->scenario_id,
                            "exchange_commit") == 0
                     && strcmp(boundary->operation,
                               "CommitExchange") == 0)
                    || (strcmp(evidence->control->scenario_id,
                               "exchange_skip") == 0
                        && strcmp(boundary->operation,
                                  "SkipExchange") == 0)
                    || (strcmp(evidence->control->scenario_id,
                               "round_continue") == 0
                        && strcmp(boundary->operation,
                                  "PrepareBattle") == 0));
            if (!declared)
                s61_die("FACILITY_SESSION undeclared active terminal");
            evidence->active_boundary_observed = true;
        }
        return;
    }
    if (evidence->trace_cursor == evidence->trace_end)
        return;
    char pending_operation[40U];
    const char *pending_end = NULL;
    (void)s61_facility_expected_operation(
        evidence, pending_operation, &pending_end);
    if (s61_facility_operation_is_non_native(pending_operation)) {
        const char *next = pending_end + 1U;
        if (next < evidence->trace_end && *next == ',')
            ++next;
        bool final_record = next == evidence->trace_end;
        if (s61_facility_instruction_is_native(evidence, instruction_pc)) {
            if (final_record)
                s61_die("FACILITY_SESSION terminal decision followed native");
            s61_facility_consume_non_native(
                core, evidence, instruction_pc,
                S61_FACILITY_BOUNDARY_DECISION_BEFORE_NATIVE);
        } else if (final_record && s61_field_terminal(core)) {
            s61_facility_consume_non_native(
                core, evidence, instruction_pc,
                S61_FACILITY_BOUNDARY_DECISION_AT_FIELD_RELEASE);
            return;
        } else {
            return;
        }
    }
    for (unsigned index = 0U;
         index < evidence->native_entry_count; ++index) {
        const struct S61FacilityNativeSpec *spec =
            &s61_facility_native_specs[index];
        if (spec->family != evidence->family
            || evidence->native_entries[index] != instruction_pc)
            continue;
        if (evidence->call_active)
            s61_die("FACILITY_SESSION nested lifecycle export observed");
        char expected_operation[40U];
        const char *record_end = NULL;
        (void)s61_facility_expected_operation(
            evidence, expected_operation, &record_end);
        if (strcmp(expected_operation, spec->operation) != 0)
            s61_die("FACILITY_SESSION native entry order differs");
        if (evidence->trace_count >= S61_FACILITY_SESSION_MAX_TRACE)
            s61_die("FACILITY_SESSION native trace buffer overflow");
        struct S61FacilityNativeBoundary *boundary =
            &evidence->boundaries[evidence->trace_count];
        memset(boundary, 0, sizeof(*boundary));
        boundary->boundary_kind =
            (uint8_t)S61_FACILITY_BOUNDARY_NATIVE_CALL_RETURN;
        boundary->battle_index = S61_FACILITY_SESSION_NULL_U16;
        boundary->round_index = S61_FACILITY_SESSION_NULL_U16;
        boundary->mechanic = S61_FACILITY_SESSION_NULL_U16;
        boundary->completion_pending = S61_FACILITY_SESSION_NULL_U16;
        boundary->reward_window = S61_FACILITY_SESSION_NULL_U16;
        boundary->reward_result_kind = S61_FACILITY_SESSION_NULL_U16;
        (void)snprintf(
            boundary->operation, sizeof(boundary->operation),
            "%s", spec->operation);
        boundary->entry_pc = instruction_pc;
        boundary->entry_instruction_ordinal =
            evidence->instruction_ordinal;
        boundary->return_pc =
            ((uint32_t)read_register(core, "lr")) & ~1U;
        if (boundary->return_pc < 0x08000000U
            || boundary->return_pc >= 0x0A000000U)
            s61_die("FACILITY_SESSION native LR return is outside ROM");
        if (evidence->trace_count == 0U) {
            const struct S61Capture *root_capture = evidence->root_capture;
            if (root_capture == NULL)
                s61_die("FACILITY_SESSION physical root capture is missing");
            evidence->root_instruction_ordinal =
                root_capture->event_first_root_ordinal;
            evidence->physical_root_before_first_native =
                root_capture->event_root_script_pointer_hits != 0U
                && root_capture->event_first_root_script_pointer
                    == evidence->control->values[0]
                && root_capture->event_first_root_ordinal
                    < boundary->entry_instruction_ordinal;
            if (!evidence->physical_root_before_first_native)
                s61_die("FACILITY_SESSION native entry preceded physical root");
        }
        if (evidence->family == S61_FACILITY_RUNTIME_MIRAGE) {
            evidence->entry_round = read8(core, 0x0203EE00U + 0x29U);
            evidence->entry_battle_in_round = read8(
                core, 0x0203EE00U + 0x2AU);
            evidence->entry_mechanic = read8(
                core, 0x0203EE00U + 0x2BU);
        }
        s61_facility_snapshot_hashes(
            core, evidence, boundary->region_sha256_before,
            boundary->party_sha256_before,
            boundary->storage_sha256_before);
        evidence->call_active = true;
        evidence->active_operation = spec->operation;
        evidence->active_return_pc = boundary->return_pc;
        return;
    }
}

static void s61_finalize_facility_execution(
    struct mCore *core, struct S61Capture *capture)
{
    struct S61FacilityExecutionEvidence *evidence = &capture->facility;
    if (evidence->control == NULL)
        return;
    if (evidence->call_active)
        s61_die("FACILITY_SESSION native call did not return");
    evidence->terminal_cursor_exact = evidence->trace_cursor
        == evidence->trace_end
        && evidence->trace_count == evidence->control->values[2];
    if (!evidence->terminal_cursor_exact
        || !evidence->physical_root_before_first_native
        || evidence->native_boundary_count
               + evidence->non_native_boundary_count != evidence->trace_count)
        s61_die("FACILITY_SESSION runtime trace is incomplete");
    s61_facility_snapshot_hashes(
        core, evidence, evidence->final_region_sha256,
        evidence->final_party_sha256, evidence->final_storage_sha256);
    evidence->party_restored = strcmp(
        evidence->initial_party_sha256,
        evidence->final_party_sha256) == 0;
    evidence->storage_restored = strcmp(
        evidence->initial_storage_sha256,
        evidence->final_storage_sha256) == 0;
    const struct S61FacilityNativeBoundary *last =
        &evidence->boundaries[evidence->trace_count - 1U];
    if (last->active != evidence->active_boundary_observed)
        s61_die("FACILITY_SESSION active terminal observation differs");
    if (!last->active
        && (!evidence->party_restored || !evidence->storage_restored))
        s61_die("FACILITY_SESSION terminal party/storage restoration differs");
    evidence->control->deferred_applied = true;
    evidence->control->deferred_hit_count = evidence->trace_count;
}

static void s61_release_facility_execution(struct S61Capture *capture)
{
    if (s61_active_facility_execution == &capture->facility)
        s61_active_facility_execution = NULL;
    free(capture->facility.fixture_raw);
    capture->facility.fixture_raw = NULL;
    capture->facility.trace_cursor = NULL;
    capture->facility.trace_end = NULL;
    capture->facility.control = NULL;
    capture->facility.root_capture = NULL;
}

static void s61_apply_storage_layout(struct mCore *core, const char *reference)
{
    uint8_t *raw = s61_load_control_fixture(reference, S61_POKEMON_STORAGE_SIZE);
    uint32_t storage = read32(core, S61_POKEMON_STORAGE_PTR);
    if (storage < 0x02000000U
        || storage + S61_POKEMON_STORAGE_SIZE > 0x02040000U
        || (storage & 3U) != 0U) {
        free(raw);
        s61_die("catalog storage pointer is invalid");
    }
    for (unsigned index = 0U; index < S61_POKEMON_STORAGE_SIZE; ++index)
        write8(core, storage + index, raw[index]);
    free(raw);
}

static void s61_verify_storage_layout(struct mCore *core,
                                      const char *reference)
{
    uint8_t *raw = s61_load_control_fixture(reference, S61_POKEMON_STORAGE_SIZE);
    uint32_t storage = read32(core, S61_POKEMON_STORAGE_PTR);
    if (storage < 0x02000000U
        || storage + S61_POKEMON_STORAGE_SIZE > 0x02040000U
        || (storage & 3U) != 0U
        || !s61_core_range_equals(
            core, storage, raw, S61_POKEMON_STORAGE_SIZE,
            "catalog storage fixture")) {
        free(raw);
        s61_die("catalog storage layout readback differs");
    }
    free(raw);
}

static uint32_t s61_pc_item_count(struct mCore *core, uint16_t item)
{
    uint32_t save1 = s61_catalog_save1(core);
    uint32_t count = 0U;
    for (unsigned slot = 0U; slot < 30U; ++slot) {
        uint32_t address = save1 + 0x298U + slot * 4U;
        if (read16(core, address) == item)
            count += read16(core, address + 2U);
    }
    return count;
}

static uint16_t s61_party_move_slot(struct mCore *core, uint16_t move)
{
    uint8_t count = read8(core, BOOTSTRAP_PLAYER_COUNT);
    if (count > S61_PARTY_SLOT_COUNT)
        s61_die("catalog party count exceeds six");
    if (!s61_sync_host_call_pc(core))
        s61_die("catalog party-move readback scheduler did not settle");
    uint16_t result = 6U;
    for (unsigned slot = 0U; slot < count && result == 6U; ++slot) {
        uint32_t mon = BOOTSTRAP_PLAYER_PARTY + slot * S61_PARTY_RECORD_SIZE;
        bool egg = call_preserving(
            core, BATTLE_CORE_GET_MON_DATA, mon,
            WORLD_MON_DATA_IS_EGG, 0U, 0U) != 0U;
        if (egg)
            continue;
        for (unsigned move_slot = 0U; move_slot < 4U; ++move_slot) {
            if (call_preserving(
                    core, BATTLE_CORE_GET_MON_DATA, mon,
                    WORLD_MON_DATA_MOVE1 + move_slot, 0U, 0U) == move) {
                result = (uint16_t)slot;
                break;
            }
        }
    }
    run_key_frames(core, 0U, 1U);
    return result;
}

struct S61PcCapacityProbeResult {
    uint8_t expected_result;
    uint8_t actual_result;
    uint32_t before_count;
    uint32_t after_count;
    uint64_t pc_raw_before_hash;
    uint64_t pc_raw_after_hash;
    uint64_t pc_raw_restored_hash;
    uint64_t all_owner_before_hash;
    uint64_t all_owner_after_hash;
    uint64_t all_owner_restored_hash;
    uint8_t pc_raw_before[S61_PC_ITEM_SLOT_COUNT * S61_PC_ITEM_SLOT_SIZE];
    uint8_t pc_raw_after[S61_PC_ITEM_SLOT_COUNT * S61_PC_ITEM_SLOT_SIZE];
    uint8_t pc_raw_restored[S61_PC_ITEM_SLOT_COUNT * S61_PC_ITEM_SLOT_SIZE];
    unsigned target_slot;
    uint32_t allowed_offsets[4U];
    unsigned allowed_offset_count;
    uint32_t actual_delta_offsets[4U];
    unsigned actual_delta_count;
    bool mutation_exact;
    bool pc_raw_expected_byte_exact;
    bool all_memory_outside_allowed_exact;
    bool all_owner_hashes_restored;
};

static uint32_t s61_add_pc_item_symbol(void)
{
    uint32_t symbol = (uint32_t)s61_uint_env(
        "S61_ADD_PC_ITEM_SYMBOL", 0U, UINT32_MAX);
    if (symbol != S61_ADD_PC_ITEM)
        s61_die("PC_CAPACITY AddPCItem oracle entry differs");
    return symbol;
}

static uint64_t s61_hash_all_mutable_owner_memory(struct mCore *core)
{
    /* Every persistent/control owner used by the interaction runner lives in
     * EWRAM or IWRAM.  Hash both complete address spaces so restoration cannot
     * be declared from the PC item slice alone. */
    uint64_t hash = UINT64_C(14695981039346656037);
    const uint32_t starts[] = {0x02000000U, 0x03000000U};
    const uint32_t sizes[] = {0x00040000U, 0x00008000U};
    for (unsigned range = 0U; range < ARRAY_LEN(starts); ++range) {
        for (uint32_t offset = 0U; offset < sizes[range]; ++offset) {
            hash ^= read8(core, starts[range] + offset);
            hash *= UINT64_C(1099511628211);
        }
    }
    return hash;
}

static void s61_read_all_mutable_owner_memory(
    struct mCore *core, uint8_t *raw)
{
    for (uint32_t offset = 0U; offset < 0x00040000U; ++offset)
        raw[offset] = read8(core, 0x02000000U + offset);
    for (uint32_t offset = 0U; offset < 0x00008000U; ++offset)
        raw[0x00040000U + offset] = read8(
            core, 0x03000000U + offset);
}

static bool s61_pc_offset_allowed(
    const struct S61PcCapacityProbeResult *result, uint32_t offset)
{
    for (unsigned index = 0U; index < result->allowed_offset_count; ++index)
        if (result->allowed_offsets[index] == offset)
            return true;
    return false;
}

static uint32_t s61_pc_item_plain_count(struct mCore *core, uint16_t item)
{
    uint32_t save1 = s61_catalog_save1(core);
    uint32_t count = 0U;
    for (unsigned slot = 0U; slot < S61_PC_ITEM_SLOT_COUNT; ++slot) {
        uint32_t address = save1 + S61_PC_ITEMS_OFFSET
            + slot * S61_PC_ITEM_SLOT_SIZE;
        if (read16(core, address) == item)
            count += read16(core, address + 2U);
    }
    return count;
}

static struct S61PcCapacityProbeResult s61_probe_pc_capacity(
    struct mCore *core, uint16_t item, uint16_t quantity,
    bool expected_result)
{
    struct S61PcCapacityProbeResult result = {
        .expected_result = expected_result ? 1U : 0U,
        .target_slot = UINT_MAX,
    };
    size_t state_size = core->stateSize(core);
    void *state = malloc(state_size);
    uint8_t *memory_before = malloc(0x00048000U);
    uint8_t *memory_after = malloc(0x00048000U);
    if (state == NULL || memory_before == NULL || memory_after == NULL)
        s61_die("PC_CAPACITY savestate allocation failed");
    if (!s61_sync_host_call_pc(core))
        s61_die("PC_CAPACITY actual-call scheduler PC did not settle");
    uint32_t save1 = s61_catalog_save1(core);
    uint32_t pc_base = save1 + S61_PC_ITEMS_OFFSET;
    result.before_count = s61_pc_item_plain_count(core, item);
    s61_read_core_range(core, pc_base, result.pc_raw_before,
                        sizeof(result.pc_raw_before));
    result.pc_raw_before_hash = s61_hash_bytes(
        result.pc_raw_before, sizeof(result.pc_raw_before));
    s61_read_all_mutable_owner_memory(core, memory_before);
    result.all_owner_before_hash = s61_hash_bytes(
        memory_before, 0x00048000U);
    if (!core->saveState(core, state))
        s61_die("PC_CAPACITY savestate capture failed");

    bool found_item = false;
    unsigned empty_slot = UINT_MAX;
    uint8_t expected_pc[sizeof(result.pc_raw_before)];
    memcpy(expected_pc, result.pc_raw_before, sizeof(expected_pc));
    for (unsigned slot = 0U; slot < S61_PC_ITEM_SLOT_COUNT; ++slot) {
        const uint8_t *slot_raw = result.pc_raw_before
            + slot * S61_PC_ITEM_SLOT_SIZE;
        uint16_t slot_item = (uint16_t)slot_raw[0]
            | (uint16_t)((uint16_t)slot_raw[1] << 8U);
        uint16_t slot_quantity = (uint16_t)slot_raw[2]
            | (uint16_t)((uint16_t)slot_raw[3] << 8U);
        if (slot_item == item) {
            found_item = true;
            if ((uint32_t)slot_quantity + quantity <= 999U) {
                result.target_slot = slot;
                uint16_t updated = (uint16_t)(slot_quantity + quantity);
                expected_pc[slot * 4U + 2U] = (uint8_t)updated;
                expected_pc[slot * 4U + 3U] = (uint8_t)(updated >> 8U);
                result.allowed_offsets[0] = slot * 4U + 2U;
                result.allowed_offsets[1] = slot * 4U + 3U;
                result.allowed_offset_count = 2U;
            }
            break;
        }
        if (empty_slot == UINT_MAX && slot_item == 0U)
            empty_slot = slot;
    }
    if (!found_item && empty_slot != UINT_MAX) {
        result.target_slot = empty_slot;
        expected_pc[empty_slot * 4U] = (uint8_t)item;
        expected_pc[empty_slot * 4U + 1U] = (uint8_t)(item >> 8U);
        expected_pc[empty_slot * 4U + 2U] = (uint8_t)quantity;
        expected_pc[empty_slot * 4U + 3U] = (uint8_t)(quantity >> 8U);
        for (unsigned byte = 0U; byte < 4U; ++byte)
            result.allowed_offsets[byte] = empty_slot * 4U + byte;
        result.allowed_offset_count = 4U;
    }
    if (!expected_result) {
        result.target_slot = UINT_MAX;
        result.allowed_offset_count = 0U;
        memcpy(expected_pc, result.pc_raw_before, sizeof(expected_pc));
    }

    result.actual_result = (uint8_t)call_preserving(
        core, s61_add_pc_item_symbol(), item, quantity, 0U, 0U);
    result.after_count = s61_pc_item_plain_count(core, item);
    s61_read_core_range(core, pc_base, result.pc_raw_after,
                        sizeof(result.pc_raw_after));
    result.pc_raw_after_hash = s61_hash_bytes(
        result.pc_raw_after, sizeof(result.pc_raw_after));
    s61_read_all_mutable_owner_memory(core, memory_after);
    result.all_owner_after_hash = s61_hash_bytes(
        memory_after, 0x00048000U);
    result.pc_raw_expected_byte_exact = memcmp(
        result.pc_raw_after, expected_pc, sizeof(expected_pc)) == 0;
    result.all_memory_outside_allowed_exact = true;
    for (uint32_t offset = 0U; offset < sizeof(result.pc_raw_before);
         ++offset) {
        if (result.pc_raw_before[offset] == result.pc_raw_after[offset])
            continue;
        if (result.actual_delta_count >= ARRAY_LEN(
                result.actual_delta_offsets))
            s61_die("PC_CAPACITY actual delta exceeds one slot");
        result.actual_delta_offsets[result.actual_delta_count++] = offset;
        if (!s61_pc_offset_allowed(&result, offset))
            result.all_memory_outside_allowed_exact = false;
    }
    for (uint32_t offset = 0U; offset < 0x00048000U; ++offset) {
        if (memory_before[offset] == memory_after[offset])
            continue;
        bool allowed = false;
        if (offset < 0x00040000U) {
            uint32_t address = 0x02000000U + offset;
            if (address >= pc_base
                && address < pc_base + sizeof(result.pc_raw_before))
                allowed = s61_pc_offset_allowed(
                    &result, address - pc_base);
        }
        if (!allowed)
            result.all_memory_outside_allowed_exact = false;
    }
    bool changed = result.pc_raw_after_hash != result.pc_raw_before_hash;
    result.mutation_exact = result.actual_result == result.expected_result
        && result.pc_raw_expected_byte_exact
        && result.all_memory_outside_allowed_exact
        && (expected_result
            ? result.after_count == result.before_count + quantity && changed
            : result.after_count == result.before_count && !changed);

    if (!core->loadState(core, state))
        s61_die("PC_CAPACITY savestate restore failed");
    save1 = s61_catalog_save1(core);
    s61_read_core_range(
        core, save1 + S61_PC_ITEMS_OFFSET, result.pc_raw_restored,
        sizeof(result.pc_raw_restored));
    result.pc_raw_restored_hash = s61_hash_bytes(
        result.pc_raw_restored, sizeof(result.pc_raw_restored));
    result.all_owner_restored_hash = s61_hash_all_mutable_owner_memory(core);
    result.all_owner_hashes_restored =
        result.pc_raw_restored_hash == result.pc_raw_before_hash
        && result.all_owner_restored_hash == result.all_owner_before_hash
        && s61_pc_item_plain_count(core, item) == result.before_count;
    free(memory_after);
    free(memory_before);
    free(state);
    if (!result.mutation_exact || !result.all_owner_hashes_restored) {
        fprintf(stderr,
                "PC_CAPACITY_DIAGNOSTIC expected=%u actual=%u "
                "before=%" PRIu32 " after=%" PRIu32 " quantity=%u "
                "pc_before=%016" PRIX64 " pc_after=%016" PRIX64 " "
                "pc_restored=%016" PRIX64 " owner_before=%016" PRIX64 " "
                "owner_restored=%016" PRIX64 " mutation_exact=%u "
                "owner_restored_ok=%u save1=%08" PRIX32
                " quantity_encoding=PLAIN_U16\n",
                result.expected_result, result.actual_result,
                result.before_count, result.after_count, quantity,
                result.pc_raw_before_hash, result.pc_raw_after_hash,
                result.pc_raw_restored_hash, result.all_owner_before_hash,
                result.all_owner_restored_hash,
                result.mutation_exact ? 1U : 0U,
                result.all_owner_hashes_restored ? 1U : 0U,
                s61_catalog_save1(core));
        s61_die("PC_CAPACITY actual call/mutation/restore contract differs");
    }
    return result;
}

static void s61_assert_add_pc_item_preimage(struct mCore *core)
{
    uint32_t address = (uint32_t)s61_uint_env(
        "S61_ADD_PC_ITEM_CODE_ADDRESS", 0U, UINT32_MAX);
    unsigned size = s61_uint_env(
        "S61_ADD_PC_ITEM_CODE_SIZE", 0U, 0x1000U);
    if (address != 0x08099DD0U || size != 0x96U
        || s61_hash_core_range(core, address, size)
            != UINT64_C(0x7577CDFEAA174544))
        s61_die("PC_CAPACITY AddPCItem ROM preimage differs");
}

static void s61_write_pc_item_slot(struct mCore *core, unsigned slot,
                                   uint16_t item, uint16_t quantity)
{
    if (slot >= S61_PC_ITEM_SLOT_COUNT || quantity > 999U)
        s61_die("PC_CAPACITY synthetic slot value is invalid");
    uint32_t save1 = s61_catalog_save1(core);
    uint32_t address = save1 + S61_PC_ITEMS_OFFSET
        + slot * S61_PC_ITEM_SLOT_SIZE;
    write16(core, address, item);
    write16(core, address + 2U, quantity);
}

static void s61_prepare_pc_capacity_synthetic(struct mCore *core,
                                               unsigned case_index)
{
    for (unsigned slot = 0U; slot < S61_PC_ITEM_SLOT_COUNT; ++slot)
        s61_write_pc_item_slot(core, slot, 0U, 0U);
    if (case_index == 0U)
        s61_write_pc_item_slot(core, 0U, 1U, 998U);
    else if (case_index == 1U)
        s61_write_pc_item_slot(core, 0U, 1U, 999U);
    else if (case_index == 2U) {
        for (unsigned slot = 0U; slot + 1U < S61_PC_ITEM_SLOT_COUNT; ++slot)
            s61_write_pc_item_slot(
                core, slot, (uint16_t)(slot + 2U), 1U);
    } else if (case_index == 3U) {
        for (unsigned slot = 0U; slot < S61_PC_ITEM_SLOT_COUNT; ++slot)
            s61_write_pc_item_slot(
                core, slot, (uint16_t)(slot + 2U), 1U);
    } else {
        s61_die("PC_CAPACITY synthetic case index is invalid");
    }
}

static void s61_print_pc_capacity_probe(
    const char *case_id, const struct S61PcCapacityProbeResult *probe,
    bool first)
{
    printf("%s{\"case_id\":\"%s\",\"query_item\":1,\"quantity\":1,"
           "\"expected_result\":%u,\"actual_result\":%u,"
           "\"before_count\":%" PRIu32 ",\"after_count\":%" PRIu32 ","
           "\"pc_raw_before_fnv1a64\":\"%016" PRIX64 "\","
           "\"pc_raw_after_fnv1a64\":\"%016" PRIX64 "\","
           "\"pc_raw_restored_fnv1a64\":\"%016" PRIX64 "\","
           "\"pc_mutation_exact\":%s,"
           "\"all_owner_before_fnv1a64\":\"%016" PRIX64 "\","
           "\"all_owner_after_fnv1a64\":\"%016" PRIX64 "\","
           "\"all_owner_restored_fnv1a64\":\"%016" PRIX64 "\","
           "\"pc_raw_before_hex\":\"",
           first ? "" : ",", case_id,
           probe->expected_result, probe->actual_result,
           probe->before_count, probe->after_count,
           probe->pc_raw_before_hash, probe->pc_raw_after_hash,
           probe->pc_raw_restored_hash,
           probe->mutation_exact ? "true" : "false",
           probe->all_owner_before_hash, probe->all_owner_after_hash,
           probe->all_owner_restored_hash);
    for (unsigned byte = 0U; byte < sizeof(probe->pc_raw_before); ++byte)
        printf("%02X", probe->pc_raw_before[byte]);
    printf("\",\"pc_raw_after_hex\":\"");
    for (unsigned byte = 0U; byte < sizeof(probe->pc_raw_after); ++byte)
        printf("%02X", probe->pc_raw_after[byte]);
    printf("\",\"pc_raw_restored_hex\":\"");
    for (unsigned byte = 0U; byte < sizeof(probe->pc_raw_restored); ++byte)
        printf("%02X", probe->pc_raw_restored[byte]);
    printf("\",\"target_slot\":");
    if (probe->target_slot == UINT_MAX)
        printf("null");
    else
        printf("%u", probe->target_slot);
    printf(",\"allowed_offsets\":[");
    for (unsigned index = 0U; index < probe->allowed_offset_count; ++index)
        printf("%s%" PRIu32, index ? "," : "",
               probe->allowed_offsets[index]);
    printf("],\"actual_delta_offsets\":[");
    for (unsigned index = 0U; index < probe->actual_delta_count; ++index)
        printf("%s%" PRIu32, index ? "," : "",
               probe->actual_delta_offsets[index]);
    printf("],\"pc_raw_expected_byte_exact\":%s,"
           "\"all_memory_outside_allowed_exact\":%s,"
           "\"all_owner_hashes_restored\":%s}",
           probe->pc_raw_expected_byte_exact ? "true" : "false",
           probe->all_memory_outside_allowed_exact ? "true" : "false",
           probe->all_owner_hashes_restored ? "true" : "false");
}

static void s61_case_pc_capacity_contract(
    const char *rom_path, const char *directory,
    const struct S61Config *config)
{
    static const char *const case_ids[4] = {
        "pc-capacity-existing-998-plus-1",
        "pc-capacity-existing-999-plus-1",
        "pc-capacity-empty-slot",
        "pc-capacity-full",
    };
    static const bool expected[4] = {true, false, true, false};
    char save_path[4096];
    struct Fixture fixture = s61_world_fixture(
        "pc_capacity_contract", &config->giver);
    s61_save_path(save_path, sizeof(save_path), directory, fixture.name);
    s61_generate(rom_path, save_path, &fixture);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &fixture);
    s61_case_name = "pc_capacity_contract";
    bootstrap_phase = s61_case_name;
    s61_assert_add_pc_item_preimage(core);
    size_t state_size = core->stateSize(core);
    void *base_state = malloc(state_size);
    if (base_state == NULL || !core->saveState(core, base_state))
        s61_die("PC_CAPACITY synthetic baseline savestate failed");
    struct S61PcCapacityProbeResult results[4];
    for (unsigned index = 0U; index < ARRAY_LEN(results); ++index) {
        if (!core->loadState(core, base_state))
            s61_die("PC_CAPACITY synthetic baseline restore failed");
        s61_prepare_pc_capacity_synthetic(core, index);
        results[index] = s61_probe_pc_capacity(
            core, 1U, 1U, expected[index]);
    }
    if (!core->loadState(core, base_state))
        s61_die("PC_CAPACITY final baseline restore failed");
    run_key_frames(core, 0U, 2U);
    bool input_recovered = world_overworld(core)
        && !world_script_enabled(core);
    if (!input_recovered)
        s61_die("PC_CAPACITY field input did not recover");
    char artifact[4096];
    int artifact_size = snprintf(
        artifact, sizeof(artifact), "%s/pc-capacity-final", directory);
    if (artifact_size <= 0 || (size_t)artifact_size >= sizeof(artifact))
        s61_die("PC_CAPACITY artifact path is too long");
    s61_write_framebuffer_ppm(
        artifact, s61_video, "CONTRACT_FIELD_FRAME");
    printf("{\"schema_version\":3,\"status\":\"PASS\","
           "\"case\":\"pc_capacity_contract\","
           "\"oracle_thumb_entry\":\"0x08099DD1\","
           "\"rom_preimage_checked\":true,"
           "\"savestate_actual_call_restore\":true,"
           "\"all_mutable_owner_hashes_restored\":true,"
           "\"actual_call_full_ewram_iwram_outside_allowed_byte_exact\":true,"
           "\"pc_slot_expected_bytes_all_cases_exact\":true,"
           "\"synthetic_case_count\":4,\"results\":[");
    for (unsigned index = 0U; index < ARRAY_LEN(results); ++index)
        s61_print_pc_capacity_probe(case_ids[index], &results[index],
                                    index == 0U);
    printf("],\"fresh_core\":true,\"field_input_recovered\":true,"
           "\"failed\":0,\"untested\":0,\"warnings\":0}\n");
    free(base_state);
    bootstrap_close_core(core);
}

