static void s61_print_object_snapshot(const struct S61ObjectSnapshot *snapshot)
{
    bool visible = snapshot->active && !snapshot->invisible;
    printf("{\"active\":%s,\"visible\":%s,\"invisible\":%s,"
           "\"slot\":",
           snapshot->active ? "true" : "false",
           visible ? "true" : "false",
           snapshot->invisible ? "true" : "false");
    if (snapshot->active)
        printf("%d,\"current\":[%d,%d],\"previous\":[%d,%d]}",
               snapshot->slot, snapshot->current_x, snapshot->current_y,
               snapshot->previous_x, snapshot->previous_y);
    else
        printf("null,\"current\":null,\"previous\":null}");
}

