static int s61_runtime_object_key_compare(
    const struct S61RuntimeObjectEntry *left,
    const struct S61RuntimeObjectEntry *right)
{
    if (left->group != right->group)
        return left->group < right->group ? -1 : 1;
    if (left->map != right->map)
        return left->map < right->map ? -1 : 1;
    if (left->local_id != right->local_id)
        return left->local_id < right->local_id ? -1 : 1;
    if (left->slot != right->slot)
        return left->slot < right->slot ? -1 : 1;
    return 0;
}

static void s61_print_runtime_object_entry(
    const struct S61RuntimeObjectEntry *entry)
{
    printf("{\"slot\":%u,\"local_id\":%u,\"map\":\"%u/%u\","
           "\"invisible\":%s,\"visible\":%s,"
           "\"current\":[%d,%d],\"previous\":[%d,%d]}",
           entry->slot, entry->local_id, entry->group, entry->map,
           entry->invisible ? "true" : "false",
           entry->invisible ? "false" : "true",
           entry->current_x, entry->current_y,
           entry->previous_x, entry->previous_y);
}

static void s61_print_runtime_object_inventory(
    const struct S61RuntimeObjectInventory *inventory)
{
    putchar('[');
    for (unsigned index = 0U; index < inventory->count; ++index) {
        if (index != 0U)
            putchar(',');
        s61_print_runtime_object_entry(&inventory->entries[index]);
    }
    putchar(']');
}

static void s61_print_runtime_object_changes(
    const struct S61RuntimeObjectInventory *before,
    const struct S61RuntimeObjectInventory *after)
{
    bool changed_ids[256] = {false};
    unsigned left = 0U;
    unsigned right = 0U;
    bool comma = false;
    putchar('[');
    while (left < before->count || right < after->count) {
        const struct S61RuntimeObjectEntry *old_entry =
            left < before->count ? &before->entries[left] : NULL;
        const struct S61RuntimeObjectEntry *new_entry =
            right < after->count ? &after->entries[right] : NULL;
        int comparison = old_entry == NULL ? 1
            : new_entry == NULL ? -1
            : s61_runtime_object_key_compare(old_entry, new_entry);
        const struct S61RuntimeObjectEntry *old_value = NULL;
        const struct S61RuntimeObjectEntry *new_value = NULL;
        if (comparison < 0)
            old_value = &before->entries[left++];
        else if (comparison > 0)
            new_value = &after->entries[right++];
        else {
            old_value = &before->entries[left++];
            new_value = &after->entries[right++];
            if (memcmp(old_value, new_value, sizeof(*old_value)) == 0)
                continue;
        }
        uint8_t local_id = old_value != NULL
            ? old_value->local_id : new_value->local_id;
        changed_ids[local_id] = true;
        printf("%s{\"local_id\":%u,\"before\":",
               comma ? "," : "", local_id);
        if (old_value != NULL)
            s61_print_runtime_object_entry(old_value);
        else
            printf("null");
        printf(",\"after\":");
        if (new_value != NULL)
            s61_print_runtime_object_entry(new_value);
        else
            printf("null");
        putchar('}');
        comma = true;
    }
    printf("],\"changed_local_ids\":[");
    comma = false;
    for (unsigned id = 0U; id < 256U; ++id) {
        if (!changed_ids[id])
            continue;
        printf("%s%u", comma ? "," : "", id);
        comma = true;
    }
    putchar(']');
}

static void s61_print_loaded_template_changed_ids(
    const struct S61LoadedTemplateInventory *before,
    const struct S61LoadedTemplateInventory *after)
{
    bool changed[256] = {false};
    unsigned left = 0U;
    unsigned right = 0U;
    while (left < before->count || right < after->count) {
        const struct S61LoadedTemplateEntry *old_entry =
            left < before->count ? &before->entries[left] : NULL;
        const struct S61LoadedTemplateEntry *new_entry =
            right < after->count ? &after->entries[right] : NULL;
        if (new_entry == NULL
            || (old_entry != NULL
                && old_entry->local_id < new_entry->local_id)) {
            changed[old_entry->local_id] = true;
            ++left;
        } else if (old_entry == NULL
                   || new_entry->local_id < old_entry->local_id) {
            changed[new_entry->local_id] = true;
            ++right;
        } else {
            if (old_entry->hash != new_entry->hash)
                changed[old_entry->local_id] = true;
            ++left;
            ++right;
        }
    }
    putchar('[');
    bool comma = false;
    for (unsigned id = 0U; id < 256U; ++id) {
        if (!changed[id])
            continue;
        printf("%s%u", comma ? "," : "", id);
        comma = true;
    }
    putchar(']');
}

static void s61_print_loaded_template_changes(
    const struct S61LoadedTemplateInventory *before,
    const struct S61LoadedTemplateInventory *after)
{
    unsigned left = 0U;
    unsigned right = 0U;
    bool comma = false;
    putchar('[');
    while (left < before->count || right < after->count) {
        const struct S61LoadedTemplateEntry *old_entry =
            left < before->count ? &before->entries[left] : NULL;
        const struct S61LoadedTemplateEntry *new_entry =
            right < after->count ? &after->entries[right] : NULL;
        if (new_entry == NULL
            || (old_entry != NULL
                && old_entry->local_id < new_entry->local_id)) {
            printf("%s{\"local_id\":%u,"
                   "\"before_fnv1a64\":\"%016" PRIX64 "\","
                   "\"after_fnv1a64\":null}",
                   comma ? "," : "", old_entry->local_id,
                   old_entry->hash);
            ++left;
            comma = true;
        } else if (old_entry == NULL
                   || new_entry->local_id < old_entry->local_id) {
            printf("%s{\"local_id\":%u,\"before_fnv1a64\":null,"
                   "\"after_fnv1a64\":\"%016" PRIX64 "\"}",
                   comma ? "," : "", new_entry->local_id,
                   new_entry->hash);
            ++right;
            comma = true;
        } else {
            if (old_entry->hash != new_entry->hash) {
                printf("%s{\"local_id\":%u,"
                       "\"before_fnv1a64\":\"%016" PRIX64 "\","
                       "\"after_fnv1a64\":\"%016" PRIX64 "\"}",
                       comma ? "," : "", old_entry->local_id,
                       old_entry->hash, new_entry->hash);
                comma = true;
            }
            ++left;
            ++right;
        }
    }
    putchar(']');
}

static unsigned s61_saveblock_changed_byte_count(
    const uint8_t *before, const uint8_t *after, size_t size,
    unsigned block, bool include_volatile)
{
    unsigned count = 0U;
    for (size_t offset = 0U; offset < size; ++offset) {
        if (before[offset] == after[offset])
            continue;
        if (!include_volatile
            && s61_saveblock_byte_is_volatile(block, offset))
            continue;
        ++count;
    }
    return count;
}

static void s61_print_saveblock_delta(
    const uint8_t *before, const uint8_t *after, size_t size,
    unsigned block, uint64_t before_raw_hash, uint64_t after_raw_hash,
    uint64_t before_normalized_hash, uint64_t after_normalized_hash)
{
    unsigned raw_count = s61_saveblock_changed_byte_count(
        before, after, size, block, true);
    unsigned normalized_count = s61_saveblock_changed_byte_count(
        before, after, size, block, false);
    printf("{\"bytes_scanned\":%zu,\"raw_changed\":%s,"
           "\"normalized_changed\":%s,"
           "\"raw_changed_byte_count\":%u,"
           "\"normalized_changed_byte_count\":%u,"
           "\"raw_before_fnv1a64\":\"%016" PRIX64 "\","
           "\"raw_after_fnv1a64\":\"%016" PRIX64 "\","
           "\"normalized_before_fnv1a64\":\"%016" PRIX64 "\","
           "\"normalized_after_fnv1a64\":\"%016" PRIX64 "\","
           "\"changes\":[",
           size, raw_count != 0U ? "true" : "false",
           normalized_count != 0U ? "true" : "false",
           raw_count, normalized_count,
           before_raw_hash, after_raw_hash,
           before_normalized_hash, after_normalized_hash);
    bool comma = false;
    for (size_t offset = 0U; offset < size; ++offset) {
        if (before[offset] == after[offset])
            continue;
        printf("%s{\"offset\":%zu,\"before\":%u,\"after\":%u,"
               "\"volatile\":%s}",
               comma ? "," : "", offset, before[offset], after[offset],
               s61_saveblock_byte_is_volatile(block, offset)
                   ? "true" : "false");
        comma = true;
    }
    printf("]}");
}

static void s61_print_side_effects(
    const struct S61SideEffectSnapshot *before,
    const struct S61SideEffectSnapshot *after)
{
    printf("{\"complete\":true,\"coverage\":{"
           "\"flags\":{\"ids_scanned\":6400,"
           "\"before_fnv1a64\":\"%016" PRIX64 "\","
           "\"after_fnv1a64\":\"%016" PRIX64 "\"},"
           "\"engine_special_flags\":{\"ids_scanned\":128,"
           "\"owner_address\":\"0x%08X\","
           "\"before_fnv1a64\":\"%016" PRIX64 "\","
           "\"after_fnv1a64\":\"%016" PRIX64 "\"},"
           "\"vars\":{\"ids_scanned\":768,"
           "\"before_fnv1a64\":\"%016" PRIX64 "\","
           "\"after_fnv1a64\":\"%016" PRIX64 "\"},"
           "\"items\":{\"slots_scanned\":186,"
           "\"entries_before\":%u,\"entries_after\":%u,"
           "\"before_fnv1a64\":\"%016" PRIX64 "\","
           "\"after_fnv1a64\":\"%016" PRIX64 "\"},"
           "\"trainers\":{\"ids_scanned\":768,"
           "\"before_fnv1a64\":\"%016" PRIX64 "\","
           "\"after_fnv1a64\":\"%016" PRIX64 "\"}",
           before->flags_hash, after->flags_hash,
           WORLD_ENGINE_SPECIAL_FLAGS,
           before->engine_special_flags_hash,
           after->engine_special_flags_hash,
           before->vars_hash, after->vars_hash,
           before->bag_entry_count, after->bag_entry_count,
           before->items_hash, after->items_hash,
           before->trainers_hash, after->trainers_hash);
    printf(",\"objects\":{\"slots_scanned\":16,"
           "\"active_before\":%u,\"active_after\":%u,"
           "\"before_fnv1a64\":\"%016" PRIX64 "\","
           "\"after_fnv1a64\":\"%016" PRIX64 "\"},"
           "\"object_templates\":{\"capacity_scanned\":64,"
           "\"entries_before\":%u,\"entries_after\":%u,"
           "\"before_fnv1a64\":\"%016" PRIX64 "\","
           "\"after_fnv1a64\":\"%016" PRIX64 "\","
           "\"changed_local_ids\":",
           before->runtime_objects.count, after->runtime_objects.count,
           before->runtime_objects.hash, after->runtime_objects.hash,
           before->loaded_templates.count, after->loaded_templates.count,
           before->loaded_templates.hash, after->loaded_templates.hash);
    s61_print_loaded_template_changed_ids(
        &before->loaded_templates, &after->loaded_templates);
    printf(",\"changes\":");
    s61_print_loaded_template_changes(
        &before->loaded_templates, &after->loaded_templates);
    printf("},\"party\":{\"slots_scanned\":6,"
           "\"record_size\":100,\"raw_byte_length\":600,"
           "\"count_before\":%u,"
           "\"count_after\":%u,"
           "\"raw_sha256_before\":\"%s\","
           "\"raw_sha256_after\":\"%s\"},"
           "\"storage\":{\"raw_byte_length\":33744,"
           "\"raw_sha256_before\":\"%s\","
           "\"raw_sha256_after\":\"%s\"},"
           "\"persistent\":{"
           "\"saveblock1\":{\"bytes_scanned\":%u,"
           "\"raw_before_fnv1a64\":\"%016" PRIX64 "\","
           "\"raw_after_fnv1a64\":\"%016" PRIX64 "\","
           "\"normalized_before_fnv1a64\":\"%016" PRIX64 "\","
           "\"normalized_after_fnv1a64\":\"%016" PRIX64 "\","
           "\"volatile_ranges\":[]},"
           "\"saveblock2\":{\"bytes_scanned\":%u,"
           "\"raw_before_fnv1a64\":\"%016" PRIX64 "\","
           "\"raw_after_fnv1a64\":\"%016" PRIX64 "\","
           "\"normalized_before_fnv1a64\":\"%016" PRIX64 "\","
           "\"normalized_after_fnv1a64\":\"%016" PRIX64 "\","
           "\"volatile_ranges\":[{\"start\":%u,\"end\":%u,"
           "\"meaning\":\"play_time_vblank_owner\"}]}}},"
           "\"flags\":[",
           before->party_count, after->party_count,
           before->party_raw_sha256, after->party_raw_sha256,
           before->storage_raw_sha256, after->storage_raw_sha256,
           S61_SAVE_BLOCK1_SIZE,
           before->saveblock1_raw_hash, after->saveblock1_raw_hash,
           before->saveblock1_normalized_hash,
           after->saveblock1_normalized_hash,
           S61_SAVE_BLOCK2_SIZE,
           before->saveblock2_raw_hash, after->saveblock2_raw_hash,
           before->saveblock2_normalized_hash,
           after->saveblock2_normalized_hash,
           S61_SAVE_BLOCK2_PLAY_TIME_START,
           S61_SAVE_BLOCK2_PLAY_TIME_END);
    bool comma = false;
    for (uint16_t id = 0U; id < 0x1900U; ++id) {
        bool old_value = s61_snapshot_flag(before, id);
        bool new_value = s61_snapshot_flag(after, id);
        if (old_value == new_value)
            continue;
        printf("%s{\"id\":%u,\"before\":%s,\"after\":%s}",
               comma ? "," : "", id,
               old_value ? "true" : "false",
               new_value ? "true" : "false");
        comma = true;
    }
    printf("],\"engine_special_flags\":[");
    comma = false;
    for (unsigned bit = 0U; bit < 128U; ++bit) {
        bool old_value = (before->engine_special_flags[bit >> 3U]
                          & (1U << (bit & 7U))) != 0U;
        bool new_value = (after->engine_special_flags[bit >> 3U]
                          & (1U << (bit & 7U))) != 0U;
        if (old_value == new_value)
            continue;
        printf("%s{\"id\":%u,\"before\":%s,\"after\":%s}",
               comma ? "," : "", 0x4000U + bit,
               old_value ? "true" : "false",
               new_value ? "true" : "false");
        comma = true;
    }
    printf("],\"vars\":[");
    comma = false;
    for (unsigned domain = 0U; domain < 2U; ++domain) {
        uint16_t start = domain == 0U ? 0x4000U : 0x5000U;
        unsigned count = domain == 0U
            ? S61_STOCK_VAR_COUNT : S61_EXPANDED_VAR_COUNT;
        for (unsigned index = 0U; index < count; ++index) {
            uint16_t id = (uint16_t)(start + index);
            uint16_t old_value = s61_snapshot_var(before, id);
            uint16_t new_value = s61_snapshot_var(after, id);
            if (old_value == new_value)
                continue;
            printf("%s{\"id\":%u,\"before\":%u,\"after\":%u}",
                   comma ? "," : "", id, old_value, new_value);
            comma = true;
        }
    }
    printf("],\"items\":[");
    comma = false;
    unsigned left = 0U;
    unsigned right = 0U;
    while (left < before->item_count || right < after->item_count) {
        uint16_t id;
        if (right >= after->item_count
            || (left < before->item_count
                && before->items[left].id < after->items[right].id))
            id = before->items[left++].id;
        else if (left >= before->item_count
                 || after->items[right].id < before->items[left].id)
            id = after->items[right++].id;
        else {
            id = before->items[left].id;
            ++left;
            ++right;
        }
        uint32_t old_value = s61_snapshot_item(before, id);
        uint32_t new_value = s61_snapshot_item(after, id);
        if (old_value == new_value)
            continue;
        printf("%s{\"id\":%u,\"before\":%" PRIu32
               ",\"after\":%" PRIu32 "}",
               comma ? "," : "", id, old_value, new_value);
        comma = true;
    }
    printf("],\"trainers\":[");
    comma = false;
    for (uint16_t id = 0U; id < S61_TRAINER_COUNT; ++id) {
        bool old_value = s61_snapshot_flag(
            before, (uint16_t)(S61_TRAINER_FLAG_START + id));
        bool new_value = s61_snapshot_flag(
            after, (uint16_t)(S61_TRAINER_FLAG_START + id));
        if (old_value == new_value)
            continue;
        printf("%s{\"id\":%u,\"before\":%s,\"after\":%s}",
               comma ? "," : "", id,
               old_value ? "true" : "false",
               new_value ? "true" : "false");
        comma = true;
    }
    printf("],\"economy\":{"
           "\"money\":{\"before\":%" PRIu32 ",\"after\":%" PRIu32 "},"
           "\"berry_powder\":{\"before\":%" PRIu32
           ",\"after\":%" PRIu32 "},"
           "\"vega_coins\":{\"before\":%u,\"after\":%u},"
           "\"cfru_coins\":{\"before\":%" PRIu32
           ",\"after\":%" PRIu32 "}},"
           "\"party\":{\"count_before\":%u,\"count_after\":%u,"
           "\"raw_byte_length\":600,"
           "\"raw_sha256_before\":\"%s\","
           "\"raw_sha256_after\":\"%s\"},"
           "\"storage\":{\"changed\":%s,"
           "\"raw_byte_length\":33744,"
           "\"raw_sha256_before\":\"%s\","
           "\"raw_sha256_after\":\"%s\"},"
           "\"persistent\":{\"saveblock1\":",
           before->money, after->money,
           before->berry_powder, after->berry_powder,
           before->vega_coins, after->vega_coins,
           before->cfru_coins, after->cfru_coins,
           before->party_count, after->party_count,
           before->party_raw_sha256, after->party_raw_sha256,
           strcmp(before->storage_raw_sha256,
                  after->storage_raw_sha256) != 0 ? "true" : "false",
           before->storage_raw_sha256, after->storage_raw_sha256);
    s61_print_saveblock_delta(
        before->saveblock1, after->saveblock1, S61_SAVE_BLOCK1_SIZE, 1U,
        before->saveblock1_raw_hash, after->saveblock1_raw_hash,
        before->saveblock1_normalized_hash,
        after->saveblock1_normalized_hash);
    printf(",\"saveblock2\":");
    s61_print_saveblock_delta(
        before->saveblock2, after->saveblock2, S61_SAVE_BLOCK2_SIZE, 2U,
        before->saveblock2_raw_hash, after->saveblock2_raw_hash,
        before->saveblock2_normalized_hash,
        after->saveblock2_normalized_hash);
    printf("},\"objects\":{\"changed\":%s,\"before\":",
           before->runtime_objects.hash != after->runtime_objects.hash
               ? "true" : "false");
    s61_print_runtime_object_inventory(&before->runtime_objects);
    printf(",\"after\":");
    s61_print_runtime_object_inventory(&after->runtime_objects);
    printf(",\"changes\":");
    s61_print_runtime_object_changes(
        &before->runtime_objects, &after->runtime_objects);
    printf("},\"world\":{\"changed\":%s,\"before\":",
           memcmp(&before->world, &after->world,
                  sizeof(before->world)) != 0 ? "true" : "false");
    s61_print_world_snapshot(&before->world);
    printf(",\"after\":");
    s61_print_world_snapshot(&after->world);
    bool before_visible = before->object.active && !before->object.invisible;
    bool after_visible = after->object.active && !after->object.invisible;
    bool object_changed =
        memcmp(&before->object, &after->object,
               sizeof(before->object)) != 0
        || memcmp(&before->object_template, &after->object_template,
                  sizeof(before->object_template)) != 0;
    printf("},\"object\":{\"changed\":%s,"
           "\"visibility_changed\":%s,\"before\":",
           object_changed ? "true" : "false",
           before_visible != after_visible ? "true" : "false");
    s61_print_object_snapshot(&before->object);
    printf(",\"after\":");
    s61_print_object_snapshot(&after->object);
    printf(",\"template_before\":");
    s61_print_object_template_snapshot(&before->object_template);
    printf(",\"template_after\":");
    s61_print_object_template_snapshot(&after->object_template);
    printf("},\"battle\":{\"opponent_changed\":%s,\"before\":",
           memcmp(&before->battle, &after->battle,
                  sizeof(before->battle)) != 0 ? "true" : "false");
    s61_print_battle_snapshot(&before->battle);
    printf(",\"after\":");
    s61_print_battle_snapshot(&after->battle);
    printf("},\"input\":{\"recovered\":%s,\"before\":",
           after->input.field_input_recovered ? "true" : "false");
    s61_print_input_snapshot(&before->input);
    printf(",\"after\":");
    s61_print_input_snapshot(&after->input);
    printf("}}");
}

static void s61_case_catalog_batch(const char *rom_path,
                                   const char *directory)
{
    const char *catalog_path = getenv("S61_CATALOG_TSV");
    if (catalog_path == NULL || catalog_path[0] == '\0')
        s61_die("S61_CATALOG_TSV is required for catalog_batch");
    FILE *stream = fopen(catalog_path, "rb");
    if (stream == NULL)
        s61_die("catalog TSV could not be opened");
    char line[S61_CATALOG_LINE_SIZE];
    if (fgets(line, sizeof(line), stream) == NULL)
        s61_die("catalog TSV is empty");
    size_t header_size = strlen(line);
    while (header_size != 0U
           && (line[header_size - 1U] == '\n'
               || line[header_size - 1U] == '\r'))
        line[--header_size] = '\0';
    if (strcmp(line, S61_CATALOG_HEADER) != 0)
        s61_die("catalog TSV header differs");

    char save_path[4096];
    struct S61Interaction base_interaction = {
        S61_EVENT_RUNTIME_BASE_GROUP, S61_EVENT_RUNTIME_BASE_MAP,
        20U, 20U, WORLD_KEY_DOWN, 1U, 0U,
    };
    struct Fixture base = s61_world_fixture(
        "catalog_batch_base", &base_interaction);
    s61_save_path(save_path, sizeof(save_path), directory, base.name);
    s61_generate(rom_path, save_path, &base);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &base);
    s61_assert_text_printer_preimage(core);
    size_t state_size = core->stateSize(core);
    void *base_state = malloc(state_size);
    void *interaction_state = malloc(state_size);
    color_t *interaction_video = malloc(sizeof(s61_video));
    struct S61SideEffectSnapshot *side_before = malloc(sizeof(*side_before));
    struct S61SideEffectSnapshot *side_after = malloc(sizeof(*side_after));
    struct S61SideEffectSnapshot *side_final = malloc(sizeof(*side_final));
    struct S61SideEffectSnapshot *approach_before = malloc(
        sizeof(*approach_before));
    struct S61SideEffectSnapshot *approach_after = malloc(
        sizeof(*approach_after));
    if (base_state == NULL || interaction_state == NULL
        || interaction_video == NULL || side_before == NULL
        || side_after == NULL || side_final == NULL
        || approach_before == NULL || approach_after == NULL
        || !core->saveState(core, base_state))
        s61_die("catalog baseline state capture failed");

    printf("{\"schema_version\":9,\"case\":\"catalog_batch\","
           "\"baseline_natural_continue\":true,"
           "\"per_case_stock_warp\":true,"
           "\"input_sequence_probe_via_state_restore\":true,"
           "\"results\":[");
    unsigned count = 0U;
    unsigned interactive_count = 0U;
    unsigned hidden_count = 0U;
    unsigned choice_attempt_count = 0U;
    unsigned successful_path_count = 0U;
    unsigned failed = 0U;
    unsigned empty_text = 0U;
    unsigned softlocks = 0U;
    unsigned terminal_mismatches = 0U;
    unsigned frame_diff_failures = 0U;
    unsigned input_recovery_failures = 0U;
    unsigned invalid_control_flow_failures = 0U;
    unsigned internal_control_failures = 0U;
    unsigned root_script_failures = 0U;
    unsigned link_session_attempt_count = 0U;
    unsigned rfu_session_attempt_count = 0U;
    unsigned rfu_session_failure_count = 0U;
    unsigned rfu_host_memory_write_count = 0U;
    unsigned center_link_session_attempt_count = 0U;
    unsigned center_link_session_failure_count = 0U;
    unsigned center_link_host_memory_write_count = 0U;
    while (fgets(line, sizeof(line), stream) != NULL) {
        if (strchr(line, '\n') == NULL && !feof(stream))
            s61_die("catalog TSV line exceeds the bounded buffer");
        if (line[0] == '\n' || line[0] == '\r' || line[0] == '\0')
            s61_die("catalog TSV contains a blank row");
        struct S61CatalogRow row = s61_parse_catalog_row(line);
        s61_case_name = row.case_id;
        bootstrap_phase = row.case_id;
        if (!core->loadState(core, base_state))
            s61_die("catalog baseline state restore failed");
        run_key_frames(core, 0U, 3U);
        s61_apply_catalog_state(core, &row);
        s61_apply_catalog_external_state(core, &row, false);
        struct Fixture fixture = s61_world_fixture(
            row.case_id, &row.interaction);
        struct S61CatalogRuntimePositionObservation runtime_position = {0};
        s61_catalog_position_for_row(
            core, &row, &fixture, true, &runtime_position);
        s61_apply_catalog_post_warp_external_state(core, &row, true);
        /* Host writes prepare only the requested branch state.  The map load
         * is allowed to execute normally, then every live target is reread
         * before any player input is accepted. */
        s61_verify_catalog_state(core, &row);
        s61_verify_catalog_external_state(core, &row, false, false);
        bool visible = s61_object_visible(core, &row.interaction);
        runtime_position.target_materialized_before_walk = visible;
        runtime_position.target_materialization_deferred_to_real_walk =
            runtime_position.producer_required && row.expect_visible
            && row.expect_interaction && row.actual_walk_required
            && !visible;
        if (visible != row.expect_visible
            && !runtime_position.target_materialization_deferred_to_real_walk) {
            s61_snapshot_side_effects(core, &row.interaction, side_before);
            fprintf(stderr,
                    "catalog visibility diagnostic case=%s expected=%u "
                    "actual=%u runtime_template=%u/%d/%u,%u "
                    "live=%u visible=%u/%d/%u,%u player=%u,%u\n",
                    row.case_id, row.expect_visible, visible,
                    side_before->object_template.found,
                    side_before->object_template.slot,
                    side_before->object_template.x,
                    side_before->object_template.y,
                    side_before->object.active,
                    side_before->object.active
                        && !side_before->object.invisible,
                    side_before->object.slot,
                    side_before->object.current_x,
                    side_before->object.current_y,
                    side_before->world.x, side_before->world.y);
            s61_die("catalog NPC visibility differs before interaction");
        }
        uint64_t visibility_framebuffer = 0U;
        if (count != 0U)
            putchar(',');
        unsigned walked = 0U;
        struct S61CatalogApproachObservation approach = {0};
        struct S61Capture approach_capture = {0};
        if (row.expect_interaction) {
            char approach_label[1024];
            int approach_label_size = snprintf(
                approach_label, sizeof(approach_label),
                "%s-physical-approach", row.case_id);
            if (approach_label_size <= 0
                || (size_t)approach_label_size >= sizeof(approach_label))
                s61_die("catalog approach artifact label is too long");
            char approach_artifact[4096];
            approach_capture = s61_new_capture(
                directory, approach_label, approach_artifact,
                sizeof(approach_artifact));
            s61_snapshot_side_effects(
                core, &row.interaction, approach_before);
            s61_assert_catalog_preinteraction_identity(
                &row, approach_before,
                row.runtime_position_producer.kind
                    == S61_CATALOG_RUNTIME_POSITION_NONE);
            approach.effect_hook_hits_before =
                s61_effect_observer_total_hook_hits();
            walked = s61_walk_catalog_execution(
                core, &row, &approach_capture, &approach);
            approach.effect_hook_hits_after =
                s61_effect_observer_total_hook_hits();
            s61_snapshot_side_effects(
                core, &row.interaction, approach_after);
            s61_assert_catalog_preinteraction_identity(
                &row, approach_after, true);
            s61_catalog_approach_persistent_observation(
                approach_before, approach_after, &approach);
            if (!s61_catalog_approach_exact(
                    &row, &approach_capture, &approach)) {
                s61_report_catalog_approach_failure(
                    &row, &approach_capture, &approach);
                s61_die(
                    "catalog physical approach observation is not exact");
            }
        }
        visible = s61_object_visible(core, &row.interaction);
        runtime_position.target_materialized_before_a = visible;
        if (visible != row.expect_visible)
            s61_die("catalog NPC visibility differs after real approach");
        if (runtime_position.producer_required) {
            runtime_position.exact = runtime_position.exact
                && runtime_position.target_materialized_before_a
                    == row.expect_visible;
            if (!runtime_position.exact)
                s61_die("catalog runtime-position target materialization differs");
        }
        s61_write_catalog_visibility_frame(directory, row.case_id);
        visibility_framebuffer = bootstrap_framebuffer_hash(s61_video);
        s61_verify_catalog_state(core, &row);
        s61_verify_catalog_external_state(core, &row, false, true);
        s61_apply_catalog_external_state(core, &row, true);
        s61_verify_catalog_external_state(core, &row, true, true);
        s61_prepare_rfu_var_result_preimage(core, &row);
        s61_snapshot_side_effects(core, &row.interaction, side_before);
        s61_assert_catalog_preinteraction_identity(&row, side_before, true);
        /* Arm the hidden no-input probe only after the exact owner identity
         * gate.  This excludes map-load/walk hits and shared-root aliases. */
        struct S61Capture hidden_root_capture = {0};
        if (!row.expect_interaction) {
            hidden_root_capture.event_root_script_pointer = row.runtime_root;
            hidden_root_capture.suppress_semantic_content = true;
            /* A hidden owner is one source-identity no-dispatch case.  Arm
             * only after its exact template/live identity has passed: map
             * load and any approach work are outside this raw-watch window. */
            s61_effect_observer_begin_case(core, row.case_id);
            s61_step_capture_frames(core, 0U, 3U, &hidden_root_capture);
            s61_effect_observer_end_case(core);
            if (hidden_root_capture.invalid_control_flow
                || hidden_root_capture.event_root_script_pointer_hits != 0U
                || hidden_root_capture.event_first_root_script_pointer != 0U)
                s61_die("catalog hidden owner executed without player input");
        }
        printf("{\"case_id\":\"%s\",\"base_case_id\":\"%s\","
               "\"owner_key\":\"%s\",\"catalog_branch\":\"%s\","
               "\"map\":\"%u/%u\",\"local_id\":%u,"
               "\"runtime_root\":\"0x%08" PRIX32 "\","
               "\"actual_walk_steps\":%u,\"direction_plus_a\":%s,"
               "\"interaction_trigger\":\"%s\","
               "\"walk_path_basis\":\"%s\","
               "\"stance\":[%u,%u],\"interaction_distance\":%u,"
               "\"counter_tile_present\":%s,"
               "\"actual_walk_required\":%s,"
               "\"map_level_real_walk_probe_required\":%s,"
               "\"direct_script_call\":false,"
               "\"state_counts\":{\"flags\":%u,\"vars\":%u,"
               "\"items\":%u,\"trainers\":%u,"
               "\"external_controls\":%u,\"internal_controls\":%u},"
               "\"control_abi_complete\":%s,"
               "\"expect_visible\":%s,\"interaction_expected\":%s,"
               "\"object_visible\":%s,"
               "\"visibility_framebuffer_fnv1a64\":\"%016" PRIX64 "\",",
               row.case_id, row.base_case_id, row.owner_key,
               row.catalog_branch, row.interaction.group,
               row.interaction.map, row.interaction.local_id,
               row.runtime_root, walked,
               row.expect_interaction ? "true" : "false",
               row.interaction_trigger, row.walk_path_basis,
               row.stance_x, row.stance_y,
               row.interaction_distance,
               row.counter_tile_present ? "true" : "false",
               row.actual_walk_required ? "true" : "false",
               row.map_level_real_walk_probe_required ? "true" : "false",
               row.flag_count, row.var_count, row.item_count,
               row.trainer_count, row.external_control_count,
               row.internal_control_count,
               row.control_abi_complete ? "true" : "false",
               row.expect_visible ? "true" : "false",
               row.expect_interaction ? "true" : "false",
               visible ? "true" : "false", visibility_framebuffer);
        printf("\"approach_observation\":");
        if (row.expect_interaction)
            s61_print_catalog_approach_observation(
                &row, &approach_capture, &approach);
        else
            fputs("null", stdout);
        printf(",\"runtime_position_producer\":");
        s61_print_catalog_runtime_position_observation(
            &row, &runtime_position);
        putchar(',');
        printf("\"preinteraction_object_identity\":");
        s61_print_catalog_preinteraction_identity(&row, side_before);
        printf(",\"root_probe\":{"
               "\"expected\":\"0x%08" PRIX32 "\","
               "\"armed_after_identity\":true,"
               "\"input_attempted\":%s,"
               "\"hidden_idle_frames\":%u,"
               "\"hidden_hits\":%u,\"hidden_first\":",
               row.runtime_root,
               row.expect_interaction ? "true" : "false",
               row.expect_interaction ? 0U : 3U,
               hidden_root_capture.event_root_script_pointer_hits);
        if (row.expect_interaction)
            fputs("null", stdout);
        else
            printf("\"0x%08" PRIX32 "\"",
                   hidden_root_capture.event_first_root_script_pointer);
        fputs("},\"input_sequence_attempts\":[", stdout);
        if (row.expect_interaction) {
            ++interactive_count;
            if ((row.actual_walk_required && walked == 0U)
                || !core->saveState(core, interaction_state))
                s61_die("catalog post-walk state capture failed");
            memcpy(interaction_video, s61_video, sizeof(s61_video));
            for (unsigned sequence_index = 0U;
                 sequence_index < row.input_sequence_count;
                 ++sequence_index) {
                const struct S61CatalogInputSequence *sequence =
                    &row.input_sequences[sequence_index];
                if (!core->loadState(core, interaction_state))
                    s61_die("catalog post-walk state restore failed");
                const struct S61ExternalControl *rfu_control =
                    s61_catalog_rfu_control(&row);
                s61_rfu_attempt_begin(
                    core, rom_path, save_path, interaction_state,
                    state_size, rfu_control, &row);
                char effect_case_id[S61_EFFECT_MAX_CASE_ID];
                s61_effect_observer_sequence_case_id(
                    effect_case_id, sizeof(effect_case_id), row.case_id,
                    sequence_index);
                /* Each input sequence is an independent execution case.
                 * Its raw preimage is captured immediately after restoring
                 * the exact post-walk state; map load and physical approach
                 * therefore cannot contribute hooks or state transitions. */
                s61_effect_observer_begin_case(core, effect_case_id);
                memcpy(s61_video, interaction_video, sizeof(s61_video));
                char label[1024];
                int label_size = snprintf(
                    label, sizeof(label), "%s-%s",
                    row.case_id, sequence->sequence_id);
                if (label_size <= 0 || (size_t)label_size >= sizeof(label))
                    s61_die("catalog choice artifact label is too long");
                char artifact[4096];
                struct S61Capture capture = s61_new_capture(
                    directory, label, artifact, sizeof(artifact));
                /* Each sequence owns a fresh counter armed after physical
                 * walk, facing and exact template/live identity validation.
                 * No map-load or approach hit can satisfy this contract. */
                capture.event_root_script_pointer = row.runtime_root;
                s61_begin_internal_control_capture(
                    core, &row, sequence, &capture);
                struct S61SequenceDriveResult drive =
                    s61_drive_input_sequence(
                        core, sequence, &capture, true);
                struct S61RfuAttemptEvidence rfu_evidence = {0};
                s61_rfu_attempt_end(&capture, &rfu_evidence);
                bool rfu_exact = !rfu_evidence.applicable
                    || rfu_evidence.exact;
                if (rfu_evidence.applicable) {
                    ++link_session_attempt_count;
                    if (rfu_evidence.center_link_session) {
                        ++center_link_session_attempt_count;
                        center_link_host_memory_write_count +=
                            rfu_evidence.host_memory_writes;
                        if (!rfu_evidence.exact)
                            ++center_link_session_failure_count;
                    } else {
                        ++rfu_session_attempt_count;
                        rfu_host_memory_write_count +=
                            rfu_evidence.host_memory_writes;
                        if (!rfu_evidence.exact)
                            ++rfu_session_failure_count;
                    }
                }
                bool internal_controls_ok = s61_internal_controls_ok(
                    core, &row, sequence);
                s61_end_internal_control_capture();
                bool terminal_seen = drive.terminal_seen;
                bool battle_started = s61_battle_active(core);
                bool field_released = world_overworld(core)
                    && !world_script_enabled(core) && !battle_started;
                bool invalid_control_flow = capture.invalid_control_flow;
                bool root_script_failure =
                    capture.event_root_script_pointer_hits == 0U
                    || capture.event_first_root_script_pointer
                        != row.runtime_root
                    || capture.event_first_root_group
                        != row.interaction.group
                    || capture.event_first_root_map != row.interaction.map
                    || capture.event_first_root_x != row.stance_x
                    || capture.event_first_root_y != row.stance_y;
                bool empty = !invalid_control_flow
                    && sequence->visible_text_expected
                    && capture.printer_call_count == 0U;
                bool unexpected_visible_text = !invalid_control_flow
                    && !sequence->visible_text_expected
                    && capture.printer_call_count != 0U;
                bool softlock = !invalid_control_flow
                    && (!terminal_seen || drive.premature_terminal
                        || drive.steps_consumed != sequence->step_count
                        || (!field_released && !battle_started));
                bool terminal_mismatch = !softlock
                    && !invalid_control_flow
                    && !s61_catalog_terminal_matches(
                        row.terminal, field_released, battle_started);
                bool frame_diff_failure = !invalid_control_flow &&
                    capture.maximum_baseline_pixel_difference < 2000U;
                s61_snapshot_side_effects(
                    core, &row.interaction, side_after);
                struct S61BattleLifecycleResult battle_lifecycle = {0};
                struct S61PostBattleContinuationResult
                    post_battle_continuation = {0};
                struct S61FieldRoundtripResult field_roundtrip = {0};
                if (battle_started) {
                    battle_lifecycle = s61_complete_battle_lifecycle(
                        core, row.case_id,
                        side_after->world.location.group,
                        side_after->world.location.map, sequence,
                        &post_battle_continuation);
                    s61_snapshot_side_effects(
                        core, &row.interaction, side_final);
                } else if (field_released) {
                    field_roundtrip = s61_field_roundtrip(
                        core, row.case_id,
                        side_after->world.location.group,
                        side_after->world.location.map);
                    s61_snapshot_side_effects(
                        core, &row.interaction, side_final);
                } else {
                    memcpy(side_final, side_after, sizeof(*side_final));
                }
                s61_finalize_facility_execution(core, &capture);
                /* Close only after this sequence has reached its final field
                 * state (including post-battle continuation/recovery).  The
                 * next sequence restores the same post-walk preimage and
                 * receives a fresh ordinal/counter namespace. */
                s61_effect_observer_end_case(core);
                bool field_roundtrip_failure = field_released
                    && !s61_field_roundtrip_exact(&field_roundtrip);
                bool facility_active_boundary = battle_started
                    && post_battle_continuation.facility_active_boundary;
                bool input_recovery_failure = !invalid_control_flow &&
                    (field_released
                        ? (field_roundtrip_failure
                           || !side_final->input.field_input_recovered)
                        : battle_started
                            ? (!side_after->input.battle_input_owned
                               || !battle_lifecycle.completed_via_keys
                               || (facility_active_boundary
                                   ? battle_lifecycle
                                           .field_released_after_battle
                                       || battle_lifecycle.start_menu_opened
                                       || battle_lifecycle
                                           .field_input_recovered
                                   : !battle_lifecycle
                                           .field_released_after_battle
                                       || !battle_lifecycle.start_menu_opened
                                       || !battle_lifecycle
                                           .field_input_recovered))
                            : true);
                bool success = !invalid_control_flow && !empty
                    && !unexpected_visible_text && !softlock
                    && !terminal_mismatch
                    && !frame_diff_failure && !input_recovery_failure
                    && internal_controls_ok && !root_script_failure
                    && rfu_exact;
                const char *reason = invalid_control_flow
                    ? "INVALID_CONTROL_FLOW"
                    : root_script_failure ? "ROOT_SCRIPT_NOT_OBSERVED"
                    : empty ? "EMPTY_TEXT"
                    : unexpected_visible_text ? "UNEXPECTED_VISIBLE_TEXT"
                    : softlock ? "SOFTLOCK"
                    : terminal_mismatch ? "TERMINAL_MISMATCH"
                    : frame_diff_failure ? "NO_FRAME_DIFF"
                    : field_roundtrip_failure
                        ? "FIELD_START_B_ROUNDTRIP_FAILED"
                    : input_recovery_failure ? "INPUT_NOT_RECOVERED"
                    : !internal_controls_ok ? "INTERNAL_CONTROL_MISMATCH"
                    : !rfu_exact ? "RFU_SESSION_MISMATCH"
                    : "NONE";
                if (sequence_index != 0U)
                    putchar(',');
                printf("{\"sequence_id\":\"%s\","
                       "\"expected_static_branch_token\":\"%s\","
                       "\"visible_text_expected\":%s,"
                       "\"silent_text_basis_sha256\":%s%s%s,"
                       "\"input_tokens\":[",
                       sequence->sequence_id,
                       sequence->expected_branch_token,
                       sequence->visible_text_expected ? "true" : "false",
                       sequence->visible_text_expected ? "null" : "\"",
                       sequence->visible_text_expected
                           ? "" : sequence->silent_basis_sha256,
                       sequence->visible_text_expected ? "" : "\"");
                for (unsigned step_index = 0U;
                     step_index < sequence->step_count; ++step_index) {
                    if (step_index != 0U)
                        putchar(',');
                    printf("\"%s\"", sequence->steps[step_index].token);
                }
                printf("],\"input_step_count\":%u,"
                       "\"input_steps_consumed\":%u,"
                       "\"premature_terminal\":%s,"
                       "\"success\":%s,"
                       "\"failure_reason\":\"%s\",\"terminal\":\"%s\","
                       "\"field_released\":%s,\"battle_started\":%s,"
                       "\"post_battle\":",
                       sequence->step_count, drive.steps_consumed,
                       drive.premature_terminal ? "true" : "false",
                       success ? "true" : "false",
                       reason, battle_started ? "BATTLE_START"
                           : field_released ? "FIELD_RELEASE" : "NONE",
                       field_released ? "true" : "false",
                       battle_started ? "true" : "false");
                s61_print_battle_lifecycle(&battle_lifecycle);
                printf(",\"post_battle_continuation\":");
                s61_print_post_battle_continuation(
                    &post_battle_continuation, sequence);
                printf(",\"field_roundtrip\":");
                if (field_released)
                    s61_print_field_roundtrip(&field_roundtrip);
                else
                    fputs("null", stdout);
                printf(",\"root_script_pointer_expected\":"
                       "\"0x%08" PRIX32 "\","
                       "\"root_counter_armed_after_identity\":true,"
                       "\"root_script_pointer_hits\":%u,"
                       "\"first_root_script_pointer\":"
                       "\"0x%08" PRIX32 "\","
                       "\"first_root_context\":{"
                       "\"map\":\"%u/%u\",\"player\":[%u,%u]},"
                       "\"preinteraction_object_identity\":",
                       row.runtime_root,
                       capture.event_root_script_pointer_hits,
                       capture.event_first_root_script_pointer,
                       capture.event_first_root_group,
                       capture.event_first_root_map,
                       capture.event_first_root_x,
                       capture.event_first_root_y);
                s61_print_catalog_preinteraction_identity(&row, side_before);
                printf(",\"capture\":");
                s61_print_capture(&capture);
                printf(",\"internal_controls\":");
                s61_print_internal_controls(&row, sequence);
                printf(",\"deferred_external_controls\":");
                s61_print_deferred_external_controls(core, &row, &capture);
                printf(",\"rfu_session\":");
                s61_print_rfu_attempt_evidence(&rfu_evidence);
                printf(",\"battle_start_side_effects\":");
                if (battle_started)
                    s61_print_side_effects(side_before, side_after);
                else
                    fputs("null", stdout);
                printf(",\"side_effects\":");
                s61_print_side_effects(side_before, side_final);
                printf("}");
                s61_write_peak_frame(&capture, "peak");
                s61_release_facility_execution(&capture);
                ++choice_attempt_count;
                if (success)
                    ++successful_path_count;
                else
                    ++failed;
                if (empty)
                    ++empty_text;
                if (softlock)
                    ++softlocks;
                if (terminal_mismatch)
                    ++terminal_mismatches;
                if (frame_diff_failure)
                    ++frame_diff_failures;
                if (input_recovery_failure)
                    ++input_recovery_failures;
                if (invalid_control_flow)
                    ++invalid_control_flow_failures;
                if (!internal_controls_ok)
                    ++internal_control_failures;
                if (root_script_failure)
                    ++root_script_failures;
            }
        } else {
            ++hidden_count;
        }
        uint32_t save1 = world_save1(core, row.case_id);
        printf("],\"final_map\":\"%u/%u\"}",
               read8(core, save1 + 4U), read8(core, save1 + 5U));
        ++count;
    }
    if (ferror(stream) || fclose(stream) != 0)
        s61_die("catalog TSV read/close failed");
    if (count == 0U)
        s61_die("catalog TSV has zero interaction rows");
    printf("],\"status\":\"%s\",\"fixture_count\":%u,"
           "\"interactive_count\":%u,\"hidden_count\":%u,"
           "\"input_sequence_attempt_count\":%u,"
           "\"successful_path_count\":%u,"
           "\"failed\":%u,\"empty_text\":%u,\"softlocks\":%u,"
           "\"terminal_mismatches\":%u,\"frame_diff_failures\":%u,"
           "\"input_recovery_failures\":%u,"
           "\"invalid_control_flow_failures\":%u,"
           "\"internal_control_failures\":%u,"
           "\"root_script_failures\":%u,"
           "\"link_session_attempt_count\":%u,"
           "\"rfu_session_attempt_count\":%u,"
           "\"rfu_session_failure_count\":%u,"
           "\"rfu_host_memory_write_count\":%u,"
           "\"center_link_session_attempt_count\":%u,"
           "\"center_link_session_failure_count\":%u,"
           "\"center_link_host_memory_write_count\":%u,"
           "\"side_effect_capture_failures\":0,"
           "\"untested\":0,\"warnings\":0}\n",
           failed == 0U ? "PASS" : "FAIL", count,
           interactive_count, hidden_count, choice_attempt_count,
           successful_path_count, failed, empty_text, softlocks,
           terminal_mismatches, frame_diff_failures,
           input_recovery_failures, invalid_control_flow_failures,
           internal_control_failures, root_script_failures,
           link_session_attempt_count,
           rfu_session_attempt_count, rfu_session_failure_count,
           rfu_host_memory_write_count,
           center_link_session_attempt_count,
           center_link_session_failure_count,
           center_link_host_memory_write_count);
    free(side_after);
    free(side_final);
    free(side_before);
    free(approach_after);
    free(approach_before);
    free(interaction_video);
    free(interaction_state);
    free(base_state);
    bootstrap_close_core(core);
}

static void s61_event_delta(uint16_t key, int *dx, int *dy)
{
    *dx = key == WORLD_KEY_RIGHT ? 1 : key == WORLD_KEY_LEFT ? -1 : 0;
    *dy = key == WORLD_KEY_DOWN ? 1 : key == WORLD_KEY_UP ? -1 : 0;
    if (*dx == 0 && *dy == 0)
        s61_die("event runtime direction is not cardinal");
}

static const char *s61_event_key_name(uint16_t key)
{
    if (key == WORLD_KEY_UP)
        return "UP";
    if (key == WORLD_KEY_DOWN)
        return "DOWN";
    if (key == WORLD_KEY_LEFT)
        return "LEFT";
    if (key == WORLD_KEY_RIGHT)
        return "RIGHT";
    s61_die("event runtime evidence key is not cardinal");
    return "";
}

static void s61_event_stock_warp(struct mCore *core, const char *case_id,
                                 uint8_t group, uint8_t map,
                                 uint16_t x, uint16_t y)
{
    struct S61Interaction interaction = {
        group, map, x, y, WORLD_KEY_DOWN, 1U, 0U,
    };
    struct Fixture fixture = s61_world_fixture(case_id, &interaction);
    s61_catalog_warp(core, &fixture);
}

static void s61_event_prepare_hidden_state(
    struct mCore *core, const struct S61EventTriggerRow *trigger)
{
    uint32_t function = strcmp(trigger->hidden_variant,
                               "ALREADY_COLLECTED") == 0
        ? WORLD_FLAG_SET : WORLD_FLAG_CLEAR;
    (void)s61_call_synced(
        core, function, trigger->collection_flag, 0U, 0U, 0U);
    bool set = s61_flag(core, trigger->collection_flag) != 0U;
    if (set != (strcmp(trigger->hidden_variant,
                       "ALREADY_COLLECTED") == 0))
        s61_die("event runtime hidden collection flag preparation differs");
    if (trigger->underfoot) {
        if (s61_call_synced(
                core, BATTLE_CORE_CHECK_BAG_HAS_ITEM,
                261U, 1U, 0U, 0U) == 0U)
            s61_die("event runtime Itemfinder fixture lacks item 261");
        write16(core, s61_catalog_save1(core) + 0x296U, 261U);
        if (read16(core, s61_catalog_save1(core) + 0x296U) != 261U)
            s61_die("event runtime Itemfinder registration differs");
    }
}

static bool s61_event_map_engine_seed(
    const struct S61EventTriggerRow *trigger)
{
    return strcmp(trigger->transition_contract,
                  "ENGINE_PLAYER_TELEPORT_MAP_LOAD") == 0
        || strcmp(trigger->transition_contract,
                  "ENGINE_TELEPORT_THEN_FIELD_RETURN") == 0;
}

static bool s61_event_map_connection_seed(
    const struct S61EventTriggerRow *trigger)
{
    return strcmp(trigger->transition_contract,
                  "STOCK_CONNECTION_BOUNDARY_STEP") == 0
        || strcmp(trigger->transition_contract,
                  "STOCK_CONNECTION_THEN_FIELD_RETURN") == 0;
}

static unsigned s61_event_prepare_physical_trigger(
    struct mCore *core, const struct S61EventTriggerRow *trigger)
{
    if (trigger->effective_kind == S61_EVENT_OBJECT_FACE_A
        || trigger->effective_kind == S61_EVENT_BG_FACE_A
        || trigger->effective_kind == S61_EVENT_COORD_STEP
        || trigger->effective_kind == S61_EVENT_HIDDEN_ITEM) {
        /* Host setup ends at the producer's exact start tile.  The event
         * dispatcher consumes every cardinal token and checks every loaded-
         * field coordinate, including paths that depend on dynamic topology. */
        s61_event_stock_warp(
            core, trigger->case_id, trigger->group, trigger->map,
            trigger->walk_start_x, trigger->walk_start_y);
    } else if (trigger->effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
               && !s61_event_map_engine_seed(trigger)) {
        /* Boundary seeds start from the oracle-pinned predecessor.  A resume
         * callback is never called by the host: its only producer is the real
         * boundary step followed by START-menu field return. */
        s61_event_stock_warp(
            core, trigger->case_id,
            trigger->source_group, trigger->source_map,
            trigger->predecessor_x, trigger->predecessor_y);
    } else if (trigger->effective_kind == S61_EVENT_MAP_TRANSITION_LOAD) {
        /* ENGINE_PLAYER_TELEPORT_MAP_LOAD is itself the physical producer.
         * Invoke it only after instruction capture has been armed. */
    } else {
        s61_die("event runtime trigger kind is not physically supported");
    }
    if (trigger->effective_kind == S61_EVENT_COORD_STEP
        && trigger->trigger_var != 0U) {
        (void)s61_call_synced(
            core, WORLD_VAR_SET, trigger->trigger_var,
            trigger->trigger_value, 0U, 0U);
        if (s61_call_synced(
                core, WORLD_VAR_GET, trigger->trigger_var,
                0U, 0U, 0U) != trigger->trigger_value)
            s61_die("event runtime COORD condition preparation differs");
    }
    if (trigger->effective_kind == S61_EVENT_HIDDEN_ITEM)
        s61_event_prepare_hidden_state(core, trigger);
    return 0U;
}

static void s61_event_assert_prefix(
    const struct S61CatalogInputSequence *sequence,
    const struct S61EventTriggerRow *trigger)
{
    if (sequence->step_count < trigger->trigger_prefix_count)
        s61_die("event runtime sequence shorter than trigger prefix");
    const char *expected[3] = {NULL, NULL, NULL};
    unsigned count = 0U;
    if (trigger->effective_kind == S61_EVENT_OBJECT_FACE_A
        || trigger->effective_kind == S61_EVENT_BG_FACE_A) {
        expected[0] = "WALK_TO_ADJACENT";
        expected[1] = "FACE_REQUIRED_DIRECTION";
        expected[2] = "A";
        count = 3U;
    } else if (trigger->effective_kind == S61_EVENT_COORD_STEP) {
        expected[0] = "WALK_FROM_ADJACENT_ONTO_COORD";
        count = 1U;
    } else if (trigger->effective_kind == S61_EVENT_HIDDEN_ITEM) {
        if (trigger->underfoot) {
            expected[0] = "WALK_ONTO_COORD";
            expected[1] = "USE_ITEMFINDER";
            count = 2U;
        } else {
            expected[0] = "WALK_TO_ADJACENT";
            expected[1] = "FACE_REQUIRED_DIRECTION";
            expected[2] = "A";
            count = 3U;
        }
    } else if (trigger->effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
               && strcmp(trigger->seed_kind, "stock_warp") == 0) {
        expected[0] = "WALK_ONTO_WARP";
        expected[1] = "WAIT_MAP_LOAD";
        count = 2U;
    } else if (trigger->effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
               && strcmp(trigger->seed_kind, "stock_connection") == 0) {
        expected[0] = "WALK_ACROSS_CONNECTION";
        expected[1] = "WAIT_FIRST_ROOT_HIT";
        count = 2U;
    } else if (trigger->effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
               && strcmp(trigger->seed_kind, "engine_teleport") == 0) {
        expected[0] = "ENGINE_PLAYER_TELEPORT_MAP_LOAD";
        expected[1] = "WAIT_FIRST_ROOT_HIT";
        count = 2U;
    } else if (trigger->effective_kind == S61_EVENT_MAP_TRANSITION_LOAD) {
        expected[0] = "START";
        expected[1] = "B";
        count = 2U;
    } else {
        count = trigger->trigger_prefix_count;
    }
    if (count != trigger->trigger_prefix_count)
        s61_die("event runtime trigger prefix count differs");
    for (unsigned index = 0U; index < count && expected[index] != NULL;
         ++index) {
        if (strcmp(sequence->steps[index].token, expected[index]) != 0)
            s61_die("event runtime trigger token differs");
    }
}

static bool s61_event_resume_callback_ordered(
    const struct S61Capture *capture)
{
    return capture->event_first_callback_install_ordinal != 0U
        && capture->event_first_callback_dispatch_ordinal
            >= capture->event_first_callback_install_ordinal
        && capture->event_first_resume_callback_ordinal
            >= capture->event_first_callback_dispatch_ordinal
        && capture->event_map_field_return_first_root_ordinal
            >= capture->event_first_resume_callback_ordinal;
}

static void s61_event_finalize_map_evidence(
    const struct S61EventTriggerRow *trigger,
    const struct S61Capture *capture,
    struct S61SequenceDriveResult *result)
{
    if (trigger->effective_kind != S61_EVENT_MAP_TRANSITION_LOAD)
        return;
    const struct S61MapPhaseControlEvidence *pre_transition =
        &capture->event_map_phase_controls[0];
    const struct S61MapPhaseControlEvidence *pre_field =
        &capture->event_map_phase_controls[1];
    const struct S61MapEngineClearEvidence *clear =
        &capture->event_map_engine_clear;
    bool first_attempt_exact = false;
    bool first_tag2_exact = false;
    for (unsigned index = 0U;
         index < capture->event_map_lifecycle_observation_count; ++index) {
        const struct S61MapLifecycleObservation *observation =
            &capture->event_map_lifecycle_observations[index];
        bool attempt = observation->kind == S61_MAP_OBSERVATION_DIRECT_ATTEMPT
            || observation->kind == S61_MAP_OBSERVATION_CONDITIONAL_ATTEMPT;
        if (!attempt)
            continue;
        if (observation->attempt_ordinal == clear->first_attempt_ordinal
            && observation->tag == clear->first_attempt_tag
            && observation->instruction_ordinal
                == clear->capture_instruction_ordinal)
            first_attempt_exact = true;
        if (observation->tag == 2U
            && observation->attempt_ordinal == pre_field->first_attempt_ordinal
            && observation->instruction_ordinal
                == pre_field->application_instruction_ordinal)
            first_tag2_exact = true;
    }
    if (!capture->event_map_producer_started
        || !pre_transition->applied
        || pre_transition->application_count != 1U
        || !pre_transition->readback_exact
        || pre_transition->first_attempt_ordinal != 0U
        || !pre_field->applied || pre_field->application_count != 1U
        || !pre_field->readback_exact
        || !clear->preimage_captured || !clear->postimage_captured
        || clear->capture_count != 1U || !clear->readback_exact
        || clear->first_attempt_ordinal != 0U
        || pre_transition->application_instruction_ordinal
            >= clear->capture_instruction_ordinal
        || pre_field->application_instruction_ordinal
            < clear->capture_instruction_ordinal
        || !first_attempt_exact || !first_tag2_exact)
        s61_die("event runtime MAP phase/engine-clear evidence differs");
    if (strcmp(trigger->seed_kind, "resume_callback") != 0)
        return;
    result->map_field_return_callback_dispatched =
        capture->event_resume_callback_hits != 0U
        && capture->event_callback_install_instruction_hits != 0U
        && capture->event_callback_dispatch_instruction_hits != 0U;
    result->map_callback_ordered =
        s61_event_resume_callback_ordered(capture);
    result->map_input_recovered =
        result->map_start_pressed && result->map_start_menu_opened
        && result->map_back_pressed
        && result->map_field_return_callback_dispatched
        && result->map_callback_ordered
        && capture->event_map_field_return_first_root_group
            == trigger->field_return_group
        && capture->event_map_field_return_first_root_map
            == trigger->field_return_map
        && !capture->invalid_control_flow;
}

static void s61_event_wait_for_map_field_quiescence(
    struct mCore *core, const struct S61EventTriggerRow *trigger,
    struct S61Capture *capture)
{
    unsigned stable_windows = 0U;
    unsigned previous_observations =
        capture->event_map_lifecycle_observation_count;
    for (unsigned window = 0U; window < 240U; ++window) {
        s61_step_capture_frames(core, 0U, 15U, capture);
        if (capture->invalid_control_flow)
            return;
        uint32_t save1 = s61_catalog_save1(core);
        bool destination =
            read8(core, save1 + 4U) == trigger->destination_group
            && read8(core, save1 + 5U) == trigger->destination_map;
        bool lifecycle_handoff =
            capture->event_immediate_expected_root_callsite_hits != 0U
            || capture->event_map_lifecycle_quiescent
            || (strcmp(trigger->seed_kind, "resume_callback") == 0
                && s61_field_terminal(core));
        bool stable =
            capture->event_map_lifecycle_observation_count
                == previous_observations
            && !capture->event_map_lifecycle_attempt_active;
        if (destination && lifecycle_handoff && stable) {
            if (++stable_windows >= 2U)
                return;
        } else {
            stable_windows = 0U;
        }
        previous_observations =
            capture->event_map_lifecycle_observation_count;
    }
    s61_die("event runtime MAP field quiescence exceeded bound");
}

static unsigned s61_event_execute_exact_walk(
    struct mCore *core, const struct S61EventTriggerRow *trigger,
    struct S61Capture *capture, struct S61SequenceDriveResult *result,
    unsigned control_token_index)
{
    uint32_t save1 = s61_catalog_save1(core);
    result->event_walk_start_confirmed =
        read8(core, save1 + 4U) == trigger->group
        && read8(core, save1 + 5U) == trigger->map
        && read16(core, save1) == trigger->walk_start_x
        && read16(core, save1 + 2U) == trigger->walk_start_y;
    if (!result->event_walk_start_confirmed)
        s61_die("event runtime exact walk start/map differs");
    int expected_x = trigger->walk_start_x;
    int expected_y = trigger->walk_start_y;
    result->event_walk_path_exact = true;
    for (unsigned index = 0U; index < trigger->walk_key_count; ++index) {
        int dx = 0;
        int dy = 0;
        s61_event_delta(trigger->walk_keys[index], &dx, &dy);
        expected_x += dx;
        expected_y += dy;
        s61_active_control_token_index = control_token_index;
        s61_step_capture_pulse(
            core, trigger->walk_keys[index], 2U, 60U, capture);
        save1 = s61_catalog_save1(core);
        uint16_t observed_x = read16(core, save1);
        uint16_t observed_y = read16(core, save1 + 2U);
        result->event_walk_observed_x[index] = observed_x;
        result->event_walk_observed_y[index] = observed_y;
        ++result->event_walk_step_count;
        if (observed_x != (uint16_t)expected_x
            || observed_y != (uint16_t)expected_y) {
            result->event_walk_path_exact = false;
            s61_die("event runtime loaded-field intermediate walk tile differs");
        }
    }
    result->event_walk_final_tile_confirmed =
        result->event_walk_step_count == trigger->walk_key_count
        && result->event_walk_path_exact;
    if (!result->event_walk_final_tile_confirmed)
        s61_die("event runtime exact walk did not reach final tile");
    return result->event_walk_step_count;
}

static unsigned s61_event_execute_prefix(
    struct mCore *core, const struct S61EventTriggerRow *trigger,
    const struct S61CatalogInputSequence *sequence,
    struct S61Capture *capture, struct S61SequenceDriveResult *result)
{
    unsigned walked = 0U;
    if (trigger->effective_kind == S61_EVENT_OBJECT_FACE_A
        || trigger->effective_kind == S61_EVENT_BG_FACE_A
        || (trigger->effective_kind == S61_EVENT_HIDDEN_ITEM
            && !trigger->underfoot)) {
        walked = s61_event_execute_exact_walk(
            core, trigger, capture, result, 0U);
        uint32_t save1 = s61_catalog_save1(core);
        result->event_walk_stance_confirmed =
            read16(core, save1) == trigger->stance_x
            && read16(core, save1 + 2U) == trigger->stance_y;
        if (!result->event_walk_stance_confirmed)
            s61_die("event runtime face walk did not reach exact stance");
        s61_active_control_token_index = 1U;
        s61_step_capture_pulse(core, trigger->face_key, 2U, 12U, capture);
        save1 = s61_catalog_save1(core);
        if (read16(core, save1) != trigger->stance_x
            || read16(core, save1 + 2U) != trigger->stance_y)
            s61_die("event runtime facing input moved off exact stance");
        s61_active_control_token_index = 2U;
        s61_step_capture_pulse(core, WORLD_KEY_A, 2U, 60U, capture);
    } else if (trigger->effective_kind == S61_EVENT_COORD_STEP
               || (trigger->effective_kind == S61_EVENT_HIDDEN_ITEM
                   && trigger->underfoot)) {
        walked = s61_event_execute_exact_walk(
            core, trigger, capture, result, 0U);
        if (trigger->effective_kind == S61_EVENT_HIDDEN_ITEM) {
            uint32_t save1 = s61_catalog_save1(core);
            if (read16(core, save1) != trigger->x
                || read16(core, save1 + 2U) != trigger->y)
                s61_die("event runtime Itemfinder did not reach underfoot tile");
            s61_active_control_token_index = 1U;
            s61_step_capture_pulse(core, S61_KEY_SELECT, 2U, 180U, capture);
        }
    } else if (trigger->effective_kind == S61_EVENT_MAP_TRANSITION_LOAD) {
        bool resume = strcmp(trigger->seed_kind, "resume_callback") == 0;
        bool engine = s61_event_map_engine_seed(trigger);
        uint32_t save1 = s61_catalog_save1(core);
        if (engine) {
            /* Capture is already armed here.  BOOTSTRAP_KANTO_WARP is the
             * engine map-load producer, not a substitute for the map script. */
            result->map_source_setup = true;
            result->map_predecessor_tile = true;
            s61_active_control_token_index = resume
                ? S61_CATALOG_MAX_INPUT_STEPS : 0U;
            s61_map_phase_control_apply(core, capture, 0U, 0U);
            s61_map_engine_clear_capture_preimage(core, capture);
            capture->event_map_producer_started = true;
            if (!s61_sync_host_call_pc(core))
                s61_die("event runtime engine teleport scheduler differs");
            (void)call_preserving(
                core, BOOTSTRAP_KANTO_WARP,
                trigger->destination_group, trigger->destination_map,
                trigger->arrival_x, trigger->arrival_y);
            result->map_engine_teleport = true;
        } else {
            result->map_source_setup =
                read8(core, save1 + 4U) == trigger->source_group
                && read8(core, save1 + 5U) == trigger->source_map;
            result->map_predecessor_tile =
                read16(core, save1) == trigger->predecessor_x
                && read16(core, save1 + 2U) == trigger->predecessor_y;
            if (!result->map_source_setup || !result->map_predecessor_tile)
                s61_die("event runtime MAP predecessor setup differs");
            s61_active_control_token_index = resume
                ? S61_CATALOG_MAX_INPUT_STEPS : 0U;
            s61_map_phase_control_apply(core, capture, 0U, 0U);
            s61_map_engine_clear_capture_preimage(core, capture);
            capture->event_map_producer_started = true;
            s61_step_capture_pulse(
                core, trigger->trigger_key, 2U, 30U, capture);
            ++walked;
            bool connection = s61_event_map_connection_seed(trigger);
            result->map_real_connection_step = connection;
            result->map_real_warp_step = !connection;
        }
        if (!resume)
            s61_active_control_token_index = 1U;
        s61_event_wait_for_map_field_quiescence(core, trigger, capture);
        result->map_load_root_identity_captured =
            capture->event_immediate_expected_root_callsite_hits != 0U
            && capture->event_immediate_expected_root_executor_hits != 0U;
        if (result->map_load_root_identity_captured) {
            result->map_load_root_group =
                capture->event_first_expected_root_group;
            result->map_load_root_map = capture->event_first_expected_root_map;
            result->map_load_root_x = capture->event_first_expected_root_x;
            result->map_load_root_y = capture->event_first_expected_root_y;
        } else if (resume) {
            /* tag 5/7 are intentionally absent from the initial load.  Their
             * required root hit is captured after START/B; retain the settled
             * target identity here solely as the predecessor field proof. */
            save1 = s61_catalog_save1(core);
            result->map_load_root_group = read8(core, save1 + 4U);
            result->map_load_root_map = read8(core, save1 + 5U);
            result->map_load_root_x = read16(core, save1);
            result->map_load_root_y = read16(core, save1 + 2U);
        }
        bool load_identity_available =
            result->map_load_root_identity_captured || resume;
        result->map_destination_loaded =
            load_identity_available
            && result->map_load_root_group == trigger->destination_group
            && result->map_load_root_map == trigger->destination_map;
        result->map_arrival_tile =
            load_identity_available
            && result->map_load_root_x == trigger->arrival_x
            && result->map_load_root_y == trigger->arrival_y;
        if (!result->map_destination_loaded || !result->map_arrival_tile
            || (!resume && !result->map_load_root_identity_captured))
            s61_die("event runtime MAP first-root transition identity differs");
        if (resume) {
            result->map_owner_hits_before_start =
                capture->event_immediate_expected_root_callsite_hits;
            result->map_field_recovered_before_start =
                s61_field_terminal(core);
            if (!result->map_field_recovered_before_start)
                s61_die("event runtime MAP resume predecessor did not settle");
            s61_map_lifecycle_mark_phase(
                core, capture, S61_MAP_LIFECYCLE_PHASE_FIELD_RETURN);
            capture->suppress_semantic_content = true;
            s61_active_control_token_index = 0U;
            result->map_start_pressed = true;
            s61_step_capture_pulse(
                core, sequence->steps[0].key,
                sequence->steps[0].pressed,
                sequence->steps[0].released, capture);
            result->map_start_menu_opened =
                read32(core, S61_START_MENU_CALLBACK) == S61_START_MENU_INPUT;
            if (!result->map_start_menu_opened)
                s61_die("event runtime MAP resume START menu did not open");
            capture->suppress_semantic_content = false;
            s61_active_control_token_index = 1U;
            result->map_back_pressed = true;
            s61_step_capture_pulse(
                core, sequence->steps[1].key,
                sequence->steps[1].pressed,
                sequence->steps[1].released, capture);
            result->map_field_return_callback_dispatched =
                capture->event_resume_callback_hits != 0U
                && capture->event_callback_install_instruction_hits != 0U
                && capture->event_callback_dispatch_instruction_hits != 0U;
            result->map_callback_ordered =
                s61_event_resume_callback_ordered(capture);
            result->map_input_recovered =
                result->map_field_return_callback_dispatched
                && result->map_callback_ordered
                && !capture->invalid_control_flow;
        }
    }
    return walked;
}

static struct S61SequenceDriveResult s61_drive_event_sequence(
    struct mCore *core, const struct S61EventTriggerRow *trigger,
    const struct S61CatalogInputSequence *sequence,
    struct S61Capture *capture)
{
    struct S61SequenceDriveResult result = {0};
    write16(core, WORLD_SPECIAL_RESULT, 0xFFFFU);
    result.trigger_real_walk_steps = s61_event_execute_prefix(
        core, trigger, sequence, capture, &result);
    result.steps_consumed = trigger->trigger_prefix_count;
    bool saw_owner = capture->event_root_script_pointer_hits != 0U
        || capture->event_immediate_expected_root_callsite_hits != 0U
        || capture->event_consumer_instruction_hits != 0U
        || capture->event_caller_script_pointer_hits != 0U
        || capture->printer_call_count != 0U || world_script_enabled(core);
    for (unsigned index = trigger->trigger_prefix_count;
         index < sequence->step_count; ++index) {
        s61_active_control_token_index = index;
        if (s61_field_terminal(core) || s61_battle_active(core)) {
            result.premature_terminal = true;
            return result;
        }
        const struct S61CatalogInputStep *step = &sequence->steps[index];
        if (step->wait_frames != 0U)
            s61_step_capture_frames(core, 0U, step->wait_frames, capture);
        else
            s61_step_capture_pulse(
                core, step->key, step->pressed, step->released, capture);
        ++result.steps_consumed;
        if (capture->invalid_control_flow)
            return result;
        saw_owner = saw_owner || world_script_enabled(core)
            || capture->printer_call_count != 0U
            || capture->event_root_script_pointer_hits != 0U
            || capture->event_immediate_expected_root_callsite_hits != 0U;
    }
    unsigned quiet = 0U;
    for (unsigned tail = 0U; tail < 80U; ++tail) {
        if (s61_battle_active(core)) {
            result.terminal_seen = saw_owner;
            return result;
        }
        if (s61_field_terminal(core)) {
            if (saw_owner && ++quiet >= 6U) {
                result.terminal_seen = true;
                return result;
            }
        } else {
            quiet = 0U;
        }
        s61_step_capture_frames(core, 0U, 15U, capture);
        if (capture->invalid_control_flow)
            return result;
        saw_owner = saw_owner || world_script_enabled(core)
            || capture->printer_call_count != 0U
            || capture->event_root_script_pointer_hits != 0U
            || capture->event_immediate_expected_root_callsite_hits != 0U;
    }
    return result;
}

static void s61_print_event_physical_walk_evidence(
    const struct S61EventTriggerRow *trigger,
    const struct S61SequenceDriveResult *drive)
{
    bool physical = trigger->effective_kind == S61_EVENT_OBJECT_FACE_A
        || trigger->effective_kind == S61_EVENT_BG_FACE_A
        || trigger->effective_kind == S61_EVENT_COORD_STEP
        || trigger->effective_kind == S61_EVENT_HIDDEN_ITEM;
    if (!physical) {
        fputs("null", stdout);
        return;
    }
    bool face = trigger->effective_kind == S61_EVENT_OBJECT_FACE_A
        || trigger->effective_kind == S61_EVENT_BG_FACE_A
        || (trigger->effective_kind == S61_EVENT_HIDDEN_ITEM
            && !trigger->underfoot);
    printf("{\"start_tile\":[%u,%u],\"walk_sequence\":[",
           trigger->walk_start_x, trigger->walk_start_y);
    for (unsigned index = 0U; index < trigger->walk_key_count; ++index)
        printf("%s\"%s\"", index == 0U ? "" : ",",
               s61_event_key_name(trigger->walk_keys[index]));
    fputs("],\"expected_tiles\":[", stdout);
    int expected_x = trigger->walk_start_x;
    int expected_y = trigger->walk_start_y;
    for (unsigned index = 0U; index < trigger->walk_key_count; ++index) {
        int dx = 0;
        int dy = 0;
        s61_event_delta(trigger->walk_keys[index], &dx, &dy);
        expected_x += dx;
        expected_y += dy;
        printf("%s[%d,%d]", index == 0U ? "" : ",",
               expected_x, expected_y);
    }
    fputs("],\"observed_tiles\":[", stdout);
    for (unsigned index = 0U; index < drive->event_walk_step_count; ++index)
        printf("%s[%u,%u]", index == 0U ? "" : ",",
               drive->event_walk_observed_x[index],
               drive->event_walk_observed_y[index]);
    printf("],\"step_count\":%u,\"start_tile_confirmed\":%s,"
           "\"all_intermediate_tiles_confirmed\":%s,"
           "\"final_tile_confirmed\":%s,\"stance_tile\":",
           drive->event_walk_step_count,
           drive->event_walk_start_confirmed ? "true" : "false",
           drive->event_walk_path_exact ? "true" : "false",
           drive->event_walk_final_tile_confirmed ? "true" : "false");
    if (face)
        printf("[%u,%u]", trigger->stance_x, trigger->stance_y);
    else
        fputs("null", stdout);
    printf(",\"stance_confirmed\":%s,\"trigger_key\":",
           drive->event_walk_stance_confirmed ? "true" : "false");
    if (face)
        fputs("null", stdout);
    else
        printf("\"%s\"", s61_event_key_name(trigger->path_trigger_key));
    fputs(",\"required_facing\":", stdout);
    if (face)
        printf("\"%s\"", s61_event_key_name(trigger->face_key));
    else
        fputs("null", stdout);
    printf(",\"runtime_topology_probe_required\":%s,"
           "\"runtime_topology_probe_satisfied\":%s}",
           trigger->runtime_topology_probe_required ? "true" : "false",
           (!trigger->runtime_topology_probe_required
            || (drive->event_walk_start_confirmed
                && drive->event_walk_final_tile_confirmed
                && drive->event_walk_stance_confirmed)) ? "true" : "false");
}

static const char *s61_map_lifecycle_phase_name(
    enum S61MapLifecyclePhase phase)
{
    if (phase == S61_MAP_LIFECYCLE_PHASE_INITIAL_LOAD)
        return "INITIAL_LOAD";
    if (phase == S61_MAP_LIFECYCLE_PHASE_FIELD_RETURN)
        return "FIELD_RETURN";
    if (phase == S61_MAP_LIFECYCLE_PHASE_NONE)
        return "NONE";
    s61_die("MAP lifecycle phase enum differs");
    return "INVALID";
}

static const char *s61_map_lifecycle_source_phase_name(
    enum S61MapLifecycleSourcePhase phase)
{
    static const char *const names[] = {
        "NONE", "INITIAL_TRANSITION", "INITIAL_LOAD", "INITIAL_RESUME",
        "INITIAL_WARP_IN", "PRE_FIELD_INPUT_ON_FRAME",
        "FIELD_RETURN_RESUME", "FIELD_RETURN_RETURN_TO_FIELD",
    };
    if ((unsigned)phase >= ARRAY_LEN(names))
        s61_die("MAP lifecycle source phase enum differs");
    return names[phase];
}

static const char *s61_map_lifecycle_producer_kind(
    const struct S61EventTriggerRow *trigger)
{
    if (strstr(trigger->transition_contract, "CONNECTION") != NULL)
        return "CONNECTION";
    if (strstr(trigger->transition_contract, "ENGINE") != NULL)
        return "ENGINE_TELEPORT";
    if (strstr(trigger->transition_contract, "WARP") != NULL)
        return "STOCK_WARP";
    s61_die("MAP lifecycle producer kind differs");
    return "INVALID";
}

static const char *s61_map_lifecycle_kind_name(
    enum S61MapLifecycleObservationKind kind)
{
    static const char *const names[] = {
        "PHASE_BOUNDARY",
        "DIRECT_ATTEMPT",
        "CONDITIONAL_ATTEMPT",
        "OUTER_MATCH",
        "DIRECT_RESULT",
        "DIRECT_DISPATCH",
        "DIRECT_RETURN",
        "CONDITIONAL_OUTER_RESULT",
        "CONDITION_SCAN",
        "CONDITION_COMPARE",
        "CONDITION_SELECTION",
        "CONDITIONAL_RETURN",
        "ROOT_EXECUTOR",
        "TAG2_DISPATCH",
        "TAG4_DISPATCH",
    };
    if ((unsigned)kind >= sizeof(names) / sizeof(names[0]))
        s61_die("MAP lifecycle observation kind enum differs");
    return names[kind];
}

static const char *s61_map_lifecycle_result_name(
    enum S61MapLifecycleAttemptResult result)
{
    static const char *const names[] = {
        "NONE", "TAG_ABSENT", "NO_CONDITION_MATCH", "DISPATCH",
    };
    if ((unsigned)result >= sizeof(names) / sizeof(names[0]))
        s61_die("MAP lifecycle attempt result enum differs");
    return names[result];
}

static void s61_print_map_lifecycle_optional_address(uint32_t address)
{
    if (address == 0U)
        fputs("null", stdout);
    else
        printf("\"0x%08" PRIX32 "\"", address);
}

static void s61_print_map_phase_control_evidence(
    const struct S61Capture *capture)
{
    static const char *const markers[] = {
        "PRE_TRANSITION", "PRE_FIELD_INPUT",
    };
    fputc('[', stdout);
    for (unsigned index = 0U; index < ARRAY_LEN(markers); ++index) {
        const struct S61MapPhaseControlEvidence *evidence =
            &capture->event_map_phase_controls[index];
        printf("%s{\"phase_marker\":\"%s\",\"applied\":%s,"
               "\"application_count\":%u,\"readback_exact\":%s,"
               "\"application_instruction_ordinal\":%" PRIu64 ","
               "\"first_attempt_ordinal\":%" PRIu32 "}",
               index == 0U ? "" : ",", markers[index],
               evidence->applied ? "true" : "false",
               evidence->application_count,
               evidence->readback_exact ? "true" : "false",
               evidence->application_instruction_ordinal,
               evidence->first_attempt_ordinal);
    }
    fputc(']', stdout);
}

static void s61_print_map_engine_clear_state(
    const struct S61MapEngineClearState *state)
{
    static const uint16_t system_flags[] = {
        0x0803U, 0x0804U, 0x0805U, 0x0807U, 0x0842U,
    };
    fputs("{\"variables\":[", stdout);
    for (unsigned index = 0U; index < ARRAY_LEN(state->variables); ++index)
        printf("%s{\"id\":%u,\"value\":%u}",
               index == 0U ? "" : ",", 0x4000U + index,
               state->variables[index]);
    fputs("],\"temporary_flags\":[", stdout);
    for (unsigned index = 0U;
         index < ARRAY_LEN(state->temporary_flags); ++index)
        printf("%s{\"id\":%u,\"value\":%s}",
               index == 0U ? "" : ",", index,
               state->temporary_flags[index] ? "true" : "false");
    fputs("],\"system_flags\":[", stdout);
    for (unsigned index = 0U; index < ARRAY_LEN(system_flags); ++index)
        printf("%s{\"id\":%u,\"value\":%s}",
               index == 0U ? "" : ",", system_flags[index],
               state->system_flags[index] ? "true" : "false");
    fputs("]}", stdout);
}

static void s61_print_map_engine_clear_evidence(
    const struct S61Capture *capture)
{
    const struct S61MapEngineClearEvidence *evidence =
        &capture->event_map_engine_clear;
    printf("{\"phase_marker\":\"DESTINATION_TEMP_CLEAR\","
           "\"capture_count\":%u,"
           "\"capture_instruction_ordinal\":%" PRIu64 ","
           "\"first_attempt_ordinal\":%" PRIu32 ","
           "\"first_attempt_tag\":%u,\"preimage\":",
           evidence->capture_count, evidence->capture_instruction_ordinal,
           evidence->first_attempt_ordinal, evidence->first_attempt_tag);
    s61_print_map_engine_clear_state(&evidence->preimage);
    fputs(",\"postimage\":", stdout);
    s61_print_map_engine_clear_state(&evidence->postimage);
    printf(",\"readback_exact\":%s}",
           evidence->readback_exact ? "true" : "false");
}

static void s61_print_map_ordered_owner(
    const struct S61MapLifecycleOrderedAttempt *attempt)
{
    if (attempt->result != S61_MAP_ATTEMPT_RESULT_DISPATCH) {
        fputs("null", stdout);
        return;
    }
    if (attempt->outer_index == UINT32_MAX
        || attempt->root_field_address == 0U || attempt->root_pc == 0U)
        s61_die("MAP lifecycle ordered owner fields differ");
    if (attempt->selected_condition_index == UINT32_MAX)
        printf("\"MAP:%03u/%03u:%03" PRIu32 ":DIRECT\"",
               attempt->group, attempt->map, attempt->outer_index);
    else
        printf("\"MAP:%03u/%03u:%03" PRIu32 ":%03" PRIu32 "\"",
               attempt->group, attempt->map, attempt->outer_index,
               attempt->selected_condition_index);
}

static void s61_print_map_ordered_attempt_payload(
    const struct S61MapLifecycleOrderedAttempt *attempt, bool include_owner)
{
    fputs("\"outer_index\":", stdout);
    if (attempt->outer_index == UINT32_MAX)
        fputs("null", stdout);
    else
        printf("%" PRIu32, attempt->outer_index);
    fputs(",\"outer_record_address\":", stdout);
    s61_print_map_lifecycle_optional_address(attempt->outer_record_address);
    fputs(",\"selected_condition_index\":", stdout);
    if (attempt->selected_condition_index == UINT32_MAX)
        fputs("null", stdout);
    else
        printf("%" PRIu32, attempt->selected_condition_index);
    fputs(",\"selected_condition_record_address\":", stdout);
    s61_print_map_lifecycle_optional_address(
        attempt->selected_condition_record_address);
    fputs(",\"root_field_address\":", stdout);
    s61_print_map_lifecycle_optional_address(attempt->root_field_address);
    fputs(",\"root_pc\":", stdout);
    s61_print_map_lifecycle_optional_address(attempt->root_pc);
    if (include_owner) {
        fputs(",\"owner_id\":", stdout);
        s61_print_map_ordered_owner(attempt);
    }
}

static void s61_print_map_ordered_projection(
    const struct S61EventTriggerRow *trigger,
    const struct S61Capture *capture)
{
    printf("{\"schema_version\":1,"
           "\"kind\":\"STAGE61_MAP_LIFECYCLE_ACTUAL_ORDERED_PROJECTION\","
           "\"capacity\":%u,"
           "\"capacity_scope\":"
           "\"PRE_FIELD_INPUT_ON_FRAME_TAG2_ATTEMPTS\","
           "\"producer_kind\":\"%s\",\"include_field_return\":%s,"
           "\"phase_boundaries\":[",
           S61_MAP_LIFECYCLE_TAG2_ATTEMPT_CAP,
           s61_map_lifecycle_producer_kind(trigger),
           capture->event_map_lifecycle_phase_boundary_count == 2U
               ? "true" : "false");
    for (unsigned index = 0U;
         index < capture->event_map_lifecycle_phase_boundary_count; ++index) {
        const struct S61MapLifecyclePhaseBoundary *boundary =
            &capture->event_map_lifecycle_phase_boundaries[index];
        printf("%s{\"boundary_ordinal\":%" PRIu32 ","
               "\"phase_marker\":\"%s\","
               "\"before_observed_attempt_ordinal\":%" PRIu32 ","
               "\"before_source_attempt_ordinal\":%" PRIu32 "}",
               index == 0U ? "" : ",", boundary->boundary_ordinal,
               s61_map_lifecycle_phase_name(boundary->phase),
               boundary->before_observed_attempt_ordinal,
               boundary->before_source_attempt_ordinal);
    }
    fputs("],\"ordered_attempts\":[", stdout);
    for (unsigned index = 0U;
         index < capture->event_map_lifecycle_attempt_count; ++index) {
        const struct S61MapLifecycleOrderedAttempt *attempt =
            &capture->event_map_lifecycle_attempts[index];
        if (attempt->result == S61_MAP_ATTEMPT_RESULT_NONE)
            s61_die("MAP lifecycle ordered attempt remained unfinished");
        printf("%s{\"observed_attempt_ordinal\":%" PRIu32 ","
               "\"source_attempt_ordinal\":%" PRIu32 ","
               "\"phase_marker\":\"%s\","
               "\"source_phase_marker\":\"%s\",\"tag\":%u,"
               "\"result\":\"%s\",",
               index == 0U ? "" : ",",
               attempt->observed_attempt_ordinal,
               attempt->source_attempt_ordinal,
               s61_map_lifecycle_phase_name(attempt->phase),
               s61_map_lifecycle_source_phase_name(attempt->source_phase),
               attempt->tag,
               s61_map_lifecycle_result_name(attempt->result));
        s61_print_map_ordered_attempt_payload(attempt, true);
        printf(",\"map\":{\"group\":%u,\"map\":%u}}",
               attempt->group, attempt->map);
    }
    fputs("],\"ordered_dispatches\":[", stdout);
    for (unsigned index = 0U;
         index < capture->event_map_lifecycle_dispatch_count; ++index) {
        const struct S61MapLifecycleOrderedDispatch *dispatch =
            &capture->event_map_lifecycle_dispatches[index];
        if (dispatch->observed_attempt_ordinal
            >= capture->event_map_lifecycle_attempt_count)
            s61_die("MAP lifecycle ordered dispatch attempt range differs");
        const struct S61MapLifecycleOrderedAttempt *attempt =
            &capture->event_map_lifecycle_attempts[
                dispatch->observed_attempt_ordinal];
        printf("%s{\"dispatch_ordinal\":%" PRIu32 ","
               "\"observed_attempt_ordinal\":%" PRIu32 ","
               "\"source_attempt_ordinal\":%" PRIu32 ","
               "\"phase_marker\":\"%s\","
               "\"source_phase_marker\":\"%s\",\"tag\":%u,"
               "\"owner_id\":",
               index == 0U ? "" : ",", dispatch->dispatch_ordinal,
               dispatch->observed_attempt_ordinal,
               dispatch->source_attempt_ordinal,
               s61_map_lifecycle_phase_name(attempt->phase),
               s61_map_lifecycle_source_phase_name(attempt->source_phase),
               attempt->tag);
        s61_print_map_ordered_owner(attempt);
        fputs(",", stdout);
        s61_print_map_ordered_attempt_payload(attempt, false);
        printf(",\"map\":{\"group\":%u,\"map\":%u}}",
               attempt->group, attempt->map);
    }
    printf("],\"attempt_count\":%u,\"dispatch_count\":%u,"
           "\"tag2_attempt_count\":%u,\"overflow\":false}",
           capture->event_map_lifecycle_attempt_count,
           capture->event_map_lifecycle_dispatch_count,
           capture->event_map_lifecycle_tag2_attempt_count);
}

static void s61_print_map_lifecycle_observations(
    const struct S61EventTriggerRow *trigger,
    const struct S61Capture *capture)
{
    if (trigger->effective_kind != S61_EVENT_MAP_TRANSITION_LOAD) {
        fputs("null", stdout);
        return;
    }
    printf("{\"capacity\":%u,\"count\":%u,\"attempt_count\":%u,"
           "\"overflow\":false,\"phase_controls\":",
           S61_MAP_LIFECYCLE_TAG2_ATTEMPT_CAP,
           capture->event_map_lifecycle_observation_count,
           capture->event_map_lifecycle_attempt_count);
    s61_print_map_phase_control_evidence(capture);
    fputs(",\"engine_clear\":", stdout);
    s61_print_map_engine_clear_evidence(capture);
    fputs(",\"ordered_projection\":", stdout);
    s61_print_map_ordered_projection(trigger, capture);
    fputs(",\"observations\":[", stdout);
    for (unsigned index = 0U;
         index < capture->event_map_lifecycle_observation_count; ++index) {
        const struct S61MapLifecycleObservation *observation =
            &capture->event_map_lifecycle_observations[index];
        printf("%s{\"kind\":\"%s\",\"ordinal\":%" PRIu64 ","
               "\"instruction_ordinal\":%" PRIu64 ","
               "\"instruction_pc\":\"0x%08" PRIX32 "\","
               "\"frame\":%" PRIu32 ",\"phase_marker\":\"%s\","
               "\"phase_boundary\":%s,\"attempt_ordinal\":",
               index == 0U ? "" : ",",
               s61_map_lifecycle_kind_name(observation->kind),
               observation->ordinal, observation->instruction_ordinal,
               observation->instruction_pc, observation->frame,
               s61_map_lifecycle_phase_name(observation->phase),
               observation->kind == S61_MAP_OBSERVATION_PHASE_BOUNDARY
                   ? "true" : "false");
        if (observation->attempt_ordinal == UINT32_MAX)
            fputs("null", stdout);
        else
            printf("%" PRIu32, observation->attempt_ordinal);
        fputs(",\"tag\":", stdout);
        if (observation->tag == 0U)
            fputs("null", stdout);
        else
            printf("%u", observation->tag);
        printf(",\"result\":\"%s\",\"map\":{\"group\":%u,"
               "\"map\":%u},\"outer_record_address\":",
               s61_map_lifecycle_result_name(observation->result),
               observation->group, observation->map);
        s61_print_map_lifecycle_optional_address(
            observation->outer_record_address);
        fputs(",\"root_field_address\":", stdout);
        s61_print_map_lifecycle_optional_address(
            observation->root_field_address);
        fputs(",\"root_pc\":", stdout);
        s61_print_map_lifecycle_optional_address(observation->root_pc);
        printf(",\"registers\":{\"r0\":\"0x%08" PRIX32 "\","
               "\"r1\":\"0x%08" PRIX32 "\","
               "\"r2\":\"0x%08" PRIX32 "\","
               "\"r4\":\"0x%08" PRIX32 "\","
               "\"r5\":\"0x%08" PRIX32 "\","
               "\"r6\":\"0x%08" PRIX32 "\","
               "\"lr\":\"0x%08" PRIX32 "\"}}",
               observation->r0, observation->r1, observation->r2,
               observation->r4, observation->r5, observation->r6,
               observation->lr);
    }
    fputs("]}", stdout);
}

static void s61_event_map_evidence_json(
    char *buffer, size_t size, const struct S61EventTriggerRow *trigger,
    const struct S61SequenceDriveResult *drive,
    const struct S61Capture *capture)
{
    if (trigger->effective_kind != S61_EVENT_MAP_TRANSITION_LOAD) {
        if (size < 5U)
            s61_die("event runtime map evidence buffer is too small");
        memcpy(buffer, "null", 5U);
        return;
    }
    bool resume = strcmp(trigger->seed_kind, "resume_callback") == 0;
    bool engine = s61_event_map_engine_seed(trigger);
    bool connection = s61_event_map_connection_seed(trigger);
    const char *order = resume
        ? engine
            ? "ENGINE_TELEPORT_LOAD_ROOT_FIELD_START_BACK_CALLBACK_OWNER"
            : connection
                ? "SOURCE_SETUP_CONNECTION_STEP_LOAD_ROOT_FIELD_START_BACK_CALLBACK_OWNER"
                : "SOURCE_SETUP_WARP_STEP_LOAD_ROOT_FIELD_START_BACK_CALLBACK_OWNER"
        : engine ? "ENGINE_TELEPORT_LOAD_ROOT_OWNER"
        : connection ? "SOURCE_SETUP_CONNECTION_STEP_LOAD_ROOT_OWNER"
        : "SOURCE_SETUP_WARP_STEP_LOAD_ROOT_OWNER";
    int length = snprintf(
        buffer, size,
        "{\"seed_kind\":\"%s\",\"contract\":\"%s\","
        "\"source_map\":\"%u/%u\","
        "\"predecessor_tile\":[%u,%u],"
        "\"source_setup\":%s,\"predecessor_tile_confirmed\":%s,"
        "\"real_warp_step\":%s,\"real_connection_step\":%s,"
        "\"engine_teleport\":%s,"
        "\"destination_map\":\"%u/%u\","
        "\"arrival_tile\":[%u,%u],"
        "\"destination_map_loaded\":%s,\"arrival_tile_confirmed\":%s,"
        "\"load_root_hit_map\":\"%u/%u\","
        "\"load_root_hit_tile\":[%u,%u],"
        "\"load_root_hit_identity_captured\":%s,"
        "\"load_identity_source\":\"%s\","
        "\"field_return_root_hit_map\":\"%u/%u\","
        "\"field_return_root_hit_tile\":[%u,%u],"
        "\"field_return_root_hit_identity_captured\":%s,"
        "\"map_owner_callback\":%s,"
        "\"map_owner_hits_before_start\":%u,"
        "\"map_owner_hits_after_field_return\":%u,"
        "\"resume_callback_pc\":\"0x%08" PRIX32 "\","
        "\"resume_callback_hits\":%u,"
        "\"callback_install_instruction_pc\":\"0x%08" PRIX32 "\","
        "\"callback_install_hits\":%u,"
        "\"callback_dispatch_instruction_pc\":\"0x%08" PRIX32 "\","
        "\"callback_dispatch_hits\":%u,"
        "\"callback_install_ordinal\":%" PRIu64 ","
        "\"callback_dispatch_ordinal\":%" PRIu64 ","
        "\"resume_callback_ordinal\":%" PRIu64 ","
        "\"map_owner_ordinal\":%" PRIu64 ","
        "\"callback_ordered\":%s,"
        "\"field_recovered_before_start\":%s,"
        "\"start_pressed\":%s,\"start_menu_opened\":%s,"
        "\"back_pressed\":%s,"
        "\"field_return_callback_dispatched\":%s,"
        "\"input_recovered\":%s,\"direct_callback_call\":false,"
        "\"lifecycle_order\":\"%s\"}",
        trigger->seed_kind, trigger->transition_contract,
        trigger->source_group, trigger->source_map,
        trigger->predecessor_x, trigger->predecessor_y,
        drive->map_source_setup ? "true" : "false",
        drive->map_predecessor_tile ? "true" : "false",
        drive->map_real_warp_step ? "true" : "false",
        drive->map_real_connection_step ? "true" : "false",
        drive->map_engine_teleport ? "true" : "false",
        trigger->destination_group, trigger->destination_map,
        trigger->arrival_x, trigger->arrival_y,
        drive->map_destination_loaded ? "true" : "false",
        drive->map_arrival_tile ? "true" : "false",
        drive->map_load_root_group, drive->map_load_root_map,
        drive->map_load_root_x, drive->map_load_root_y,
        drive->map_load_root_identity_captured ? "true" : "false",
        drive->map_load_root_identity_captured
            ? "MAP_OWNER_ROOT_HIT" : "SETTLED_PREDECESSOR_FIELD",
        resume ? capture->event_map_field_return_first_root_group : 0U,
        resume ? capture->event_map_field_return_first_root_map : 0U,
        resume ? capture->event_map_field_return_first_root_x : 0U,
        resume ? capture->event_map_field_return_first_root_y : 0U,
        resume
            && capture->event_map_field_return_expected_root_callsite_hits
                != 0U
            ? "true" : "false",
        (resume
         ? capture->event_map_field_return_expected_root_callsite_hits
         : capture->event_immediate_expected_root_callsite_hits) != 0U
            ? "true" : "false",
        drive->map_owner_hits_before_start,
        capture->event_map_field_return_expected_root_callsite_hits,
        trigger->resume_callback & ~1U,
        capture->event_resume_callback_hits,
        trigger->callback_install_instruction_pc,
        capture->event_callback_install_instruction_hits,
        trigger->callback_dispatch_instruction_pc,
        capture->event_callback_dispatch_instruction_hits,
        capture->event_first_callback_install_ordinal,
        capture->event_first_callback_dispatch_ordinal,
        capture->event_first_resume_callback_ordinal,
        capture->event_map_field_return_first_root_ordinal,
        drive->map_callback_ordered ? "true" : "false",
        drive->map_field_recovered_before_start ? "true" : "false",
        drive->map_start_pressed ? "true" : "false",
        drive->map_start_menu_opened ? "true" : "false",
        drive->map_back_pressed ? "true" : "false",
        drive->map_field_return_callback_dispatched ? "true" : "false",
        drive->map_input_recovered ? "true" : "false", order);
    if (length <= 0 || (size_t)length >= size)
        s61_die("event runtime map evidence formatting failed");
}

static void s61_case_event_runtime_batch(const char *rom_path,
                                         const char *directory)
{
    const char *catalog_path = getenv("S61_CATALOG_TSV");
    const char *trigger_path = getenv("S61_EVENT_TRIGGER_TSV");
    if (catalog_path == NULL || trigger_path == NULL
        || catalog_path[0] == '\0' || trigger_path[0] == '\0')
        s61_die("event runtime catalog/trigger TSV is required");
    FILE *catalog = fopen(catalog_path, "rb");
    FILE *triggers = fopen(trigger_path, "rb");
    if (catalog == NULL || triggers == NULL)
        s61_die("event runtime TSV open failed");
    char catalog_line[S61_CATALOG_LINE_SIZE];
    char trigger_line[S61_CATALOG_LINE_SIZE];
    if (fgets(catalog_line, sizeof(catalog_line), catalog) == NULL
        || fgets(trigger_line, sizeof(trigger_line), triggers) == NULL)
        s61_die("event runtime TSV is empty");
    size_t size = strlen(catalog_line);
    while (size != 0U && (catalog_line[size - 1U] == '\n'
                          || catalog_line[size - 1U] == '\r'))
        catalog_line[--size] = '\0';
    size = strlen(trigger_line);
    while (size != 0U && (trigger_line[size - 1U] == '\n'
                          || trigger_line[size - 1U] == '\r'))
        trigger_line[--size] = '\0';
    if (strcmp(catalog_line, S61_CATALOG_HEADER) != 0
        || strcmp(trigger_line, S61_EVENT_TRIGGER_HEADER) != 0)
        s61_die("event runtime TSV header differs");

    struct S61Interaction base_interaction = {
        96U, 5U, 20U, 20U, WORLD_KEY_DOWN, 1U, 0U,
    };
    struct Fixture base = s61_world_fixture(
        "event_runtime_batch_base", &base_interaction);
    char save_path[4096];
    s61_save_path(save_path, sizeof(save_path), directory, base.name);
    s61_generate(rom_path, save_path, &base);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &base);
    s61_assert_text_printer_preimage(core);
    s61_assert_map_lifecycle_hook_preimages(core);
    size_t state_size = core->stateSize(core);
    void *base_state = malloc(state_size);
    struct S61SideEffectSnapshot *side_before = malloc(sizeof(*side_before));
    struct S61SideEffectSnapshot *side_after = malloc(sizeof(*side_after));
    struct S61SideEffectSnapshot *side_final = malloc(sizeof(*side_final));
    if (base_state == NULL || side_before == NULL || side_after == NULL
        || side_final == NULL
        || !core->saveState(core, base_state))
        s61_die("event runtime baseline capture failed");

    printf("{\"schema_version\":2,\"status\":\"PASS\","
           "\"case\":\"event_runtime_batch\","
           "\"actual_consumer_trigger_dispatch\":true,\"results\":[");
    unsigned count = 0U;
    unsigned sequence_count = 0U;
    unsigned failed = 0U;
    unsigned empty_text = 0U;
    unsigned softlocks = 0U;
    unsigned invalid_control_flow_failures = 0U;
    char **owner_ids = NULL;
    unsigned owner_count = 0U;
    unsigned owner_capacity = 0U;
    while (fgets(catalog_line, sizeof(catalog_line), catalog) != NULL) {
        if (fgets(trigger_line, sizeof(trigger_line), triggers) == NULL)
            s61_die("event runtime trigger TSV ended before catalog");
        s61_event_runtime_catalog_parse = true;
        struct S61CatalogRow row = s61_parse_catalog_row(catalog_line);
        s61_event_runtime_catalog_parse = false;
        struct S61EventTriggerRow trigger =
            s61_parse_event_trigger_row(trigger_line);
        if (strcmp(row.case_id, trigger.case_id) != 0
            || strcmp(row.owner_key, trigger.owner_id) != 0
            || row.input_sequence_count != 1U)
            s61_die("event runtime catalog/trigger lockstep differs");
        bool engine_zero_walk =
            trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
            && s61_event_map_engine_seed(&trigger);
        if (engine_zero_walk != (
                !row.actual_walk_required
                && row.walk_key_count == 0U
                && !row.map_level_real_walk_probe_required))
            s61_die("event runtime engine zero-walk lockstep differs");
        bool owner_seen = false;
        for (unsigned owner = 0U; owner < owner_count; ++owner) {
            if (strcmp(owner_ids[owner], trigger.owner_id) == 0) {
                owner_seen = true;
                break;
            }
        }
        if (!owner_seen) {
            if (owner_count == owner_capacity) {
                unsigned capacity = owner_capacity == 0U
                    ? 32U : owner_capacity * 2U;
                char **grown = realloc(
                    owner_ids, (size_t)capacity * sizeof(*grown));
                if (grown == NULL)
                    s61_die("event runtime owner set allocation failed");
                owner_ids = grown;
                owner_capacity = capacity;
            }
            size_t owner_size = strlen(trigger.owner_id) + 1U;
            owner_ids[owner_count] = malloc(owner_size);
            if (owner_ids[owner_count] == NULL)
                s61_die("event runtime owner ID allocation failed");
            memcpy(owner_ids[owner_count], trigger.owner_id, owner_size);
            ++owner_count;
        }
        const struct S61CatalogInputSequence *sequence =
            &row.input_sequences[0];
        s61_event_assert_prefix(sequence, &trigger);
        s61_case_name = row.case_id;
        bootstrap_phase = row.case_id;
        if (!core->loadState(core, base_state))
            s61_die("event runtime baseline restore failed");
        run_key_frames(core, 0U, 3U);
        s61_apply_catalog_state(core, &row);
        s61_apply_catalog_external_state(core, &row, false);
        unsigned preparation_walk = s61_event_prepare_physical_trigger(
            core, &trigger);
        s61_apply_catalog_post_warp_external_state(
            core, &row,
            trigger.effective_kind != S61_EVENT_MAP_TRANSITION_LOAD);
        s61_verify_catalog_state(core, &row);
        /* Ordinary field triggers have reached their physical stance here.
         * Every MAP producer (warp, connection, or engine teleport) executes
         * inside the observation window below, so its arrival position is
         * proven by the first-root capture rather than read prematurely at
         * the source predecessor tile. */
        s61_verify_catalog_external_state(
            core, &row, false,
            trigger.effective_kind != S61_EVENT_MAP_TRANSITION_LOAD);
        s61_apply_catalog_external_state(core, &row, true);
        s61_verify_catalog_external_state(core, &row, true, false);
        s61_snapshot_side_effects(core, &row.interaction, side_before);
        /* All setup above is a controlled precondition.  Only the physical
         * producer below belongs to the raw effect observation window. */
        s61_effect_observer_begin_case(core, row.case_id);
        char label[1024];
        int label_size = snprintf(
            label, sizeof(label), "event-%s", row.case_id);
        if (label_size <= 0 || (size_t)label_size >= sizeof(label))
            s61_die("event runtime artifact label differs");
        char artifact[4096];
        struct S61Capture capture = s61_new_capture(
            directory, label, artifact, sizeof(artifact));
        capture.event_root_script_pointer = trigger.root_pc;
        if (trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD) {
            capture.event_map_lifecycle_enabled = true;
            capture.event_map_trigger = &trigger;
            if (trigger.map_script_tag == 2U) {
                capture.event_immediate_root_callsite_pc =
                    WORLD_MAP_SCRIPT_ON_FRAME_CALLSITE_PC;
                capture.event_immediate_root_executor_pc =
                    WORLD_SCRIPT_CONTEXT1_SETUP_PC;
            } else if (trigger.map_script_tag == 4U) {
                capture.event_immediate_root_callsite_pc =
                    WORLD_MAP_SCRIPT_ON_WARP_IN_CALLSITE_PC;
                capture.event_immediate_root_executor_pc =
                    WORLD_MAP_SCRIPT_ROOT_EXECUTOR_PC;
            } else {
                capture.event_immediate_root_callsite_pc =
                    WORLD_MAP_SCRIPT_ROOT_CALLSITE_PC;
                capture.event_immediate_root_executor_pc =
                    WORLD_MAP_SCRIPT_ROOT_EXECUTOR_PC;
            }
            if (strcmp(trigger.map_subkind, "CONDITION") == 0) {
                capture.event_map_condition_target_var = trigger.trigger_var;
                capture.event_map_condition_target_value =
                    trigger.trigger_value;
                capture.event_map_precedence_guard_count =
                    trigger.map_precedence_guard_count;
                memcpy(
                    capture.event_map_precedence_guard_vars,
                    trigger.map_precedence_guard_vars,
                    sizeof(trigger.map_precedence_guard_vars));
                memcpy(
                    capture.event_map_precedence_guard_values,
                    trigger.map_precedence_guard_values,
                sizeof(trigger.map_precedence_guard_values));
            }
            s61_map_lifecycle_mark_phase(
                core, &capture, S61_MAP_LIFECYCLE_PHASE_INITIAL_LOAD);
        }
        if (trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
            && strcmp(trigger.seed_kind, "resume_callback") == 0) {
            capture.event_resume_callback_pc =
                trigger.resume_callback & ~1U;
            capture.event_callback_install_instruction_pc =
                trigger.callback_install_instruction_pc;
            capture.event_callback_dispatch_instruction_pc =
                trigger.callback_dispatch_instruction_pc;
        }
        if (strcmp(trigger.declared_kind, "COMMON_CALLER_TRIGGER") == 0) {
            s61_event_common_assert_binding(core, &trigger);
            capture.event_caller_script_pointer = trigger.physical_root_pc;
            capture.event_common_expected_physical_root_pc =
                trigger.physical_root_pc;
            capture.event_common_expected_caller_pc =
                trigger.caller_instruction_pc;
            capture.event_common_expected_root_pc = trigger.root_pc;
            capture.event_common_expected_standard_index =
                trigger.standard_index;
            capture.event_common_expected_local_id = trigger.local_id;
        } else {
            capture.event_consumer_instruction_pc = trigger.consumer_pc;
        }
        s61_begin_internal_control_capture(
            core, &row, sequence, &capture);
        struct S61SequenceDriveResult drive = s61_drive_event_sequence(
            core, &trigger, sequence, &capture);
        s61_event_finalize_map_evidence(&trigger, &capture, &drive);
        bool internal_ok = s61_internal_controls_ok(core, &row, sequence);
        s61_end_internal_control_capture();
        s61_snapshot_side_effects(core, &row.interaction, side_after);
        bool battle = s61_battle_active(core);
        bool field = s61_field_terminal(core);
        bool root_expected = trigger.effective_kind != S61_EVENT_HIDDEN_ITEM
            || trigger.consumer_root_expected_hit;
        unsigned logical_root_hits =
            trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
            ? capture.event_immediate_expected_root_callsite_hits
            : capture.event_root_script_pointer_hits;
        bool root_ok = root_expected
            ? logical_root_hits != 0U : logical_root_hits == 0U;
        if (trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD)
            root_ok = root_ok
                && capture.event_immediate_expected_root_executor_hits != 0U
                && capture.event_first_expected_root_script_pointer
                    == trigger.root_pc
                && capture.event_first_expected_root_group == trigger.group
                && capture.event_first_expected_root_map == trigger.map
                && (strcmp(trigger.map_subkind, "CONDITION") != 0
                    || (capture.event_map_condition_target_readback_exact
                        && capture.
                            event_map_precedence_guards_readback_exact));
        bool declared_common = strcmp(
            trigger.declared_kind, "COMMON_CALLER_TRIGGER") == 0;
        bool common_dispatch_exact = declared_common
            && s61_event_common_dispatch_exact(&capture);
        bool consumer_ok = declared_common
            ? common_dispatch_exact
            : trigger.consumer_pc == 0U
                || capture.event_consumer_instruction_hits != 0U;
        bool terminal_ok = drive.terminal_seen
            && (battle || field)
            && (strcmp(trigger.event_terminal, "BATTLE_START") != 0
                || battle);
        bool visible_ok = sequence->visible_text_expected
            ? capture.printer_call_count != 0U
            : capture.printer_call_count == 0U;
        bool map_transition_ok = true;
        bool physical_walk_kind =
            trigger.effective_kind == S61_EVENT_OBJECT_FACE_A
            || trigger.effective_kind == S61_EVENT_BG_FACE_A
            || trigger.effective_kind == S61_EVENT_COORD_STEP
            || trigger.effective_kind == S61_EVENT_HIDDEN_ITEM;
        bool face_walk = trigger.effective_kind == S61_EVENT_OBJECT_FACE_A
            || trigger.effective_kind == S61_EVENT_BG_FACE_A
            || (trigger.effective_kind == S61_EVENT_HIDDEN_ITEM
                && !trigger.underfoot);
        bool physical_walk_ok = !physical_walk_kind
            || (drive.event_walk_start_confirmed
                && drive.event_walk_path_exact
                && drive.event_walk_final_tile_confirmed
                && drive.event_walk_step_count == trigger.walk_key_count
                && (!face_walk || drive.event_walk_stance_confirmed));
        if (trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD) {
            map_transition_ok = drive.map_source_setup
                && drive.map_predecessor_tile
                && (drive.map_real_warp_step
                    || drive.map_real_connection_step
                    || drive.map_engine_teleport)
                && drive.map_destination_loaded && drive.map_arrival_tile;
            if (strcmp(trigger.seed_kind, "resume_callback") == 0)
                map_transition_ok = map_transition_ok
                    && drive.map_field_recovered_before_start
                    && drive.map_start_pressed
                    && drive.map_start_menu_opened
                    && drive.map_back_pressed
                    && drive.map_field_return_callback_dispatched
                    && drive.map_callback_ordered
                    && drive.map_input_recovered;
        }
        struct S61BattleLifecycleResult battle_lifecycle = {0};
        struct S61PostBattleContinuationResult
            post_battle_continuation = {0};
        if (battle) {
            battle_lifecycle = s61_complete_battle_lifecycle(
                core, row.case_id,
                side_after->world.location.group,
                side_after->world.location.map, sequence,
                &post_battle_continuation);
            s61_snapshot_side_effects(
                core, &row.interaction, side_final);
        } else {
            memcpy(side_final, side_after, sizeof(*side_final));
        }
        s61_finalize_facility_execution(core, &capture);
        s61_effect_observer_end_case(core);
        bool battle_lifecycle_ok = !battle
            || (side_after->input.battle_input_owned
                && battle_lifecycle.completed_via_keys
                && (post_battle_continuation.facility_active_boundary
                    ? !battle_lifecycle.field_released_after_battle
                        && !battle_lifecycle.start_menu_opened
                        && !battle_lifecycle.field_input_recovered
                    : battle_lifecycle.field_released_after_battle
                        && battle_lifecycle.start_menu_opened
                        && battle_lifecycle.field_input_recovered));
        bool success = drive.steps_consumed == sequence->step_count
            && !drive.premature_terminal && !capture.invalid_control_flow
            && root_ok && consumer_ok && terminal_ok && visible_ok
            && map_transition_ok && physical_walk_ok && internal_ok
            && battle_lifecycle_ok;
        if (!success)
            ++failed;
        if (sequence->visible_text_expected
            && capture.printer_call_count == 0U)
            ++empty_text;
        if (!drive.terminal_seen && !battle && !field)
            ++softlocks;
        if (capture.invalid_control_flow)
            ++invalid_control_flow_failures;
        char map_evidence[4096];
        s61_event_map_evidence_json(
            map_evidence, sizeof(map_evidence), &trigger, &drive, &capture);
        if (count != 0U)
            putchar(',');
        printf("{\"case_id\":\"%s\",\"owner_id\":\"%s\","
               "\"root_assignment_id\":%s%s%s,"
               "\"declared_kind\":\"%s\",\"effective_kind\":\"%s\","
               "\"trigger_prefix_count\":%u,"
               "\"trigger_evidence\":{\"host_map_setup\":true,"
               "\"preparation_real_walk_steps\":%u,"
               "\"trigger_real_walk_steps\":%u,"
               "\"direction_plus_a\":%s,\"itemfinder_select\":%s,"
               "\"physical_walk\":",
               row.case_id, trigger.owner_id,
               strcmp(trigger.root_assignment_id, "-") == 0 ? "" : "\"",
               strcmp(trigger.root_assignment_id, "-") == 0
                   ? "null" : trigger.root_assignment_id,
               strcmp(trigger.root_assignment_id, "-") == 0 ? "" : "\"",
               trigger.declared_kind,
               trigger.effective_kind == S61_EVENT_BG_FACE_A ? "BG_FACE_A"
                   : trigger.effective_kind == S61_EVENT_COORD_STEP
                   ? "COORD_STEP"
                   : trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
                   ? "MAP_TRANSITION_LOAD"
                   : trigger.effective_kind == S61_EVENT_HIDDEN_ITEM
                   ? "HIDDEN_ITEM" : "OBJECT_FACE_A",
               trigger.trigger_prefix_count, preparation_walk,
               drive.trigger_real_walk_steps,
               trigger.effective_kind == S61_EVENT_OBJECT_FACE_A
                   || trigger.effective_kind == S61_EVENT_BG_FACE_A
                   || (trigger.effective_kind == S61_EVENT_HIDDEN_ITEM
                       && !trigger.underfoot) ? "true" : "false",
               trigger.effective_kind == S61_EVENT_HIDDEN_ITEM
                   && trigger.underfoot ? "true" : "false");
        s61_print_event_physical_walk_evidence(&trigger, &drive);
        printf(","
               "\"root_script_pointer\":\"0x%08" PRIX32 "\","
               "\"root_script_pointer_hits\":%u,"
               "\"first_root_script_pointer\":\"0x%08" PRIX32 "\","
               "\"logical_dispatch_callsite_hits\":%u,"
               "\"logical_dispatch_executor_hits\":%u,"
               "\"map_condition_target_readback_exact\":%s,"
               "\"map_precedence_guard_count\":%u,"
               "\"map_precedence_guards_readback_exact\":%s,"
               "\"physical_root_script_pointer\":\"0x%08" PRIX32 "\","
               "\"physical_root_script_pointer_hits\":%u,"
               "\"caller_instruction_hits\":%u,"
               "\"common_prefix_ordered\":%s,"
               "\"common_dispatch\":",
               trigger.root_pc, logical_root_hits,
               trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
                   ? capture.event_first_expected_root_script_pointer
                   : capture.event_first_root_script_pointer,
               capture.event_immediate_expected_root_callsite_hits,
               capture.event_immediate_expected_root_executor_hits,
               trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
                   && strcmp(trigger.map_subkind, "CONDITION") == 0
                   && capture.event_map_condition_target_readback_exact
                   ? "true" : "false",
               trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
                   && strcmp(trigger.map_subkind, "CONDITION") == 0
                   ? trigger.map_precedence_guard_count : 0U,
               trigger.effective_kind == S61_EVENT_MAP_TRANSITION_LOAD
                   && strcmp(trigger.map_subkind, "CONDITION") == 0
                   && capture.event_map_precedence_guards_readback_exact
                   ? "true" : "false",
               trigger.physical_root_pc,
               declared_common
                   ? capture.event_common_physical_root_dispatch_hits
                   : logical_root_hits,
               declared_common
                   ? capture.event_common_caller_instruction_hits : 0U,
               common_dispatch_exact ? "true" : "false");
        if (declared_common) {
            unsigned caller_hits =
                capture.event_common_caller_instruction_hits;
            bool same_context = caller_hits != 0U
                && capture.event_common_first_physical_root_context
                    == WORLD_SCRIPT_CONTEXT1_STATE
                && capture.event_common_first_caller_context
                    == WORLD_SCRIPT_CONTEXT1_STATE
                && capture.event_common_first_root_context
                    == WORLD_SCRIPT_CONTEXT1_STATE;
            bool physical_before_caller =
                capture.event_common_first_physical_root_dispatch_ordinal != 0U
                && capture.event_common_first_physical_root_dispatch_ordinal
                    < capture.event_common_first_caller_dispatch_ordinal;
            bool caller_to_root_adjacent = caller_hits != 0U
                && capture.event_common_adjacent_edge_hits == caller_hits
                && capture.event_common_root_dispatch_hits == caller_hits
                && capture.event_common_first_root_dispatch_ordinal
                    == capture.event_common_first_caller_dispatch_ordinal + 1U;
            printf("{\"dispatcher_pc\":\"0x%08X\","
                   "\"physical_root_pc\":\"0x%08" PRIX32 "\","
                   "\"physical_root_hits\":%u,"
                   "\"physical_root_context\":\"0x%08" PRIX32 "\","
                   "\"physical_root_ordinal\":%" PRIu64 ","
                   "\"caller_pc\":\"0x%08" PRIX32 "\","
                   "\"caller_hits\":%u,"
                   "\"caller_context\":\"0x%08" PRIX32 "\","
                   "\"caller_ordinal\":%" PRIu64 ","
                   "\"opcode\":%u,\"opcode_family_exact\":%s,"
                   "\"standard_index\":%u,"
                   "\"standard_index_exact\":%s,"
                   "\"last_talked_local_id\":%u,"
                   "\"last_talked_exact\":%s,"
                   "\"declared_root_pc\":\"0x%08" PRIX32 "\","
                   "\"declared_root_hits\":%u,"
                   "\"declared_root_context\":\"0x%08" PRIX32 "\","
                   "\"declared_root_ordinal\":%" PRIu64 ","
                   "\"same_context\":%s,"
                   "\"physical_root_before_caller\":%s,"
                   "\"caller_to_root_adjacent\":%s,"
                   "\"edge_hits\":%u}",
                   S61_STATEFUL_SCRIPT_DISPATCH_PC,
                   trigger.physical_root_pc,
                   capture.event_common_physical_root_dispatch_hits,
                   capture.event_common_first_physical_root_context,
                   capture.event_common_first_physical_root_dispatch_ordinal,
                   trigger.caller_instruction_pc,
                   caller_hits,
                   capture.event_common_first_caller_context,
                   capture.event_common_first_caller_dispatch_ordinal,
                   capture.event_common_first_caller_opcode,
                   caller_hits != 0U
                       && capture.event_common_opcode_family_hits == caller_hits
                       ? "true" : "false",
                   capture.event_common_first_caller_standard_index,
                   caller_hits != 0U
                       && capture.event_common_standard_index_hits == caller_hits
                       ? "true" : "false",
                   capture.event_common_first_caller_last_talked,
                   caller_hits != 0U
                       && capture.event_common_last_talked_hits == caller_hits
                       ? "true" : "false",
                   trigger.root_pc,
                   capture.event_common_root_dispatch_hits,
                   capture.event_common_first_root_context,
                   capture.event_common_first_root_dispatch_ordinal,
                   same_context ? "true" : "false",
                   physical_before_caller ? "true" : "false",
                   caller_to_root_adjacent ? "true" : "false",
                   capture.event_common_adjacent_edge_hits);
        } else {
            fputs("null", stdout);
        }
        printf(",\"consumer_pc\":\"0x%08" PRIX32 "\","
               "\"consumer_hits\":%u,\"direct_script_call\":false,"
               "\"map_transition\":%s,\"map_lifecycle\":",
               trigger.consumer_pc,
               declared_common
                   ? capture.event_common_caller_instruction_hits
                   : capture.event_consumer_instruction_hits,
               map_evidence);
        s61_print_map_lifecycle_observations(&trigger, &capture);
        printf("},\"input_sequence_attempt\":{\"sequence_id\":\"%s\","
               "\"expected_static_branch_token\":\"%s\","
               "\"visible_text_expected\":%s,"
               "\"silent_text_basis_sha256\":%s%s%s,"
               "\"input_tokens\":[",
               sequence->sequence_id, sequence->expected_branch_token,
               sequence->visible_text_expected ? "true" : "false",
               sequence->visible_text_expected ? "null" : "\"",
               sequence->visible_text_expected
                   ? "" : sequence->silent_basis_sha256,
               sequence->visible_text_expected ? "" : "\"");
        for (unsigned index = 0U; index < sequence->step_count; ++index)
            printf("%s\"%s\"", index == 0U ? "" : ",",
                   sequence->steps[index].token);
        printf("],\"input_step_count\":%u,\"input_steps_consumed\":%u,"
               "\"premature_terminal\":%s,\"success\":%s,"
               "\"failure_reason\":\"%s\",\"terminal\":\"%s\","
               "\"field_released\":%s,\"battle_started\":%s,"
               "\"post_battle\":",
               sequence->step_count, drive.steps_consumed,
               drive.premature_terminal ? "true" : "false",
               success ? "true" : "false",
               success ? "NONE" : "EVENT_TRIGGER_OR_TERMINAL_MISMATCH",
               battle ? "BATTLE_START" : field ? "FIELD_RELEASE" : "NONE",
               field ? "true" : "false", battle ? "true" : "false");
        s61_print_battle_lifecycle(&battle_lifecycle);
        printf(",\"post_battle_continuation\":");
        s61_print_post_battle_continuation(
            &post_battle_continuation, sequence);
        printf(",\"capture\":");
        s61_print_capture(&capture);
        printf(",\"internal_controls\":");
        s61_print_internal_controls(&row, sequence);
        printf(",\"deferred_external_controls\":");
        s61_print_deferred_external_controls(core, &row, &capture);
        printf(",\"battle_start_side_effects\":");
        if (battle)
            s61_print_side_effects(side_before, side_after);
        else
            fputs("null", stdout);
        printf(",\"side_effects\":");
        s61_print_side_effects(side_before, side_final);
        printf("}}");
        s61_write_peak_frame(&capture, "peak");
        s61_release_facility_execution(&capture);
        free(capture.event_map_lifecycle_observations);
        capture.event_map_lifecycle_observations = NULL;
        ++count;
        ++sequence_count;
    }
    if (fgets(trigger_line, sizeof(trigger_line), triggers) != NULL
        || ferror(catalog) || ferror(triggers)
        || fclose(catalog) != 0 || fclose(triggers) != 0)
        s61_die("event runtime TSV close/row count differs");
    if (count == 0U)
        s61_die("event runtime TSV has zero rows");
    printf("],\"fixture_count\":%u,\"owner_count\":%u,"
           "\"sequence_count\":%u,\"failed\":%u,"
           "\"empty_text\":%u,\"softlocks\":%u,"
           "\"invalid_control_flow_failures\":%u,\"untested\":0,"
           "\"warnings\":0}\n",
           count, owner_count, sequence_count, failed, empty_text, softlocks,
           invalid_control_flow_failures);
    for (unsigned owner = 0U; owner < owner_count; ++owner)
        free(owner_ids[owner]);
    free(owner_ids);
    free(side_after);
    free(side_final);
    free(side_before);
    free(base_state);
    bootstrap_close_core(core);
}

static const char *s61_choice_name(enum S61Choice choice)
{
    if (choice == S61_CHOICE_ADVANCE)
        return "ADVANCE";
    if (choice == S61_CHOICE_NO)
        return "NO";
    if (choice == S61_CHOICE_YES)
        return "YES";
    if (choice == S61_CHOICE_CANCEL)
        return "CANCEL";
    s61_die("internal calibration choice is invalid");
    return "INVALID";
}

static void s61_set_legacy_var_canaries(struct mCore *core,
                                        const struct S61CatalogRow *row)
{
    static const uint16_t identifiers[3] = {0x4000U, 0x4040U, 0x40FFU};
    static const uint16_t values[3] = {0x1357U, 0x2468U, 0x369CU};
    for (unsigned canary = 0U; canary < 3U; ++canary) {
        for (unsigned index = 0U; index < row->var_count; ++index) {
            if (row->vars[index].id == identifiers[canary])
                s61_die("expanded-state row overlaps a legacy var canary");
        }
        (void)s61_call_synced(core, WORLD_VAR_SET,
                             identifiers[canary], values[canary], 0U, 0U);
        if (s61_call_synced(core, WORLD_VAR_GET,
                            identifiers[canary], 0U, 0U, 0U)
                != values[canary])
            s61_die("legacy var canary write/read failed");
    }
}

static bool s61_persistence_readback_matches(
    struct mCore *core, const struct S61CatalogRow *row,
    bool require_legacy_canaries)
{
    static const uint16_t canary_ids[3] = {0x4000U, 0x4040U, 0x40FFU};
    static const uint16_t canary_values[3] = {0x1357U, 0x2468U, 0x369CU};
    bool matches = true;
    for (unsigned index = 0U; index < row->flag_count; ++index) {
        bool actual = s61_flag(core, row->flags[index].flag) != 0U;
        if (actual != row->flags[index].value) {
            fprintf(stderr,
                    "persistence flag mismatch id=%u expected=%u actual=%u\n",
                    row->flags[index].flag, row->flags[index].value, actual);
            matches = false;
        }
    }
    for (unsigned index = 0U; index < row->var_count; ++index) {
        uint16_t actual = (uint16_t)s61_call_synced(
            core, WORLD_VAR_GET, row->vars[index].id, 0U, 0U, 0U);
        if (actual != row->vars[index].value) {
            fprintf(stderr,
                    "persistence var mismatch id=%u expected=%u actual=%u\n",
                    row->vars[index].id, row->vars[index].value, actual);
            matches = false;
        }
    }
    if (require_legacy_canaries) {
        for (unsigned index = 0U; index < 3U; ++index) {
            uint16_t actual = (uint16_t)s61_call_synced(
                core, WORLD_VAR_GET, canary_ids[index], 0U, 0U, 0U);
            if (actual != canary_values[index]) {
                fprintf(stderr,
                        "persistence legacy var canary mismatch "
                        "id=%u expected=%u actual=%u\n",
                        canary_ids[index], canary_values[index], actual);
                matches = false;
            }
        }
    }
    return matches;
}

static void s61_read_core_range(struct mCore *core, uint32_t address,
                                uint8_t *destination, size_t size)
{
    for (size_t index = 0U; index < size; ++index)
        destination[index] = read8(core, address + (uint32_t)index);
}

static uint64_t s61_hash_core_range(struct mCore *core, uint32_t address,
                                    size_t size)
{
    uint64_t hash = UINT64_C(14695981039346656037);
    for (size_t index = 0U; index < size; ++index) {
        hash ^= read8(core, address + (uint32_t)index);
        hash *= UINT64_C(1099511628211);
    }
    return hash;
}

static bool s61_core_range_equals(struct mCore *core, uint32_t address,
                                  const uint8_t *expected, size_t size,
                                  const char *label)
{
    for (size_t index = 0U; index < size; ++index) {
        uint8_t actual = read8(core, address + (uint32_t)index);
        if (actual != expected[index]) {
            fprintf(stderr,
                    "%s mismatch offset=%#06zx expected=%#04x actual=%#04x\n",
                    label, index, expected[index], actual);
            return false;
        }
    }
    return true;
}

static bool s61_core_range_zero(struct mCore *core, uint32_t address,
                                size_t size)
{
    for (size_t index = 0U; index < size; ++index) {
        uint8_t actual = read8(core, address + (uint32_t)index);
        if (actual != 0U) {
            fprintf(stderr,
                    "expanded baseline nonzero offset=%#06zx value=%#04x\n",
                    index, actual);
            return false;
        }
    }
    return true;
}

static bool s61_sector31_ledger_matches(struct mCore *core,
                                        uint64_t *hash_out)
{
    s61_flash_select_bank(core, 1U);
    uint64_t hash = UINT64_C(14695981039346656037);
    uint32_t live_checksum = UINT32_C(2166136261);
    uint32_t flash_checksum = UINT32_C(2166136261);
    unsigned differences = 0U;
    bool minute_changed = false;
    for (uint32_t index = 0U; index < WORLD_SECTOR31_LEDGER_SIZE; ++index) {
        uint8_t ewram = read8(core, WORLD_SECTOR31_LEDGER + index);
        uint8_t flash = read8(core, WORLD_SECTOR31_LEDGER_FLASH + index);
        uint8_t live_hash_byte = index >= 8U && index < 12U ? 0U : ewram;
        uint8_t flash_hash_byte = index >= 8U && index < 12U ? 0U : flash;
        live_checksum ^= live_hash_byte;
        live_checksum *= UINT32_C(16777619);
        flash_checksum ^= flash_hash_byte;
        flash_checksum *= UINT32_C(16777619);
        hash ^= flash;
        hash *= UINT64_C(1099511628211);
        if (ewram != flash) {
            ++differences;
            if (index == 0x746U)
                minute_changed = true;
            else if (index < 8U || index >= 12U)
                return false;
        }
    }
    if (read32(core, WORLD_SECTOR31_LEDGER) != UINT32_C(0x31534756)
        || read16(core, WORLD_SECTOR31_LEDGER + 4U) != 2U
        || read16(core, WORLD_SECTOR31_LEDGER + 6U)
            != WORLD_SECTOR31_LEDGER_SIZE
        || read32(core, WORLD_SECTOR31_LEDGER + 8U) != live_checksum
        || read32(core, WORLD_SECTOR31_LEDGER_FLASH)
            != UINT32_C(0x31534756)
        || read16(core, WORLD_SECTOR31_LEDGER_FLASH + 4U) != 2U
        || read16(core, WORLD_SECTOR31_LEDGER_FLASH + 6U)
            != WORLD_SECTOR31_LEDGER_SIZE
        || read32(core, WORLD_SECTOR31_LEDGER_FLASH + 8U)
            != flash_checksum)
        return false;
    if (minute_changed) {
        uint8_t live_minute = read8(
            core, WORLD_SECTOR31_LEDGER + 0x746U);
        uint8_t flash_minute = read8(
            core, WORLD_SECTOR31_LEDGER_FLASH + 0x746U);
        if (differences < 2U || differences > 5U || flash_minute >= 59U
            || live_minute != flash_minute + 1U)
            return false;
    } else if (differences != 0U) {
        return false;
    }
    *hash_out = hash;
    return true;
}

static bool s61_normal_input_save(struct mCore *core)
{
    if (!world_overworld(core) || world_script_enabled(core)) {
        fprintf(stderr, "normal input save pre-field callback=%08" PRIX32
                " lock=%u\n", read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                world_script_enabled(core));
        return false;
    }
    s61_pulse(core, WORLD_KEY_START, 2U, 120U, NULL);
    if (read32(core, WORLD_START_MENU_CALLBACK) != WORLD_START_MENU_INPUT) {
        fprintf(stderr, "normal input save start callback=%08" PRIX32
                " callback2=%08" PRIX32 " lock=%u\n",
                read32(core, WORLD_START_MENU_CALLBACK),
                read32(core, BATTLE_CORE_MAIN_CALLBACK2),
                world_script_enabled(core));
        return false;
    }
    uint8_t count = read8(core, WORLD_START_MENU_COUNT);
    uint8_t cursor = read8(core, WORLD_START_MENU_CURSOR);
    if (count == 0U || count > 9U || cursor >= count) {
        fprintf(stderr, "normal input save menu count=%u cursor=%u\n",
                count, cursor);
        return false;
    }
    uint8_t target = count;
    for (uint8_t index = 0U; index < count; ++index) {
        if (read8(core, WORLD_START_MENU_ORDER + index)
                == WORLD_START_MENU_SAVE_ACTION) {
            target = index;
            break;
        }
    }
    if (target >= count) {
        fprintf(stderr, "normal input save action missing count=%u order=",
                count);
        for (uint8_t index = 0U; index < count; ++index)
            fprintf(stderr, "%s%u", index == 0U ? "" : ",",
                    read8(core, WORLD_START_MENU_ORDER + index));
        fputc('\n', stderr);
        return false;
    }
    unsigned down = (unsigned)(target + count - cursor) % count;
    unsigned up = (unsigned)(cursor + count - target) % count;
    uint16_t key = down <= up ? WORLD_KEY_DOWN : WORLD_KEY_UP;
    unsigned steps = down <= up ? down : up;
    for (unsigned step = 0U; step < steps; ++step)
        s61_pulse(core, key, 2U, 30U, NULL);
    if (read8(core, WORLD_START_MENU_CURSOR) != target) {
        fprintf(stderr, "normal input save cursor=%u target=%u\n",
                read8(core, WORLD_START_MENU_CURSOR), target);
        return false;
    }
    s61_pulse(core, WORLD_KEY_A, 2U, 120U, NULL);
    bool callback_seen = false;
    for (unsigned prompt = 0U; prompt < 32U; ++prompt) {
        if (read32(core, WORLD_START_MENU_CALLBACK)
                == WORLD_START_MENU_SAVE_CALLBACK)
            callback_seen = true;
        if (callback_seen && world_overworld(core)
            && !world_script_enabled(core)) {
            run_key_frames(core, 0U, 180U);
            uint64_t ledger_hash = 0U;
            return world_overworld(core) && !world_script_enabled(core)
                && s61_sector31_ledger_matches(core, &ledger_hash);
        }
        /* JP same-file Save is DefaultYes.  Every transition remains an
         * ordinary released A pulse, including the confirmation/result text. */
        s61_pulse(core, WORLD_KEY_A, 2U, 180U, NULL);
    }
    fprintf(stderr,
            "normal input save timeout callback_seen=%u menu=%08" PRIX32
            " callback2=%08" PRIX32 " lock=%u\n",
            callback_seen, read32(core, WORLD_START_MENU_CALLBACK),
            read32(core, BATTLE_CORE_MAIN_CALLBACK2),
            world_script_enabled(core));
    return false;
}

static void s61_prepare_master_ball_fixture(struct mCore *core)
{
    if (s61_item(core, WORLD_MASTER_BALL) != 0U)
        s61_die("last-ball fixture unexpectedly already owns a Master Ball");
    if (s61_call_synced(core, BATTLE_CORE_ADD_BAG_ITEM,
                        WORLD_MASTER_BALL, 1U, 0U, 0U) != 1U
        || s61_item(core, WORLD_MASTER_BALL) != 1U)
        s61_die("last-ball fixture could not add one Master Ball");

    /* A single real party slot makes the captured event mon observable in
     * normal party storage and avoids a PC/full-party side branch. */
    for (unsigned slot = 1U; slot < BOOTSTRAP_TEAM_SIZE; ++slot) {
        uint32_t mon = BOOTSTRAP_PLAYER_PARTY
            + slot * BOOTSTRAP_MON_SIZE;
        for (unsigned byte = 0U; byte < BOOTSTRAP_MON_SIZE; ++byte)
            write8(core, mon + byte, 0U);
    }
    write8(core, BOOTSTRAP_PLAYER_COUNT, 1U);
}

static void s61_prepare_ball_pocket_cursor(struct mCore *core)
{
    /* This is inventory/menu preparation only.  The battle action cursor is
     * never written: Bag selection and item confirmation are real keys. */
    write16(core, BATTLE_CORE_BAG_STATE + 6U,
            WORLD_BAG_BALL_POCKET);
    for (unsigned cursor = 0U; cursor < 6U; ++cursor)
        write16(core, BATTLE_CORE_BAG_STATE + 8U + cursor * 2U, 0U);
}

static void s61_case_last_ball_persistence(
    const char *rom_path, const char *directory, bool write_phase,
    const struct S61Config *config)
{
    char save_path[4096];
    char artifact[4096];
    struct Fixture giver = s61_world_fixture(
        "last_ball_persistence", &config->giver);
    struct Fixture snorlax = s61_world_fixture(
        "last_ball_persistence", &config->snorlax);
    s61_save_path(save_path, sizeof(save_path), directory,
                  "last-ball-persist");
    if (write_phase)
        s61_generate(rom_path, save_path, &giver);
    if (write_phase)
        s61_snapshot_persistence_writer_before(save_path);

    s61_allow_savedata_time_offset_notice = !write_phase;
    struct mCore *core = s61_open_fresh(
        rom_path, save_path, write_phase ? &giver : &snorlax);
    s61_allow_savedata_time_offset_notice = false;
    if ((write_phase && s61_savedata_time_offset_notices != 0U)
        || s61_savedata_time_offset_notices > 1U)
        s61_die("last-ball fresh-process RTC notice count differs");

    unsigned walked = 0U;
    uint16_t battle_species = 0U;
    uint8_t battle_outcome = 0U;
    struct S61BallThrowResult throw_result = {0};
    unsigned normal_save_generations = 0U;
    if (write_phase) {
        if (read16(core, WORLD_LAST_USED_BALL) != 0U)
            s61_die("new-game last-ball baseline is not zero");
        char producer_path[4096];
        struct S61Capture producer = s61_new_capture(
            directory, "last-ball-producer", producer_path,
            sizeof(producer_path));
        s61_acquire_flute(core, config, &producer, &walked);
        s61_prepare_master_ball_fixture(core);
        s61_stock_warp_save(core, &snorlax);
        bootstrap_close_core(core);

        s61_allow_savedata_time_offset_notice = true;
        core = s61_open_fresh(rom_path, save_path, &snorlax);
        s61_allow_savedata_time_offset_notice = false;
        if (s61_savedata_time_offset_notices > 1U)
            s61_die("last-ball consumer RTC notice count differs");
        s61_prepare_ball_pocket_cursor(core);
        walked += s61_walk_approach(core, &config->snorlax);
        char battle_path[4096];
        struct S61Capture battle_capture = s61_new_capture(
            directory, "last-ball-snorlax", battle_path,
            sizeof(battle_path));
        if (!s61_drive_interaction(
                core, config->snorlax.action_key, S61_CHOICE_YES,
                &battle_capture, true)
            || !s61_battle_active(core))
            s61_die("last-ball Snorlax battle did not start by walk+keys");
        struct FixtureResult battle = {0};
        world_record_wild(core, &snorlax, &battle);
        battle_species = battle.first_wild_species;
        if (battle_species != config->snorlax_species)
            s61_die("last-ball fixture entered the wrong event battle");
        throw_result = s61_throw_master_ball_with_keys(core, &snorlax);
        battle_outcome = throw_result.outcome;
        if (s61_item(core, WORLD_MASTER_BALL) != 0U)
            s61_die("real Master Ball throw did not consume the item");
        if (!s61_normal_input_save(core) || !s61_normal_input_save(core))
            s61_die("last-ball normal-input two-generation save failed");
        normal_save_generations = 2U;
    } else {
        if (s61_item(core, WORLD_MASTER_BALL) != 0U)
            s61_die("consumed Master Ball reappeared after Continue");
    }
    if (read16(core, WORLD_LAST_USED_BALL) != WORLD_MASTER_BALL)
        s61_die("last-used ball did not survive fresh-process Continue");
    if (s61_flag(core, config->flute_flag) == 0U
        || s61_flag(core, config->snorlax_hidden_flag) == 0U)
        s61_die("last-ball story state did not persist with the capture");

    int artifact_size = snprintf(
        artifact, sizeof(artifact), "%s/last-ball-%s",
        directory, write_phase ? "writer" : "reader");
    if (artifact_size <= 0 || (size_t)artifact_size >= sizeof(artifact))
        s61_die("last-ball framebuffer path formatting failed");
    s61_write_framebuffer_ppm(
        artifact, s61_video,
        write_phase ? "PERSISTENCE_WRITER_FRAME"
                    : "PERSISTENCE_READER_FRAME");
    printf("{\"schema_version\":2,\"status\":\"PASS\","
           "\"case\":\"last_ball_persistence\",\"phase\":\"%s\","
           "\"fresh_title_continue\":true,"
           "\"fresh_process_rtc_offset_notice\":%s,"
           "\"producer_via_normal_dialogue\":%s,"
           "\"fresh_consumer_continue_before_battle\":%s,"
           "\"stock_warp_before_battle\":%s,"
           "\"actual_walk_direction_a_battle\":%s,"
           "\"actual_battle_bag_direction_a\":%s,"
           "\"battle_action_cursor_host_write\":false,"
           "\"battle_preparation_host_writes_only\":true,"
           "\"actual_walk_steps\":%u,\"battle_species\":%u,"
           "\"battle_outcome\":%u,\"master_ball_consumed\":true,"
           "\"last_used_ball_address\":\"0x%08X\","
           "\"last_used_ball\":%u,"
           "\"save_via_start_menu_input\":%s,"
           "\"normal_save_generations\":%u,"
           "\"separate_process_readback\":%s,"
           "\"warnings\":0}\n",
           write_phase ? "WRITE" : "READ",
           s61_savedata_time_offset_notices != 0U ? "true" : "false",
           write_phase ? "true" : "false",
           write_phase ? "true" : "false",
           write_phase ? "true" : "false",
           write_phase ? "true" : "false",
           write_phase ? "true" : "false",
           walked, battle_species, battle_outcome,
           WORLD_LAST_USED_BALL, read16(core, WORLD_LAST_USED_BALL),
           write_phase ? "true" : "false", normal_save_generations,
           write_phase ? "false" : "true");
    bootstrap_close_core(core);
}

static void s61_case_critical_fixed_encounter_save(
    const char *rom_path, const char *directory,
    const struct S61Config *config)
{
    char save_path[4096U];
    char producer_artifact[4096U];
    char no_artifact[4096U];
    char yes_artifact[4096U];
    char final_artifact[4096U];
    struct Fixture giver = s61_world_fixture(
        "critical_fixed_encounter_save", &config->giver);
    struct Fixture snorlax = s61_world_fixture(
        "critical_fixed_encounter_save", &config->snorlax);
    s61_save_path(save_path, sizeof(save_path), directory,
                  "critical-fixed-encounter-save");

    /* Start from a real title/new-game generated save, then enter every
     * gameplay phase through a fresh-core title Continue. */
    s61_generate(rom_path, save_path, &giver);
    struct mCore *core = s61_open_fresh(
        rom_path, save_path, &giver);
    unsigned walked = 0U;
    struct S61Capture producer_capture = s61_new_capture(
        directory, "critical-flute-producer", producer_artifact,
        sizeof(producer_artifact));
    s61_acquire_flute(
        core, config, &producer_capture, &walked);
    if (producer_capture.count == 0U)
        s61_die("critical flute producer showed no rendered dialogue");

    /* The event, choices, battle completion, field return, and saves all use
     * ordinary GBA input or stock game entry points. */
    s61_stock_warp_save(core, &snorlax);
    uint8_t *pre_battle_save = s61_cow_clone_savedata(core);
    uint64_t pre_battle_save_hash = s61_hash_bytes(
        pre_battle_save, BOOTSTRAP_SAVE_SIZE);
    bootstrap_close_core(core);
    core = NULL;
    s61_write_exact_binary(
        save_path, pre_battle_save, BOOTSTRAP_SAVE_SIZE);
    free(pre_battle_save);

    core = s61_open_fresh(rom_path, save_path, &snorlax);
    bool visible_before = s61_object_visible(core, &config->snorlax);
    if (!visible_before) {
        uint32_t save1 = world_save1(core, s61_case_name);
        fprintf(stderr,
                "critical Snorlax pre-walk hidden group=%u map=%u "
                "x=%u y=%u flute_flag=%u hidden_flag=%u item=%u\n",
                read8(core, save1 + 4U), read8(core, save1 + 5U),
                read16(core, save1), read16(core, save1 + 2U),
                s61_flag(core, config->flute_flag),
                s61_flag(core, config->snorlax_hidden_flag),
                s61_item(core, config->flute_item));
        s61_die("critical Snorlax is hidden before battle");
    }
    walked += s61_walk_approach(core, &config->snorlax);

    struct S61Capture no_capture = s61_new_capture(
        directory, "critical-snorlax-no", no_artifact,
        sizeof(no_artifact));
    bool no_released = s61_drive_interaction(
        core, config->snorlax.action_key, S61_CHOICE_NO,
        &no_capture, false);
    bool no_preserved = visible_before && no_released
        && !s61_battle_active(core)
        && s61_flag(core, config->snorlax_hidden_flag) == 0U
        && s61_object_visible(core, &config->snorlax)
        && no_capture.count != 0U;
    if (!no_preserved)
        s61_die("critical Snorlax No branch did not return to field");

    struct S61Capture yes_capture = s61_new_capture(
        directory, "critical-snorlax-yes", yes_artifact,
        sizeof(yes_artifact));
    bool yes_started = s61_drive_interaction(
        core, config->snorlax.action_key, S61_CHOICE_YES,
        &yes_capture, true);
    if (!yes_started || !s61_battle_active(core)
        || yes_capture.count == 0U)
        s61_die("critical Snorlax Yes branch did not start a battle");
    struct FixtureResult battle = {0};
    world_record_wild(core, &snorlax, &battle);
    if (battle.first_wild_species != config->snorlax_species)
        s61_die("critical Snorlax battle species differs");
    world_finish_battle(core, &snorlax, &battle, false);
    world_wait_player_ready(core, &snorlax);
    bool battle_completed = battle.battle_completed;
    bool event_state_exact = s61_flag(
        core, config->snorlax_hidden_flag) == 1U
        && !s61_object_visible(core, &config->snorlax)
        && s61_flag(core, config->flute_flag) == 1U
        && s61_item(core, config->flute_item) == 1U;
    struct S61FieldRoundtripResult post_battle_roundtrip =
        s61_field_roundtrip(
            core, "critical-fixed-post-battle",
            snorlax.group, snorlax.map);
    if (!battle_completed || !event_state_exact
        || !s61_field_roundtrip_exact(&post_battle_roundtrip)) {
        fprintf(stderr,
                "critical fixed diagnostic completed=%u outcome=%u "
                "hidden=%u visible=%u flute_flag=%u item=%u "
                "field=%u controls=%u running=%u tile=%u start=%u "
                "menu=%08" PRIX32 " back=%u callback=%u map=%u\n",
                battle.battle_completed ? 1U : 0U,
                battle.battle_outcome,
                s61_flag(core, config->snorlax_hidden_flag),
                s61_object_visible(core, &config->snorlax) ? 1U : 0U,
                s61_flag(core, config->flute_flag),
                s61_item(core, config->flute_item),
                s61_field_roundtrip_exact(&post_battle_roundtrip) ? 1U : 0U,
                post_battle_roundtrip.controls_released ? 1U : 0U,
                post_battle_roundtrip.running_state_released ? 1U : 0U,
                post_battle_roundtrip.tile_transition_released ? 1U : 0U,
                post_battle_roundtrip.start_pressed ? 1U : 0U,
                post_battle_roundtrip.menu_callback_observed,
                post_battle_roundtrip.back_pressed ? 1U : 0U,
                post_battle_roundtrip.callback_ordered ? 1U : 0U,
                post_battle_roundtrip.map_preserved ? 1U : 0U);
        s61_die("critical fixed battle did not reach a stable field state");
    }

    if (!s61_normal_input_save(core) || !s61_normal_input_save(core))
        s61_die("critical normal-input two-generation save failed");
    uint8_t *saved = s61_cow_clone_savedata(core);
    uint64_t saved_hash = s61_hash_bytes(saved, BOOTSTRAP_SAVE_SIZE);
    bootstrap_close_core(core);
    core = NULL;
    s61_write_exact_binary(save_path, saved, BOOTSTRAP_SAVE_SIZE);

    core = s61_open_fresh(rom_path, save_path, &snorlax);
    uint8_t *reloaded = s61_cow_clone_savedata(core);
    uint64_t reloaded_hash = s61_hash_bytes(
        reloaded, BOOTSTRAP_SAVE_SIZE);
    bool save_raw_exact = memcmp(
        saved, reloaded, BOOTSTRAP_SAVE_SIZE) == 0;
    free(reloaded);
    bool reloaded_state_exact =
        s61_flag(core, config->flute_flag) == 1U
        && s61_item(core, config->flute_item) == 1U
        && s61_flag(core, config->snorlax_hidden_flag) == 1U
        && !s61_object_visible(core, &config->snorlax);
    struct S61FieldRoundtripResult reload_roundtrip = s61_field_roundtrip(
        core, "critical-fixed-after-reload",
        snorlax.group, snorlax.map);
    if (!save_raw_exact || !reloaded_state_exact
        || !s61_field_roundtrip_exact(&reload_roundtrip))
        s61_die("critical fresh Continue did not preserve battle/save state");

    int artifact_size = snprintf(
        final_artifact, sizeof(final_artifact),
        "%s/critical-fixed-after-reload", directory);
    if (artifact_size <= 0
        || (size_t)artifact_size >= sizeof(final_artifact))
        s61_die("critical final framebuffer path is too long");
    s61_write_framebuffer_ppm(
        final_artifact, s61_video, "CRITICAL_FIXED_AFTER_RELOAD_FRAME");

    uint8_t *final_save = s61_cow_clone_savedata(core);
    bootstrap_close_core(core);
    core = NULL;
    s61_write_exact_binary(save_path, final_save, BOOTSTRAP_SAVE_SIZE);
    free(final_save);
    free(saved);

    printf("{\"schema_version\":1,\"status\":\"PASS\","
           "\"case\":\"critical_fixed_encounter_save\","
           "\"fresh_core_continue_count\":3,"
           "\"producer_via_normal_dialogue\":true,"
           "\"actual_walk_steps\":%u,"
           "\"stock_warp_then_fresh_continue\":true,"
           "\"no_branch_preserved\":true,"
           "\"yes_branch_battle_started\":true,"
           "\"battle_species\":%u,\"battle_outcome_last_sample\":%u,"
           "\"battle_completed_via_normal_fight_input\":true,"
           "\"post_battle_field_input_recovered\":true,"
           "\"normal_start_menu_save_generations\":2,"
           "\"fresh_continue_after_normal_save\":true,"
           "\"save_raw_128k_exact_after_continue\":true,"
           "\"pre_battle_save_fnv1a64\":\"%016" PRIX64 "\","
           "\"saved_fnv1a64\":\"%016" PRIX64 "\","
           "\"reloaded_fnv1a64\":\"%016" PRIX64 "\","
           "\"flute_item_persisted\":true,"
           "\"snorlax_hidden_flag_persisted\":true,"
           "\"captures\":{\"producer\":",
           walked, config->snorlax_species, battle.battle_outcome,
           pre_battle_save_hash, saved_hash, reloaded_hash);
    s61_print_capture(&producer_capture);
    printf(",\"no\":");
    s61_print_capture(&no_capture);
    printf(",\"yes\":");
    s61_print_capture(&yes_capture);
    printf("},\"post_battle_field_roundtrip\":");
    s61_print_field_roundtrip(&post_battle_roundtrip);
    printf(",\"reload_field_roundtrip\":");
    s61_print_field_roundtrip(&reload_roundtrip);
    printf(",\"failed\":0,\"untested\":0,\"warnings\":0}\n");
}

static uint32_t s61_crc32_core_range(struct mCore *core,
                                     uint32_t address, size_t size)
{
    uint32_t crc = 0xFFFFFFFFU;
    for (size_t index = 0U; index < size; ++index) {
        crc ^= read8(core, address + (uint32_t)index);
        for (unsigned bit = 0U; bit < 8U; ++bit) {
            uint32_t mask = 0U - (crc & 1U);
            crc = (crc >> 1) ^ (0xEDB88320U & mask);
        }
    }
    return crc ^ 0xFFFFFFFFU;
}

static unsigned s61_popcount14(uint16_t value)
{
    unsigned count = 0U;
    for (unsigned bit = 0U; bit < WORLD_SAVE_SLOT_SECTORS; ++bit)
        count += (value >> bit) & 1U;
    return count;
}

static void s61_flash_select_bank(struct mCore *core, unsigned bank)
{
    if (bank > 1U)
        s61_die("flash bank is outside the 1 Mbit save device");
    /* The GBA exposes 1 Mbit Flash through a banked 64 KiB window.  mCore's
     * bus API intentionally models that hardware window: adding 0x10000 to
     * an address does not select bank 1.  Use the stock AMD command sequence
     * before inspecting a physical sector, then keep all reads inside the
     * 0x0E000000..0x0E00FFFF window. */
    core->busWrite8(core, WORLD_FLASH_COMMAND_A, 0xAAU);
    core->busWrite8(core, WORLD_FLASH_COMMAND_B, 0x55U);
    core->busWrite8(core, WORLD_FLASH_COMMAND_A, 0xB0U);
    core->busWrite8(core, WORLD_FLASH_BANK_REGISTER, (uint8_t)bank);
}

static uint32_t s61_flash_sector_window(struct mCore *core,
                                        unsigned physical_sector)
{
    if (physical_sector >= 32U)
        s61_die("physical flash sector is outside the save device");
    s61_flash_select_bank(core, physical_sector / 16U);
    return WORLD_FLASH_BASE
        + (physical_sector % 16U) * WORLD_SECTOR_SIZE;
}

static uint16_t s61_valid_generation_mask(struct mCore *core,
                                          uint32_t counter,
                                          bool *duplicate)
{
    uint16_t mask = 0U;
    *duplicate = false;
    for (unsigned sector = 0U;
         sector < WORLD_SAVE_SLOT_SECTORS * 2U; ++sector) {
        uint32_t address = s61_flash_sector_window(core, sector);
        if (read32(core, address + WORLD_SAVE_SIGNATURE_OFFSET)
                != WORLD_SAVE_SIGNATURE
            || read32(core, address + WORLD_SAVE_COUNTER_OFFSET) != counter)
            continue;
        uint16_t id = read16(core, address + WORLD_SAVE_ID_OFFSET);
        if (id >= WORLD_SAVE_SLOT_SECTORS)
            continue;
        uint16_t bit = (uint16_t)(1U << id);
        if ((mask & bit) != 0U)
            *duplicate = true;
        mask |= bit;
    }
    return mask;
}

static bool s61_stage61_record_matches_live(struct mCore *core,
                                            uint32_t sector_address)
{
    uint32_t record = sector_address + WORLD_STAGE61_RECORD_OFFSET;
    uint32_t payload = record + WORLD_STAGE61_RECORD_HEADER_SIZE;
    if (read32(core, record) != WORLD_STAGE61_RECORD_MAGIC
        || read16(core, record + 4U) != WORLD_STAGE61_RECORD_VERSION
        || read16(core, record + 6U)
            != WORLD_STAGE61_RECORD_PAYLOAD_SIZE)
        return false;
    uint32_t crc = read32(core, record + 8U);
    if (read32(core, record + 12U) != ~crc
        || s61_crc32_core_range(
               core, payload, WORLD_STAGE61_RECORD_PAYLOAD_SIZE) != crc)
        return false;
    for (uint32_t index = 0U; index < 0x200U; ++index)
        if (read8(core, payload + index)
                != read8(core, WORLD_EXPANDED_FLAGS_VARS + index))
            return false;
    for (uint32_t index = 0U; index < 0x400U; ++index)
        if (read8(core, payload + 0x200U + index)
                != read8(core, WORLD_EXPANDED_FLAGS_VARS + 0x200U + index))
            return false;
    for (uint32_t index = 0U; index < 2U; ++index)
        if (read8(core, payload + 0x600U + index)
                != read8(core, WORLD_LAST_USED_BALL + index))
            return false;
    for (uint32_t index = 0U; index < 4U; ++index)
        if (read8(core, payload + 0x602U + index)
                != read8(core, WORLD_PLAYER_COINS + index))
            return false;
    return true;
}

static unsigned s61_generation_id13_physical_sector(struct mCore *core)
{
    uint16_t first = read16(core, WORLD_FIRST_SAVE_SECTOR);
    uint32_t counter = read32(core, WORLD_SAVE_COUNTER);
    return (unsigned)((first + 13U)
        % WORLD_SAVE_SLOT_SECTORS)
        + WORLD_SAVE_SLOT_SECTORS * (unsigned)(counter & 1U);
}

static void s61_apply_link_save_canaries(struct mCore *core)
{
    (void)s61_call_synced(core, WORLD_FLAG_SET,
                         0x18B4U, 0U, 0U, 0U);
    (void)s61_call_synced(core, WORLD_VAR_SET,
                         0x5170U, 0x61A5U, 0U, 0U);
    write16(core, WORLD_LAST_USED_BALL, 3U);
    write32_bytes(core, WORLD_PLAYER_COINS, 0x00054321U);
    if (s61_flag(core, 0x18B4U) != 1U
        || s61_call_synced(core, WORLD_VAR_GET,
                           0x5170U, 0U, 0U, 0U) != 0x61A5U
        || read16(core, WORLD_LAST_USED_BALL) != 3U
        || read32(core, WORLD_PLAYER_COINS) != 0x00054321U)
        s61_die("link-full canary preparation did not commit");
}

static void s61_assert_link_save_canaries(struct mCore *core)
{
    if (s61_flag(core, 0x18B4U) != 1U
        || s61_call_synced(core, WORLD_VAR_GET,
                           0x5170U, 0U, 0U, 0U) != 0x61A5U
        || read16(core, WORLD_LAST_USED_BALL) != 3U
        || read32(core, WORLD_PLAYER_COINS) != 0x00054321U)
        s61_die("link-full canaries differ after save/Continue");
}

static void s61_case_link_full_save_persistence(
    const char *rom_path, const char *directory, bool write_phase,
    const struct S61Config *config)
{
    char save_path[4096];
    char artifact[4096];
    struct Fixture fixture = s61_world_fixture(
        "link_full_save_persistence", &config->giver);
    s61_save_path(save_path, sizeof(save_path), directory,
                  "link-full-persist");
    if (write_phase)
        s61_generate(rom_path, save_path, &fixture);
    if (write_phase)
        s61_snapshot_persistence_writer_before(save_path);

    s61_allow_savedata_time_offset_notice = !write_phase;
    struct mCore *core = s61_open_fresh(rom_path, save_path, &fixture);
    s61_allow_savedata_time_offset_notice = false;
    if ((write_phase && s61_savedata_time_offset_notices != 0U)
        || s61_savedata_time_offset_notices > 1U)
        s61_die("link-full fresh-process RTC notice count differs");

    uint8_t sector31_before[WORLD_SECTOR_SIZE];
    s61_flash_select_bank(core, 1U);
    s61_read_core_range(core, WORLD_SECTOR31_FLASH,
                        sector31_before, sizeof(sector31_before));
    bool duplicate = false;
    uint32_t previous_counter = read32(core, WORLD_SAVE_COUNTER);
    uint32_t committed_counter = previous_counter;
    unsigned delayed_valid_chunks = WORLD_SAVE_SLOT_SECTORS;
    unsigned committed_valid_chunks = 0U;
    unsigned atomic_diff_count = 0U;
    bool delayed_signature_observed = false;
    bool delayed_record_exact = false;
    bool task_states[12] = {false};
    unsigned id13_physical_sector = 0U;
    uint32_t id13_sector = 0U;
    uint8_t *delayed_sector = malloc(WORLD_SECTOR_SIZE);
    if (delayed_sector == NULL)
        s61_die("link-full delayed-sector allocation failed");

    if (write_phase) {
        uint16_t previous_mask = s61_valid_generation_mask(
            core, previous_counter, &duplicate);
        if (duplicate || previous_mask != 0x3FFFU) {
            fprintf(stderr,
                    "link-full baseline counter=%08" PRIX32
                    " first=%u mask=%04X duplicate=%u\n",
                    previous_counter,
                    read16(core, WORLD_FIRST_SAVE_SECTOR),
                    previous_mask, duplicate);
            for (unsigned sector = 0U;
                 sector < WORLD_SAVE_SLOT_SECTORS * 2U; ++sector) {
                uint32_t address = s61_flash_sector_window(core, sector);
                fprintf(stderr,
                        "link-full baseline sector=%u id=%u"
                        " signature=%08" PRIX32
                        " counter=%08" PRIX32 "\n",
                        sector,
                        read16(core, address + WORLD_SAVE_ID_OFFSET),
                        read32(core, address + WORLD_SAVE_SIGNATURE_OFFSET),
                        read32(core, address + WORLD_SAVE_COUNTER_OFFSET));
            }
            s61_die("link-full baseline generation is incomplete");
        }
        s61_apply_link_save_canaries(core);
        bootstrap_prepare_save_map_view(core);
        /* A real Union Room entry records the field return point in
         * SaveBlock1.dynamicWarp before Task_LinkFullSave reaches state 3.
         * The task deliberately persists CONTINUE_GAME_WARP while its saved
         * chunk is being written, so omitting this stock prerequisite creates
         * a self-consistent flash generation that resumes at zero/zero. */
        uint32_t save1 = world_save1(core, fixture.name);
        (void)s61_call_synced(
            core, WORLD_SET_DYNAMIC_WARP, 0U,
            fixture.group, fixture.map, UINT32_MAX);
        save1 = world_save1(core, fixture.name);
        if (read8(core, save1 + 0x14U) != fixture.group
            || read8(core, save1 + 0x15U) != fixture.map
            || read8(core, save1 + 0x16U) != 0xFFU
            || read16(core, save1 + 0x18U) != read16(core, save1)
            || read16(core, save1 + 0x1AU) != read16(core, save1 + 2U))
            s61_die("Union Room dynamic return warp preparation differs");
        uint32_t task_entry = (uint32_t)s61_uint_env(
            "S61_TASK_LINK_FULL_SAVE", WORLD_TASK_LINK_FULL_SAVE,
            UINT32_MAX);
        uint32_t replace_symbol = (uint32_t)s61_uint_env(
            "S61_HANDLE_REPLACE_SYMBOL", 0U, UINT32_MAX);
        if ((task_entry & 1U) == 0U
            || task_entry < 0x08000001U || task_entry >= 0x0A000000U
            || replace_symbol < 0x09000000U
            || replace_symbol >= 0x0A000000U)
            s61_die("link-full runtime symbol contract differs");
        uint32_t task_id = s61_call_synced(
            core, WORLD_CREATE_TASK, task_entry, 5U, 0U, 0U);
        if (task_id >= 16U)
            s61_die("Task_LinkFullSave could not allocate a real task");
        uint32_t task = WORLD_TASKS + task_id * WORLD_TASK_SIZE;
        if (read32(core, task) != task_entry)
            s61_die("created link-full task callback differs");

        /* States 0..2 are peer-link handshakes.  The fixture supplies the
         * already-reached Union Room barrier and then lets the real task own
         * serialization, all 14 writes, delayed replace and signature commit. */
        write16(core, task + WORLD_TASK_DATA, 3U);
        write16(core, task + WORLD_TASK_DATA + 2U, 0U);
        for (unsigned frame = 0U; frame < 12000U; ++frame) {
            if (read8(core, task + 4U) == 0U)
                break;
            uint16_t state = read16(core, task + WORLD_TASK_DATA);
            if (state < 12U)
                task_states[state] = true;
            if (state == 7U && !delayed_signature_observed) {
                committed_counter = read32(core, WORLD_SAVE_COUNTER);
                if (committed_counter != previous_counter + 1U)
                    s61_die("Task_LinkFullSave did not increment generation");
                id13_physical_sector =
                    s61_generation_id13_physical_sector(core);
                id13_sector = s61_flash_sector_window(
                    core, id13_physical_sector);
                if (read16(core, id13_sector + WORLD_SAVE_ID_OFFSET) != 13U
                    || read32(core, id13_sector
                                    + WORLD_SAVE_COUNTER_OFFSET)
                        != committed_counter
                    || read8(core, id13_sector
                                   + WORLD_SAVE_SIGNATURE_OFFSET) != 0xFFU
                    || read8(core, id13_sector
                                   + WORLD_SAVE_SIGNATURE_OFFSET + 1U) != 0x20U
                    || read8(core, id13_sector
                                   + WORLD_SAVE_SIGNATURE_OFFSET + 2U) != 0x01U
                    || read8(core, id13_sector
                                   + WORLD_SAVE_SIGNATURE_OFFSET + 3U) != 0x08U)
                    s61_die("chunk13 was valid before peer signature commit");
                uint16_t delayed_mask = s61_valid_generation_mask(
                    core, committed_counter, &duplicate);
                delayed_valid_chunks = s61_popcount14(delayed_mask);
                if (duplicate || delayed_mask != 0x1FFFU)
                    s61_die("delayed generation is not exactly chunks 0..12");
                id13_sector = s61_flash_sector_window(
                    core, id13_physical_sector);
                delayed_record_exact = s61_stage61_record_matches_live(
                    core, id13_sector);
                if (!delayed_record_exact)
                    s61_die("delayed chunk13 Stage61 record differs");
                s61_read_core_range(core, id13_sector, delayed_sector,
                                    WORLD_SECTOR_SIZE);
                delayed_signature_observed = true;
            }
            if (state == 8U || state == 10U)
                write32_bytes(core, WORLD_LINK_CALLBACK, 0U);
            s61_frames(core, 0U, 1U, NULL);
        }
        if (read8(core, task + 4U) != 0U)
            s61_die("Task_LinkFullSave did not reach DestroyTask");
        for (unsigned state = 3U; state <= 11U; ++state)
            if (!task_states[state])
                s61_die("Task_LinkFullSave skipped a save/commit state");
        if (!delayed_signature_observed)
            s61_die("Task_LinkFullSave delayed signature was not observed");
        uint16_t committed_mask = s61_valid_generation_mask(
            core, committed_counter, &duplicate);
        committed_valid_chunks = s61_popcount14(committed_mask);
        id13_sector = s61_flash_sector_window(
            core, id13_physical_sector);
        if (duplicate || committed_mask != 0x3FFFU
            || read32(core, id13_sector + WORLD_SAVE_SIGNATURE_OFFSET)
                != WORLD_SAVE_SIGNATURE
            || !s61_stage61_record_matches_live(core, id13_sector))
            s61_die("committed link-full generation/record differs");
        for (unsigned index = 0U; index < WORLD_SECTOR_SIZE; ++index) {
            uint8_t actual = read8(core, id13_sector + index);
            if (actual != delayed_sector[index]) {
                ++atomic_diff_count;
                if (index != WORLD_SAVE_SIGNATURE_OFFSET
                    || delayed_sector[index] != 0xFFU
                    || actual != (WORLD_SAVE_SIGNATURE & 0xFFU))
                    s61_die("link-full atomic commit changed more than signature");
            }
        }
        if (atomic_diff_count != 1U)
            s61_die("link-full atomic commit did not change exactly one byte");
        s61_assert_link_save_canaries(core);
    } else {
        s61_assert_link_save_canaries(core);
        committed_counter = read32(core, WORLD_SAVE_COUNTER);
        id13_physical_sector =
            s61_generation_id13_physical_sector(core);
        uint16_t committed_mask = s61_valid_generation_mask(
            core, committed_counter, &duplicate);
        committed_valid_chunks = s61_popcount14(committed_mask);
        id13_sector = s61_flash_sector_window(
            core, id13_physical_sector);
        if (duplicate || committed_mask != 0x3FFFU
            || read16(core, id13_sector + WORLD_SAVE_ID_OFFSET) != 13U
            || !s61_stage61_record_matches_live(core, id13_sector))
            s61_die("fresh Continue did not load a complete link generation");
        delayed_record_exact = true;
    }
    s61_flash_select_bank(core, 1U);
    if (!s61_core_range_equals(
            core, WORLD_SECTOR31_FLASH, sector31_before,
            sizeof(sector31_before), "sector31 during link-full save"))
        s61_die("link-full save changed sector31");
    uint64_t ledger_hash = 0U;
    if (!s61_sector31_ledger_matches(core, &ledger_hash))
        s61_die("link-full sector31 ledger differs");

    int artifact_size = snprintf(
        artifact, sizeof(artifact), "%s/link-full-%s",
        directory, write_phase ? "writer" : "reader");
    if (artifact_size <= 0 || (size_t)artifact_size >= sizeof(artifact))
        s61_die("link-full framebuffer path formatting failed");
    s61_write_framebuffer_ppm(
        artifact, s61_video,
        write_phase ? "PERSISTENCE_WRITER_FRAME"
                    : "PERSISTENCE_READER_FRAME");
    printf("{\"schema_version\":1,\"status\":\"PASS\","
           "\"case\":\"link_full_save_persistence\","
           "\"phase\":\"%s\",\"fresh_title_continue\":true,"
           "\"fresh_process_rtc_offset_notice\":%s,"
           "\"task_link_full_save_scheduler\":%s,"
           "\"union_room_peer_barrier_fixture\":%s,"
           "\"union_room_dynamic_warp_prepared\":%s,"
           "\"task_entry\":\"0x%08X\",\"task_state_seed\":3,"
           "\"task_states_seen\":[",
           write_phase ? "WRITE" : "READ",
           s61_savedata_time_offset_notices != 0U ? "true" : "false",
           write_phase ? "true" : "false",
           write_phase ? "true" : "false",
           write_phase ? "true" : "false",
           (unsigned)s61_uint_env(
               "S61_TASK_LINK_FULL_SAVE", WORLD_TASK_LINK_FULL_SAVE,
               UINT32_MAX));
    bool first_state = true;
    for (unsigned state = 0U; state < 12U; ++state) {
        if (!task_states[state])
            continue;
        printf("%s%u", first_state ? "" : ",", state);
        first_state = false;
    }
    printf("],\"handle_replace_symbol\":\"0x%08X\","
           "\"logical_record_chunk\":13,"
           "\"previous_counter\":%" PRIu32 ","
           "\"committed_counter\":%" PRIu32 ","
           "\"delayed_signature_observed\":%s,"
           "\"delayed_generation_valid_chunk_count\":%u,"
           "\"committed_generation_valid_chunk_count\":%u,"
           "\"record_payload_crc_exact\":%s,"
           "\"atomic_sector_diff_count\":%u,"
           "\"atomic_sector_diff_offset\":%s,"
           "\"expanded_flag_var_last_ball_coins_readback\":true,"
           "\"sector31_full_preserved\":true,"
           "\"sector31_ledger_match\":true,"
           "\"sector31_ledger_fnv1a64\":\"%016" PRIX64 "\","
           "\"separate_process_readback\":%s,\"warnings\":0}\n",
           (unsigned)s61_uint_env(
               "S61_HANDLE_REPLACE_SYMBOL", 0U, UINT32_MAX),
           previous_counter, committed_counter,
           delayed_signature_observed ? "true" : "false",
           delayed_valid_chunks, committed_valid_chunks,
           delayed_record_exact ? "true" : "false",
           atomic_diff_count,
           write_phase ? "4088" : "null",
           ledger_hash, write_phase ? "false" : "true");
    free(delayed_sector);
    bootstrap_close_core(core);
}

struct S61CatalogFreshReadConsumerResult {
    bool executed;
    struct S61CatalogRuntimePositionObservation runtime_position;
    bool object_visible;
    uint64_t visibility_framebuffer_hash;
    unsigned walked;
    const char *sequence_id;
    struct S61CatalogApproachObservation approach;
    struct S61Capture approach_capture;
    struct S61Capture interaction_capture;
    struct S61SequenceDriveResult drive;
    bool internal_controls_ok;
    bool field_released;
    bool battle_started;
    struct S61FieldRoundtripResult field_roundtrip;
    struct S61BattleLifecycleResult battle_lifecycle;
    struct S61PostBattleContinuationResult post_battle_continuation;
    struct S61SideEffectSnapshot *side_before;
    struct S61SideEffectSnapshot *side_after;
    struct S61SideEffectSnapshot *side_final;
};

static void s61_run_catalog_fresh_read_consumer(
    struct mCore *core, const char *directory, struct S61CatalogRow *row,
    struct S61CatalogFreshReadConsumerResult *result)
{
    if (!row->expect_interaction || !row->expect_visible
        || row->input_sequence_count == 0U
        || !row->actual_walk_required || row->walk_key_count == 0U)
        s61_die("persistence fresh reader requires an interactive walked row");
    result->side_before = malloc(sizeof(*result->side_before));
    result->side_after = malloc(sizeof(*result->side_after));
    result->side_final = malloc(sizeof(*result->side_final));
    struct S61SideEffectSnapshot *approach_before = malloc(
        sizeof(*approach_before));
    struct S61SideEffectSnapshot *approach_after = malloc(
        sizeof(*approach_after));
    if (result->side_before == NULL || result->side_after == NULL
        || result->side_final == NULL || approach_before == NULL
        || approach_after == NULL)
        s61_die("persistence fresh consumer snapshot allocation failed");

    /* The fresh process has already proved the serialized state.  From this
     * point onward the host performs positioning only: no branch flag, var,
     * item, trainer, rematch, RNG, or other catalog prerequisite is written.
     * Stock warp/map load and ordinary GBA keys must consume the persisted
     * state exactly as a player would. */
    struct Fixture fixture = s61_world_fixture(row->case_id, &row->interaction);
    s61_catalog_position_for_row(
        core, row, &fixture, false, &result->runtime_position);
    s61_verify_catalog_state(core, row);
    result->runtime_position.target_materialized_before_walk =
        s61_object_visible(core, &row->interaction);
    result->runtime_position.target_materialization_deferred_to_real_walk =
        result->runtime_position.producer_required
        && !result->runtime_position.target_materialized_before_walk;
    if (!result->runtime_position.target_materialized_before_walk
        && !result->runtime_position
                .target_materialization_deferred_to_real_walk)
        s61_die("persistence fresh consumer target is not visible after warp");

    s61_effect_observer_begin_case(core, row->case_id);
    char approach_label[1024];
    int approach_label_size = snprintf(
        approach_label, sizeof(approach_label),
        "%s-persist-reader-approach", row->case_id);
    if (approach_label_size <= 0
        || (size_t)approach_label_size >= sizeof(approach_label))
        s61_die("persistence approach artifact label is too long");
    char approach_artifact[4096];
    result->approach_capture = s61_new_capture(
        directory, approach_label, approach_artifact,
        sizeof(approach_artifact));
    s61_snapshot_side_effects(core, &row->interaction, approach_before);
    s61_assert_catalog_preinteraction_identity(
        row, approach_before,
        row->runtime_position_producer.kind
            == S61_CATALOG_RUNTIME_POSITION_NONE);
    result->approach.effect_hook_hits_before =
        s61_effect_observer_total_hook_hits();
    result->walked = s61_walk_catalog_execution(
        core, row, &result->approach_capture, &result->approach);
    result->approach.effect_hook_hits_after =
        s61_effect_observer_total_hook_hits();
    s61_snapshot_side_effects(core, &row->interaction, approach_after);
    s61_assert_catalog_preinteraction_identity(row, approach_after, true);
    s61_catalog_approach_persistent_observation(
        approach_before, approach_after, &result->approach);
    free(approach_after);
    free(approach_before);
    if (!s61_catalog_approach_exact(
            row, &result->approach_capture, &result->approach)) {
        s61_report_catalog_approach_failure(
            row, &result->approach_capture, &result->approach);
        s61_die("persistence fresh consumer approach is not exact");
    }
    result->object_visible = s61_object_visible(core, &row->interaction);
    result->runtime_position.target_materialized_before_a =
        result->object_visible;
    result->runtime_position.exact = result->runtime_position.exact
        && result->object_visible;
    if (!result->runtime_position.exact)
        s61_die("persistence fresh consumer target did not materialize");
    result->visibility_framebuffer_hash = bootstrap_framebuffer_hash(s61_video);

    /* This second readback occurs immediately before A.  It is deliberately
     * read-only and proves stock map load plus the real walk did not replace
     * the persisted branch state. */
    s61_verify_catalog_state(core, row);
    s61_snapshot_side_effects(
        core, &row->interaction, result->side_before);
    s61_assert_catalog_preinteraction_identity(
        row, result->side_before, true);

    const struct S61CatalogInputSequence *sequence =
        &row->input_sequences[0U];
    result->sequence_id = sequence->sequence_id;
    char interaction_label[1024];
    int interaction_label_size = snprintf(
        interaction_label, sizeof(interaction_label),
        "%s-persist-reader-%s", row->case_id, sequence->sequence_id);
    if (interaction_label_size <= 0
        || (size_t)interaction_label_size >= sizeof(interaction_label))
        s61_die("persistence interaction artifact label is too long");
    char interaction_artifact[4096];
    result->interaction_capture = s61_new_capture(
        directory, interaction_label, interaction_artifact,
        sizeof(interaction_artifact));
    result->interaction_capture.event_root_script_pointer = row->runtime_root;
    s61_begin_internal_control_capture(
        core, row, sequence, &result->interaction_capture);
    result->drive = s61_drive_input_sequence(
        core, sequence, &result->interaction_capture, true);
    result->internal_controls_ok = s61_internal_controls_ok(
        core, row, sequence);
    s61_end_internal_control_capture();
    result->battle_started = s61_battle_active(core);
    result->field_released = s61_field_terminal(core);
    s61_snapshot_side_effects(
        core, &row->interaction, result->side_after);
    if (result->battle_started) {
        result->battle_lifecycle = s61_complete_battle_lifecycle(
            core, row->case_id,
            result->side_after->world.location.group,
            result->side_after->world.location.map, sequence,
            &result->post_battle_continuation);
    } else if (result->field_released) {
        result->field_roundtrip = s61_field_roundtrip(
            core, row->case_id,
            result->side_after->world.location.group,
            result->side_after->world.location.map);
    }
    s61_snapshot_side_effects(
        core, &row->interaction, result->side_final);
    s61_finalize_facility_execution(core, &result->interaction_capture);
    s61_effect_observer_end_case(core);

    bool root_exact =
        result->interaction_capture.event_root_script_pointer_hits != 0U
        && result->interaction_capture.event_first_root_script_pointer
            == row->runtime_root
        && result->interaction_capture.event_first_root_group
            == row->interaction.group
        && result->interaction_capture.event_first_root_map
            == row->interaction.map
        && result->interaction_capture.event_first_root_x == row->stance_x
        && result->interaction_capture.event_first_root_y == row->stance_y;
    bool terminal_exact = result->drive.terminal_seen
        && !result->drive.premature_terminal
        && result->drive.steps_consumed == sequence->step_count
        && s61_catalog_terminal_matches(
            row->terminal, result->field_released, result->battle_started);
    bool text_exact = sequence->visible_text_expected
        ? result->interaction_capture.printer_call_count != 0U
        : result->interaction_capture.printer_call_count == 0U;
    bool lifecycle_exact = result->field_released
        ? s61_field_roundtrip_exact(&result->field_roundtrip)
        : result->battle_started
            && result->battle_lifecycle.completed_via_keys
            && (result->post_battle_continuation.facility_active_boundary
                ? !result->battle_lifecycle.field_released_after_battle
                    && !result->battle_lifecycle.start_menu_opened
                    && !result->battle_lifecycle.field_input_recovered
                : result->battle_lifecycle.field_released_after_battle
                    && result->battle_lifecycle.start_menu_opened
                    && result->battle_lifecycle.field_input_recovered);
    if (result->interaction_capture.invalid_control_flow
        || !root_exact || !terminal_exact || !text_exact
        || result->interaction_capture.maximum_baseline_pixel_difference
            < 2000U
        || !result->internal_controls_ok || !lifecycle_exact
        || result->side_final->input.field_input_recovered
            != !result->post_battle_continuation.facility_active_boundary)
        s61_die("persistence fresh reader physical consumer is not exact");
    result->executed = true;
}

static void s61_print_catalog_fresh_read_consumer(
    struct mCore *core, const struct S61CatalogRow *row,
    const struct S61CatalogFreshReadConsumerResult *result)
{
    printf("{\"fresh_process_after_title_continue\":true,"
           "\"branch_state_host_rewrites_after_continue\":0,"
           "\"host_positioning_only\":true,"
           "\"stock_warp_map_load\":%s,"
           "\"engine_teleport_map_load\":%s,"
           "\"runtime_position_producer\":",
           row->runtime_position_producer.kind
                   != S61_CATALOG_RUNTIME_POSITION_ENGINE_TELEPORT
               && row->runtime_position_producer.kind
                   != S61_CATALOG_RUNTIME_POSITION_TRAINER_TOWER_ON_TRANSITION
               ? "true" : "false",
           row->runtime_position_producer.kind
                   == S61_CATALOG_RUNTIME_POSITION_ENGINE_TELEPORT
               || row->runtime_position_producer.kind
                   == S61_CATALOG_RUNTIME_POSITION_TRAINER_TOWER_ON_TRANSITION
               ? "true" : "false");
    s61_print_catalog_runtime_position_observation(
        row, &result->runtime_position);
    printf(","
           "\"object_visible\":%s,"
           "\"visibility_framebuffer_fnv1a64\":\"%016" PRIX64 "\","
           "\"actual_walk_steps\":%u,\"approach_observation\":",
           result->object_visible ? "true" : "false",
           result->visibility_framebuffer_hash, result->walked);
    s61_print_catalog_approach_observation(
        row, &result->approach_capture, &result->approach);
    printf(",\"preinteraction_object_identity\":");
    s61_print_catalog_preinteraction_identity(row, result->side_before);
    printf(",\"input_sequence_id\":\"%s\","
           "\"input_steps_consumed\":%u,"
           "\"root_script_pointer_hits\":%u,"
           "\"first_root_script_pointer\":\"0x%08" PRIX32 "\","
           "\"capture\":",
           result->sequence_id, result->drive.steps_consumed,
           result->interaction_capture.event_root_script_pointer_hits,
           result->interaction_capture.event_first_root_script_pointer);
    s61_print_capture(&result->interaction_capture);
    printf(",\"internal_controls\":");
    s61_print_internal_controls(
        row, &row->input_sequences[0U]);
    printf(",\"deferred_external_controls\":");
    /* The consumer result is printed before the core is closed, so all raw
     * postinteraction control owners remain directly readable here. */
    s61_print_deferred_external_controls(
        core, row, &result->interaction_capture);
    printf(",\"field_roundtrip\":");
    if (result->field_released)
        s61_print_field_roundtrip(&result->field_roundtrip);
    else
        fputs("null", stdout);
    printf(",\"post_battle\":");
    s61_print_battle_lifecycle(&result->battle_lifecycle);
    printf(",\"post_battle_continuation\":");
    s61_print_post_battle_continuation(
        &result->post_battle_continuation, &row->input_sequences[0U]);
    printf(",\"side_effects\":");
    s61_print_side_effects(result->side_before, result->side_final);
    fputs(",\"effect_visibility_and_input_exact\":true,"
          "\"field_input_recovered\":true,\"exact\":true}", stdout);
}

static void s61_free_catalog_fresh_read_consumer(
    struct S61CatalogFreshReadConsumerResult *result)
{
    s61_release_facility_execution(&result->interaction_capture);
    free(result->side_final);
    free(result->side_after);
    free(result->side_before);
    result->side_final = NULL;
    result->side_after = NULL;
    result->side_before = NULL;
}

static void s61_case_catalog_state_persistence(const char *rom_path,
                                               const char *directory,
                                               bool write_phase,
                                               bool legacy_source)
{
    const char *catalog_path = getenv("S61_PERSIST_TSV");
    if (catalog_path == NULL || catalog_path[0] == '\0')
        s61_die("S61_PERSIST_TSV is required for state persistence");
    FILE *stream = fopen(catalog_path, "rb");
    if (stream == NULL)
        s61_die("state persistence TSV could not be opened");
    char header[4096];
    char line[S61_CATALOG_LINE_SIZE];
    if (fgets(header, sizeof(header), stream) == NULL)
        s61_die("state persistence TSV is empty");
    size_t header_size = strlen(header);
    while (header_size != 0U
           && (header[header_size - 1U] == '\n'
               || header[header_size - 1U] == '\r'))
        header[--header_size] = '\0';
    if (strcmp(header, S61_CATALOG_HEADER) != 0)
        s61_die("state persistence TSV header differs");
    if (fgets(line, sizeof(line), stream) == NULL)
        s61_die("state persistence TSV has no state row");
    struct S61CatalogRow row = s61_parse_catalog_row(line);
    char extra[2];
    if (fgets(extra, sizeof(extra), stream) != NULL || ferror(stream)
        || fclose(stream) != 0)
        s61_die("state persistence TSV must contain exactly one row");
    bool expanded_flag = false;
    bool expanded_var = false;
    for (unsigned index = 0U; index < row.flag_count; ++index)
        expanded_flag = expanded_flag || row.flags[index].flag >= 0x1000U;
    for (unsigned index = 0U; index < row.var_count; ++index)
        expanded_var = expanded_var || row.vars[index].id > 0x40FFU;
    if (!expanded_flag || !expanded_var)
        s61_die("persistence probe requires expanded flag and expanded var");
    if (legacy_source) {
        for (unsigned index = 0U; index < row.flag_count; ++index)
            if (row.flags[index].flag < 0x0900U)
                s61_die("legacy migration row contains a stock flag");
        for (unsigned index = 0U; index < row.var_count; ++index)
            if (row.vars[index].id < 0x5000U)
                s61_die("legacy migration row contains a stock var");
        if (row.item_count != 0U || row.trainer_count != 0U)
            s61_die("legacy migration row may only mutate expanded state");
    }

    s61_case_name = row.case_id;
    bootstrap_phase = row.case_id;
    char save_path[4096];
    int save_size = snprintf(
        save_path, sizeof(save_path), "%s/%s-%spersist.srm",
        directory, row.case_id, legacy_source ? "legacy-" : "");
    if (save_size <= 0 || (size_t)save_size >= sizeof(save_path))
        s61_die("state persistence save path formatting failed");
    struct S61Interaction location = row.interaction;
    if (legacy_source) {
        location.group = (uint8_t)s61_uint_env(
            "S61_LEGACY_GROUP", 96U, 255U);
        location.map = (uint8_t)s61_uint_env(
            "S61_LEGACY_MAP", 5U, 255U);
        location.start_x = (uint16_t)s61_uint_env(
            "S61_LEGACY_X", 20U, 65535U);
        location.start_y = (uint16_t)s61_uint_env(
            "S61_LEGACY_Y", 20U, 65535U);
        location.action_key = WORLD_KEY_UP;
        location.approach_steps = 1U;
        location.local_id = 0U;
    }
    struct Fixture fixture = s61_world_fixture(row.case_id, &location);
    if (write_phase && !legacy_source)
        s61_generate(rom_path, save_path, &fixture);
    if (write_phase && !legacy_source)
        s61_snapshot_persistence_writer_before(save_path);
    bool expect_rtc_notice = !write_phase || legacy_source;
    s61_allow_savedata_time_offset_notice = expect_rtc_notice;
    struct mCore *core = s61_open_fresh(rom_path, save_path, &fixture);
    s61_allow_savedata_time_offset_notice = false;
    if ((!expect_rtc_notice && s61_savedata_time_offset_notices != 0U)
        || s61_savedata_time_offset_notices > 1U)
        s61_die("fresh-process save RTC notice count differs");

    uint8_t sector31_before[WORLD_SECTOR_SIZE];
    uint8_t legacy_before[WORLD_LEGACY_FLAGS_VARS_SIZE];
    uint8_t legacy_save_baseline[WORLD_LEGACY_FLAGS_VARS_SIZE];
    s61_flash_select_bank(core, 1U);
    s61_read_core_range(core, WORLD_SECTOR31_FLASH,
                        sector31_before, sizeof(sector31_before));
    uint32_t save1 = world_save1(core, row.case_id);
    s61_read_core_range(
        core, save1 + WORLD_LEGACY_FLAGS_VARS_OFFSET,
        legacy_before, sizeof(legacy_before));
    bool expanded_zero_before_write = false;
    if (write_phase && legacy_source) {
        expanded_zero_before_write = s61_core_range_zero(
            core, WORLD_EXPANDED_FLAGS_VARS,
            WORLD_EXPANDED_FLAGS_VARS_SIZE);
        if (!expanded_zero_before_write)
            s61_die("expanded state is nonzero before first persistence write");
    }
    unsigned save_generations = 0U;
    if (write_phase) {
        if (!legacy_source)
            s61_set_legacy_var_canaries(core, &row);
        s61_apply_catalog_state(core, &row);
        if (!s61_persistence_readback_matches(
                core, &row, !legacy_source))
            s61_die("expanded state changed before normal ROM save");
        s61_read_core_range(
            core, save1 + WORLD_LEGACY_FLAGS_VARS_OFFSET,
            legacy_save_baseline, sizeof(legacy_save_baseline));
        if (legacy_source
            && memcmp(legacy_before, legacy_save_baseline,
                      sizeof(legacy_before)) != 0)
            s61_die("expanded state preparation changed legacy state");
        if (!s61_normal_input_save(core) || !s61_normal_input_save(core))
            s61_die("expanded state normal-input ROM save failed");
        save_generations = 2U;
        if (!s61_persistence_readback_matches(
                core, &row, !legacy_source))
            s61_die("expanded state changed after normal ROM save");
        if (!s61_core_range_equals(
                core, save1 + WORLD_LEGACY_FLAGS_VARS_OFFSET,
                legacy_save_baseline, sizeof(legacy_save_baseline),
                "legacy flags/vars during normal save"))
            s61_die("normal ROM save changed legacy flags/vars");
        s61_flash_select_bank(core, 1U);
        if (!s61_core_range_equals(
                core, WORLD_SECTOR31_FLASH, sector31_before,
                sizeof(sector31_before), "sector31 during normal save"))
            s61_die("normal ROM save changed sector31");
    } else {
        if (!s61_persistence_readback_matches(
                core, &row, !legacy_source))
            s61_die("expanded state/canary changed across process Continue");
        s61_read_core_range(
            core, save1 + WORLD_LEGACY_FLAGS_VARS_OFFSET,
            legacy_save_baseline, sizeof(legacy_save_baseline));
    }
    uint64_t sector31_ledger_hash = 0U;
    if (!s61_sector31_ledger_matches(core, &sector31_ledger_hash))
        s61_die("sector31 ledger differs from its live EWRAM image");
    uint64_t sector31_before_hash = s61_hash_bytes(
        sector31_before, sizeof(sector31_before));
    s61_flash_select_bank(core, 1U);
    uint64_t sector31_after_hash = s61_hash_core_range(
        core, WORLD_SECTOR31_FLASH, WORLD_SECTOR_SIZE);
    uint64_t legacy_state_hash = s61_hash_core_range(
        core, save1 + WORLD_LEGACY_FLAGS_VARS_OFFSET,
        WORLD_LEGACY_FLAGS_VARS_SIZE);
    if (sector31_before_hash != sector31_after_hash)
        s61_die("sector31 hash differs despite byte-exact guard");
    struct S61CatalogFreshReadConsumerResult fresh_consumer = {0};
    if (!write_phase && !legacy_source)
        s61_run_catalog_fresh_read_consumer(
            core, directory, &row, &fresh_consumer);
    char artifact[4096];
    int artifact_size = snprintf(
        artifact, sizeof(artifact), "%s/%s-%spersist-%s",
        directory, row.case_id, legacy_source ? "legacy-" : "",
        write_phase ? "writer" : "reader");
    if (artifact_size <= 0 || (size_t)artifact_size >= sizeof(artifact))
        s61_die("state persistence framebuffer path formatting failed");
    s61_write_framebuffer_ppm(
        artifact, s61_video,
        write_phase ? "PERSISTENCE_WRITER_FRAME"
                    : "PERSISTENCE_READER_FRAME");
    const char *canaries = legacy_source ? "[]" :
        "[{\"id\":16384,\"value\":4951},"
        "{\"id\":16448,\"value\":9320},"
        "{\"id\":16639,\"value\":13980}]";
    printf("{\"schema_version\":3,\"status\":\"PASS\","
           "\"case\":\"%s\",\"phase\":\"%s\","
           "\"persistence_kind\":\"%s\","
           "\"case_id\":\"%s\",\"base_case_id\":\"%s\","
           "\"fresh_title_continue\":true,"
           "\"fresh_process_rtc_offset_notice\":%s,"
           "\"save_via_start_menu_input\":%s,"
           "\"normal_save_generations\":%u,"
           "\"state_counts\":{\"flags\":%u,\"vars\":%u,"
           "\"items\":%u,\"trainers\":%u},"
           "\"expanded_flag_readback\":true,"
           "\"expanded_var_readback\":true,"
           "\"expanded_state_zero_before_write\":%s,"
           "\"legacy_save_zero_migration_baseline\":%s,"
           "\"legacy_state_preserved\":true,"
           "\"legacy_state_fnv1a64\":\"%016" PRIX64 "\","
           "\"sector31_full_preserved\":true,"
           "\"sector31_full_fnv1a64_before\":\"%016" PRIX64 "\","
           "\"sector31_full_fnv1a64_after\":\"%016" PRIX64 "\","
           "\"sector31_ledger_match\":true,"
           "\"sector31_ledger_fnv1a64\":\"%016" PRIX64 "\","
           "\"legacy_saveblock1_var_canaries\":%s,"
           "\"fresh_read_consumer\":",
           legacy_source ? "catalog_state_legacy_persistence"
                         : "catalog_state_persistence",
           write_phase ? "WRITE" : "READ",
           legacy_source ? "LEGACY_STAGE60" : "GENERATED",
           row.case_id, row.base_case_id,
           s61_savedata_time_offset_notices != 0U ? "true" : "false",
           write_phase ? "true" : "false",
           save_generations, row.flag_count,
           row.var_count, row.item_count, row.trainer_count,
           expanded_zero_before_write ? "true" : "false",
           legacy_source && write_phase ? "true" : "false",
           legacy_state_hash, sector31_before_hash, sector31_after_hash,
           sector31_ledger_hash, canaries);
    if (fresh_consumer.executed)
        s61_print_catalog_fresh_read_consumer(
            core, &row, &fresh_consumer);
    else
        fputs("null", stdout);
    fputs(",\"warnings\":0}\n", stdout);
    s61_free_catalog_fresh_read_consumer(&fresh_consumer);
    bootstrap_close_core(core);
}

static struct S61CalibrationRow s61_parse_calibration_row(char *line)
{
    char *fields[S61_CALIBRATION_FIELD_COUNT];
    if (s61_split_catalog_fields(
            line, fields, S61_CALIBRATION_FIELD_COUNT)
            != S61_CALIBRATION_FIELD_COUNT)
        s61_die("calibration TSV field count differs");
    struct S61CalibrationRow row = {0};
    row.case_id = fields[0];
    row.owner_key = fields[1];
    if (!s61_catalog_identifier(row.case_id, false)
        || !s61_catalog_identifier(row.owner_key, true))
        s61_die("calibration identifier contains unsafe characters");
    row.group = (uint8_t)s61_parse_catalog_uint(
        fields[2], "group", 255U);
    row.map = (uint8_t)s61_parse_catalog_uint(fields[3], "map", 255U);
    row.local_id = (uint8_t)s61_parse_catalog_uint(
        fields[4], "local_id", 255U);
    row.object_x = (uint16_t)s61_parse_catalog_uint(
        fields[5], "object_x", 65535U);
    row.object_y = (uint16_t)s61_parse_catalog_uint(
        fields[6], "object_y", 65535U);
    row.visibility_flag = (uint16_t)s61_parse_catalog_uint(
        fields[7], "visibility_flag", 65535U);
    s61_parse_catalog_runtime_position_control(
        fields, 8U, &row.runtime_position_control);
    s61_parse_catalog_runtime_position_producer(
        fields, 11U, &row.runtime_position_producer);
    s61_validate_catalog_runtime_position_producer(
        &row.runtime_position_producer, row.group, row.map);
    s61_validate_catalog_runtime_position_binding(
        &row.runtime_position_control, &row.runtime_position_producer);
    return row;
}

static bool s61_try_wait_field_ready(
    struct mCore *core, const struct S61CalibrationRow *row,
    uint16_t expected_x, uint16_t expected_y)
{
    unsigned stable = 0U;
    for (unsigned frames = 0U; frames < 3600U; frames += 15U) {
        run_key_frames(core, 0U, 15U);
        uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
        bool save_ready = save1 >= 0x02000000U && save1 < 0x02040000U
            && (save1 & 3U) == 0U;
        uint8_t player = read8(core, WORLD_PLAYER_AVATAR + 5U);
        bool player_ready = player < 16U;
        if (player_ready) {
            uint32_t object = WORLD_OBJECT_EVENTS + player * 0x24U;
            player_ready = (read8(core, object) & 1U) != 0U
                && read8(core, WORLD_PLAYER_AVATAR
                         + WORLD_PLAYER_RUNNING_STATE_OFFSET) == 0U
                && read8(core, WORLD_PLAYER_AVATAR
                         + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET) == 0U;
        }
        bool ready = save_ready && player_ready && world_overworld(core)
            && !world_script_enabled(core)
            && read8(core, save1 + 4U) == row->group
            && read8(core, save1 + 5U) == row->map
            && read16(core, save1) == expected_x
            && read16(core, save1 + 2U) == expected_y;
        if (ready) {
            stable += 15U;
            if (stable >= 60U)
                return true;
        } else {
            stable = 0U;
        }
    }
    return false;
}

static bool s61_try_calibration_warp(
    struct mCore *core, const struct S61CalibrationRow *row,
    uint16_t start_x, uint16_t start_y)
{
    (void)s61_call_synced(core, BOOTSTRAP_KANTO_WARP,
                          row->group, row->map, start_x, start_y);
    run_key_frames(core, 0U, BOOTSTRAP_FIELD_FRAMES);
    return s61_try_wait_field_ready(core, row, start_x, start_y);
}

static bool s61_calibration_object_visible(
    struct mCore *core, const struct S61CalibrationRow *row)
{
    struct S61Interaction interaction = {
        row->group, row->map, 0U, 0U, WORLD_KEY_UP, 1U, row->local_id,
    };
    return s61_object_visible(core, &interaction);
}

static bool s61_try_calibration_walk(
    struct mCore *core, uint16_t action_key)
{
    struct FixtureResult movement = {0};
    uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    if (save1 < 0x02000000U || save1 >= 0x02040000U || (save1 & 3U))
        return false;
    uint16_t x = read16(core, save1);
    uint16_t y = read16(core, save1 + 2U);
    if (!world_walk_to_new_tile(core, action_key, &x, &y, &movement)
        || movement.successful_steps != 1U)
        return false;
    uint16_t adjacent_x = read16(core, save1);
    uint16_t adjacent_y = read16(core, save1 + 2U);
    s61_pulse(core, action_key, 2U, 12U, NULL);
    return world_overworld(core) && !world_script_enabled(core)
        && read16(core, save1) == adjacent_x
        && read16(core, save1 + 2U) == adjacent_y;
}

static bool s61_prepare_calibration_attempt(
    struct mCore *core, const void *base_state,
    const struct S61CalibrationRow *row,
    uint16_t start_x, uint16_t start_y, uint16_t action_key,
    bool *visible_out,
    struct S61CatalogRuntimePositionObservation *runtime_position)
{
    *visible_out = false;
    if (!core->loadState(core, base_state))
        s61_die("calibration baseline state restore failed");
    run_key_frames(core, 0U, 3U);
    if (row->visibility_flag != 0U) {
        (void)s61_call_synced(core, WORLD_FLAG_CLEAR,
                              row->visibility_flag, 0U, 0U, 0U);
        if (s61_flag(core, row->visibility_flag) != 0U)
            s61_die("calibration visibility flag clear did not commit");
    }
    struct S61CatalogRow positioning_row = {0};
    positioning_row.case_id = row->case_id;
    positioning_row.interaction.group = row->group;
    positioning_row.interaction.map = row->map;
    positioning_row.interaction.local_id = row->local_id;
    positioning_row.interaction.start_x = start_x;
    positioning_row.interaction.start_y = start_y;
    positioning_row.interaction.action_key = action_key;
    positioning_row.runtime_position_control =
        row->runtime_position_control;
    positioning_row.runtime_position_producer =
        row->runtime_position_producer;
    struct Fixture fixture = s61_world_fixture(
        row->case_id, &positioning_row.interaction);
    if (row->runtime_position_producer.kind
            == S61_CATALOG_RUNTIME_POSITION_NONE) {
        memset(runtime_position, 0, sizeof(*runtime_position));
        s61_catalog_prepare_runtime_position_control(
            core, &row->runtime_position_control, true,
            &runtime_position->control);
        if (!s61_try_calibration_warp(core, row, start_x, start_y))
            return false;
        runtime_position->exact = runtime_position->control.exact;
    } else {
        s61_catalog_position_for_row(
            core, &positioning_row, &fixture, true, runtime_position);
    }
    runtime_position->target_materialized_before_walk =
        s61_calibration_object_visible(core, row);
    runtime_position->target_materialization_deferred_to_real_walk =
        runtime_position->producer_required
        && !runtime_position->target_materialized_before_walk;
    bool walked = s61_try_calibration_walk(core, action_key);
    *visible_out = s61_calibration_object_visible(core, row);
    runtime_position->target_materialized_before_a = *visible_out;
    if (runtime_position->producer_required)
        runtime_position->exact = runtime_position->exact && *visible_out;
    return walked && *visible_out;
}

static void s61_initialize_memory_capture(struct S61Capture *capture)
{
    memset(capture, 0, sizeof(*capture));
    memcpy(capture->baseline, s61_video, sizeof(capture->baseline));
}

static unsigned s61_calibration_pulse_limit(void)
{
    return s61_uint_env("S61_CALIBRATION_PULSES", 16U, 160U);
}

static void s61_case_catalog_calibrate(const char *rom_path,
                                       const char *directory)
{
    static const enum S61Choice choices[S61_CALIBRATION_CHOICE_COUNT] = {
        S61_CHOICE_ADVANCE, S61_CHOICE_CANCEL,
        S61_CHOICE_NO, S61_CHOICE_YES,
    };
    static const int starts_x[4] = {0, 0, 2, -2};
    static const int starts_y[4] = {2, -2, 0, 0};
    static const uint16_t actions[4] = {
        WORLD_KEY_UP, WORLD_KEY_DOWN, WORLD_KEY_LEFT, WORLD_KEY_RIGHT,
    };
    const char *catalog_path = getenv("S61_CALIBRATION_TSV");
    if (catalog_path == NULL || catalog_path[0] == '\0')
        s61_die("S61_CALIBRATION_TSV is required for catalog_calibrate");
    FILE *stream = fopen(catalog_path, "rb");
    if (stream == NULL)
        s61_die("calibration TSV could not be opened");
    char line[S61_CATALOG_LINE_SIZE];
    if (fgets(line, sizeof(line), stream) == NULL)
        s61_die("calibration TSV is empty");
    size_t header_size = strlen(line);
    while (header_size != 0U
           && (line[header_size - 1U] == '\n'
               || line[header_size - 1U] == '\r'))
        line[--header_size] = '\0';
    if (strcmp(line, S61_CALIBRATION_HEADER) != 0)
        s61_die("calibration TSV header differs");

    char save_path[4096];
    struct S61Interaction base_interaction = {
        96U, 5U, 20U, 20U, WORLD_KEY_DOWN, 1U, 0U,
    };
    struct Fixture base = s61_world_fixture(
        "catalog_calibration_base", &base_interaction);
    s61_save_path(save_path, sizeof(save_path), directory, base.name);
    s61_generate(rom_path, save_path, &base);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &base);
    size_t state_size = core->stateSize(core);
    void *base_state = malloc(state_size);
    struct S61Capture *captures = calloc(
        S61_CALIBRATION_CHOICE_COUNT, sizeof(*captures));
    if (base_state == NULL || captures == NULL
        || !core->saveState(core, base_state))
        s61_die("calibration baseline allocation/capture failed");

    unsigned pulse_limit = s61_calibration_pulse_limit();
    printf("{\"schema_version\":2,\"status\":\"PASS\","
           "\"case\":\"catalog_calibrate\","
           "\"baseline_natural_continue\":true,"
           "\"choice_probe_via_state_restore\":true,"
           "\"pulse_limit\":%u,\"results\":[", pulse_limit);
    unsigned count = 0U;
    unsigned resolved = 0U;
    unsigned unresolved = 0U;
    while (fgets(line, sizeof(line), stream) != NULL) {
        if (strchr(line, '\n') == NULL && !feof(stream))
            s61_die("calibration TSV line exceeds the bounded buffer");
        if (line[0] == '\n' || line[0] == '\r' || line[0] == '\0')
            s61_die("calibration TSV contains a blank row");
        struct S61CalibrationRow row = s61_parse_calibration_row(line);
        s61_case_name = row.case_id;
        bootstrap_phase = row.case_id;
        bool any_visible = false;
        bool port_found = false;
        unsigned attempted_ports = 0U;
        uint16_t start_x = 0U;
        uint16_t start_y = 0U;
        uint16_t action_key = 0U;
        struct S61CatalogRuntimePositionObservation runtime_position = {0};
        for (unsigned port = 0U; port < 4U; ++port) {
            int candidate_x = (int)row.object_x + starts_x[port];
            int candidate_y = (int)row.object_y + starts_y[port];
            if (candidate_x < 0 || candidate_y < 0
                || candidate_x > 65535 || candidate_y > 65535)
                continue;
            ++attempted_ports;
            bool visible = false;
            if (s61_prepare_calibration_attempt(
                    core, base_state, &row,
                    (uint16_t)candidate_x, (uint16_t)candidate_y,
                    actions[port], &visible, &runtime_position)) {
                start_x = (uint16_t)candidate_x;
                start_y = (uint16_t)candidate_y;
                action_key = actions[port];
                port_found = true;
                any_visible = true;
                break;
            }
            any_visible = any_visible || visible;
        }

        bool successes[S61_CALIBRATION_CHOICE_COUNT] = {false};
        bool released[S61_CALIBRATION_CHOICE_COUNT] = {false};
        bool battles[S61_CALIBRATION_CHOICE_COUNT] = {false};
        unsigned success_count = 0U;
        unsigned attempted_choices = 0U;
        if (port_found) {
            for (unsigned choice_index = 0U;
                 choice_index < S61_CALIBRATION_CHOICE_COUNT;
                 ++choice_index) {
                ++attempted_choices;
                bool visible = false;
                if (!s61_prepare_calibration_attempt(
                        core, base_state, &row, start_x, start_y,
                        action_key, &visible, &runtime_position))
                    continue;
                s61_initialize_memory_capture(&captures[choice_index]);
                bool terminal_seen = s61_drive_interaction_limited(
                    core, action_key, choices[choice_index],
                    &captures[choice_index], true, pulse_limit, true, true);
                battles[choice_index] = s61_battle_active(core);
                released[choice_index] = world_overworld(core)
                    && !world_script_enabled(core)
                    && !battles[choice_index];
                successes[choice_index] = terminal_seen
                    && (released[choice_index] || battles[choice_index])
                    && captures[choice_index].count != 0U
                    && captures[choice_index].active_frames != 0U
                    && captures[choice_index]
                           .maximum_baseline_pixel_difference >= 2000U;
                if (successes[choice_index])
                    ++success_count;
            }
        }

        if (count != 0U)
            putchar(',');
        const char *reason = success_count != 0U ? "NONE"
            : !any_visible ? "NO_VISIBLE_OBJECT"
            : !port_found ? "NO_LEGAL_APPROACH"
            : "NO_FINITE_VISIBLE_PATH";
        printf("{\"case_id\":\"%s\",\"owner_key\":\"%s\","
               "\"map\":\"%u/%u\",\"local_id\":%u,"
               "\"object\":[%u,%u],\"visibility_flag\":%u,"
               "\"status\":\"%s\",\"failure_reason\":\"%s\","
               "\"attempted_ports\":%u,\"attempted_choices\":%u,"
               "\"port\":",
               row.case_id, row.owner_key, row.group, row.map,
               row.local_id, row.object_x, row.object_y,
               row.visibility_flag,
               success_count != 0U ? "RESOLVED" : "UNRESOLVED",
               reason, attempted_ports,
               attempted_choices);
        if (port_found) {
            printf("{\"start\":[%u,%u],\"action_key\":%u,"
                   "\"approach_steps\":1}",
                   start_x, start_y, action_key);
        } else {
            printf("null");
        }
        printf(",\"runtime_position_producer\":");
        struct S61CatalogRow positioning_row = {0};
        positioning_row.case_id = row.case_id;
        positioning_row.interaction.group = row.group;
        positioning_row.interaction.map = row.map;
        positioning_row.interaction.local_id = row.local_id;
        positioning_row.interaction.start_x = start_x;
        positioning_row.interaction.start_y = start_y;
        positioning_row.interaction.action_key = action_key;
        positioning_row.runtime_position_control =
            row.runtime_position_control;
        positioning_row.runtime_position_producer =
            row.runtime_position_producer;
        s61_print_catalog_runtime_position_observation(
            &positioning_row, &runtime_position);
        printf(",\"successful_paths\":[");
        bool first_path = true;
        for (unsigned choice_index = 0U;
             choice_index < S61_CALIBRATION_CHOICE_COUNT;
             ++choice_index) {
            if (!successes[choice_index])
                continue;
            if (!first_path)
                putchar(',');
            first_path = false;
            printf("{\"choice\":\"%s\",\"terminal\":\"%s\","
                   "\"field_released\":%s,\"battle_started\":%s,"
                   "\"capture\":",
                   s61_choice_name(choices[choice_index]),
                   battles[choice_index] ? "BATTLE_START" : "FIELD_RELEASE",
                   released[choice_index] ? "true" : "false",
                   battles[choice_index] ? "true" : "false");
            s61_print_capture(&captures[choice_index]);
            printf("}");
        }
        printf("]}");
        if (success_count != 0U)
            ++resolved;
        else
            ++unresolved;
        ++count;
    }
    if (ferror(stream) || fclose(stream) != 0)
        s61_die("calibration TSV read/close failed");
    if (count == 0U)
        s61_die("calibration TSV has zero object rows");
    printf("],\"fixture_count\":%u,\"resolved\":%u,"
           "\"unresolved\":%u,\"failed\":0,\"untested\":0,"
           "\"warnings\":0}\n", count, resolved, unresolved);
    free(captures);
    free(base_state);
    bootstrap_close_core(core);
}

struct S61QuestLogEventScan {
    uint64_t full_hash;
    unsigned departed_count;
    unsigned matching_location_count;
    uint8_t last_section;
    uint8_t last_location;
};

static struct S61QuestLogEventScan s61_scan_quest_log_departed(
    struct mCore *core, uint8_t expected_location)
{
    struct S61QuestLogEventScan result = {0};
    uint32_t save1 = world_save1(core, s61_case_name);
    result.full_hash = s61_hash_core_range(core, save1 + 0x1300U, 0x19A0U);
    for (unsigned scene = 0U; scene < 4U; ++scene) {
        uint32_t script = save1 + 0x1300U + scene * 0x668U + 0x568U;
        for (unsigned word = 0U; word + 2U < 128U; ++word) {
            if ((read16(core, script + word * 2U) & 0x0FFFU) != 35U)
                continue;
            uint8_t section = read8(core, script + (word + 2U) * 2U);
            uint8_t location = read8(
                core, script + (word + 2U) * 2U + 1U);
            ++result.departed_count;
            result.last_section = section;
            result.last_location = location;
            if (location == expected_location)
                ++result.matching_location_count;
        }
    }
    return result;
}

static const char *s61_transition_case_id(void)
{
    const char *value = getenv("S61_TRANSITION_CASE_ID");
    if (value == NULL || value[0] == '\0')
        s61_die("S61_TRANSITION_CASE_ID is required");
    for (const unsigned char *cursor = (const unsigned char *)value;
         *cursor != '\0'; ++cursor) {
        if (!(isalnum(*cursor) || *cursor == '_' || *cursor == '-'))
            s61_die("transition case ID contains an unsafe byte");
    }
    return value;
}

static void s61_case_consumer_warp_transition(const char *rom_path,
                                              const char *directory)
{
    const char *case_id = s61_transition_case_id();
    uint8_t source_group = (uint8_t)s61_uint_env(
        "S61_TRANSITION_SOURCE_GROUP", 0U, 255U);
    uint8_t source_map = (uint8_t)s61_uint_env(
        "S61_TRANSITION_SOURCE_MAP", 0U, 255U);
    uint16_t start_x = (uint16_t)s61_uint_env(
        "S61_TRANSITION_START_X", 0U, 65535U);
    uint16_t start_y = (uint16_t)s61_uint_env(
        "S61_TRANSITION_START_Y", 0U, 65535U);
    uint16_t action_key = (uint16_t)s61_uint_env(
        "S61_TRANSITION_ACTION_KEY", 0U, 255U);
    uint8_t destination_group = (uint8_t)s61_uint_env(
        "S61_TRANSITION_DESTINATION_GROUP", 0U, 255U);
    uint8_t destination_map = (uint8_t)s61_uint_env(
        "S61_TRANSITION_DESTINATION_MAP", 0U, 255U);
    uint16_t flag = (uint16_t)s61_uint_env(
        "S61_TRANSITION_FLAG", 0U, 65535U);
    uint16_t var = (uint16_t)s61_uint_env(
        "S61_TRANSITION_VAR", 0U, 65535U);
    uint16_t sentinel = (uint16_t)s61_uint_env(
        "S61_TRANSITION_SENTINEL", 0U, 65535U);
    uint16_t entrance = (uint16_t)s61_uint_env(
        "S61_TRANSITION_EXPECTED_ENTRANCE", 0U, 65535U);
    uint16_t post_var = (uint16_t)s61_uint_env(
        "S61_TRANSITION_EXPECTED_POST_VAR", 0U, 65535U);
    if (!(action_key == WORLD_KEY_UP || action_key == WORLD_KEY_DOWN
          || action_key == WORLD_KEY_LEFT || action_key == WORLD_KEY_RIGHT))
        s61_die("consumer transition action is not cardinal input");

    struct S61Interaction base_interaction = {
        96U, 5U, 20U, 20U, WORLD_KEY_DOWN, 1U, 0U,
    };
    struct Fixture base = s61_world_fixture(
        "consumer_transition_base", &base_interaction);
    char save_path[4096];
    s61_save_path(save_path, sizeof(save_path), directory, case_id);
    s61_generate(rom_path, save_path, &base);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &base);
    s61_case_name = case_id;
    bootstrap_phase = case_id;

    (void)s61_call_synced(core, WORLD_FLAG_CLEAR, flag, 0U, 0U, 0U);
    (void)s61_call_synced(core, WORLD_VAR_SET, var, sentinel, 0U, 0U);
    bool prepared_flag = s61_flag(core, flag) != 0U;
    uint16_t prepared_var = (uint16_t)s61_call_synced(
        core, WORLD_VAR_GET, var, 0U, 0U, 0U);
    struct S61QuestLogEventScan before_map =
        s61_scan_quest_log_departed(core, (uint8_t)entrance);
    if (prepared_flag || prepared_var != sentinel)
        s61_die("consumer transition pre-map state preparation differs");

    (void)s61_call_synced(core, BOOTSTRAP_KANTO_WARP,
                         source_group, source_map, start_x, start_y);
    run_key_frames(core, 0U, BOOTSTRAP_FIELD_FRAMES);
    struct Fixture source = {
        case_id, FIXTURE_FACING_DIALOGUE, source_group, source_map,
        start_x, start_y, action_key, 0U, 0U, 0U, 0U,
    };
    world_wait_player_ready(core, &source);
    uint32_t save1 = world_save1(core, case_id);
    if (read8(core, save1 + 4U) != source_group
        || read8(core, save1 + 5U) != source_map
        || read16(core, save1) != start_x
        || read16(core, save1 + 2U) != start_y)
        s61_die("consumer transition source stock warp differs");
    bool check_flag = s61_flag(core, flag) != 0U;
    uint16_t check_var = (uint16_t)s61_call_synced(
        core, WORLD_VAR_GET, var, 0U, 0U, 0U);
    if (!check_flag || check_var != entrance)
        s61_die("consumer transition entry Check did not arm expected state");
    struct S61QuestLogEventScan before_exit =
        s61_scan_quest_log_departed(core, (uint8_t)entrance);

    int delta_x = action_key == WORLD_KEY_LEFT ? -1
        : action_key == WORLD_KEY_RIGHT ? 1 : 0;
    int delta_y = action_key == WORLD_KEY_UP ? -1
        : action_key == WORLD_KEY_DOWN ? 1 : 0;
    uint16_t warp_x = (uint16_t)((int)start_x + delta_x);
    uint16_t warp_y = (uint16_t)((int)start_y + delta_y);
    bool warp_tile_seen = false;
    bool destination_seen = false;
    unsigned transition_frames = 0U;
    for (; transition_frames < 3600U; ++transition_frames) {
        s61_frames(core, action_key, 1U, NULL);
        save1 = world_save1(core, case_id);
        uint8_t group = read8(core, save1 + 4U);
        uint8_t map = read8(core, save1 + 5U);
        if (group == source_group && map == source_map
            && read16(core, save1) == warp_x
            && read16(core, save1 + 2U) == warp_y)
            warp_tile_seen = true;
        if (group == destination_group && map == destination_map) {
            destination_seen = true;
            break;
        }
    }
    s61_frames(core, 0U, 30U, NULL);
    if (!warp_tile_seen || !destination_seen)
        s61_die("consumer transition actual walk did not traverse warp");
    struct Fixture destination = {
        case_id, FIXTURE_FACING_DIALOGUE,
        destination_group, destination_map, 0U, 0U,
        action_key, 0U, 0U, 0U, 0U,
    };
    world_wait_player_ready(core, &destination);
    save1 = world_save1(core, case_id);
    bool post_flag = s61_flag(core, flag) != 0U;
    uint16_t actual_post_var = (uint16_t)s61_call_synced(
        core, WORLD_VAR_GET, var, 0U, 0U, 0U);
    struct S61QuestLogEventScan after_exit =
        s61_scan_quest_log_departed(core, (uint8_t)entrance);
    bool input_recovered = world_overworld(core)
        && !world_script_enabled(core)
        && read8(core, WORLD_PLAYER_AVATAR
                       + WORLD_PLAYER_RUNNING_STATE_OFFSET) == 0U
        && read8(core, WORLD_PLAYER_AVATAR
                       + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET) == 0U;
    if (read8(core, save1 + 4U) != destination_group
        || read8(core, save1 + 5U) != destination_map
        || post_flag || actual_post_var != post_var
        || after_exit.matching_location_count
            <= before_exit.matching_location_count
        || !input_recovered)
        s61_die("consumer transition Try/event/input postcondition differs");

    char artifact[4096];
    int artifact_size = snprintf(
        artifact, sizeof(artifact), "%s/%s-final", directory, case_id);
    if (artifact_size <= 0 || (size_t)artifact_size >= sizeof(artifact))
        s61_die("consumer transition artifact path is too long");
    s61_write_framebuffer_ppm(
        artifact, s61_video, "TRANSITION_DESTINATION_FRAME");
    printf("{\"schema_version\":1,\"status\":\"PASS\","
           "\"case\":\"consumer_warp_transition\","
           "\"case_id\":\"%s\",\"preparation_only_host_writes\":true,"
           "\"entry_check_via_stock_map_load\":true,"
           "\"exit_try_via_actual_walk\":true,"
           "\"source\":\"%u/%u\",\"start\":[%u,%u],"
           "\"warp_tile\":[%u,%u],\"destination\":\"%u/%u\","
           "\"action_key\":%u,\"transition_frames\":%u,"
           "\"prepared\":{\"flag\":%s,\"var\":%u},"
           "\"after_check\":{\"flag\":%s,\"var\":%u},"
           "\"after_try\":{\"flag\":%s,\"var\":%u},"
           "\"quest_log\":{\"before_map_fnv1a64\":\"%016" PRIX64
           "\",\"before_exit_fnv1a64\":\"%016" PRIX64
           "\",\"after_exit_fnv1a64\":\"%016" PRIX64
           "\",\"departed_before_map\":%u,"
           "\"departed_before_exit\":%u,\"departed_after_exit\":%u,"
           "\"matching_before_exit\":%u,\"matching_after_exit\":%u,"
           "\"last_section\":%u,\"last_location\":%u},"
           "\"input_recovered\":true,\"failed\":0,"
           "\"untested\":0,\"warnings\":0}\n",
           case_id, source_group, source_map, start_x, start_y,
           warp_x, warp_y, destination_group, destination_map,
           action_key, transition_frames + 1U,
           prepared_flag ? "true" : "false", prepared_var,
           check_flag ? "true" : "false", check_var,
           post_flag ? "true" : "false", actual_post_var,
           before_map.full_hash, before_exit.full_hash, after_exit.full_hash,
           before_map.departed_count, before_exit.departed_count,
           after_exit.departed_count,
           before_exit.matching_location_count,
           after_exit.matching_location_count,
           after_exit.last_section, after_exit.last_location);
    bootstrap_close_core(core);
}

struct S61WalkWarpResult {
    unsigned frames;
    uint16_t landing_x;
    uint16_t landing_y;
};

static struct S61WalkWarpResult s61_walk_cardinal_warp(
    struct mCore *core, const char *case_id,
    uint8_t source_group, uint8_t source_map,
    uint16_t warp_x, uint16_t warp_y, uint16_t action_key,
    uint8_t destination_group, uint8_t destination_map,
    unsigned maximum_frames)
{
    if (!(action_key == WORLD_KEY_UP || action_key == WORLD_KEY_DOWN
          || action_key == WORLD_KEY_LEFT || action_key == WORLD_KEY_RIGHT))
        s61_die("Quest Log lifecycle action is not cardinal input");
    bool warp_tile_seen = false;
    bool destination_seen = false;
    unsigned frame = 0U;
    for (; frame < maximum_frames; ++frame) {
        s61_frames(core, action_key, 1U, NULL);
        uint32_t save1 = world_save1(core, case_id);
        uint8_t group = read8(core, save1 + 4U);
        uint8_t map = read8(core, save1 + 5U);
        if (group == source_group && map == source_map
            && read16(core, save1) == warp_x
            && read16(core, save1 + 2U) == warp_y)
            warp_tile_seen = true;
        if (group == destination_group && map == destination_map) {
            destination_seen = true;
            break;
        }
    }
    s61_frames(core, 0U, 30U, NULL);
    if (!warp_tile_seen || !destination_seen)
        s61_die("Quest Log lifecycle actual walk did not traverse warp");
    struct Fixture destination = {
        case_id, FIXTURE_FACING_DIALOGUE,
        destination_group, destination_map, 0U, 0U,
        action_key, 0U, 0U, 0U, 0U,
    };
    world_wait_player_ready(core, &destination);
    uint32_t save1 = world_save1(core, case_id);
    if (read8(core, save1 + 4U) != destination_group
        || read8(core, save1 + 5U) != destination_map)
        s61_die("Quest Log lifecycle destination map changed while settling");
    struct S61WalkWarpResult result = {
        .frames = frame + 1U,
        .landing_x = read16(core, save1),
        .landing_y = read16(core, save1 + 2U),
    };
    return result;
}

static void s61_quest_log_stock_warp(struct mCore *core,
                                     const char *case_id,
                                     uint8_t group, uint8_t map,
                                     uint16_t x, uint16_t y)
{
    (void)s61_call_synced(core, BOOTSTRAP_KANTO_WARP,
                         group, map, x, y);
    run_key_frames(core, 0U, BOOTSTRAP_FIELD_FRAMES);
    struct Fixture fixture = {
        case_id, FIXTURE_FACING_DIALOGUE, group, map, x, y,
        WORLD_KEY_UP, 0U, 0U, 0U, 0U,
    };
    world_wait_player_ready(core, &fixture);
    uint32_t save1 = world_save1(core, case_id);
    if (read8(core, save1 + 4U) != group
        || read8(core, save1 + 5U) != map
        || read16(core, save1) != x || read16(core, save1 + 2U) != y)
        s61_die("Quest Log lifecycle stock warp source differs");
}

static void s61_case_quest_log_lifecycle(const char *rom_path,
                                         const char *directory)
{
    enum {
        FLAG_QL_DEPARTED = 0x0808U,
        VAR_QL_LOCATION = 0x404DU,
        SENTINEL = 0x7A61U,
        LOCATION_PEWTER_GYM = 8U,
        LOCATION_SS_ANNE = 19U,
    };
    const char *case_id = "msc17_quest_log_lifecycle";
    struct S61Interaction base_interaction = {
        96U, 5U, 20U, 20U, WORLD_KEY_DOWN, 1U, 0U,
    };
    struct Fixture base = s61_world_fixture(case_id, &base_interaction);
    char save_path[4096];
    s61_save_path(save_path, sizeof(save_path), directory, case_id);
    s61_generate(rom_path, save_path, &base);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &base);
    s61_case_name = case_id;
    bootstrap_phase = case_id;
    size_t state_size = core->stateSize(core);
    void *baseline = malloc(state_size);
    if (baseline == NULL || !core->saveState(core, baseline))
        s61_die("Quest Log lifecycle baseline savestate failed");

    /* 97/4 is the sole policy-approved SS Anne component extra. */
    (void)s61_call_synced(
        core, WORLD_FLAG_CLEAR, FLAG_QL_DEPARTED, 0U, 0U, 0U);
    (void)s61_call_synced(
        core, WORLD_VAR_SET, VAR_QL_LOCATION, SENTINEL, 0U, 0U);
    struct S61QuestLogEventScan two_hop_before =
        s61_scan_quest_log_departed(core, LOCATION_SS_ANNE);
    s61_quest_log_stock_warp(core, case_id, 97U, 5U, 19U, 2U);
    if (s61_flag(core, FLAG_QL_DEPARTED) == 0U
        || s61_call_synced(core, WORLD_VAR_GET, VAR_QL_LOCATION,
                           0U, 0U, 0U) != LOCATION_SS_ANNE)
        s61_die("SS Anne entry Check did not arm location 19");
    struct S61WalkWarpResult component_leg = s61_walk_cardinal_warp(
        core, case_id, 97U, 5U, 19U, 1U, WORLD_KEY_UP,
        97U, 4U, 3600U);
    struct S61QuestLogEventScan component_scan =
        s61_scan_quest_log_departed(core, LOCATION_SS_ANNE);
    if (s61_flag(core, FLAG_QL_DEPARTED) == 0U
        || s61_call_synced(core, WORLD_VAR_GET, VAR_QL_LOCATION,
                           0U, 0U, 0U) != LOCATION_SS_ANNE
        || component_scan.departed_count != two_hop_before.departed_count
        || component_scan.matching_location_count
            != two_hop_before.matching_location_count)
        s61_die("SS Anne component hop did not preserve pending state");
    if (component_leg.landing_x != 32U || component_leg.landing_y != 15U)
        s61_die("SS Anne component landing coordinate differs");
    struct S61WalkWarpResult canonical_exit = s61_walk_cardinal_warp(
        core, case_id, 97U, 4U, 32U, 5U, WORLD_KEY_UP,
        96U, 5U, 3600U);
    struct S61QuestLogEventScan two_hop_after =
        s61_scan_quest_log_departed(core, LOCATION_SS_ANNE);
    if (s61_flag(core, FLAG_QL_DEPARTED) != 0U
        || s61_call_synced(core, WORLD_VAR_GET, VAR_QL_LOCATION,
                           0U, 0U, 0U) != LOCATION_SS_ANNE
        || two_hop_after.departed_count <= component_scan.departed_count
        || two_hop_after.matching_location_count
            <= component_scan.matching_location_count
        || two_hop_after.last_location != LOCATION_SS_ANNE)
        s61_die("SS Anne canonical exit did not emit event 35");
    char two_hop_artifact[4096];
    int two_hop_size = snprintf(
        two_hop_artifact, sizeof(two_hop_artifact),
        "%s/%s-two-hop-final", directory, case_id);
    if (two_hop_size <= 0
        || (size_t)two_hop_size >= sizeof(two_hop_artifact))
        s61_die("Quest Log two-hop artifact path is too long");
    s61_write_framebuffer_ppm(
        two_hop_artifact, s61_video, "QUEST_LOG_TWO_HOP_FRAME");

    /* 97/6 is outside the SS Anne component.  It must clear pending state
     * without event 35; a later imported Pewter Gym load must re-arm row 8. */
    if (!core->loadState(core, baseline))
        s61_die("Quest Log lifecycle baseline restore failed");
    run_key_frames(core, 0U, 3U);
    (void)s61_call_synced(
        core, WORLD_FLAG_CLEAR, FLAG_QL_DEPARTED, 0U, 0U, 0U);
    (void)s61_call_synced(
        core, WORLD_VAR_SET, VAR_QL_LOCATION, SENTINEL, 0U, 0U);
    struct S61QuestLogEventScan mismatch_before =
        s61_scan_quest_log_departed(core, LOCATION_SS_ANNE);
    s61_quest_log_stock_warp(core, case_id, 97U, 5U, 3U, 9U);
    if (s61_flag(core, FLAG_QL_DEPARTED) == 0U
        || s61_call_synced(core, WORLD_VAR_GET, VAR_QL_LOCATION,
                           0U, 0U, 0U) != LOCATION_SS_ANNE)
        s61_die("SS Anne mismatch fixture did not arm pending state");
    struct S61WalkWarpResult mismatch_leg = s61_walk_cardinal_warp(
        core, case_id, 97U, 5U, 3U, 8U, WORLD_KEY_UP,
        97U, 6U, 3600U);
    struct S61QuestLogEventScan mismatch_after =
        s61_scan_quest_log_departed(core, LOCATION_SS_ANNE);
    if (s61_flag(core, FLAG_QL_DEPARTED) != 0U
        || s61_call_synced(core, WORLD_VAR_GET, VAR_QL_LOCATION,
                           0U, 0U, 0U) != LOCATION_SS_ANNE
        || mismatch_after.departed_count != mismatch_before.departed_count
        || mismatch_after.matching_location_count
            != mismatch_before.matching_location_count)
        s61_die("namespace mismatch did not clear without event 35");
    s61_quest_log_stock_warp(core, case_id, 98U, 12U, 6U, 4U);
    bool rearmed_flag = s61_flag(core, FLAG_QL_DEPARTED) != 0U;
    uint16_t rearmed_location = (uint16_t)s61_call_synced(
        core, WORLD_VAR_GET, VAR_QL_LOCATION, 0U, 0U, 0U);
    struct S61QuestLogEventScan rearmed_scan =
        s61_scan_quest_log_departed(core, LOCATION_PEWTER_GYM);
    if (!rearmed_flag || rearmed_location != LOCATION_PEWTER_GYM
        || rearmed_scan.departed_count != mismatch_after.departed_count)
        s61_die("different imported inside did not re-arm location 8");
    char rearm_artifact[4096];
    int rearm_size = snprintf(
        rearm_artifact, sizeof(rearm_artifact),
        "%s/%s-rearm-final", directory, case_id);
    if (rearm_size <= 0 || (size_t)rearm_size >= sizeof(rearm_artifact))
        s61_die("Quest Log rearm artifact path is too long");
    s61_write_framebuffer_ppm(
        rearm_artifact, s61_video, "QUEST_LOG_REARM_FRAME");

    bool input_recovered = world_overworld(core)
        && !world_script_enabled(core)
        && read8(core, WORLD_PLAYER_AVATAR
                       + WORLD_PLAYER_RUNNING_STATE_OFFSET) == 0U
        && read8(core, WORLD_PLAYER_AVATAR
                       + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET) == 0U;
    if (!input_recovered)
        s61_die("Quest Log lifecycle input did not recover");
    printf("{\"schema_version\":1,\"status\":\"PASS\","
           "\"case\":\"quest_log_lifecycle\","
           "\"stock_map_load_checks\":true,"
           "\"actual_warp_tile_tries\":true,"
           "\"two_hop\":{\"location\":19,"
           "\"canonical_inside\":\"97/5\","
           "\"component_extra\":\"97/4\","
           "\"component_landing\":[%u,%u],"
           "\"component_frames\":%u,\"pending_preserved\":true,"
           "\"departed_before\":%u,\"departed_after_component\":%u,"
           "\"canonical_exit\":\"96/5\","
           "\"exit_landing\":[%u,%u],\"exit_frames\":%u,"
           "\"pending_cleared\":true,\"event35_generated\":true,"
           "\"matching_before_exit\":%u,"
           "\"matching_after_exit\":%u},"
           "\"mismatch_rearm\":{\"location_before\":19,"
           "\"mismatch_destination\":\"97/6\","
           "\"mismatch_landing\":[%u,%u],\"mismatch_frames\":%u,"
           "\"pending_cleared\":true,\"event35_generated\":false,"
           "\"departed_before\":%u,\"departed_after\":%u,"
           "\"rearm_inside\":\"98/12\",\"rearmed_location\":8,"
           "\"rearmed\":true},\"input_recovered\":true,"
           "\"failed\":0,\"untested\":0,\"warnings\":0}\n",
           component_leg.landing_x, component_leg.landing_y,
           component_leg.frames, two_hop_before.departed_count,
           component_scan.departed_count,
           canonical_exit.landing_x, canonical_exit.landing_y,
           canonical_exit.frames,
           component_scan.matching_location_count,
           two_hop_after.matching_location_count,
           mismatch_leg.landing_x, mismatch_leg.landing_y,
           mismatch_leg.frames, mismatch_before.departed_count,
           mismatch_after.departed_count);
    free(baseline);
    bootstrap_close_core(core);
}

static void s61_execute_field_special(struct mCore *core, uint16_t special,
                                      uint16_t argument)
{
    uint8_t saved[4U];
    for (unsigned byte = 0U; byte < sizeof(saved); ++byte)
        saved[byte] = read8(core, WORLD_FIELD_SCRIPT_SCRATCH + byte);
    /* Data-only field bytecode: special <u16>; end.  The host writes only the
     * deterministic script fixture and its explicit VAR_8000 argument; the
     * ROM's ScriptContext1 dispatcher owns every consumer call below. */
    write8(core, WORLD_FIELD_SCRIPT_SCRATCH, 0x25U);
    write16(core, WORLD_FIELD_SCRIPT_SCRATCH + 1U, special);
    write8(core, WORLD_FIELD_SCRIPT_SCRATCH + 3U, 0x02U);
    write16(core, WORLD_SPECIAL_VAR_8000, argument);
    (void)s61_call_synced(
        core, WORLD_SCRIPT_CONTEXT1_SETUP,
        WORLD_FIELD_SCRIPT_SCRATCH, 0U, 0U, 0U);
    unsigned stable = 0U;
    for (unsigned frame = 0U; frame < 600U && stable < 30U; ++frame) {
        run_key_frames(core, 0U, 1U);
        if (world_overworld(core) && !world_script_enabled(core))
            ++stable;
        else
            stable = 0U;
    }
    if (stable < 30U)
        s61_die("field special script did not return to stable input");
    for (unsigned byte = 0U; byte < sizeof(saved); ++byte)
        write8(core, WORLD_FIELD_SCRIPT_SCRATCH + byte, saved[byte]);
}

struct S61PreviewWatch {
    unsigned stock_fade_hits;
    unsigned preview_index_hits;
    unsigned cfru_fade_hits;
    uint16_t expected_duration;
    bool duration_seen;
    int duration_task_slot;
    uint32_t last_frame;
};

static void s61_preview_watch_step(struct mCore *core,
                                   struct S61PreviewWatch *watch)
{
    uint32_t instruction = (
        (uint32_t)read_register(core, "pc") - 4U) & ~1U;
    if (instruction == 0x0807D378U)
        ++watch->stock_fade_hits;
    else if (instruction == 0x080F9150U)
        ++watch->preview_index_hits;
    else if (instruction == 0x0911FEC8U)
        ++watch->cfru_fade_hits;
    core->step(core);
    if (watch->stock_fade_hits != 0U && !watch->duration_seen) {
        for (unsigned slot = 0U; slot < 16U; ++slot) {
            uint32_t task = WORLD_TASKS + slot * WORLD_TASK_SIZE;
            if (read32(core, task) != 0U
                && read16(core, task + WORLD_TASK_DATA + 20U)
                    == watch->expected_duration) {
                watch->duration_seen = true;
                watch->duration_task_slot = (int)slot;
                break;
            }
        }
    }
    watch->last_frame = core->frameCounter(core);
}

static void s61_case_warp_preview_transition(const char *rom_path,
                                             const char *directory)
{
    const char *case_id = s61_transition_case_id();
    uint8_t source_group = (uint8_t)s61_uint_env(
        "S61_TRANSITION_SOURCE_GROUP", 0U, 255U);
    uint8_t source_map = (uint8_t)s61_uint_env(
        "S61_TRANSITION_SOURCE_MAP", 0U, 255U);
    uint16_t start_x = (uint16_t)s61_uint_env(
        "S61_TRANSITION_START_X", 0U, 65535U);
    uint16_t start_y = (uint16_t)s61_uint_env(
        "S61_TRANSITION_START_Y", 0U, 65535U);
    uint16_t action_key = (uint16_t)s61_uint_env(
        "S61_TRANSITION_ACTION_KEY", 0U, 255U);
    uint8_t destination_group = (uint8_t)s61_uint_env(
        "S61_TRANSITION_DESTINATION_GROUP", 0U, 255U);
    uint8_t destination_map = (uint8_t)s61_uint_env(
        "S61_TRANSITION_DESTINATION_MAP", 0U, 255U);
    uint8_t destination_warp_id = (uint8_t)s61_uint_env(
        "S61_TRANSITION_DESTINATION_WARP", 0U, 255U);
    uint16_t visit_flag = (uint16_t)s61_uint_env(
        "S61_PREVIEW_VISIT_FLAG", 0U, 65535U);
    bool initially_visited = s61_bool_env(
        "S61_PREVIEW_INITIALLY_VISITED", false);
    uint16_t expected_duration = (uint16_t)s61_uint_env(
        "S61_PREVIEW_EXPECTED_DURATION", 1U, 65535U);
    if (!(action_key == WORLD_KEY_UP || action_key == WORLD_KEY_DOWN
          || action_key == WORLD_KEY_LEFT || action_key == WORLD_KEY_RIGHT))
        s61_die("warp preview action is not cardinal input");

    struct S61Interaction base_interaction = {
        96U, 5U, 20U, 20U, WORLD_KEY_DOWN, 1U, 0U,
    };
    struct Fixture base = s61_world_fixture(
        "warp_preview_transition_base", &base_interaction);
    char save_path[4096];
    s61_save_path(save_path, sizeof(save_path), directory, case_id);
    s61_generate(rom_path, save_path, &base);
    struct mCore *core = s61_open_fresh(rom_path, save_path, &base);
    s61_case_name = case_id;
    bootstrap_phase = case_id;
    (void)s61_call_synced(
        core, initially_visited ? WORLD_FLAG_SET : WORLD_FLAG_CLEAR,
        visit_flag, 0U, 0U, 0U);
    if ((s61_flag(core, visit_flag) != 0U) != initially_visited)
        s61_die("warp preview visit flag preparation differs");
    (void)s61_call_synced(core, BOOTSTRAP_KANTO_WARP,
                         source_group, source_map, start_x, start_y);
    run_key_frames(core, 0U, BOOTSTRAP_FIELD_FRAMES);
    struct Fixture source = {
        case_id, FIXTURE_FACING_DIALOGUE, source_group, source_map,
        start_x, start_y, action_key, 0U, 0U, 0U, 0U,
    };
    world_wait_player_ready(core, &source);
    uint32_t save1 = world_save1(core, case_id);
    if (read8(core, save1 + 4U) != source_group
        || read8(core, save1 + 5U) != source_map
        || read16(core, save1) != start_x
        || read16(core, save1 + 2U) != start_y)
        s61_die("warp preview source stock warp differs");

    int delta_x = action_key == WORLD_KEY_LEFT ? -1
        : action_key == WORLD_KEY_RIGHT ? 1 : 0;
    int delta_y = action_key == WORLD_KEY_UP ? -1
        : action_key == WORLD_KEY_DOWN ? 1 : 0;
    uint16_t warp_x = (uint16_t)((int)start_x + delta_x);
    uint16_t warp_y = (uint16_t)((int)start_y + delta_y);
    struct S61PreviewWatch watch = {
        .expected_duration = expected_duration,
        .duration_task_slot = -1,
        .last_frame = core->frameCounter(core),
    };
    uint32_t first_frame = core->frameCounter(core);
    bool warp_tile_seen = false;
    bool destination_warp_seen = false;
    bool destination_seen = false;
    unsigned stable = 0U;
    core->setKeys(core, action_key);
    while ((uint32_t)(core->frameCounter(core) - first_frame) < 6000U
           && stable < 30U) {
        uint32_t frame_before = core->frameCounter(core);
        s61_preview_watch_step(core, &watch);
        if (core->frameCounter(core) == frame_before)
            continue;
        save1 = world_save1(core, case_id);
        uint8_t group = read8(core, save1 + 4U);
        uint8_t map = read8(core, save1 + 5U);
        if (group == source_group && map == source_map
            && read16(core, save1) == warp_x
            && read16(core, save1 + 2U) == warp_y)
            warp_tile_seen = true;
        if (read8(core, WORLD_WARP_DESTINATION) == destination_group
            && read8(core, WORLD_WARP_DESTINATION + 1U) == destination_map
            && read8(core, WORLD_WARP_DESTINATION + 2U)
                == destination_warp_id)
            destination_warp_seen = true;
        if (group == destination_group && map == destination_map) {
            destination_seen = true;
            core->setKeys(core, 0U);
        }
        if (destination_seen && watch.duration_seen
            && world_overworld(core) && !world_script_enabled(core)
            && read8(core, WORLD_PLAYER_AVATAR
                           + WORLD_PLAYER_RUNNING_STATE_OFFSET) == 0U
            && read8(core, WORLD_PLAYER_AVATAR
                           + WORLD_PLAYER_TILE_TRANSITION_STATE_OFFSET) == 0U)
            ++stable;
        else
            stable = 0U;
    }
    core->setKeys(core, 0U);
    save1 = world_save1(core, case_id);
    bool visit_flag_after = s61_flag(core, visit_flag) != 0U;
    bool input_recovered = stable >= 30U && world_overworld(core)
        && !world_script_enabled(core);
    if (!warp_tile_seen || !destination_warp_seen || !destination_seen
        || watch.stock_fade_hits == 0U || watch.preview_index_hits == 0U
        || watch.cfru_fade_hits != 0U || !watch.duration_seen
        || watch.duration_task_slot < 0 || !visit_flag_after
        || !input_recovered)
        s61_die("actual warp preview consumer contract differs");

    char artifact[4096];
    int artifact_size = snprintf(
        artifact, sizeof(artifact), "%s/%s-final", directory, case_id);
    if (artifact_size <= 0 || (size_t)artifact_size >= sizeof(artifact))
        s61_die("warp preview artifact path is too long");
    s61_write_framebuffer_ppm(
        artifact, s61_video, "WARP_PREVIEW_DESTINATION_FRAME");
    printf("{\"schema_version\":1,\"status\":\"PASS\","
           "\"case\":\"warp_preview_transition\","
           "\"case_id\":\"%s\",\"preparation_only_host_writes\":true,"
           "\"actual_warp_via_player_input\":true,"
           "\"source\":\"%u/%u\",\"start\":[%u,%u],"
           "\"warp_tile\":[%u,%u],\"destination\":\"%u/%u\","
           "\"destination_warp_id\":%u,\"landing\":[%u,%u],"
           "\"action_key\":%u,\"initially_visited\":%s,"
           "\"visit_flag\":%u,\"visit_flag_after\":true,"
           "\"preview_duration\":%u,\"duration_task_slot\":%d,"
           "\"hook_hits\":{\"stock_warp_fade\":%u,"
           "\"stock_preview_index\":%u,\"cfru_warp_fade\":0},"
           "\"transition_frames\":%u,\"input_recovered\":true,"
           "\"failed\":0,\"untested\":0,\"warnings\":0}\n",
           case_id, source_group, source_map, start_x, start_y,
           warp_x, warp_y, destination_group, destination_map,
           destination_warp_id, read16(core, save1),
           read16(core, save1 + 2U), action_key,
           initially_visited ? "true" : "false", visit_flag,
           expected_duration, watch.duration_task_slot,
           watch.stock_fade_hits, watch.preview_index_hits,
           (unsigned)(core->frameCounter(core) - first_frame));
    bootstrap_close_core(core);
}

struct S61RaidConsumerRow {
    const char *case_id;
    uint8_t group;
    uint8_t map;
    uint16_t x;
    uint16_t y;
    uint8_t expected_source_section;
    uint8_t expected_index;
};

static uint32_t s61_runtime_symbol_env(const char *name)
{
    uint32_t symbol = (uint32_t)s61_uint_env(name, 0U, UINT32_MAX);
    if (symbol < 0x09000000U || symbol >= 0x0A000000U)
        s61_die("Stage61 runtime consumer symbol is outside payload ROM");
    return symbol | 1U;
}

static void s61_case_save_corruption_generate(
    const char *rom_path, const char *directory,
    const struct S61Config *config)
{
    struct Fixture fixture = s61_world_fixture(
        "save_corruption_baseline", &config->giver);
    char save_path[4096];
    s61_save_path(save_path, sizeof(save_path), directory,
                  "save-corruption-baseline");
    s61_generate(rom_path, save_path, &fixture);
    printf("{\"schema_version\":1,\"status\":\"PASS\","
           "\"case\":\"save_corruption_generate\","
           "\"natural_new_game\":true,\"stock_warp\":true,"
           "\"normal_save_generations\":2,\"warnings\":0}\n");
}

static void s61_snapshot_live_save_blocks(
    struct mCore *core, uint8_t *save1_copy, uint8_t *save2_copy,
    uint8_t *storage_copy, uint32_t *save1, uint32_t *save2,
    uint32_t *storage)
{
    *save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    *save2 = read32(core, BOOTSTRAP_SAVE_BLOCK2_PTR);
    *storage = read32(core, WORLD_POKEMON_STORAGE_PTR);
    if (*save1 < 0x02000000U
        || *save1 + S61_SAVE_BLOCK1_SIZE > 0x02040000U
        || (*save1 & 3U) != 0U
        || *save2 < 0x02000000U
        || *save2 + S61_SAVE_BLOCK2_SIZE > 0x02040000U
        || (*save2 & 3U) != 0U
        || *storage < 0x02000000U
        || *storage + S61_POKEMON_STORAGE_SIZE > 0x02040000U
        || (*storage & 3U) != 0U)
        s61_die("save corruption live save-block pointers are invalid");
    s61_read_core_range(
        core, *save1, save1_copy, S61_SAVE_BLOCK1_SIZE);
    s61_read_core_range(
        core, *save2, save2_copy, S61_SAVE_BLOCK2_SIZE);
    s61_read_core_range(
        core, *storage, storage_copy, S61_POKEMON_STORAGE_SIZE);
}

static bool s61_live_save_blocks_equal(
    struct mCore *core, const uint8_t *save1_copy,
    const uint8_t *save2_copy, const uint8_t *storage_copy,
    uint32_t save1, uint32_t save2, uint32_t storage)
{
    return s61_core_range_equals(
               core, save1, save1_copy, S61_SAVE_BLOCK1_SIZE,
               "invalid loader SaveBlock1 canary")
        && s61_core_range_equals(
               core, save2, save2_copy, S61_SAVE_BLOCK2_SIZE,
               "invalid loader SaveBlock2 canary")
        && s61_core_range_equals(
               core, storage, storage_copy, S61_POKEMON_STORAGE_SIZE,
               "invalid loader PokemonStorage canary");
}

static bool s61_loaded_owner_image_exact(struct mCore *core,
                                         const uint8_t *expected)
{
    uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    uint32_t save2 = read32(core, BOOTSTRAP_SAVE_BLOCK2_PTR);
    uint32_t storage = read32(core, WORLD_POKEMON_STORAGE_PTR);
    return s61_core_range_equals(
               core, save2, expected, S61_SAVE_BLOCK2_SIZE,
               "selected generation SaveBlock2 exact oracle")
        && s61_core_range_equals(
               core, save1, expected + S61_SAVE_BLOCK2_SIZE,
               S61_SAVE_BLOCK1_SIZE,
               "selected generation SaveBlock1 exact oracle")
        && s61_core_range_equals(
               core, storage,
               expected + S61_SAVE_BLOCK2_SIZE + S61_SAVE_BLOCK1_SIZE,
               S61_POKEMON_STORAGE_SIZE,
               "selected generation PokemonStorage exact oracle");
}

static bool s61_loaded_owner_canaries_exact(struct mCore *core,
                                            const uint8_t *expected)
{
    static const uint16_t sizes[WORLD_SAVE_SLOT_SECTORS] = {
        0x0F24U,
        0x0F80U, 0x0F80U, 0x0F80U, 0x0EC0U,
        0x0F80U, 0x0F80U, 0x0F80U, 0x0F80U, 0x0F80U,
        0x0F80U, 0x0F80U, 0x0F80U, 0x07D0U,
    };
    static const uint16_t canary_offsets[WORLD_SAVE_SLOT_SECTORS] = {
        0x0B20U, 0x0632U, 0x0F50U, 0x0638U, 0x060CU,
        0x0022U, 0x0042U, 0x0062U, 0x0032U, 0x0052U,
        0x0022U, 0x0042U, 0x0062U, 0x0032U,
    };
    uint32_t owners[WORLD_SAVE_SLOT_SECTORS];
    owners[0] = read32(core, BOOTSTRAP_SAVE_BLOCK2_PTR);
    uint32_t save1 = read32(core, BOOTSTRAP_SAVE_BLOCK1_PTR);
    uint32_t storage = read32(core, WORLD_POKEMON_STORAGE_PTR);
    uint32_t owner_offset = sizes[0];
    uint32_t save1_offset = 0U;
    for (unsigned id = 1U; id < 5U; ++id) {
        owners[id] = save1 + save1_offset;
        save1_offset += sizes[id];
    }
    uint32_t storage_offset = 0U;
    for (unsigned id = 5U; id < WORLD_SAVE_SLOT_SECTORS; ++id) {
        owners[id] = storage + storage_offset;
        storage_offset += sizes[id];
    }
    for (unsigned id = 0U; id < WORLD_SAVE_SLOT_SECTORS; ++id) {
        if (read8(core, owners[id] + canary_offsets[id])
            != expected[owner_offset - sizes[id] + canary_offsets[id]])
            return false;
        if (id + 1U < WORLD_SAVE_SLOT_SECTORS)
            owner_offset += sizes[id + 1U];
    }
    return true;
}

static void s61_case_save_corruption_probe(
    const char *rom_path, const char *directory,
    const struct S61Config *config)
{
    const char *fixture_id = getenv("S61_SAVE_CORRUPTION_ID");
    bool expect_valid = s61_uint_env(
        "S61_SAVE_EXPECT_VALID", 0U, 1U) != 0U;
    uint32_t expected_counter = (uint32_t)s61_uint_env(
        "S61_SAVE_EXPECT_COUNTER", 0U, UINT32_MAX);
    uint16_t expected_first_sector = (uint16_t)s61_uint_env(
        "S61_SAVE_EXPECT_FIRST_SECTOR", 0U, 13U);
    uint8_t expected_status = (uint8_t)s61_uint_env(
        "S61_SAVE_EXPECT_STATUS", 0U, 255U);
    bool require_resave = s61_uint_env(
        "S61_SAVE_REQUIRE_RESAVE", 0U, 1U) != 0U;
    const char *owner_image_path = getenv("S61_SAVE_EXPECT_OWNER_IMAGE");
    uint32_t valid_status_symbol = s61_runtime_symbol_env(
        "S61_GET_SAVE_VALID_STATUS_SYMBOL");
    uint32_t load_symbol = s61_runtime_symbol_env(
        "S61_HANDLE_LOAD_SYMBOL");
    if (fixture_id == NULL || fixture_id[0] == '\0')
        s61_die("S61_SAVE_CORRUPTION_ID is required");
    if (owner_image_path == NULL || owner_image_path[0] == '\0')
        s61_die("S61_SAVE_EXPECT_OWNER_IMAGE is required");
    const size_t owner_image_size = S61_SAVE_BLOCK2_SIZE
        + S61_SAVE_BLOCK1_SIZE + S61_POKEMON_STORAGE_SIZE;
    uint8_t *expected_owner = expect_valid
        ? s61_load_control_fixture(owner_image_path, owner_image_size)
        : NULL;
    char save_path[4096];
    s61_save_path(save_path, sizeof(save_path), directory,
                  "save-corruption-probe");
    struct Fixture fixture = s61_world_fixture(
        fixture_id, &config->giver);

    bool fresh_title_continue = false;
    bool no_continue_safe_ui = false;
    bool input_recovered = false;
    uint64_t ui_before = 0U;
    uint64_t ui_start = 0U;
    uint64_t ui_after = 0U;
    struct mCore *core = NULL;
    if (expect_valid) {
        s61_allow_savedata_time_offset_notice = true;
        core = s61_open_fresh(rom_path, save_path, &fixture);
        s61_allow_savedata_time_offset_notice = false;
        fresh_title_continue = true;
        input_recovered = world_overworld(core)
            && !world_script_enabled(core);
    } else {
        /* A completely invalid image has no Continue row.  Boot it through
         * the real title/menu owner, press START then B, and prove that the
         * UI remains executable and responsive without copying a generation
         * into RAM.  The direct loader no-copy proof below is a separate
         * fresh mCore so UI liveness cannot mask memory corruption. */
        core = bootstrap_open_core(rom_path, save_path, s61_video);
        s61_diagnostic_core = core;
        s61_illegal_opcode_dumped = false;
        s61_frames(core, 0U, BOOTSTRAP_TITLE_FRAMES, NULL);
        ui_before = bootstrap_framebuffer_hash(s61_video);
        s61_frames(core, WORLD_KEY_START, 2U, NULL);
        s61_frames(core, 0U, BOOTSTRAP_CONTINUE_WAIT_FRAMES, NULL);
        ui_start = bootstrap_framebuffer_hash(s61_video);
        char ui_artifact[4096];
        int ui_size = snprintf(
            ui_artifact, sizeof(ui_artifact), "%s/%s-safe-ui",
            directory, fixture_id);
        if (ui_size <= 0 || (size_t)ui_size >= sizeof(ui_artifact))
            s61_die("save corruption UI artifact path is too long");
        s61_write_framebuffer_ppm(
            ui_artifact, s61_video, "SAVE_CORRUPTION_SAFE_UI_FRAME");
        s61_frames(core, WORLD_KEY_B, 2U, NULL);
        s61_frames(core, 0U, BOOTSTRAP_CONTINUE_WAIT_FRAMES, NULL);
        ui_after = bootstrap_framebuffer_hash(s61_video);
        uint32_t pc = (uint32_t)read_register(core, "pc");
        no_continue_safe_ui = s61_cpu_pc_is_executable(pc)
            && !s61_illegal_opcode_dumped;
        input_recovered = no_continue_safe_ui
            && ui_before != ui_start && ui_start != ui_after;
        bootstrap_close_core(core);

        memset(s61_video, 0, sizeof(s61_video));
        core = bootstrap_open_core(rom_path, save_path, NULL);
        s61_diagnostic_core = core;
        s61_illegal_opcode_dumped = false;
        run_trace_prefix(core);
        run_fixed_frames(core);
        if (!world_overworld(core))
            s61_die("invalid-save natural new game did not reach field");
    }

    uint8_t *save1_copy = malloc(S61_SAVE_BLOCK1_SIZE);
    uint8_t *save2_copy = malloc(S61_SAVE_BLOCK2_SIZE);
    uint8_t *storage_copy = malloc(S61_POKEMON_STORAGE_SIZE);
    if (save1_copy == NULL || save2_copy == NULL || storage_copy == NULL)
        s61_die("save corruption canary allocation failed");
    uint32_t save1 = 0U;
    uint32_t save2 = 0U;
    uint32_t storage = 0U;
    s61_snapshot_live_save_blocks(
        core, save1_copy, save2_copy, storage_copy,
        &save1, &save2, &storage);
    uint8_t status = (uint8_t)s61_call_synced(
        core, valid_status_symbol, WORLD_RAM_SAVE_SECTOR_LOCATIONS,
        0U, 0U, 0U);
    if (status != expected_status)
        s61_die("bounded save generation status differs");
    uint32_t selected_counter_before_load = read32(
        core, WORLD_SAVE_COUNTER);
    uint16_t selected_first_sector_before_load = read16(
        core, WORLD_FIRST_SAVE_SECTOR);
    bool tear_injected = false;
    unsigned tear_physical = 0U;
    const char *tear_text = getenv("S61_SAVE_TEAR_PHYSICAL");
    if (tear_text != NULL && tear_text[0] != '\0') {
        tear_physical = s61_uint_env(
            "S61_SAVE_TEAR_PHYSICAL", 0U, 27U);
        uint32_t sector = s61_flash_sector_window(core, tear_physical);
        uint32_t target = sector + WORLD_SAVE_SIGNATURE_OFFSET;
        uint8_t before = read8(core, target);
        if (before != (WORLD_SAVE_SIGNATURE & 0xFFU))
            s61_die("selection/copy tear target is not a valid signature");
        /* AMD byte-program clears one bit in the first signature byte.  It
         * models power loss after generation selection but before the
         * loader's second full validation, without host-editing RAM. */
        core->busWrite8(core, WORLD_FLASH_COMMAND_A, 0xAAU);
        core->busWrite8(core, WORLD_FLASH_COMMAND_B, 0x55U);
        core->busWrite8(core, WORLD_FLASH_COMMAND_A, 0xA0U);
        core->busWrite8(core, target, (uint8_t)(before & 0x20U));
        if (read8(core, target) != (uint8_t)(before & 0x20U))
            s61_die("selection/copy tear byte programming failed");
        tear_injected = true;
    }
    if (!s61_sync_host_call_pc(core))
        s61_die("save corruption HandleLoad scheduler PC did not settle");
    uint8_t load_result = (uint8_t)call_preserving(
        core, load_symbol, 0U, WORLD_RAM_SAVE_SECTOR_LOCATIONS, 0U, 0U);
    if (load_result != 1U)
        s61_die("bounded save generation loader status differs");
    bool selected_owner_exact = expect_valid
        && s61_loaded_owner_image_exact(core, expected_owner);
    uint64_t selected_owner_hash = expect_valid
        ? s61_hash_bytes(expected_owner, owner_image_size) : 0U;
    if (expect_valid && !selected_owner_exact)
        s61_die("selected generation full owner image differs");
    /* Only release the scheduler after the 53,300-byte transaction snapshot.
     * A field frame can legitimately advance volatile play time. */
    run_key_frames(core, 0U, 1U);
    bool canaries_unchanged = s61_live_save_blocks_equal(
        core, save1_copy, save2_copy, storage_copy,
        save1, save2, storage);
    if (!expect_valid && !canaries_unchanged)
        s61_die("invalid generation copied bytes into live save blocks");
    if (expect_valid) {
        uint32_t loaded_save1 = world_save1(core, fixture_id);
        if (read32(core, WORLD_SAVE_COUNTER) != expected_counter
            || read16(core, WORLD_FIRST_SAVE_SECTOR)
                != expected_first_sector
            || read8(core, loaded_save1 + 4U) != fixture.group
            || read8(core, loaded_save1 + 5U) != fixture.map)
            s61_die("fallback generation/counter selection differs");
    } else if (read32(core, WORLD_SAVE_COUNTER) != 0U
               || read16(core, WORLD_FIRST_SAVE_SECTOR) != 0U) {
        s61_die("invalid generations did not fail closed bookkeeping");
    }
    uint32_t loaded_selected_counter = read32(core, WORLD_SAVE_COUNTER);
    uint16_t loaded_selected_first_sector = read16(
        core, WORLD_FIRST_SAVE_SECTOR);
    bool resave_via_start_menu = false;
    bool resave_fresh_continue = false;
    bool resave_canaries_exact = false;
    bool resave_field_input_recovered = false;
    uint32_t resave_selected_counter = 0U;
    uint16_t resave_selected_first_sector = 0U;
    if (require_resave) {
        if (!expect_valid || !selected_owner_exact)
            s61_die("fallback resave requested without exact selected owner");
        resave_via_start_menu = s61_normal_input_save(core);
        if (!resave_via_start_menu)
            s61_die("physical-rotation fallback real START save failed");
        bootstrap_close_core(core);
        core = NULL;
        s61_allow_savedata_time_offset_notice = true;
        core = s61_open_fresh(rom_path, save_path, &fixture);
        s61_allow_savedata_time_offset_notice = false;
        resave_fresh_continue = true;
        resave_canaries_exact = s61_loaded_owner_canaries_exact(
            core, expected_owner);
        resave_field_input_recovered = world_overworld(core)
            && !world_script_enabled(core)
            && read8(core, WORLD_FIELD_CONTROLS_LOCKED) == 0U;
        resave_selected_counter = read32(core, WORLD_SAVE_COUNTER);
        resave_selected_first_sector = read16(
            core, WORLD_FIRST_SAVE_SECTOR);
        if (!resave_canaries_exact || !resave_field_input_recovered)
            s61_die("fallback resave fresh Continue/canaries differ");
    }
    char artifact[4096];
    int artifact_size = snprintf(
        artifact, sizeof(artifact), "%s/%s-final",
        directory, fixture_id);
    if (artifact_size <= 0 || (size_t)artifact_size >= sizeof(artifact))
        s61_die("save corruption final artifact path is too long");
    s61_write_framebuffer_ppm(
        artifact, s61_video, "SAVE_CORRUPTION_FINAL_FRAME");
    printf("{\"schema_version\":2,\"status\":\"PASS\","
           "\"case\":\"save_corruption_probe\","
           "\"fixture_id\":\"%s\",\"expected_valid\":%s,"
           "\"fresh_title_continue\":%s,"
           "\"no_continue_safe_ui\":%s,"
           "\"fresh_mcore_boot\":true,"
           "\"runtime_loader_fresh_mcore\":true,"
           "\"get_save_valid_status\":%u,"
           "\"handle_load_status\":%u,"
           "\"selected_owner_image_size\":%zu,"
           "\"selected_owner_image_fnv1a64\":\"%016" PRIX64 "\","
           "\"selected_owner_full_byte_exact\":%s,"
           "\"selected_counter_before_load\":%" PRIu32 ","
           "\"selected_first_sector_before_load\":%u,"
           "\"tear_after_selection_before_copy\":%s,"
           "\"tear_physical_sector\":",
           fixture_id, expect_valid ? "true" : "false",
           fresh_title_continue ? "true" : "false",
           no_continue_safe_ui ? "true" : "false",
           status, load_result,
           expect_valid ? owner_image_size : 0U, selected_owner_hash,
           selected_owner_exact ? "true" : "false",
           selected_counter_before_load,
           selected_first_sector_before_load,
           tear_injected ? "true" : "false");
    if (tear_injected)
        printf("%u", tear_physical);
    else
        printf("null");
    printf(","
           "\"expected_counter\":%" PRIu32 ","
           "\"selected_counter\":%" PRIu32 ","
           "\"selected_first_sector\":%u,"
           "\"saveblock1_saveblock2_storage_unchanged\":%s,"
           "\"resave_after_fallback\":%s,"
           "\"resave_via_start_menu_input\":%s,"
           "\"resave_fresh_continue\":%s,"
           "\"resave_canaries_exact\":%s,"
           "\"resave_field_input_recovered\":%s,"
           "\"resave_selected_counter\":%" PRIu32 ","
           "\"resave_selected_first_sector\":%u,"
           "\"safe_ui_framebuffer_before_fnv1a64\":\"%016" PRIX64
           "\",\"safe_ui_framebuffer_start_fnv1a64\":\"%016" PRIX64
           "\",\"safe_ui_framebuffer_after_fnv1a64\":\"%016" PRIX64
           "\",\"input_recovered\":%s,\"warnings\":0}\n",
           expected_counter,
           loaded_selected_counter,
           loaded_selected_first_sector,
           canaries_unchanged ? "true" : "false",
           require_resave ? "true" : "false",
           resave_via_start_menu ? "true" : "false",
           resave_fresh_continue ? "true" : "false",
           resave_canaries_exact ? "true" : "false",
           resave_field_input_recovered ? "true" : "false",
           resave_selected_counter, resave_selected_first_sector,
           ui_before, ui_start, ui_after,
           input_recovered ? "true" : "false");
    free(storage_copy);
    free(save2_copy);
    free(save1_copy);
    free(expected_owner);
    bootstrap_close_core(core);
}

static void s61_write_exact_binary(const char *path,
                                   const uint8_t *bytes, size_t size)
{
    FILE *stream = fopen(path, "wb");
    if (stream == NULL)
        s61_die("partial link baseline save restore failed");
    bool wrote = fwrite(bytes, 1U, size, stream) == size;
    bool closed = fclose(stream) == 0;
    if (!wrote || !closed)
        s61_die("partial link baseline save restore failed");
}

enum S61CowPhase {
    S61_COW_PHASE_NONE,
    S61_COW_PHASE_PREFLIGHT,
    S61_COW_PHASE_STOCK,
    S61_COW_PHASE_POST,
    S61_COW_PHASE_COUNT,
};

enum S61CowCallbackKind {
    S61_COW_CALLBACK_ERASE,
    S61_COW_CALLBACK_PROGRAM,
};

enum S61CowSilentSuccessMode {
    S61_COW_SILENT_ERASE_NO_EFFECT,
    S61_COW_SILENT_PROGRAM_NO_OP,
    S61_COW_SILENT_PROGRAM_WRONG_BYTE,
    S61_COW_SILENT_SUCCESS_MODE_COUNT,
};

enum {
    S61_COW_CALLBACKS_PER_SECTOR = 4097U,
    S61_COW_PREFLIGHT_CALLBACKS = 57358U,
    S61_COW_STOCK_CALLBACKS = 20485U,
    S61_COW_POST_CALLBACKS = 57359U,
    /* The stock 128 KiB flash driver does not call the public
     * ProgramFlashByte pointer while writing a sector.  Its aggregate
     * program-sector owner calls this pinned internal byte routine directly.
     * Both addresses are part of the unmodified FireRed save ABI. */
    S61_STOCK_PROGRAM_FLASH_SECTOR = 0x081C302DU,
    S61_STOCK_INTERNAL_PROGRAM_FLASH_BYTE = 0x081C2FF5U,
    S61_READ_FLASH_SECTION = 0x080DB179U,
    S61_COW_MAX_CHECKPOINTS = 192U,
    S61_COW_MAX_FAULT_RESULTS = 160U,
};

